		\lim_{\varepsilon\to 0}\lim_{\delta \to 0}f_\gamma(\varepsilon,\delta)=0.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.895084+00:00","domain":"probability theory","id":"claim_02bb3356d4b245e4528fcb813f53b9da101272659298f6c81d1acd6db255a9f4","kind":"definition","schema_version":1,"statement":"[Definition def: cocycle property of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] A random field $\Psi\colon \Omega \times \mathbb{Z}^{d} \to \mathbb{R}$ satisfies the \emph{cocycle property} if for $\mathbb{P}$-a.e.\ $\omega$

  \begin{align}

    \Psi(\omega, y) - \Psi(\omega,x)
    \;=\;
    \Psi(\tau_{x}\omega, y-x),
    \qquad \forall\, x, y \in \mathbb{Z}^{d}.
  \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.654869+00:00","domain":"probability theory","id":"claim_02bd75e358471e13699946ba9a286ca2209f974a38ced414a5385a9d65ea87ea","kind":"concept","schema_version":1,"statement":"[Theorem Martingale Repr THeorem of arXiv:2411.04631, 'Existence of Martingale Solutions to Stochastic Constrained Heat Equation'] Consider Hilbert space $\mathcal{H}$ and $\mathcal{M} \in \mathcal{M}^{2}_{T}(\mathcal{H})$ with 
   \begin{align}
       \left\langle \mathcal{M} \right\rangle_{s}=\int_{0}^{s} \left(f(u)\mathbb{Q}^{\frac{1}{2}}\right)\cdot \left(f(u)\mathbb{Q}^{\frac{1}{2}}\right)^{*} du \nonumber
   \end{align}
   where $f(s)$ is a predictable process. \\ $\mathcal{H}_{0}=\mathbb{Q}^{\frac{1}{2}}\mathcal{H}$ is Hilbert space with following inner product
   \begin{align}
       \left\langle h, k \right\rangle_{\mathcal{H}_{0}}:= \left\langle \mathbb{Q}^{-\frac{1}{2}}h , \mathbb{Q}^{-\frac{1}{2}} k \right\rangle_{\mathcal{H}}, \;\; h,k \in \mathcal{H}_{0} \nonumber.
   \end{align}
And $\mathbb{Q}$ is a symmetric, bounded and non-negative operator in $\mathcal{H}$.
Then one can find the probability space $(\hat{\Omega},\hat{\mathcal{F}},\hat{\mathbb{P}})$, a filtration $\mathcal{F}_{s}$ and a $\mathcal{H}-$ valued $\mathbb{Q}-$ Wiener process $W$ defined on $\left(\Omega \times \hat{\Omega}, \mathcal{F} \times \hat{\mathcal{F}}, \mathbb{P} \times \hat{\mathbb{P}}\right)$ adapted to $\mathcal{F} \times \hat{\mathcal{F}}$ such that for all $(\omega,\hat{\omega}) \in \Omega \times \hat{\Omega}$,
\begin{align}
    \mathcal{M}(s,\omega,\hat{\omega})=\int_{0}^{s} f(u,\omega,\hat{\omega})d\omega(u,\omega,\hat{\omega}), \; s\in [0,T] ,
\end{align}
with
\begin{align}
    \mathcal{M}(s,\omega,\hat{\omega})=\mathcal{M}(s,\omega), \text{ and }\; f(s,\omega,\hat{\omega})=f(s,\omega).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:47.656404+00:00","domain":"probability theory","id":"claim_02c2b3f9e0d097b266658443c95d37b4c94e412486b6ed167fb216a8377e07ad","kind":"concept","schema_version":1,"statement":"[Lemme 3 of arXiv:2605.07571, '\textbf{On the Besov-Orlicz path regularity of some Gaussian processes}'] There exists two positive constants $A_{H, K}$ and $B_{H, K}$ such that  for all $0<h<1/2$ and $t \in [0, 1-h]$ 
\begin{eqnarray} 
\E(|F_h(t)|^p)\leq \begin{dcases}
	(A_{H, K} c_p)^p h^{HKp},&\quad  \mbox{if}\quad \,  t\in [0, h]; \\
	(B_{H, K} c_p)^p h^{p}t^{-(1-HK)p},&   \mbox{if}\quad \,  t\in [h, 1-h].
	\end{dcases}  
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:07.299601+00:00","domain":"probability theory","id":"claim_02c4b49a0baff5efdf368ea314b51d021e8b022e8717c3479d32c3f80abaca20","kind":"lemma","schema_version":1,"statement":"[Lemma 16 of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] For any probability measure $\mu$ with $\mom(\mu) \defeq (\int \|x\|^2\,\mu(\!\dd x))^{1/2} < \infty$ and any $t > 0$,
    \begin{align*}
        \FI(q_t^\mu\mmid \gamma)
        &\le e^{-2t}\,\mom^2(\mu) + \frac{e^{-4t}}{1-e^{-2t}}\,d\,.
    \end{align*}
    In particular, if $\mom(\mu) \le \sqrt d$,
    \begin{align*}
        \FI(q_t^\mu\mmid \gamma)
        &\le \frac{de^{-2t}}{1-e^{-2t}}\,.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.570141+00:00","domain":"probability theory","id":"claim_02cb0eafe10f58f608c9294dccdc752bbe8f3e76231baf38b14297ba912bd661","kind":"concept","schema_version":1,"statement":"[Corollary 6 of arXiv:2608.27307, '2608.27307'] Under the assumptions of Theorem~\ref{thm:opt_ll}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
