{"assumptions":[],"created_at":"2026-10-27T22:34:45.626773+00:00","domain":"probability theory","id":"claim_05128aedcd6d478b9b02ef723a3bf2da65f21efdd5a15bbed7bab66bdb43e98b","kind":"concept","schema_version":1,"statement":"[Lemma lem:VolumeGrowthEstimate of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $A_0 \subset A_1 \subset A_2 = \mathbb R^s$ be affine subspaces of dimension $d_0 < d_1$ and $d_2 = s$ equipped with the Euclidean distance. Let $X_i \subset A_i$ be compact subsets with $\operatorname{diam}(X_0) \leq \delta_0$ and $\operatorname{dist}(X_{i-1}, X_i) \leq \delta_i$ for $i = 1, 2$. Then
	\begin{equation*}
		\operatorname{vol}(X_2) \ll_{d_0, d_1, d_2} (\delta_0 + \delta_1 + \delta_2)^{d_0} (\delta_1 + \delta_2)^{d_1 - d_0} \delta_2^{d_2 - d_1}. 
	\end{equation*}
	When $\delta_0 \geq \delta_1 \geq \delta_2$, this simplifies to $\operatorname{vol}(X_2) \ll_{d_0, d_1, d_2} \delta_0^{d_0} \delta_1^{d_1 - d_0} \delta_2^{d_2 - d_1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.557263+00:00","domain":"probability theory","id":"claim_0518b5dfa57bc54ff3feceecac318075b7e235ec6c4dd3cbc93d465da26c460a","kind":"concept","schema_version":1,"statement":"[Problem problem-kac of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Let
    \begin{align}
        \Phi(x,y)=\frac{1}{\tfrac{1}{x}+\tfrac{1}{y}-1}.
    \end{align}
    Prove that if
    \begin{align}
        \Phi\left(
            \int_{-\infty}^{+\infty} e^{i\xi t}\,d\sigma_1(t),
            \int_{-\infty}^{+\infty} e^{i\xi t}\,d\sigma_2(t)
        \right)
        =\frac{1}{1+\xi^2},
    \end{align}
