{"assumptions":[],"created_at":"2026-10-27T13:20:07.906997+00:00","domain":"probability theory","id":"claim_06c7d13382268f016fea9420c42cca8070cc4c84dfabd7711693fbaf750b5062","kind":"concept","schema_version":1,"statement":"[Proposition IRLS:basicproperties of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] \allowbreak Let $\varepsilon >0$,  $\mathcal{J}_{\varepsilon}: \R^{d_1 \times d_2}  \to \R$ be defined as in (eq:smoothedell1:objective of the paper) 
  and $Q_{\varepsilon}(\cdot \mid \mathbf{X}): \R^{d_1 \times d_2} \to \R$ 
  as defined in (eq:smoothedell1:IRLSmajorizer of the paper) via weight operator $\W{\mathbf{X}}{\varepsilon}: \R^{d_1 \times d_2} \to \R^{d_1 \times d_2}$ defined in (def:optimalweightoperator of the paper). Then the quadratic model and the smoothed surrogate function $\mathcal{J}_{\varepsilon}(\cdot)$ coincide at the reference point, i.e., $Q_{\varepsilon}(\mathbf{X}\mid\mathbf{X}) = \mathcal{J}_{\varepsilon}(\mathbf{X})$ for $\mathbf{X} \in \R^{d_1 \times d_2}$. Furthermore, if the weight operator core matrix $\mathbf{H}_{\boldsymbol{\sigma}, \varepsilon} \in \R^{d_1 \times d_2}$ satisfies $(\mathbf{H}_{\boldsymbol{\sigma}, \varepsilon})_{ii} = \max(\sigma_i,\varepsilon)^{-1}$ for all $i \in [d]$, then, for any  $\mathbf{X} \in \R^{d_1 \times d_2}$, the following gradient condition holds: 
		\begin{equation} 
			\W{\mathbf{X}}{\varepsilon}(\mathbf{X}) = \nabla\mathcal{J}_{\varepsilon}(\mathbf{X}) \quad \text{ for each } \mathbf{X} \in \R^{d_1 \times d_2},
		\end{equation}
		and the quadratic model satisfies for each $\mathbf{Z},\mathbf{X} \in \R^{d_1 \times d_2}$ that
		\begin{equation}
		Q_{\varepsilon}(\mathbf{Z}\mid\mathbf{X})  
    = 
    \mathcal{J}_{\varepsilon}(\mathbf{X}) 
    + \frac{1}{2} \innerproduct{ \mathbf{Z}, \W{\mathbf{X}}{\varepsilon}(\mathbf{Z}) }
    - \frac{1}{2} \innerproduct{ \mathbf{X},\W{\mathbf{X}}{\varepsilon} (\mathbf{X}) }.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:41:11.645867+00:00","domain":"probability theory","id":"claim_06d264869a834ae37b0ae0d3aad657511735096e65b188441c0d7f0a144e588b","kind":"concept","schema_version":1,"statement":"[Thm domination2 of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Let $\gamma \in \Gamma_{-\infty}$, $A \in \ensuremath{\mathcal{A}}(\gamma)$ and $\lambda>0$. Then it holds that, in law, 
\begin{equation}
\ensuremath{\mathbb{Q}}_A= \ensuremath{\mathbb{Q}}_{\gamma^c} \bigoplus  \ensuremath{\mathcal{L}} (\sum_{i\in \ensuremath{\mathcal{Z}}} \delta_{Z^{(i)}}),
\end{equation}
  where $ \ensuremath{\mathcal{L}} (\sum_{i\in \ensuremath{\mathcal{Z}}} \delta_{Z^{(i)}})$ is the law of $\sum_{i\in \ensuremath{\mathcal{Z}}} \delta_{Z^{(i)}}$ and the $Z^{(i)}$'s are random walk paths in $S$ that intersects $\gamma$ having the following properties, depending on an auxiliary random variable $\mathbf{y}$:
\begin{enumerate}
\item  random walk paths:
\begin{enumerate}
   \item The $Z^{(i)}$'s have the conditional law $P^{RW}(\;\cdot \;|\; D_i)$, where the random event $D_i $  
 only concerns the behaviour of $Z^{(i)}$ in the time interval $[-|\gamma|,-1]$.   
    \item We associate an anchor point $z_i \in \{-|\gamma|,...,-1\}$ to each $Z^{(i)}$.
          This point in particular satisfies $Z^{(i)}_{z_i} = \gamma_{z_i}$, and is a function of $\mathbf{y}$.
    \item 
    $D_i$ satisfies $\{Z^{(i)}_{z_i}=\gamma_{z_i}\}\cap\{ Z^{(i)}_s \neq \gamma_s, z_i<s\leq -1 \} \subset D_i \subset \{Z^{(i)}_{z_i}=\gamma_{z_i}\}$ and is a deterministic function of $\mathbf{y}$.
\end{enumerate}

\item  independence and conditional independence:
\begin{enumerate}
      \item conditioned on $\mathbf{y}$ the $Z^{(i)}$'s are independent.
      \item $\eta^{\gamma^c}$ and $(\mathbf{y}, \ensuremath{\mathcal{Z}}, Z^{(i)}, 1\leq i\leq \ensuremath{\mathcal{Z}})$ are independent.
\end{enumerate}

\item  stochastic domination:

\begin{enumerate}
\item There is an $n=n(\lambda) \in \ensuremath{\mathbb{N}}$ such that $|\ensuremath{\mathcal{Z}}_s| \preceq Poi(\lambda)+n$, where $\ensuremath{\mathcal{Z}}_s := \{ i : z_i = s \}$, $s\in \{-|\gamma|,\dots,-1\}$.
\item The vector $(|\ensuremath{\mathcal{Z}}_s|)_{s=-|\gamma|,\dots,-1}$ is stochastically dominated by a vector of independent $Poi(\lambda)+n$-distributed random variables.
\end{enumerate}

\item   random walk bounds when $d\geq 3$:
\begin{enumerate}
      \item there is $\delta>0$ not depending on $\gamma$ nor $A$ such that $P^{RW}(D_i)>\delta$.
\item there exists a constant $C<\infty$, not depending on $\lambda, \gamma$ nor $A$, so that 
\begin{equation} 
\ensuremath{\mathbb{Q}}_A(Z^{i}_t = x \;|\; \mathbf{y}, z_i) \leq C(t-z_i)^{-\frac d2 }.
\end{equation}
\end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.762193+00:00","domain":"probability theory","id":"claim_06d418a0d637a775f83b08470a9980c34ce88d00f817dfa1c467722873d2de32","kind":"concept","schema_version":1,"statement":"[Lemma 15 of arXiv:2512.04544, 'On the diameter of random uniform hypergraphs in dense regime'] Let $t,c,d,n,p$ be as in Assumption~\ref{ass main} and $\mathcal{H} \in \mathscr{H} (n,t,p)$.  Suppose  $\alpha = (x,y)$, where $x$ and $y$ are two vertices and  
