{"assumptions":[],"created_at":"2026-10-26T20:57:44.956017+00:00","domain":"probability theory","id":"claim_08b2c07d00081954d96141cdb8ea8bce05fabbc8a01561d01fd79290097662db","kind":"theorem","schema_version":1,"statement":"[Theorem 7 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] Consider large $n\in\mN$  and let $A_{ij}\sim \cN(0,1)$ be the independent elements of $A\in\mR^{n\times n}$. For a real scalar $c_3\geq 0$ set
  \begin{eqnarray}

 \hat{\bar{\gamma}}_{1} & = &  \frac{c_3\sqrt{2} + \sqrt{2 c_3^2+4}}{4}
 \nonumber \\
 \bar{\phi}_{1}(\gamma_1) & = &  \gamma_{1}c_3\sqrt{2} - \frac{1}{2}\log \lp 1 - \frac{c_3\sqrt{2}}{2 \gamma_{1}}   \rp
 \end{eqnarray}
 Let $\xi^+_{wig}$ be as in (\ref{eq:wiginteq1ab0}) and for a real scalar $u\geq \mE \xi^+_{wig}$ set
 \begin{eqnarray}

 \nonumber \\
 \bar{\phi}_u(u) & = & -\frac{c_3^2}{2} + \bar{\phi}_{1}(\hat{\bar{\gamma}}_1)  -c_3 u .
 \end{eqnarray}
One then has the following LDP with the indicator rate function $\zeta_u(u)$
\begin{eqnarray}

\lim_{n\rightarrow \infty} \frac{\log\lp \mP\lp \xi^+_{wig} \geq u  \rp \rp}{n} \leq \min_{c_3\geq 0}\bar{\phi}_u(u) \triangleq -\bar{\zeta}_u(u).
\end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:59:53.322446+00:00","domain":"probability theory","id":"claim_08b2c3e481fa3ce86bbdf8e824aa06c1e3ab059518a5fd00bab008f6f60bd26a","kind":"lemma","schema_version":1,"statement":"[Lemma lem-event-E-diamond of arXiv:2607.22324, 'The conclave process'] {}
    Define
