\\
& +\lim _{x_{i+1} \rightarrow x_i}\left(x_{i+1}-x_i\right)^{6 / \kappa-1}\left(\left.\mathcal{J}^{(m,n)}_\alpha\right|_{\Gamma_1 \mapsto \Gamma_1^{\prime \prime\prime}}\right) .
