{"assumptions":[],"created_at":"2026-10-27T19:47:40.716067+00:00","domain":"probability theory","id":"claim_0ac8fa5533ca7d4d32888a96413e432b95e8d763bab07992ca586976d3cb1b82","kind":"theorem","schema_version":1,"statement":"[Prop Eq c 1 int of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] As $\delta\to 0$,
$$
\mu^{\rm loop}_{\mathbb{D}}
(t_{\gamma}>\delta, \indx_{\gamma}(0) \text{ odd})
=
c_{1}\log(\delta^{-1})
+
\mathbf{c}_\mathbb{D}^{\rm{loop}} + o(1),
$$
where
\begin{equation}

c_{1}
=
\dfrac{1}{2}\int_{0}^{+\infty}
\mathbb{P}_{\mathbb{C},u}^{1,1}(\indx_{\gamma}(0) \text{ odd}) \,
\dfrac{du}{u^{2}},
\end{equation}
and
\begin{equation}

\mathbf{c}_\mathbb{D}^{\rm{loop}}
=
-
\mu^{\rm loop}_{\mathbb{C}}
(\gamma(0)\in\mathbb{D}, 
\gamma \cap (\mathbb{C}\setminus\overline{\mathbb{D}})\neq\emptyset,
\indx_{\gamma}(0) \text{ odd})
+
\dfrac{1}{2}\int_{0}^{+\infty}
\mathbb{P}_{\mathbb{C},u}^{1,1}(\indx_{\gamma}(0) \text{ odd}) \,
\log(u)
\dfrac{du}{u^{2}} .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:06:55.276058+00:00","domain":"probability theory","id":"claim_0ace57f9d48e17fbdfc05e39afa4040fdcb27947bba158d62825b7786f7a97a6","kind":"definition","schema_version":1,"statement":"[Definition def:gen-supermartingale of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\Omega,\hat\mathcal{Z},T)$ be a generalized sequential gamble space.
  A sequence $\{X_t:\mathcal{S}_t\to\overline{\mathbb{R}}\}_{t\leq T}$ is a \emph{game-theoretic supermartingale} if for all $t< T$ and situations $s\in\mathcal{S}_t$, we have 
  \begin{align}

    \overline{\textsf{\textbf{E}}}[ X_{t+1} \mid s] \leq X_t(s)~,
  \end{align}
  and a \emph{game-theoretic martingale} if $\textsf{\textbf{E}}[ X_{t+1} \mid s] = X_t(s)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.458281+00:00","domain":"probability theory","id":"claim_0ad03a245a9fe17d30c38980d28d3448f8f7d9ac6008935016b1a7d9317f0965","kind":"concept","schema_version":1,"statement":"[Lem uniqueness of arXiv:2605.14910, 'Sharp Phase Transition for the Formation of Infinite Tubes'] Let $w>0$, and let $G_w=(V_w,E_w)$ be the associated directed graph.
  Then for every $p\in[0,1]$, the following holds $\mathbb{P}_p$-almost surely$:$
  If
  \[
  \pi^-=(\ldots,\Delta_{-2}^-,\Delta_{-1}^-,\Delta_0^-)\in V_w^{\mathbb{Z}_{\le0}}
  \quad\text{and}\quad
  \pi^+=(\Delta_0^+,\Delta_1^+,\Delta_2^+,\ldots)\in V_w^{\mathbb{Z}_{\ge0}}
  \]
  are in-ray and out-ray, respectively, then there exists a double ray
  \[
  \pi=(\ldots,\Delta_{-1},\Delta_0,\Delta_1,\ldots)\in V_w^\mathbb{Z}
  \]
  such that
  \begin{equation}
  \pi|_{\mathbb{Z}\cap(-\infty,-I]}=\pi^-|_{\mathbb{Z}\cap(-\infty,-I]}
  \quad\text{and}\quad
  \pi|_{\mathbb{Z}\cap[I,\infty)}=\pi^+|_{\mathbb{Z}\cap[I,\infty)}
  \end{equation}
  for some $I\in\mathbb{N}_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

