	where $\pi:T^*M\to M$ is the canonical projection and $\Phi^s_H$ is the Hamiltonian flow of $H$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.607442+00:00","domain":"probability theory","id":"claim_0b23cc49dc5689498af37cb9777a2f1fb6e94b011ff0fb055af7bf76ef424979","kind":"lemma","schema_version":1,"statement":"[Lemma lemm:est-S3 of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] Let $\phi:[0,1]\times\Omega\rightarrow{\mathbb R}^{2d}$ be a bounded measurable function. Let    $f\in{\mathbb C}_{\boldsymbol{a}} ^{(1+\alpha)\beta}$ for $\beta\in (0,\alpha-1)$. Further assume
    \begin{enumerate}
        \item there exist constants $\gamma_1,\gamma_\phi>0$ so that
        \begin{align}

        \gamma_1&>\frac{1}{2}+\frac{1}{\alpha}+\frac{\beta}{\alpha}\wedge\frac{1}{2}-\frac{\beta}{\alpha};\\

           {\mathbb E}^s|{\mathbb E}^t\phi_r-{\mathbb E}^s\phi_r|&\leqslant \gamma_\phi|r-s|^{\gamma_1}, \quad  (s,r)\in[0,1]_\leqslant^2, t\in[s,1];
        \end{align}
        \item  $\phi_{k_n(t)}$ is ${\mathcal F}_{(k_n(t)-n^{-1})\vee0}$ measurable,  $n\in{\mathbb N}$;
        \item $\phi\equiv0$ or $\beta>0$.
    \end{enumerate}
    Then for any $0<\epsilon<\frac{1}{2}$ there exists a constant $N=N(\alpha,\beta,d,\gamma_1,\epsilon)$ independent of $n$ so that for any $(S,T)\in [0,1]_\leqslant^2$ and any $\sigma$-algebra ${\mathscr G}\subset{\mathcal F}_{k_n(s)}$ the following holds
    \begin{align}

         \| \int_S^T &f(M_r+\Gamma_{r-k_n(r)}\phi_{k_n(r)})-\Gamma_{r-k_n(r)}f(M_{k_n(r)}+\phi_{k_n(r)})dr\|_{L_2(\Omega)|{\mathscr G}}\nonumber\\&\leqslant N \|f\|_{{\mathbb C}_{\boldsymbol{a}}^{(1+\alpha)\beta}}(1+\gamma_\phi)n^{-(\frac{1}{2}+\frac{\beta}{\alpha}\wedge\frac{1}{2})+2\epsilon}|T-S|^{\frac{1}{2}+\epsilon}.
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:08.972806+00:00","domain":"probability theory","id":"claim_0b23f1e6ef208fcd788cd4939bf8b1041631e4d672fe36e4c6040659069eae4e","kind":"concept","schema_version":1,"statement":"[Thm thm_mainRiemannianManifold of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] For $0<H\leq 1/2$ let $(X_{H}(\eta))_{\eta\in\mathcal{M}}$ be the fractional L\'evy field on the $d$-dimensional connected Riemannian manifold $\mathcal{M}$ without boundary. For any relatively compact set $K\subset \mathcal{M}$ with $O$ in the interior of $K$ we have
    \begin{align*} 
        \prob{ \sup_{\eta\in K} X_{H}(\eta) < \varepsilon}  =\varepsilon^{\frac{d}{H} + \mathdutchcal{o}(1)}, \qquad \text{ as } \varepsilon\searrow 0.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:59:45.458057+00:00","domain":"probability theory","id":"claim_0b2ee2e6abe4ffcd7a11900c0ad4599a3f556cb57a6899d7e573d626be9f0cbc","kind":"concept","schema_version":1,"statement":"[Proposition prop:aveflow of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small $n$--independent constants $\tau,\omega_*,\epsilon>0$, and for $i=1,2$ fix spectral parameters
	\begin{equation}

		\Lambda_{i,0}:=\left(\begin{matrix}
			\mathrm{i}\eta_{i,0} & z_{i,0} \\
			\overline{z_{i,0}} & \mathrm{i}\eta_{i,0}
		\end{matrix}\right),
	\end{equation}
	with $|z_{i,0}|\le 10$, $|\eta_{i,0}|\le \omega_*$. For $t\le T^*$ let $\Lambda_{i,t}$ be the solution of (equation eq:charflowmat of the paper) with initial condition $\Lambda_{i,0}$. Let $G_{i,t}:=(W_t-\Lambda_{i,t})^{-1}$, and let $M_{12,t}^A$ be defined in (equation eq:defm12 of the paper). Define the following control parameters and their time--dependent versions\footnote{ Recall that $\rho_i=\rho^{z_i}(\mathrm{i}\eta_i)$, and so in the time dependent case we have $\rho_{i,t}=\rho^{z_{i,t}}(\mathrm{i}\eta_{i,t})$. For example, using these notations, $\ell_t:=\min_{i=1,2}\rho_{i,t}\eta_{i,t}$.}:
	\begin{equation}
		\begin{split}

			\ell&=\ell(\eta_1,z_1,\eta_2,z_2):=\min_{i=1,2}\rho_i|\eta_i|, \qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad \ell_t:=\ell(\eta_{1,t},z_{1,t},\eta_{2,t},z_{2,t}), \\
			\gamma&=\gamma(\eta_1,z_1,\eta_2,z_2):=\frac{|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2}{|z_1-z_2|+\rho_1^2+\rho_2^2+\frac{\eta_1}{\rho_1}+\frac{\eta_2}{\rho_2}}, \qquad\quad \gamma_t:=\gamma(\eta_{1,t},z_{1,t},\eta_{2,t},z_{2,t}).
		\end{split}
	\end{equation}
	Assume that for some small $0<\xi\le \epsilon/10$, with very high probability, with $G_0^{z}(\mathrm{i}\eta):=(H_0^z-\mathrm{i}\eta)^{-1}$,  it holds
	\begin{equation}

		\big|\big\langle\big(G_0^{z_{1,0}}(\mathrm{i}\eta_1)A_1G^{z_{2,0}}(\mathrm{i}\eta_2)-M_{12}^{A_1}(\eta_1,z_{1,0},\eta_2,z_{2,0})\big)A_2\big\rangle\big|\le \frac{n^\xi}{\sqrt{n\ell_0}\gamma_0}\wedge \frac{n^\xi}{n|\eta_1\eta_2|}
	\end{equation}
	uniformly in $\lVert A_i\rVert\le 1$ and for any $|\eta_i|\in [|\eta_{i,0}|,n^{100}]$, where $\ell_0,\gamma_0$ are evaluated at\footnote{ We point out that we require (equation eq:inassav of the paper) for $(\eta_1,z_{1,0},\eta_2,z_{2,0})$, with $|\eta_i|\in[|\eta_{i,0}|,n^{100}]$, and not only for $\eta_i=\eta_{i,0}$.} $(\eta_1,z_{1,0},\eta_2,z_{2,0})$. Then,
	\begin{equation}

		\big|\langle (G_{1,t}A_1G_{2,t}-M_{12,t}^{A_1})A_2\rangle\big|\le \frac{n^{2\xi}}{\sqrt{n\ell_t}\gamma_t}\wedge \frac{n^{2\xi}}{n|\eta_{1,t}\eta_{2,t}|},
	\end{equation}
	with very high probability uniformly in $\lVert A_i\rVert\le 1$ and all $t\le T^*$ such that $n\ell_t\ge n^\epsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:19.041941+00:00","domain":"probability theory","id":"claim_0b334ab083b98d053fa6b2e78202424b2c1c64fc1b49abcbb58c2924e3f5fd75","kind":"lemma","schema_version":1,"statement":"[Lemma lemma-N1 of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Let  $2\le p< \infty$ and $q=\frac{pd}{d-1}$.
Let $\phi$ be the same as in Lemma (lemma-P1 of the paper).
Then, for $0< r< r_0$,
\begin{equation}
\sup_{x_0 \in \partial\Omega} 
\left(\fint_{B(x_0, r) \cap \Omega} |\phi -\fint_{I(x_0, r)} \phi |^q\right)^{1/q}
\le C M_p(g) (r).
\end{equation}
Moreover, for any $x\in \Omega$,
\begin{equation}
 \delta(x) |\nabla \phi (x) | 
\le C M_2 (g) (\delta (x) ), 
\end{equation}
 where $\delta (x)=  \text{\rm dist}(x, \partial\Omega)$.
 The constants  $C$ in (equation N1-0 of the paper)-(equation N1-1 of the paper)  depend at most on $d$, $p$ and the Lipschitz character of $\Omega$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.701108+00:00","domain":"probability theory","id":"claim_0b39d05d5bb3b3679d0f7043c5242b0898f84079cbd9894f1641154eb6e3715d","kind":"theorem","schema_version":1,"statement":"[Prop prior-kac-rice of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $P$ be a polynomial of degree $m$ with only simple roots. Let $U \subset \mathbb{C}$ be an open set and let $\mathscr{N}(P,U)$ denote the number of roots of $P$ in $U$. Then 
     \begin{align}
        \mathscr{N}(P,U)  = \lim_{\varepsilon \to 0} \frac{1}{\pi \varepsilon^2} \int_{U} |P'(z)|^2 \mathbbm{1}_{\{|P(z)|<\varepsilon\}} A(dz).
    \end{align}
    Moreover, 
    \begin{equation}
        \sup_{\varepsilon \in (0,\infty)} \frac{1}{\pi \varepsilon^2} \int_{U} |P'(z)|^2 \mathbbm{1}_{\{|P(z)|<\varepsilon\}} A(dz) \leq m .
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.494012+00:00","domain":"probability theory","id":"claim_0b3d55c9d4ed337667bdf0cf1f86392b3c19d447282e635b999f48808c35582d","kind":"concept","schema_version":1,"statement":"[Lemma 19 (Theorem A.2 in \cite{BW}) of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] Let $\nu$ be a nonnegative random measure on $\mathbb{R}_+$, $\nu(t) := \int_0^t \nu(ds)$, and suppose the Laplace transform
\begin{align*}
    \hat{\nu}(\lambda) := \int_0^\infty e^{-\lambda s} \nu(ds)
\end{align*}

\noindent exists almost surely for any $\lambda > 0$. If
\begin{itemize}\setlength\itemsep{0em}
\item $\rho \in [0, \infty)$ is fixed;
\item $L: (0, \infty) \to (0, \infty)$ is a deterministic slowly varying function at $0$; and 
\item $C_\nu$ is some non-negative (finite) random variable,
\end{itemize}

\noindent then we have:
\begin{align}
    \frac{\lambda^\rho}{L(\lambda^{-1})} \hat{\nu}(\lambda) \xrightarrow[\lambda \to \infty]{p} C_\nu
    \qquad \Rightarrow \qquad 
    \frac{t^{-\rho}}{L(t)} \nu(t) \xrightarrow[t \to 0^+]{p} \frac{C_\nu}{\Gamma(1+\rho)}.
\end{align}

\noindent The same implication also holds when one considers the asymptotics as $\lambda \to 0^+$ and $t \to \infty$ in \eqref{eq:tauberian} (but with $L$ being slowly varying at infinity) instead. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

