{"assumptions":[],"created_at":"2026-10-27T13:59:53.321699+00:00","domain":"probability theory","id":"claim_0c96df6a631a451236b0374d65f74b30e6e3e0f7d8c97e51267b20303bbbe201","kind":"theorem","schema_version":1,"statement":"[Corollary cor-est-maximum-Poisson of arXiv:2607.22324, 'The conclave process'] {}
