{"assumptions":[],"created_at":"2026-10-26T19:25:40.043739+00:00","domain":"probability theory","id":"claim_0d4b9f81609d89bfa0dc75d99cacf0c7925717ebc41a73df7982df1675896b9c","kind":"concept","schema_version":1,"statement":"[Corollary 13 of arXiv:2510.24244, 'Statistical properties of Markov shifts: part II-LLT'] Let Assumptions \ref{MixAss}, \ref{Assss} and \ref{Ball Ass} be in force.
There exists $0<\delta_0<1$ such that for every $z\in\bbC$ with $|z|\leq\delta_0$ there are $\lambda_j(z)\in\bbC\setminus\{0\}$, $h_j^{(z)}\in B_j$ and $\ka_j^{(z)}\in B_j^*$ such that $\ka_j^{(z)}(\textbf{1})=\ka_j^{(z)}(h_j^{(z)})=1$, 
 $\lambda_j(0)=1$, $h_j^{(0)}=\textbf{1}$, $\ka_j^{(0)}=\ka_j$
and
\begin{equation}
 L_{j,z} h_j^{(z)}=\lambda_j(z)h_{j+1}^{(z)},\, (\mathcal L_{j,z})^*\ka_{j+1}^{(z)}=\lambda_j(z)\ka_{j}^{(z)}.   
\end{equation}
Moreover, $z\to\lambda_j(z)$, $z\to h_j^{(z)}$ and $z\to\ka_j^{(z)}$ are analytic functions of $z$ with uniformly (over $z$ and $j$) bounded norms.
Finally,  there are $C_1>0, \delta_1\in(0,1)$ such that for every $g\in B_j$ and all $n$,
\begin{equation}
 \left\|L_j^{z,n}g-\lambda_{j,n}(z)\ka_j^{(z)}(g)h_{j+n}^{(z)}\right\|_{j+n,\om}\leq C_1\|g\|_{j,\om}\delta_1^n
\end{equation}
where $\lambda_{j,n}(z)=\prod_{k=j}^{j+n-1}\lambda_k(z)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:46:12.278823+00:00","domain":"probability theory","id":"claim_0d4fdf3a95770f09cfbd8d5b99bf69956f1401b68258c82cc5259601c410390d","kind":"theorem","schema_version":1,"statement":"[Proposition 14 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Assume that $A^{\epsilon}$ and $B$ satisfy the conditions {\rm [A1- A5]}. For any $t_0 \in \R$, $T>t_0$ and $\xi \in H$, there is the unique solution $X^{\epsilon}_{t;t_0,\xi}$ of Eq. \eqref{eq: SPDE}, and it holds:
    \begin{description}
      \item[(i)] For any $0<\gamma \leq \frac{(1+\beta)\lambda_1 \gamma_0}{2} $, we have
    \begin{align}
        & \E \sup_{t \in [t_0,T]} \Big\{  e^{\gamma (t-t_0)} \| X^{\epsilon}_{t;t_0,\xi} \|_{H}^{2+\beta} + \gamma_0  \int_{t_0}^{t}  e^{\gamma (s-t_0)} \|X^{\epsilon}_{s;t_0,\xi}\|_{H}^{\beta} \|X^{\epsilon}_{s;t_0,\xi}\|_{V}^{2} \, \d s \Big\}  \nonumber \\
        & \quad \leq 2 e^{-\gamma(T-t_0)} \| \xi \|_{H}^{2+\beta} + \frac{(2+\beta) (C_{A,\rho,\epsilon} + (18+10\beta )  C_{B} \epsilon )}{\gamma}, \quad \quad \forall \, T \geq t_0.  
    \end{align}
      \item[(ii)]For any $0<\delta \leq \frac{ (1+\beta)\lambda_1 \gamma_{0}}{2(2+\beta)^2 C_{B} \epsilon}$, $X^{\epsilon}_{t;t_0,\xi}$ satisfies
    \begin{align}
        \E \Big[ \exp \Big\{  \delta \sup_{t \geq t_0} & \Big( \| X^{\epsilon}_{t;t_0,\xi}\|_{H}^{2+\beta} + \frac{\gamma_0}{2} \int_{t_0}^t \| X^{\epsilon}_{s;t_0,\xi} \|_{H}^{\beta} \| X^{\epsilon}_{s;t_0,\xi} \|_{V}^{2} \, \d s  \nonumber \\
         & \quad -  (1+\frac{\beta}{2}) \big( C_{A,\rho,\epsilon}+ \beta C_B \epsilon \big) (t-t_0) \Big) \Big\} \Big] \leq 2 e^{\delta \| \xi \|_{H}^{2+\beta}  }. 
    \end{align}
      \item[(iii)] For any $t_1 \geq t_0$, it satisfies the following uniform estimates
    \begin{align}
        \E  \exp \Big\{ \delta \big\{ \| X^{\epsilon}_{t_1;t_0,\xi}\|_{H}^{2+\beta} \big\} \Big\}  & \leq 2 \,  e^{\delta \big(\| \xi \|_{H}^{2+\beta} + (2+\beta) \frac{ C_{A,\rho,\epsilon}+ \beta C_B \epsilon   }{\lambda_1 \gamma_0} \big)} ;  \\
        \E \Big[ \exp \Big\{  \frac{\delta}{2} \sup_{t \geq t_1}  \big( \frac{\gamma_0}{2} \int_{t_1}^t \| X^{\epsilon}_{s;t_0,\xi} \|_{H}^{\beta} \| X^{\epsilon}_{s;t_0,\xi} \|_{V}^{2} \, \d s & - (1+\frac{\beta}{2}) \big( C_{A,\rho,\epsilon}+ \beta C_B \epsilon \big) (t-t_1) \big) \Big\} \Big]  \nonumber \\
        &  \leq 2 \, e^{\delta  \big( \frac{\| \xi \|_{H}^{2+\beta}}{2} + \frac{2+\beta}{2} \frac{ C_{A,\rho,\epsilon} + \beta C_{B} \epsilon  }{\lambda_1 \gamma_0} \big)}. 
    \end{align}
    \end{description}
    The above results imply that $X^{\epsilon}_{t;t_0,\xi} \in L^{2}(\Omega; \sC_{t_0})$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:05:28.079104+00:00","domain":"probability theory","id":"claim_0d560abe0c81833c0fb8fc5a5fa68f8cc1f221306ec1f9dc41378f3e6f06eba3","kind":"lemma","schema_version":1,"statement":"[Lemma conv_z of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] For each $N\in\mathbb{N}$, suppose $\omega_\mathfrak{k},\omega_0\in\Omega_{N}$ are such that $d_{\Omega}(\omega_\mathfrak{k},\omega_0)\to0$ as $\mathfrak{k}\to+\infty$. Then, for each $\mathfrak{r}\in\mathbb{R}$ and $T\in\mathbb{R}^+$ ,
		\begin{align}
			\sup_{t\in[\mathfrak{r},\mathfrak{r}+T]}&\bigg[|y(\vartheta_{t}\omega_\mathfrak{k})-y(\vartheta_{t}\omega_0)|+|e^{ y(\vartheta_{t}\omega_\mathfrak{k})}-e^{ y(\vartheta_{t}\omega_0)}|\bigg]\to 0 \ \text{ as } \ \mathfrak{k}\to+\infty,\nonumber\\
			\sup_{\mathfrak{k}\in\mathbb{N}}\sup_{t\in[\mathfrak{r},\mathfrak{r}+T]}&|y(\vartheta_{t}\omega_\mathfrak{k})|\leq C(\mathfrak{r},T,\omega_0).
		\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:59:53.394245+00:00","domain":"probability theory","id":"claim_0d57ca38ec46c10fcaf81d8b85402f7b00c5b231b4ead83a4488069db974730c","kind":"lemma","schema_version":1,"statement":"[Lemma lem:weightedbochner of arXiv:2608.29657, 'Hypocoercivity of Tempered Bouncy Particle Samplers for Heavy-Tailed Targets'] For $g \in C_c^3({\mathbb R}^d)$,
    \begin{equation}
        \begin{aligned}
            \|{\mathcal L}_\sigma  g \|_{L^2(\mu)}^2 &=  \int_{{\mathbb R}^d} \sigma^4 \langle \nabla_x g , \nabla_x^2 U \nabla_x g \rangle {\mathrm d} \mu  +  \int_{{\mathbb R}^d}\sigma^4 |\nabla_x^2 g |^2_F {\mathrm d} \mu+  \int_{{\mathbb R}^d} \Theta(g, \sigma) {\mathrm d} \mu,
        \end{aligned}
