    &+ \sigma^3 |\nabla_x g |^2  \Delta_x \sigma - 2 \sigma^3 \langle \nabla_x g , \nabla_x \sigma \rangle {\mathcal L}_0 g- 2 \sigma^2 \langle \nabla_x g , \nabla_x \sigma  \rangle^2\\ &- 2 \sigma^3 \langle \nabla_x g , \nabla_x^2 \sigma \nabla_x g \rangle.
        \end{aligned}
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.258431+00:00","domain":"probability theory","id":"claim_0d589197d414054340926b04cd4e0289a49b11152330f54c78618d08b114726b","kind":"concept","schema_version":1,"statement":"[Lemma 15 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let~\eqref{co:3},~\eqref{co:6} and~\eqref{co:7} hold. Then
\begin{equation*}
