{"assumptions":[],"created_at":"2026-10-26T19:46:12.278373+00:00","domain":"probability theory","id":"claim_0dc36a8c358968852fd25ada1e795a1f24b58ba65daa8eb203db7364c5ce82a5","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Assume that {\rm [A1-A3]} hold. If $C_{\rho_2} < \lambda_1  \gamma_0$, then for any $0 \leq \epsilon \leq \epsilon_0 < \frac{\lambda_1 \gamma_0-C_{\rho_2}}{2 C_B + \lambda_1 L_B}$,
    \begin{equation} 
     \max \{ \| v\|_{H}^{\beta} ,1 \}  \big(   2 _{V^{\ast}}\<A^{\epsilon}(v)  , v\>_V + \epsilon  \, \| B(v) \|_2^2 +  \gamma_0 \|v\|_{V}^{2} \big)  \leq  C_{A,\rho,\epsilon} \leq C_{A, \rho},
    \end{equation}
    where
    \begin{align*}
      & C_{A, \rho,\epsilon}:= \max \Big\{ \frac{\|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon)}, \frac{2}{2+\beta} \Big(\frac{\beta}{\lambda_1 (2+\beta)} \Big)^{\frac{\beta}{2}} \, \delta(\epsilon) \Big( \frac{ \|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon)^2} \Big)^{1+\frac{\beta}{2}}   \Big\} + \epsilon C_{B}, \\
      & C_{A, \rho}:= \max \Big\{ \frac{\sup_{0 \leq \epsilon \leq \epsilon_0}\|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon_0)}, \frac{2}{2+\beta} \Big(\frac{\beta}{\lambda_1 (2+\beta)} \Big)^{\frac{\beta}{2}} \, \delta(\epsilon_0) \Big( \frac{ \sup_{0 \leq \epsilon \leq \epsilon_0}\|A^{\epsilon}(0)\|_{V^{\ast}}^2}{4 \delta(\epsilon_0)^2} \Big)^{1+\frac{\beta}{2}}   \Big\} + \epsilon_0 C_{B} ; \\
& \delta(\epsilon) :=\frac{\lambda_1 \gamma_0- C_{\rho_2} -2 \epsilon \, C_B - \epsilon \, \lambda_1 L_B}{2 \lambda_1}  \geq \delta(\epsilon_0)>0.
