{"assumptions":[],"created_at":"2026-10-27T06:25:55.316510+00:00","domain":"probability theory","id":"claim_0e5b17d65ba434398dfa8964215bf78b8fcc00537aa36763a88181b2a3c02396","kind":"concept","schema_version":1,"statement":"[Proposition 1 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $\kappa\in (0,4]$ and $n\ge 1$ and $\ell\in\Z$. 
Fix $r>0$ and $\bs{\alpha}, \bs{\beta}\in\LX_n$. For $1\le j\le n$, let $\gamma^j$ be annulus $\SLE_{\kappa}(\LFcro{1}^{(\kappa;\ell)})$ in $(\A_r;\ee^{\ii \alpha_j};\ee^{\ii \beta_j-r})$. 
Let $\Pind{n}^{(\kappa;\ell)}=\Pind{n}^{(\kappa;\ell)}(\A_r; \ee^{\ii\bs{\alpha}}, \ee^{\ii\bs{\beta}})$ be the probability measure on $\bs{\gamma}=(\gamma^{1}, \ldots, \gamma^{n})$ under which the curves are independent.
Define $\LFcro{n}^{(\kappa; \ell)}(r; \bs{\alpha}, \bs{\beta})$ as in~\eqref{eqn::multiannulus_pf_def}: 
\begin{align*}
\LFcro{n}^{(\kappa; \ell)}(r; \bs{\alpha}, \bs{\beta})=\prod_{j=1}^n\LFcro{1}^{(\kappa;\ell)}(r; \alpha_j, \beta_j)\times \Eind{n}^{(\kappa;\ell)}\left[\one_{\LE_{\emptyset}(\bs{\gamma})}\exp\left(\frac{\mathfrak{c}}{2}\blm(\A_r; \gamma^1, \ldots, \gamma^n)\right)\right],
\end{align*}
where $\LE_{\emptyset}(\bs{\gamma}) = \{ \gamma^{j} \cap \gamma^{i}=\emptyset, \, \forall i\neq j\}$ is the event that different curves are disjoint, and $\blm$ is the Brownian loop measure defined in~\eqref{eqn::blm_def}. 
\begin{itemize}
\item The partition function $\LFcro{n}^{(\kappa; \ell)}$ is smooth and it satisfies annulus BPZ equations~\eqref{eqn::annulus_BPZ_alpha}-\eqref{eqn::annulus_BPZ_beta} with
\begin{equation} 
F(r)=	F_n(r):=\frac{6\tilde{\mathfrak{b}}-\mathfrak{b}}{r} + 6 \tilde{\mathfrak{b}} \LE(r) + \mathfrak{b} n. 
\end{equation} 
\item Define $\LFcro{n}^{(\kappa)}(r; \bs{\alpha}, \bs{\beta})$ as in~\eqref{eqn::multiannulus_withoutspiral_def}:
\begin{align*}
\LFcro{n}^{(\kappa)}(r; \bs{\alpha}, \bs{\beta})=\sum_{\ell\in\Z}\LFcro{n}^{(\kappa;\ell)}(r; \bs{\alpha}, \bs{\beta}).
\end{align*}
Then there exists a constant $C=C(n)\in (0,\infty)$ independent of $(r; \bs{\alpha}, \bs{\beta})$ such that
\begin{align}
\LFcro{n}^{(\kappa)}(r; \bs{\alpha}, \bs{\beta})\le C\exp\left(\left(n\mathfrak{b}-\frac{(8-\kappa)}{\kappa}\right)r+\left(\frac{3\kappa}{2}-2n\right)\mathfrak{b}\log r\right). 
\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:38:58.713159+00:00","domain":"probability theory","id":"claim_0e5e25a917e72bc9072b1bc6c46698a06a07b07554baa55fddf8ab4ed370ec79","kind":"definition","schema_version":1,"statement":"[Definition def:WP of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [FSmap]
The \emph{pertubative RG map} for $V_j \in \cV$ is
\begin{align}
	\Phi_{j+1}^{\operatorname{pt}} : V_j \mapsto \E_{j+1} \theta V_{j} - P_{j,V}  ,

\end{align}
where $P_{j,V}$ is a polymer function of degree $\le 6$ that is a quadratic form of $V$ as defined in [FSmap] and satisfies bound Lemma~(lemma:FWPbounds3obs of the paper).  We also denote
\begin{align}
	U_{j+1}^{{\operatorname{pt}}} = \Phi_{j+1}^{\operatorname{pt}} (V_j)  ,\qquad V_{j+1}^{{\operatorname{pt}}} = (1- \pi_0 - \pi_{\sf ox}) U_{j+1}^{{\operatorname{pt}}} 
