\begin{align}
    c_{n,x,y}=
        \sum_{\lambda \in \Lambda_{n}} 1_{\partial U_{\lambda}}(x)1_{\partial U_{\lambda}}(y)
        a^{\lambda}_{n,x,y}, \quad n \in \N, x ,y \in V_{n} ,x \neq y,
