    \begin{align*}
        \frac{\deg_{\mathbf{T}_n}(\varnothing)-2\mu}{\sqrt{6\mu}}\overset d\longrightarrow\mathcal{N}(0,1)\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:20.953958+00:00","domain":"probability theory","id":"claim_0f472c73d0bc832cfde3d13b736f1009f13e4c1054847b1196b1ac92e92c81a2","kind":"lemma","schema_version":1,"statement":"[Lemma 29 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Let $\nu \in \mP(\mC_T^1)$ and $H_\nu^t$ be the operator defined in \eqref{eq: H_mu^t}. Then we have
    \begin{align}
\begin{split}

    K_\nu(s, u)- H^t_\nu(s,u)= \beta^2 \int_0^t K_\nu(s,r)H^t_\nu(r,u)\,dr
    =\beta^2 \int_0^t H^t_\nu(s,r) K_\nu(r,u)\,dr,\end{split}
\end{align}
for almost every $u, s, t \in [0, T]$. Moreover, the kernel $H_\nu^t$ extends to a continuous function on $[0, t]^2$, and we have
\begin{equation}

        \sup_{t \in [0, T]} \sup_{u, s \in [0, t]} H_\nu^t(u, s)  \leq A^2.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.497848+00:00","domain":"probability theory","id":"claim_0f4a6671cb74b641552c1a1268045d8e97401fa07fcec375f1878f6866202327","kind":"lemma","schema_version":1,"statement":"[Lemma two point commutation of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] For adjacent growth points $x, y \in \mathbb{R}$ (no marked points $\{z_1,z_2,\ldots,z_n\}$  are between $x$ and $y$). If the system
\begin{equation}
\left\{\begin{array}{l}
\frac{\kappa}{2} \partial_{x x} \psi+\sum_i \cot(\frac{z_i-x}{2})\partial_i \psi+\cot(\frac{y-x}{2})\partial_y \psi+\left( \left(1-\frac{6}{\kappa}\right) \frac{1}{4\sin^2(\frac{y-x}{2})}+h_1(x, z)\right) \psi=0 \\
\frac{\kappa}{2} \partial_{y y} \psi+\sum_i \cot(\frac{z_i-y}{2}) \partial_i \psi+\cot(\frac{x-y}{2}) \partial_x \psi+\left(\left(1-\frac{6}{\kappa}\right) \frac{1}{4\sin^2(\frac{x-y}{2})}+h_2(y, z)\right) \psi=0
\end{array}\right.
\end{equation}
admits a non-vanishing solution $\psi$, then: functions $h_1, h_2$ can be written as $h_1(x, z)=h(x, z), h_2(y, z)=h(y, z)$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.600408+00:00","domain":"probability theory","id":"claim_0f59fc6e05df2d64f17fe9dd80d6d523439ad06c22873b17d3ddee8e147ae2bd","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Td-ad-model-exists of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Consider an MMPP $(B,X)$ with irreducible, monotone $T$, increasing $\alpha$, eigenvector $v^*$, and which satisfies, for all triples $\ell<i<j$,
	\begin{equation}
		(\alpha_j-\alpha_i)\sum_{\ell\leq s} v^*_s\leq \sum_{\ell\leq s} (T_{is}-T_{js}).
	\end{equation}
	For any $\delta>0$, there exists an MMPP $(B^\delta,X^\delta)$ with strictly monotone $T^\delta=T+\delta E$ (with $E$ an appropriate matrix), the same $\alpha$, eigenvector $v^\delta$, and which satisfies, for all triples $\ell<i<j$,
	\begin{equation}
		(\alpha_j-\alpha_i)\sum_{\ell\leq s} v^\delta_s < \sum_{\ell\leq s} (T^\delta_{is}-T^\delta_{js}).
	\end{equation}
	Furthermore, $(B^\delta,X^\delta)$ weakly converges to $(B,X)$ as $\delta\to0$, and the eigenvectors satisfy $v^*\preceq v^\delta$ for all $\delta>0$.","status":"unverified"}

