			\begin{align*}
				(y_{t+2r}^\xi(\omega), (y^{\xi})^{\prime}_{t+2r}(\omega))_{-r \leq t \leq 0} \in \mathscr{D}_{\mathbf{B}(\theta_{r}\omega)}^{\gamma}([-r,0]).
