{"assumptions":[],"created_at":"2026-10-26T20:24:59.504413+00:00","domain":"probability theory","id":"claim_110c6786ae40c9cd96fe966b1c1246a217c4e34e0f88d096629108df03ecd797","kind":"definition","schema_version":1,"statement":"[Definition 79 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\alpha, \beta > 0$ be arbitrary. We denote by $\hat{\calc}_2^{\alpha,\beta}([0,T],W)$ the space of all functions $\Xi : \Delta_T^2 \to W$ such that $\Xi_{t,t} = 0$ for all $t \in [0,T]$ and
\begin{align*}
\| \Xi \|_{\alpha,\beta} := \| \Xi \|_{\alpha} + \| \hat{\delta} \Xi \|_{\beta} < \infty.
\end{align*}
Here $\| \Xi \|_{\alpha}$ denotes the H\"older norm \eqref{Hoelder-norm-sewing-1}. Furthermore, the function $\hat{\delta} \Xi : \Delta_T^3 \to W$ is defined as
\begin{align*}
\hat{\delta} \Xi_{s,u,t} := \Xi_{s,t} - S_{t-u} \Xi_{s,u} - \Xi_{u,t}, \quad (s,u,t) \in \Delta_T^3,
\end{align*}
and its H\"older norm is defined as
\begin{align*}
\| \hat{\delta} \Xi \|_{\beta} := \sup_{\genfrac{}{}{0pt}{}{(s,u,t) \in \Delta_T^3}{s < u < t}} \frac{|\hat{\delta} \Xi_{s,u,t}|}{|t-s|^{\beta}}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.468714+00:00","domain":"probability theory","id":"claim_110d1a8e051dc0d8a172ac9a4206315a019b28dd2c55a92a38bcb93339c8de45","kind":"concept","schema_version":1,"statement":"[Theorem thm:uppermatrix of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let the QMS $\exp(t \mathcal{L}_\gamma)$ be a lift of $\exp(t \mathcal{L}_O)$ in the sense of (def:2ndlift of the paper). The exponential convergence holds: for $X \in \mathcal{M}$ with $E_{\mathcal{F}}(X) = 0$, 
        \begin{align*}
            \norm{e^{t \mathcal{L}_\gamma} (X)}_{2,\sigma} \le C e^{-\nu t} \lVertX\rVert_{2,\sigma}\,,
        \end{align*}
    with $ C = \mathcal{O}(1)$ and $\nu = \frac{\gamma}{\gamma^2 C_0 + C_1}$,
    where 
    \begin{align*}
        C_0 = \Theta\left(\lambda_O^{-1} \right)\,, \quad C_1 = \Theta\left(
         \left(\lambda_S^{-1} + 1 + \lambda_S^{-1/2}(K_1 + K_2 \lambda_O^{-1/2}) \right)^2
           \right)\,.
    \end{align*}
   The spectral gaps $\lambda_O$ and $\lambda_S$ are given in (equation eq:spgaplado of the paper) and (equation eq:spgaplads of the paper), respectively, and the constants $K_1$ and $K_2$ are such that 
   \begin{align}  
    \norm{(\mathrm{id} - E_S)\mathcal{L}_A^\dag (-\mathcal{L}_S)^{-1} \mathcal{L}_A Y}_{2,\sigma} 
  \le & \left( K_1 \lVert\mathcal{L}_O (Y)\rVert_{2,\sigma} + K_2 \sqrt{\mathcal{E}_{\mathcal{L}_O}(Y)} \right)\,.
\end{align}
If $\gamma = \gamma_{\max} := \sqrt{C_1(T)/C_0(T)}$, we have the maximal convergence rate:
\begin{align} 
    \max_{\gamma > 0} \, \nu(\mathcal{L}_\gamma) \ge \nu(\mathcal{L}_{\gamma_{\max}}) = \Omega\left(\frac{\lambda_O^{1/2}}{ \lambda_S^{-1} + 1 + \lambda_S^{-1/2}(K_1 + K_2 \lambda_O^{-1/2})}\right)\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:06:21.668188+00:00","domain":"probability theory","id":"claim_110fc15af739875aaf1e8d42b59307cf38986334dadc7bf4f7380ed0863b737c","kind":"theorem","schema_version":1,"statement":"[Proposition 5 (Negative drift of $c_n$) of arXiv:2607.20838, 'Long-memory Markov chains with power-law intensities'] There exists $x_* > 0$ such that the following statements hold.
	\begin{enumerate}
		\item For $0 < x < x_*$, if 
		\begin{equation}
			c > C_1 
			:= \frac{2\mu \gamma + 3 \mu_{\varepsilon} + \sqrt{(2\mu \gamma + 3 \mu_{\varepsilon})^2 
					+ \frac{24  \mu \mu_{\varepsilon} \gamma x_*}{\xi}}}{4\mu}, 
		\end{equation}
		then $\mathbb{E}_{x,c}[c_n] - c < 0$.

		\item For $x \ge x_*$, if 
		\begin{equation}
			c > C_2 
			:= \frac{\gamma + \sqrt{\gamma^2 + \frac{3 \mu_{\varepsilon} \gamma}{k_p \xi}}}{2}, 
		\end{equation}
		then $\mathbb{E}_{x,c}[c_n] - c < 0$.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:48:00.296839+00:00","domain":"probability theory","id":"claim_1111d38cb8f190d740889c4aad382c9375d039f8fcb281ff2f4a465479b28caf","kind":"concept","schema_version":1,"statement":"[Theorem thrm:random_apprx_noisy_robustified of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Suppose that Assumption~(assumption:main_1Lip of the paper) holds.  Let
$N_0,N_1\in\mathbb{N}_+$ and set $N\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} N_0+N_1$.  Fix
$\varepsilon\in(0,1)$ and
$\delta_{\operatorname{net}},
 \delta_{\operatorname{noise}}\in(0,1)$
such that
$
    \varepsilon/2\le\operatorname{diam}(X)
$.
Set
\[
    \eta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{\varepsilon}{4},
    \qquad
    \beta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{\varepsilon}{2},
    \qquad
    q_\varepsilon
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \left\lceil\varepsilon^{-2}\right\rceil.
\]
Use the first $N_0$ observations as the reference block and the remaining
$N_1$ observations as the averaging block.  Assume that
\begin{equation}

\begin{aligned}
    N_0
    &\ge
    \frac{1}{a(\varepsilon/8)^s}
    \log\left(
        \frac{
            2\mathcal N(X,\rho,\varepsilon/8)
        }{
            \delta_{\operatorname{net}}
        }
    \right),
    \\
    N_1
    &\ge
    \frac{1}{a(\varepsilon/2)^s}
    \max\left\{
        2q_\varepsilon,
        8\log\left(
            \frac{
                2N_0
            }{
                \delta_{\operatorname{net}}
            }
        \right)
    \right\}.
\end{aligned}
\end{equation}

For each $k\in[N_0]_+$, set $\xi_k\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} X_k$.  If at least
$q_\varepsilon$ indices
$j\in\{N_0+1,\ldots,N_0+N_1\}$ satisfy
$
    \rho(X_j,\xi_k)\le\beta,
$
let
$
    j_{k,1}<\cdots<j_{k,q_\varepsilon}
$
be the first $q_\varepsilon$ such indices and define
\[
    \overline Y_k
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \frac{1}{q_\varepsilon}
    \sum_{\ell=1}^{q_\varepsilon}
        Y_{j_{k,\ell}}.
\]
If fewer than $q_\varepsilon$ such indices exist, set
$
    \overline Y_k\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}0
$.

Define, for every $x\in X$,
\begin{equation}

    \hat{f}(x)
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \frac{1}{2}
    \left[
        \min_{k\in[N_0]_+}
        \left\{
            \overline Y_k+\rho(x,\xi_k)
        \right\}
        +
        \max_{k\in[N_0]_+}
        \left\{
            \overline Y_k-\rho(x,\xi_k)
        \right\}
    \right].
\end{equation}
Then, for every fixed
$f\in\operatorname{Lip}((X,\rho);1)$:

\begin{enumerate}
    \item[(i)] $\hat{f}:X\to\mathbb{R}$ is $1$-Lipschitz for every
    realization of the sample;

    \item[(ii)] the random variable
    $
        \|\hat{f}-f\|_\infty
    $
    is measurable and satisfies
    \begin{equation}

        \mathbb{P}\left(
            \|\hat{f}-f\|_\infty
            \le
            \varepsilon
            \left[
                1
                +
                \sqrt{
                    C
                    \log\left(
                        \frac{
                            2N_0
                        }{
                            \delta_{\operatorname{noise}}
                        }
                    \right)
                }
            \right]
        \right)
        \ge
        1
        -
        \delta_{\operatorname{net}}
        -
        \delta_{\operatorname{noise}}.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:17:17.079061+00:00","domain":"probability theory","id":"claim_1113762907889082a6dc97cc8caad1873999152324edc2acce287cb4293baee9","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] Under the assumptions of \Cref{thm:main}, for every $d\ge1$ and
