 \item For every $1\le r<q$ and every $u=[u_n]\in\cH_r$,
 \begin{equation}
  [f_n\otimes_ru_n]_{\mathcal U}=0.

 \end{equation}
 \item For every $1\le r<q$,
 \begin{equation}
  \Ulim\norm{L_{f_n,r}}_{\op}=0.

 \end{equation}
 \item For every $1\le r<q$,
 \begin{equation}
  \Ulim\norm{f_n\otimes_rf_n}=0.

 \end{equation}
\end{enumerate}
Equivalently, if $M_{r,u}v=u\wtensor v$, then
\begin{equation}
 \boxed{\displaystyle
 \cK_q=\bigcap_{r=1}^{q-1}\ \bigcap_{u\in\cH_r}
 \Ker M_{r,u}^*.}

\end{equation}

Moreover, if $k=[f_n]\in\cK_p$ and $\ell=[g_n]\in\cK_q$, then
\begin{equation}
 \Ulim\norm{f_n\otimes_rg_n}=0

\end{equation}
for every contraction which is not total, that is, except possibly when
$p=q=r$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.604967+00:00","domain":"probability theory","id":"claim_13db91682eee90ad7f8240e484d40bb50671ed0eec5511454433e680a442c543","kind":"concept","schema_version":1,"statement":"[Theorem Propagation of chaos 2 of arXiv:2606.13264, 'Interference Queueing Networks: A Replica Mean-Field Approach in the Symmetric Setting'] Let $T > 0$. Assume that, for all $K$, for all $l \leq K$, and for all $j \in [1,N]$,
