		\medskip
		\item [(ii)]there exist  $Q_1,\ldots,Q_n\in\mathcal{ M}^e(T)\cap\operatorname{core}(V)$ and $A_1,\ldots,A_n\in\mathcal{I}$ satisfying that  $\Omega=\cup_{j=1}^nA_j$, $Q_j(A_j)=1$, and $A_j\cap A_k=\emptyset$ when $j\neq k$ such that for any $f\in B(\Omega,\mathcal{F})$,  
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}f(T^i\omega)=\sum_{j=1}^{n}\left(\int fdQ_j\right) \cdot1_{A_j}(\omega),\text{ for }V\text{-a.s. }\omega\in\Omega.
		\end{equation}
		\medskip
		\item [(iii)]there exist  $Q_1,\ldots,Q_n\in\mathcal{ M}(T)\cap\operatorname{core}(V)$ and $A_1,\ldots,A_n\in\mathcal{I}$ satisfying that  $\Omega=\cup_{j=1}^nA_j$, $Q_j(A_j)=1$, and $A_j\cap A_k=\emptyset$ when $j\neq k$ such that for any $f\in B(\Omega,\mathcal{F})$,  
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}f(T^i\omega)=\sum_{j=1}^{n}\left(\int fdQ_j\right) \cdot1_{A_j}(\omega),\text{ for }V\text{-a.s. }\omega\in\Omega.
		\end{equation}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:38:04.528994+00:00","domain":"probability theory","id":"claim_143f1c2a76275d8c1417d71f34a8fea36fd48ec4e2c79f8e76489c43fcb3375d","kind":"concept","schema_version":1,"statement":"[Proposition of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:tile_and_cell_volume_bounds}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$ and let $\varepsilon > 0$.
    Let $\overline{r}_0 > r_0 > 0$, let $(m_i)_{i \in \mathbf{N}}$ satisfy $m_i > (1+\varepsilon)/\varepsilon$ for all $i \in \mathbf{N}$, and suppose that $\overline{r}_0 \leq \varepsilon r_1$. 

    Consider the renormalisation scheme $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ associated to the renormalisation scales $(r_i)_{i \geq 0}$.

    Then there exist $c_{\mathrm{vor}}{} = c_{\mathrm{vor}}{}(G,\varepsilon) > 0$ and $C_{\mathrm{vor}}{} = C_{\mathrm{vor}}{} (G,\varepsilon) \ge 1$ such that 

    \begin{equation}
        c_{\mathrm{vor}}{}
        r_{i}^d
        \leq 
        \# \Cell{i}{j} 
        \leq
        C_{\mathrm{vor}}{}
        r_{i}^d,
        \quad
        c_{\mathrm{vor}}{}
        r_{i}^d
        \leq 
        \# \Tile{i}{j} 
        \leq
        C_{\mathrm{vor}}{}
        r_{i}^d,
        \quad 
        \text{and}
        \quad
        c_{\mathrm{vor}}{} 
        m_i^d
        \leq
        \kappa_{i,j}
        \leq 
        C_{\mathrm{vor}}{}
        m_i^d
    \end{equation}

    for any tile $\Tile{i}{j}$ and any cell $\Cell{i}{j}$.

    Further, $\Tile{i}{j} \subseteq B(x_{i,j},C_{\mathrm{vor}}{} r_i)$ for any tile $\Tile{i}{j}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.599511+00:00","domain":"probability theory","id":"claim_144052063c058e92ab84fb54be813df811f4a4edd12980d1f19a5dcc80c99d00","kind":"concept","schema_version":1,"statement":"[Theorem main of arXiv:2412.03450, 'On intermediate levels of nested occupancy scheme in random environment generated by stick'] Under Assumptions $A$ and $B$ imposed on $(\xi, \eta)=(|\log W|, |\log (1-W)|)$, let $(j_n)_{n\geq 1}$ be a sequence of positive numbers satisfying $\lim_{n\to\infty}j_n=\infty$ and
\begin{equation*}
j_n = o\left((\log n)^{\min \left(1/3,(\alpha-\beta)/(\alpha-\beta+1)\right)}\right),\quad n\to\infty,
\end{equation*}
where $\beta=\rho$ if $m_0<\infty$ and $\beta=\max (\rho, \alpha-\theta)$ if $m_0=\infty$ and $m_1<\infty$. Then
$$\left(\frac{c j_n ^\alpha }{\rho_{\lfloor j_n u \rfloor - 1}(\log n)^{\alpha \lfloor j_n u \rfloor}} K_n(\lfloor j_n u \rfloor )
\right)_{u>0}~\overset{{\rm f.d.d.}}{\longrightarrow}~\left(\int_0^\infty {\rm e}^{-\alpha u y} {\rm d} \mathcal{Z}_\alpha^\leftarrow(y) \right)_{u>0},\quad n\to\infty,
$$
where
\begin{equation}
\rho_i:= \frac{(C\Gamma(\alpha + 1))^i}{\Gamma(\alpha i + 1)}, \quad i\in \mathbb{N}_0:=\{0,1,\ldots\},
\end{equation}
and $\Gamma$ is the Euler gamma-function. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:25:40.277432+00:00","domain":"probability theory","id":"claim_144090192ae65008fb1493d1580df1a7c4ade266d5fc4da864625e14dd21e044","kind":"theorem","schema_version":1,"statement":"[Proposition prop:parity of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] A geodesic Leech labeling satisfies
