{"assumptions":[],"created_at":"2026-10-27T13:04:55.804258+00:00","domain":"probability theory","id":"claim_15467d0df2e4c0914c165de212bc96680f4b6d25a7ee6e4f1c860de7e3e71906","kind":"lemma","schema_version":1,"statement":"[Lemm l:properties-of-I of arXiv:2607.18194, 'Temperature chaos in directed polymers'] The following properties hold.
    \begin{enumerate}[label={\rm(\roman*)}]
        \item \textup{(Symmetry)}
        For all $n\in\mathbb{Z}_{\geqslant1}$ and all $f\in L^2(\mathbb{R}^{2n})$, we have
        $I_n(f) = I_n(\widetilde{f})$, 
        where $\widetilde{f}$ denotes the \emph{symmetrization} of $f$:
        \begin{align}
            \widetilde{f}(a_1;\cdots;a_n) \coloneqq  \frac{1}{n!}
            \sum_{\pi\in \mathfrak{S}_n} f(a_{\pi(1)};\cdots;a_{\pi(n)}),
            \qquad\qquad (a_1;\cdots;a_n)\in \mathbb{R}^{2n},
        \end{align}
        where $\mathfrak{S}_n$ denotes the group of permutations of $\{1,\dots,n\}$.

        For $n=0$ and $f\in L^2(\mathbb{R}^0)$, we denote $\widetilde{f}\coloneqq f$, so that $I_0(\widetilde{f})=I_0(f)$.
        \item \textup{(Orthogonality)}
        For all $n,m\in{\mathbb{Z}_{\geqslant0}}$, all $f\in L^2(\mathbb{R}^{2n})$, and all $g\in L^2(\mathbb{R}^{2m})$,
        \begin{align*}
            \mathbb{E}\left[I_n(f)I_m(g)\right]&= \begin{cases}
                0,&\quad n\ne m\\
                n!\langle \widetilde{f},\widetilde{g}\rangle_{L^2(\mathbb{R}^{2n})},&\quad n=m.
            \end{cases}
        \end{align*}
        Moreover,
        \begin{align}
            n!\langle \widetilde{f},\widetilde{g}\rangle_{L^2(\mathbb{R}^{2n})}
            &= \sum_{\pi\in\mathfrak{S}_n} \int_{\mathbb{R}^{2n}}f(a_1;\cdots;a_n)\,g(a_{\pi(1)};\cdots;a_{\pi(n)})\,da_1\dots da_n.
        \end{align}
    \end{enumerate}","status":"unverified"}

