		\end{align*}
		\item  for every bounded nonnegative test function $\varphi\colon M\to\R$,
		\begin{align}
			\mathbb{E}\!\left[\scalar{ h-h_{\ell}}{\varphi}^2\right]
			= O(\ell^{-1}),
		\end{align}
	\item For $\ell\in\N$ and $\gamma^2<\frac n8$
	\begin{align}
