{"assumptions":[],"created_at":"2026-10-27T12:27:11.448710+00:00","domain":"probability theory","id":"claim_1a2db0fddfd764f00387d58b2774a64feb5865a92ab54bb2fd37572c16fa734e","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $n\in\N, p\in\N_0$, $\mu\neq0$ be a finite measure on $\R^d$, and $x_1,...,x_n\in\R^d$. We say that $x_1,...,x_n$ form an averaging set of $\mu$ of order $p$ and size $n$ if they form an averaging set of $\mu$ and the polynomials of degree up to $p$, i.e.,
    \begin{equation}
        \frac{1}{\mu(\R^d)}\int x^{\otimes q}\, \mu(dx) = \frac{1}{n} \sum_{k=1}^n x_k^{\otimes q},\quad q\in\{0,...,p\}.
    \end{equation}
    Implicitly, we assume that the polynomials of degree up to $p$ are integrable with respect to $\mu$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.375153+00:00","domain":"probability theory","id":"claim_1a2e35b056fe63848784543608c97818cacd26731ec81b43e87d299453278a07","kind":"concept","schema_version":1,"statement":"[Cor 7 of arXiv:2606.04636, 'A Thomson-type variational principle for diffusion coefficients'] Let $\phi\in V_{0}$ with $\left\langle \phi,\phi\right\rangle \neq0$.
