\begin{align}

\sup_{ x\in \Sigma ^{ R }}\mathbf E  \left[\;
   \overline{\X_{ N}}(\tau _{ x}f_{ R  }) ^{ 2}
\right]\leqslant C _{ f}  R ^{ d  -\alpha }.
