{"assumptions":[],"created_at":"2026-10-27T22:31:02.829293+00:00","domain":"probability theory","id":"claim_1ad3483a2a07b74b43b9d48529b4b4aff7f1a7d8a284347e7c200f503d47a2ad","kind":"theorem","schema_version":1,"statement":"[Prop wrapped_orth of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let polynomials ${\bm Q}_{{\bm j}, {\bm k}, m}^n$ of $d_1+d_2$ variables be defined by
\begin{equation}
   {\bm Q}_{{\bm j}, {\bm k}, m}^n({\bm x}, {\bm y}) = {\bm R}_{{\bm j},n-m}^{(m)}({\bm y}) [\rho({\bm y})]^m {\bm P}_{{\bm k},m}\left(\frac{{\bm x}}{\rho({\bm y})}\right),  
\end{equation}
where $0 \le m \le n$, $|{\bm k}| = m$ with ${\bm k} \in {\mathbb N}_0^{d_1}$, and $|{\bm j}| = n-m$ with ${\bm j} \in {\mathbb N}_0^{d_2}$. 
Then the collection $\left\{  {\bm Q}_{{\bm j}, {\bm k}, m}^n: |{\bm k}| = m,\,  |{\bm j}| = n-m, 0 \le m \le n\right\}$ is an orthogonal basis 
of ${\mathcal V}_n(\Omega_1^{d_1}  \rtimes \Omega_2^{d_2}, {\bm W}^{\Omega_1\rtimes \Omega_2})$.
Moreover, the norm square ${\bm h}_n^{\Omega_1\rtimes \Omega_2}
 = {\langle}  {\bm Q}_{{\bm j}, {\bm k}, m}^n, {\bm Q}_{{\bm j}, {\bm k}, m}^n{\rangle}_{\bm W}$ is equal to 
$$
{\bm h}_n^{\Omega_1\rtimes \Omega_2} = {\bm h}_{{\bm j}, n-m}\big(\rho^{2m+d_1}{\bm W}_2\big) {\bm h}_m({\bm k}, {\bm W}_1)
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.569247+00:00","domain":"probability theory","id":"claim_1ad64a538b5aa80902ff96d9be134f6345153af8fad00c5489561ec674dc7f53","kind":"theorem","schema_version":1,"statement":"[Theorem 49 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X_1, \mu_1)$ and $(X_2, \mu_2)$ be Polish measure spaces, and let $c$ be a continuous cost function on $X_1\times X_2$ such that $-c(X_1 \times X_2)=[a,b)$. Fix a weight $\lambda \in (0,1)$. Assume that $(X_1, \mu_1)$ and $(X_2,\mu_2)$ satisfy the Cost-Santal\'o inequality in Lemma~\ref{l:transfer} associated with $(\lambda,c,F)$ and domain $(\mathcal{A}_1, \mathcal{A}_2)$, where $F:[a,b]\to [0,\infty)$ is a continuous, non-decreasing function such that $F(a)=0$.  Assume also that the total masses 
    \[
    0<Z_1 = \int_{X_1} \Omega(\Phi_1(x_1)) d\mu_1(x_1),\, Z_2 = \int_{X_2}\Omega(\Phi_2(x_2)) d\mu_2(x_2) <+\infty.
    \]

    Let $\Phi_1: X_1 \to [a,b]$ and $\Phi_2: X_2 \to [a,b]$ be measurable functions satisfying
    \begin{equation}

        \lambda \Phi_1(x_1) + (1-\lambda) \Phi_2(x_2) \ge -c(x_1, x_2), \quad \forall x_1\in X_1, x_2\in X_2.
    \end{equation}
    Let $\Omega: [a,b] \to (0,\infty)$ be a continuous, non-increasing, log-concave function. Moreover, assume the following balance condition holds:
    \begin{equation}

        \int_a^b \Omega(r) dF(r) \leq Z_1^\lambda Z_2^{1-\lambda}.
    \end{equation}
    Define the probability measures
    \[
    dP_1(x_1) = Z_1^{-1} \Omega(\Phi_1(x_1))d\mu_1(x_1) \quad \text{and} \quad dP_2(x_2) = Z_2^{-1} \Omega(\Phi_2(x_2)) d\mu_2(x_2)
    \]
    and define the transport cost function on $X_1 \times X_2$ by:
    \begin{equation}
        c_{\Omega}(x_1, x_2) = \log \left( \frac{\Omega(-c(x_1, x_2))^{\frac{1}{1-\lambda}}}{\Omega(\Phi_1(x_1))^{\frac{\lambda}{1-\lambda}} \Omega(\Phi_2(x_2))} \right).
    \end{equation}
    Then $c_\Omega \ge 0$, and for any $\nu_1 \in \mathcal{P}(X_1)$ having density with respect to $P_1$, and $\nu_2 \in \mathcal{P}(X_2)$ having density with respect to $P_2$, one has the optimal transport bound:
    \begin{equation}
        \mathcal{T}_{c_{\Omega}}^{\mathcal{A}}(\nu_1, \nu_2) \leq \frac{\lambda}{1-\lambda} H(\nu_1 | P_1) + H(\nu_2 | P_2),
    \end{equation}
    where $\mathcal{T}_{c_{\Omega}}^{\mathcal{A}}(\nu_1, \nu_2)$ denotes the restricted Kantorovich cost taken as the supremum over pairs $(\varphi, \psi)$ satisfying the pointwise bound $\varphi(x_1) + \psi(x_2) \le c_\Omega(x_1, x_2)$, with the additional constraint that $e^{\frac{1-\lambda}{\lambda}\varphi} \Omega(\Phi_1(\cdot)) \in \mathcal{F}(\mathcal{A}_1)$ and $e^{\psi} \Omega(\Phi_2(\cdot)) \in \mathcal{F}(\mathcal{A}_2)$.","status":"unverified"}

