\end{equation}
while
\begin{equation}

L^{\mu}_{X_{x\theta_i}}\circ A_k-(-1)^{n}A_k\circ L^{\lambda}_{X_{x\theta_i}}
=(\lambda-\lambda_k)\,\Ehat{i}\,\partial_x^{k-1}+(\mu-\lambda-N_k)\,\theta_i A_k .
