{"assumptions":[],"created_at":"2026-10-26T20:54:34.576472+00:00","domain":"probability theory","id":"claim_1c2af14b72b81a95b8f47b0098c9dcb49989fe55d74fb18f69597d4426f3aa3d","kind":"concept","schema_version":1,"statement":"[Lemma 5 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $p\geq 2$ satisfying (\ref{c1}). 

		\begin{enumerate}
			\item Let $ (Y_{N}=I_{p}(g_{N}), N\geq 1) $ be a sequence of random variables which converges in $ L ^{2}(\Omega)$.  Assume that there exists $\rho \in \mathbb{R}$ such that
			\begin{equation}
				\mathbf{E}[ X_{N} Y_{N} ]\to _{N \to \infty} \rho. 
			\end{equation}
			Then 
			\begin{equation*}
				\langle  DX_{N}, DY_{N} \rangle _{ H ^{\otimes p}} \to _{N \to \infty} p\rho \mbox{ in } L ^{2}(\Omega). 
			\end{equation*}
			\item Let $ (Y_{N}=I_{q}(g_{N}), N\geq 1) $ be a sequence of random variables in the $q$ th Wiener chaos such that $q<p$. Assume that $(Y_{N}, N\geq 1)$ is bounded in $ L ^ {2}(\Omega)$. Then 
			\begin{equation*}
				\langle  DX_{N}, DY_{N} \rangle _{ H ^{\otimes p}} \to _{N \to \infty} 0 \mbox{ in } L ^{2} (\Omega). 
			\end{equation*}

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:55.645756+00:00","domain":"probability theory","id":"claim_1c2b5f5de9812910db1565d898df9f19507c5a7ed85993be3b66878ed1b40f2b","kind":"concept","schema_version":1,"statement":"[Theorem 17 (KL local-error framework) of arXiv:2605.24937, '2605.24937'] Assume~\eqref{eq:one-step-w2-framework},~\eqref{eq:reg-framework}, and
\eqref{eq:crossreg-framework}, and let $L\in[\tfrac12,2]$. With
