{"assumptions":[],"created_at":"2026-10-28T02:16:53.596348+00:00","domain":"probability theory","id":"claim_1d24884f4811b322ed6880c5e90257959ab63d6931cb65a04f3cb6563c94f036","kind":"concept","schema_version":1,"statement":"[Theorem thm:Okura of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] \begin{enumerate}[(i)]
