{"assumptions":[],"created_at":"2026-10-26T19:47:01.669490+00:00","domain":"probability theory","id":"claim_1d903401d734a26123c23d3d4c86e784b22e489fe9062b11c1fb0240f31f0f80","kind":"definition","schema_version":1,"statement":"[Definition 4 of arXiv:2604.24390, 'Weak solutions to distribution-dependent stochastic Volterra equations'] A probability measure $P$ on $(C([0,T];\R^d),\mathcal{B}(C([0,T];\R^d)))$ is called \textup{solution to the distribution-dependent Volterra local martingale problem} given $(\mu_0,b,\sigma,K_b,K_\sigma)$ if
  \begin{enumerate}
    \item[(i)] $(Z_t)_{t\in[0,T]}$ is a $d$-dimensional semimartingale and $Z_0 \sim \mu_0$, 
    \item[(ii)]the process $(\mathcal{M}^f_t)_{t\in[0,T]}$, given by
    \begin{equation}
      \mathcal{M}^f_t:= f(Z_t)-\int_0^t \mathcal{A}^f(s,X_s,\L(X_s),Z_s)\dd s,\quad \mathcal{F}_t, \quad t\in [0,T],
    \end{equation}
    is a local martingale for every $f\in C_0^2(\R^d)$, where $\mathcal{A}^f$ is defined as in \eqref{eq:operator A},
    \begin{equation}
      X_t := Z_0 +\int_0^t K_b(s,t)\dd A_s + \int_0^tK_\sigma(s,t)\dd M_s, \quad t\in[0,T],
      \quad P\text{-a.s},
    \end{equation}
	$(A_t)_{t\in[0,T]}$ is predictable of bounded variation and $(M_t)_{t\in[0,T]}$ is a local martingale with $M_0=0$, such that $Z=A+M$. Here $\mathcal{F}_t = \mathcal{G}_{t+}$, and $\{\mathcal{G}_t\}$ is the augmentation under $P$ of the canonical filtration $\mathcal{B}_t := \sigma(Z_s\, :\, s\in [0,t])$. 
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:30.015370+00:00","domain":"probability theory","id":"claim_1d913492e5b582b869c2c92e87ec2624758ed00a41d1017b195ce642b72112de","kind":"theorem","schema_version":1,"statement":"[Thm 3 of arXiv:2605.05430, 'Dirichlet problems and exit distributions for the telegraph process and its planar extensi'] For $x\in[a,b]$, it holds that 
\begin{equation}u_0(x)=\frac{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}\end{equation}
and
\begin{equation}u_1(x)=\frac{\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}\end{equation}
Consequently,
\begin{equation}u(x)=\frac{1}{2}\;\frac{(\lambda_1c_0+\lambda_0c_1)\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)x}-2\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}{\lambda_0c_1\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)b}-\lambda_1c_0\,e^{\left(\frac{\lambda_0}{c_0}-\frac{\lambda_1}{c_1}\right)a}}\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:46:25.370098+00:00","domain":"probability theory","id":"claim_1d9987db77ad40d41a8dcf5d665870a789f47ecdc95876dadb6ee568464766f1","kind":"lemma","schema_version":1,"statement":"[Lemma Lem lim sum diff of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] The following convergence holds:
