{"assumptions":[],"created_at":"2026-10-27T08:12:13.460548+00:00","domain":"probability theory","id":"claim_1e4a5e16d165c1bc05d0eba18c9a663e268207e69d63e562d65dd1111d1dba40","kind":"concept","schema_version":1,"statement":"[Lemma 7 of arXiv:2608.28307, 'Rigidity of closed $\lambda$-self-expanders'] \cite{okumura1974hypersurfaces}
