{"assumptions":[],"created_at":"2026-10-27T17:18:19.437536+00:00","domain":"probability theory","id":"claim_1e689087fb5669c17523a148063c77b83f51a5664904cd183e948a43f8965218","kind":"definition","schema_version":1,"statement":"[Definition def:inhomo of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $W_N$ be an $N\times N$ real symmetric (or complex Hermitian) Wigner matrix, let $\Sigma_N$ be a deterministic variance-profile matrix and $A_N$ be a finite-rank perturbation.  Define
\begin{equation} 
H_N=\Sigma_N \circ W_N,  
\end{equation}
where “\(\circ\)” is the Hadamard (entrywise) product, and the corresponding deformed inhomogeneous random  matrix
\begin{equation}
    X_N=H_N+A_N.
\end{equation}
Here,  the following conditions are assumed: 

\begin{enumerate}[leftmargin=*,label=(A\arabic*)]
  \item  \textbf{(Wigner matrix)}  
    The entries $\{W_{ij}\}_{i\le j}$ are independent, symmetric, and satisfy
    \begin{equation}
      \begin{cases}
        \mathbb{E}[W_{ii}^2]=2,\;\mathbb{E}[W_{ij}^2]=1, & \text{real 
        case},\\
        \mathbb{E}[W_{ii}^2]=1,\;\mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex 
        case}.
      \end{cases}
    \end{equation}
    Moreover, there exists $\theta\ge 1$ such that for all $k\ge2$,
    \begin{equation}
      \mathbb{E}\bigl[|W_{ij}\bigr|^{2k}]
      \;\le\;
      \theta^{\,k-1}(2k-1)!!,
     \end{equation}
    where  $\theta:=\theta_N\rightarrow\infty$ may be  allowed   if needed. 
  \item  \textbf{(Variance profile)}  
    The profile matrix $\Sigma_N=(\sigma_{ij})$ has nonnegative entries such that 
    \(\sum_{j=1}^N\sigma_{ij}^2=1\) for each~$i$.  Equivalently, 
    $P_N:=(\sigma_{ij}^2)_{i,j=1}^N
    $ is a Markov transition matrix.

  \item  \textbf{(Finite-rank deformation)}  
    The perturbation $A_N$ is symmetric (resp.\ Hermitian) of rank $r$, with spectral decomposition
    \begin{equation}
        A_N = Q\,\Lambda\,Q^*, 
      \qquad
      \Lambda = \mathrm{diag}(a_1,\dots,a_r,0,\dots,0),
    \end{equation}

    where $Q$ is an orthogonal (resp.\  unitary) matrix.  
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.661790+00:00","domain":"probability theory","id":"claim_1e698b82f7679c031e8ac50123b03f58e650833fca2ae906d3d6b3546648d955","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2604.23610, 'Scaling limits of Lévy walks with random velocities'] Let $\left\{\left(V_i, T_i, \mathbf{J}_i\right)\right\}_{i\geq1}$ be the sequence of IID random vectors with components defined in Eq. \eqref{jumpdef}, then
    \begin{equation}
        U_V\left(t\right) = \sum_{i=1}^{N\left(t\right)} \mathbf{J}_i, \quad O_V\left(t\right) = \sum_{i=1}^{N\left(t\right)+1} \mathbf{J}_i, \quad W_V\left(t\right) = \sum_{i=1}^{N\left(t\right)} \mathbf{J}_i + \left(t - \sum_{i=1}^{N\left(t\right)}T_i\right)\mathbf{I}_{N\left(t\right)+1}V_{N\left(t\right)+1}
    \end{equation}
    are called wait-first L\'evy walk with random velocity, jump-first L\'evy walk with random velocity, and (continuous) L\'evy walk with random velocity, respectively. A similar model was introduced in the physics literature in \cite{Denisov2012Levy}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.284167+00:00","domain":"probability theory","id":"claim_1e6d69b01559ab5571d4fe76be2d1456ef009896b864d76bd345887e1329a3fd","kind":"theorem","schema_version":1,"statement":"[Theorem th:multidim of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] Let $\psi_1, \ldots, \psi_m$ be bounded Borel functions supported in a common compact
  interval $[r_0, r_1]$. Then
  \begin{equation}
    \left(
      \frac{\Phi_{\psi_1}(t) - \rho_1 t}{\sqrt{t}},
      \ldots,
      \frac{\Phi_{\psi_m}(t) - \rho_m t}{\sqrt{t}}
    \right)
    \xrightarrow{d}_{t \to \infty}
    \mathcal{N}(0, \Sigma),
  \end{equation}
  where the covariance matrix $\Sigma = (\Sigma_{ij})_{1 \leq i,j \leq m}$ is given by
  \begin{equation}
    \Sigma_{ij}
    = \frac{1}{\mathbb{E}[\eta_0]}
      \bigl(\operatorname{Cov}(Y_0^i, Y_0^j) + \operatorname{Cov}(Y_0^i, Y_1^j) + \operatorname{Cov}(Y_1^i, Y_0^j)\bigr).
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:53:10.203375+00:00","domain":"probability theory","id":"claim_1e6fda10343848b610b05f49e2b866d29719925c8bf87235c0e4f3bd7c99d657","kind":"concept","schema_version":1,"statement":"[Lemma LemExactKL of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] For any pair $0 < a < b < 1$, the one-step KL
divergence~(equation EqnDefnExactKL of the paper) has the exact representation
\begin{subequations}
  \begin{align}

\Gamma_{\scaleto{\operatorname{prod}}{5pt}}(a, b) & = \int_{\lambda(a)}^{\lambda(b)} \int_\eta^{\lambda(b)}
\ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\eta, \xi) \, d\xi \, d\eta \qquad \mbox{where $\lambda(r) =
  \log(r/(1-r))$.}
\end{align}
Moreover, assuming that $\ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}$ is continuous, we have the pointwise
expansion
\begin{align}

\Gamma_{\scaleto{\operatorname{prod}}{5pt}}(a, b) & = \frac{1}{2} \ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\lambda(a), \lambda(a)) \; \Delta^2 +
o(\Delta^2) \qquad \mbox{ where $\Delta \coloneqq \lambda(b) - \lambda(a)$.}
\end{align}
Finally, we have the equivalence
\begin{align}

\mathsf{q}(\lambda) & = \ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\lambda, \lambda) \qquad \mbox{for all $\lambda \in
  \real$.}
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.679254+00:00","domain":"probability theory","id":"claim_1e7310c214d8c8cf041dcd2baa6f441d51fe335244e555fbf30fd446a90a1f83","kind":"definition","schema_version":1,"statement":"[Defn d.moment-function of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \ 
We say that $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat{\mathcal{N}}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ satisfies a $p$-moment condition with respect to $\tilde{\mathcal{P}}$ 
 on {\em  finite windows}
 if $\xi( \tilde{x}_i, \tilde{\mathcal{P}}_n )$
satisfy  the $p$-moment condition~(equation e:xinpmom of the paper), that is to say

\begin{equation}

\sup_{1 \leq n< \infty} \sup_{1 \leq q \leq p} \sup_{x_1,\ldots,
  x_{q} \in W_n} \mathbb {E} _{\bk x1{q}}[ \max(1,|\xi(\tilde{x}_1, \tilde{\mathcal{P}}_n )|^p)]
\leq M_p^{\xi} < \infty.
