		\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:17:17.102842+00:00","domain":"probability theory","id":"claim_1ed586650bb4b025b3fa1be6c792b43958d03daa1b65cd5848fb14c482e86d89","kind":"lemma","schema_version":1,"statement":"[Lemma 18 (The two outer blocks) of arXiv:2608.20101, '\bfseries Largest bulk gap of the complex Ginibre ensemble'] Uniformly for \(t\in I\),
\begin{equation}
 S_>=O_I(e^{-c_I N}).
\end{equation}
Moreover,
\begin{equation}
 S_<=F_1N^2+F_2N\log N+F_3N+F_5\log N+F_6
       +O_I\!\left(\frac{\log N}{N}\right),
\end{equation}
where
\begin{align*}
 F_1={}&-\frac{t^4}{4(1+\epsilon)^2}
       \bigl(1+4\epsilon-2\log(1+\epsilon)\bigr), \qquad  F_2=-\frac{t^2}{2(1+\epsilon)},\\
 F_3={}&\frac{t^2}{1+\epsilon}\left[
 (1-\vartheta)\epsilon+1-\log(t\sqrt{2\pi})
 +\epsilon\log\frac{\epsilon}{1+\epsilon}
 +(\vartheta-1)\log(1+\epsilon)\right],\\
 F_5={}&\frac7{12}-\frac{\vartheta}{2},\\
 F_6={}&\frac{-1+6\vartheta^2}{12}\log(1+\epsilon)-\frac1\epsilon
 +\frac{1-2\vartheta}{2}\log\epsilon+\frac76\log t
