{"assumptions":[],"created_at":"2026-10-28T00:59:45.465203+00:00","domain":"probability theory","id":"claim_21002982a64b2a1f164adacbb80ca3570d7de5c221970f445bef4577aa457982","kind":"theorem","schema_version":1,"statement":"[Proposition prop:aveflowim of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small $n$--independent constants $\tau,\omega_*,\epsilon>0$, and for $i=1,2$ fix spectral parameters $\Lambda_{i,0}$ as in (equation eq:defincond of the paper), with $|z_{i,0}|\le 10$, $|\eta_{i,0}|\le \omega_*$. For $t\le T^*$ let $\Lambda_{i,t}$ be the solution of (equation eq:charflowmat of the paper) with initial condition $\Lambda_{i,0}$. Let $G_{i,t}:=(W_t-\Lambda_{i,t})^{-1}$, and let $\widehat{M}_{12,t}^A$ be the deterministic approximation of $\mathrm{Im}\, G_{1,t}A\mathrm{Im}\, G_{2,t}$ from (equation avlaw12_im of the paper). Let $\ell$ from (equation eq:defcontrolparam of the paper), and define the control parameter
	\begin{equation}

		\widehat{\gamma}=\widehat{\gamma}(\eta_1,z_1,\eta_2,z_2):=|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2, \qquad\quad \widehat{\gamma}_t:=\widehat{\gamma}(\eta_{1,t},z_{1,t},\eta_{2,t},z_{2,t}).
	\end{equation}
	Assume that for some small $0<\xi\le \epsilon/10$, with very high probability, it holds
	\begin{equation}
		\big|\big\langle\big(\mathrm{Im}\, G_{1,0}A_1\mathrm{Im}\, G_{2,0}-\widehat{M}_{12,0}^{A_1}\big)A_2\big\rangle\big|\le \frac{n^\xi\rho_{1,0}\rho_{2,0}}{\sqrt{n\ell_0}\widehat{\gamma}_0}\wedge \frac{n^\xi}{n|\eta_{1,0}\eta_{2,0}|}
	\end{equation}
	uniformly in $\lVert A_i\rVert\le 1$ and for any $|\eta_i|\in [|\eta_{i,0}|,n^{100}]$. Then,
	\begin{equation}
		\big|\langle (\mathrm{Im}\, G_{1,t}A_1\mathrm{Im}\, G_{2,t}-\widehat{M}_{12,t}^{A_1})A_2\rangle\big|\le \frac{n^{2\xi}\rho_{1,t}\rho_{2,t}}{\sqrt{n\ell_t}\widehat{\gamma}_t}\wedge \frac{n^{2\xi}}{n|\eta_{1,t}\eta_{2,t}|},
	\end{equation}
	with very high probability uniformly in $\lVert A_i\rVert\le 1$ and all $t\le T^*$ such that $n\ell_t\ge n^\epsilon$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:32:11.152251+00:00","domain":"probability theory","id":"claim_2102d1491db2ae179d0f2b832cf8d296bacdaed898e5897774b16a0f07004d7c","kind":"lemma","schema_version":1,"statement":"[Lemma lem-2moment of arXiv:2510.13733, 'Internal Diffusion Limited Aggregation \\ with Critical Branching Random Walks'] Assume $d \geq 3 $.
