{"assumptions":[],"created_at":"2026-10-27T10:02:28.606984+00:00","domain":"probability theory","id":"claim_218a318198f3cb6e37e166b4123453e106a5fb9c701e0c0f6616ec16b99698d7","kind":"theorem","schema_version":1,"statement":"[Prop 14 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $S$ be a finite set of places of $F$ containing all the archimedean and ramified places of $F$ such that $\phi\in\mathcal{S}([\bar{G}_n])$ is right invariant by $K_{n,v}$ for each $v\notin S$. Moreover, we choose a $\Phi\in\mathcal{S}(\A^n)$ such that $\Phi_v=\mathbbm{1}_{\o_v^n}$ for all $v\notin S$, as in \S\ref{sec:unramified-local-choice}. Then, for sufficiently large $\Re(s)$ we have
		\begin{multline*}
			I_2^{\mathrm{D}}(s)=\V\sum_{\pi\in\Pi_{\mathrm{c}}(\bar{G}_2)}\sum_{\varphi\in\B\left(\1_{n-2}\boxplus\pi\right)}\left\langle\phi,\Eis(\varphi, \ol{\lambda_{\mathrm{D}}(s)})\right\rangle_{[G_n]^1 }\\
			\frac{L^S\left(\tfrac{n-1}{2}+\tfrac{n}{2}s,\pi\right)L^S\left(\tfrac{1}{2}+\tfrac{n}{2}s,\pi\right)}{\sqrt{L^S(1,\pi,\Ad)}}
			\optionA{\P_S(-\lambda_{\mathrm{D}}(s);\varphi,f,f_s)}
			\optionB{\P_S(s,-\lambda_{\mathrm{D}}(s);\varphi,\Phi)},
		\end{multline*}
		and
		\begin{multline*}
			I_2^{\mathrm{C}}(s)=\frac{\V}{2}\sum_{\chi\in\Pi(G_1)}\sum_{\varphi\in\B(\1_{n-2}\boxplus\chi\boxplus\chi^{-1})}\intop_{i\mathbb{R}}\left\langle \phi,\Eis(\varphi,\overline{\lambda_{\mathrm{C}}(s,z)})\right\rangle_{[G_n]^1 }\\
			\frac{\prod_{\pm}L^S\left(\tfrac{n-1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm\right)L^S\left(\tfrac{1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm\right)}{L^S(1+2z,\chi^2)}
			\optionA{\P_S(-\lambda_{\mathrm{C}}(s,z);\varphi,f,f_s)}
			\optionB{\P_S(s,-\lambda_{\mathrm{C}}(s,z);\varphi,\Phi)}
			\, dz,
		\end{multline*}
		where $I_2^{\mathrm{D}}$ and $I_2^{\mathrm{C}}$ are as in \eqref{eq:def-I2-disc} and \eqref{eq:def-I2-cont}, respectively;
		and $\P_S:=\prod_{v\in S}\P_v$ where $\P_v$ is as in \eqref{eq:main-RS-period-local}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:58:40.872787+00:00","domain":"probability theory","id":"claim_218c018364c1023022efdc22d88c527f90b1bf0f125f980ee5525e96d34a4406","kind":"definition","schema_version":1,"statement":"[Definition def:Moran-Model of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] Fix $a, \varphi_N\geq 0$ and let $X^N=(X_0^N(t),X_1^N(t) , t \geq 0)$ be the counting process of the resident and mutant in the Moran model, that is we have $X_0^N(t)+ X_1^N(t)=N$, $\forall t \geq 0$ and with transition rates from $(k,N-k)$ given by
\begin{align}\begin{split}
    (k, N-k) \to (k+1,N-k-1) &\quad \text{ at rate } \quad  \phantom{(1+a\varphi_N)}\frac{k(N-k)}N\\
    (k, N-k) \to (k-1,N-k+1) &\quad \text{ at rate } \quad  (1+a \varphi_N)\frac{k(N-k)}N.
    \end{split}
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:02:08.142907+00:00","domain":"probability theory","id":"claim_218c46eb0b9ad532a7964d51802e7c60e27bd9217340c712b1d13068dc214759","kind":"definition","schema_version":1,"statement":"[Definition 8 (Liouville field with boundary insertions on $\bH$) of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] In the setting above, sample $(h, \bfc)$ from the infinite measure
    \begin{equation}
        C_{\bH}^{(\beta_i, s_i)_{i=1}^m}
        \bP_{\bH}
        \times \ab[ e^{(\frac{1}{2}\sum_{i=1}^m\beta_i-Q)c}\Leb_{\bR}(\d c)],
    \end{equation}
    where
    \begin{equation}
        C_{\bH}^{(\beta_i, s_i)_{i=1}^m} = 
        \begin{cases}
        \prod_{i=1}^m \ab|s_i|_+^{-\beta_i(Q-\frac{\beta_i}{2})} \exp\ab(\frac{1}{4}\sum_{j=i+1}^m \beta_i\beta_j G_{\bH}(s_i, s_j)) \text{ if } s_1\neq \infty\\
        \prod_{i=2}^m \ab|s_i|_+^{-\beta_i(Q-\frac{\beta_i}{2}-\frac{\beta_1}{2})} \exp\ab(\frac{1}{4}\sum_{j=i+1}^m \beta_i\beta_j G_{\bH}(s_i, s_j)) \text{ if } s_1= \infty
        \end{cases},
    \end{equation}
    and take
    \begin{equation}

        \phi(z) = h(z)-2Q\log\ab|z|_+ +\frac{1}{2}\sum_{i=1}^m \beta_i G_{\bH}(s_i, z)+\bfc.
    \end{equation}
    We write $\LF_{\bH}^{(\beta_i, s_i)_{i=1}^m}$ for the law of $\phi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.632050+00:00","domain":"probability theory","id":"claim_218e487c5241015b5a07eab24bfdde91af0b8fa1a02820826672199ac7ffe029","kind":"lemma","schema_version":1,"statement":"[Lemma sparse of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] Let $n \ge 3$, $z \ge 0$, and $t=\sqrt{3e}$.
