{"assumptions":[],"created_at":"2026-10-27T05:53:54.877407+00:00","domain":"probability theory","id":"claim_21d380c87235686b3766eb1d6348bb867261939fe6a423b9900c615098deb791","kind":"theorem","schema_version":1,"statement":"[Proposition 15 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] If $|u|<\alpha$, $v>-\alpha$ and $\alpha-u+2t_j>0$, $j=1,\dots N-1$, and $\alpha+v+2t_N>0$, then
\begin{multline}
     \GG_{t_1,\dots,t_N}(\alpha,u,v)
     =\Gamma(\alpha+v+2t_N) \Gamma(\alpha+u)^N \\ \cdot  \Biggl(\prod_{k=1}^{N-1}\Gamma(\alpha-u+2t_k)\Biggr)\, \EE [(1+\zeta_1+\zeta_1\zeta_2+\dots+\zeta_1\dots \zeta_{N-1})^{-u-v}]
     \end{multline}
with independent $\zeta_k\simeq \mathrm{Beta}_{II}(\alpha+u,\alpha-u+2t_{N-k})$, $k=1,\dots,N-1$.

    If $|v|<\alpha$, $u>-\alpha$ and $\alpha+v+2t_j>0$, $j=1,\dots,N$,  then
   \begin{multline}
     \GG_{t_1,\dots,t_N}(\alpha,u,v)
     =\Gamma(\alpha+u) \Gamma(\alpha-v)^{N-1} \\ \cdot   \Biggl(\prod_{k=1}^N \Gamma(\alpha+v+2t_k)\Biggr)\, \EE [(1+\xi_1+\xi_1\xi_2+\dots+\xi_1\dots\xi_{N-1})^{-u-v}]
     \end{multline}
with independent $\xi_k\simeq \mathrm{Beta}_{II}(\alpha+v+2 t_k,\alpha-v)$, $k=1,\dots,N-1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:13:18.537921+00:00","domain":"probability theory","id":"claim_21d3ad9e9e030e0ce4eadbd19089634332802fc9c110e3fbe7e6ef152e0dd2cd","kind":"concept","schema_version":1,"statement":"[Proposition 26 (Potter's bound, \protect{\autocite[Theorem 1.5.6) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] {BinghamGoldieTeugels1987RegularVariation}}]

