        \int \Bigg\| \BE_{0,y}^{\Phi}&\bigg[\int x^{\otimes q}\, K^\ast(y,dx)\times \overline{\int x^{\otimes q}\, K^\ast(0,dx)}\bigg] \nonumber\\
        &- \BE_0^{\Phi}\bigg[\int x^{\otimes q}\, K^\ast(0,dx)\bigg]\times \overline{\BE_0^{\Phi}\bigg[\int x^{\otimes q}\, K^\ast(0,dx)\bigg]} \Bigg\| \|y\|^{p-2q} \, \alpha_{\Phi}(dy) < \infty
