{"assumptions":[],"created_at":"2026-10-27T22:52:32.333925+00:00","domain":"probability theory","id":"claim_23b4743b7ed4ce86b4b24d19966f20052cd9acbe279639941371d5beeda9487c","kind":"concept","schema_version":1,"statement":"[Theorem thm:abstractresolventbounds of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] Let $(T(t))_{t\geq 0}$ be a bounded semigroup with generator $A$ on a Hilbert space $H$  such that $\sigma(A)\cap i\mathbb{R} = \varnothing.$
\begin{enumerate}
    \item \textnormal{(Batty, Duyckaerts, Burq, Lebeau)}
    The semigroup $T$ possesses logarithmic decay with rate $1/d,d>0$, i.e., 
    \begin{align}
        \forall k \in \mathbb{N} ~ \exists C_k>0: ~ \|T(t)x\|_{H} \leq \frac{C_k}{\log(t+2)^{\frac{k}{d}}} \|x\|_{A^k} ~~ \forall t\geq0,  x\in \operatorname{dom}\left(A^k\right),
    \end{align}
    if and only if the generator $A$ has exponential resolvent bounds with power $d>0$, i.e., there exists $C>0$ such that
    \begin{align}

        \|(\lambda i +A)^{-1} \|_{H \to H} \leq C \exp{(C|\lambda|^d)} ~~\forall \lambda\in \mathbb{R}, |\lambda|\gg1.
    \end{align}
    \item   \textnormal{(Borichev, Tomilov)}
    The semigroup $T$ possesses polynomial decay with rate $1/d,$  $d>0$, i.e., 
    \begin{align}
        \forall k \in \mathbb{N} ~ \exists C_k>0: ~ \|T(t)x\|_{H} \leq \frac{C_k}{(1+t)^{\frac{k}{d}}} \|x\|_{A^k} ~~ \forall t\geq0,  x\in \operatorname{dom}\left(A^k\right),
    \end{align}
    if and only if the generator $A$ has polynomial resolvent bounds with power $d>0$, i.e., there exists $C>0$ such that
    \begin{align}

        \|(\lambda i +A)^{-1} \|_{H \to H} \leq C |\lambda|^d ~~\forall \lambda\in \mathbb{R}, |\lambda|\gg 1.
    \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:53.439406+00:00","domain":"probability theory","id":"claim_23b62e671a8f3200807c31ba4153eda9b5993c4de3bf2457b256a1fbe116cce7","kind":"concept","schema_version":1,"statement":"[Theorem 1 (Local existence of mild solutions) of arXiv:2606.15425, 'Well-posedness of stochastic parabolic equations with gradient nonlinearities and applicat'] Let $d \geq 2$, $q \in (d,2d)$, $\delta \in \left(\frac dq, 1\right)$ and $\sigma >\delta-\frac dq$. Assume that $F$ and $G$ satisfy Assumptions \ref{ass:DriftNonlin} and \ref{ass:nemytskiiLipschitz}. Then, for any $p \in \left[\frac{q}{\delta q-d},\infty\right)$ and $\mathcal F_0$-measurable ${\bm z}_0 \in L^0(\Omega;B^{d/q}_{q,2p}(\mathbb T^d))$, there exists a unique maximal local solution $({\bm z},\tau)$ of \eqref{eq:FullNoiseSPDE} in the sense of Definition \ref{def:localsol}, with
\begin{enumerate}
