{"assumptions":[],"created_at":"2026-10-27T14:05:52.396496+00:00","domain":"probability theory","id":"claim_23ffc4ce27644d4fb248cb346f20204738d71dc71281108d975f74846e9effd8","kind":"concept","schema_version":1,"statement":"[Corollary theorem1.7 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $A_n$ be a random symmetric matrix with entry distribution $\zeta$ of mean 0, variance 1 and having a subgaussian tail. Fix any $\kappa>0$ and $\Delta>0$. 

We say that two eigenvalues $x_1,x_2$ of $A$ are \textit{distant} if $|x_1-x_2|\geq\Delta n^{1/2}$. Let $I_\kappa:=[-(2-\kappa)\sqrt{n},(2-\kappa)\sqrt{n}]$. Suppose moreover that $\zeta$ has a finite log-Sobolev constant. Then for any ($n$-dependent) constants $a_1,a_2,D\in\mathbb{R}$ with $a_1=1,a_2=O(1)$, the following estimate holds for any $\epsilon\geq 0$:
 \begin{equation} \begin{aligned}   &\mathbb{P}(A_n \text{ has } \text{ two \textit{distant} eigenvalues } x_1,x_2\in I_\kappa \text{ satisfying } |\sum_{i=1}^2a_ix_i-D|\leq \epsilon n^{-3/2})\\&\leq C \epsilon+2e^{-cn}.\end{aligned}\end{equation}
 More generally, for any $\sigma\in(0,1)$, we say that two eigenvalues $x_1,x_2$ of $A$ are $\sigma$-\textit{distant} if $|x_1-x_2|\geq \Delta n^{\sigma-\frac{1}{2}}$. Then for $a_1=1,a_2=O(1)$ and $D\in\mathbb{R}$, we have for any $\epsilon>0$:
  \begin{equation} \begin{aligned}   &\mathbb{P}(A_n \text{ has two } 
  \sigma-\text{distant eigenvalues } x_1,x_2\in I_\kappa \text{ satisfying } |\sum_{i=1}^2a_ix_i-D|\leq \epsilon n^{-3/2})\\&\leq C\epsilon+e^{-cn^{\sigma/2}},\end{aligned}\end{equation}
  where the constants $C,c>0$ depend on $\zeta,\Delta,\kappa,\sigma$ and $|a_2|$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.753872+00:00","domain":"probability theory","id":"claim_2400e1f1dfca8df87ca1a59713fb3718b743bb2aeb51f961c31b32ada9207c33","kind":"theorem","schema_version":1,"statement":"[Prop PropHPcharpolySDE of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] For any $N\in\mathbb{N}$ and $\mathfrak{s}\in\mathbb{C}$,
    $\mathfrak{hp}_{t;N}(z)$ satisfies the following equation
\begin{align}
\mathrm{d}\mathfrak{hp}_{t;N}(z)
    =
\mathrm{d}\mathsf{M}^N_t(z;\mathfrak{hp})
       +\mathfrak{B}^{(N)}_z\mathfrak{hp}_{t;N}(z)\mathrm{d}t,
\end{align}
with the linear operator $\mathfrak{B}^{(N)}_z$ acting on $f\in \mathsf{H}(\mathbb{C})$ as follows
\begin{align}
\mathfrak{B}^{(N)}_zf(z)&=-z^2\partial_z^2f(z)-2z\Re(\mathfrak{s})\partial_zf(z)-2z\Im(\mathfrak{s})f(z)-z^2f(z)\nonumber\\&+\frac{1}{N}\left[-z^2f(z)+\left(2z^2\Im(\mathfrak{s})+2z^3-\frac{2z^3}{N}\right)\partial_zf(z)-\frac{1}{N}\partial_z^2f(z)\right].
\end{align}
and moreover where $\mathsf{M}^N\in \mathrm{C}(\mathbb{R}_+;\mathsf{H}(\mathbb{C}))$ and for all $z\in \mathbb{C}$, $t\mapsto \mathsf{M}_t^N(z;\mathfrak{hp})$ are continuous local martingales with covariation, for $z,w \in \mathbb{C}$,
\begin{align}
\langle \mathsf{M}_t^N(z;\mathfrak{hp}),\mathsf{M}_t^N(w;\mathfrak{hp})\rangle=\frac{2zw}{z-w}\int_0^t\left(\mathfrak{hp}_{s;N}(z)\partial_w\mathfrak{hp}_{s;N}(w)-\mathfrak{hp}_{s;N}(w)\partial_z\mathfrak{hp}_{s;N}(z)+\mathsf{E}_{s;N}(z,w)\right)\mathrm{d}s,
\end{align}
and the term $\mathsf{E}_{s;N}(z,w)$, with $s\ge 0$, $z,w\in \mathbb{C}$, is given by,
\begin{equation}
