    1,&\rho=0,\\
    +\infty,&\rho>0.
  \end{cases}
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:41:03.322703+00:00","domain":"probability theory","id":"claim_2431348a2248db816570ade3869bd4ca98ba02849c3b93470b4f2532f3519d87","kind":"lemma","schema_version":1,"statement":"[Lemma le:B1cpart of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For  any $0<\kappa<\frac{d-2}{2}$, we have
