{"assumptions":[],"created_at":"2026-10-26T19:29:52.230521+00:00","domain":"probability theory","id":"claim_2441b79a61803d8580ee27b82e61f583a3a893a0d5d0374a031b2070ccb405d4","kind":"lemma","schema_version":1,"statement":"[Lemma 35 (Asymptotic inequalities for $h_\alpha, f_0, f_\pi$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $\alpha, \beta \in \mathcal M$ with $\alpha \neq \beta$. Then: \begin{itemize}
    \item Suppose that $\beta\in\mathcal M \cap (0, \pi)$. Then there exist $\e > 0$, $\eta > 0$, $r_0 > 0$, and $C > 0$ such that for all $\gamma \in \mathcal M \cap (\beta - \e, \beta + \e)$ and all $r \geq r_0$,
    \begin{equation}
        h_\gamma(r\cos(\beta), r\sin(\beta)) \geq C^{-1}e^{r(x(\beta)\cos(\alpha) + y(\beta)\sin(\beta) - \eta)} 
    \end{equation}
    and such that for all $r\geq r_0$,
    \begin{equation}
        h_\alpha(r\cos(\beta), r\sin(\beta)) \leq Ce^{r(x(\beta)\cos(\alpha) + y(\beta)\sin(\beta) - 2\eta)}.
    \end{equation}
    \item Suppose that $\beta \in \mathcal M \cap (\pi, 2\pi)$. Then there exist $\e > 0$, $\eta > 0$, $r_0 > 0$, and $C > 0$ such that for all $\gamma \in \mathcal M \cap (\beta - \e, \beta + \e)$ and all $r \geq r_0$,
    \begin{equation}
        h_\gamma(r\cos(\beta), r\sin(\beta)) \geq C^{-1}e^{r(x(\beta)\cos(\alpha) + z(\beta)\sin(\beta) - \eta)} 
    \end{equation}
    and such that for all $r\geq r_0$
    \begin{equation}
        h_\alpha(r\cos(\beta), r\sin(\beta)) \leq Ce^{r(x(\beta)\cos(\alpha) + z(\beta)\sin(\beta) - 2\eta)}.
    \end{equation}
\end{itemize}
Inequalities \eqref{ineq:halpha1} and \eqref{ineq:halpha2} also hold if $\alpha$ is replaced by $0$ (resp. $\pi$) and $h_\alpha$ by $f_0$ (resp. $f_\pi$).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:40.975667+00:00","domain":"probability theory","id":"claim_2445e5e79680da42bb4d548a5f527ad8d3fc7e64e38bc5ab01860816ac4ec9ac","kind":"theorem","schema_version":1,"statement":"[Theorem prop_4 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $m\geq1$ be an integer, $0<b<1$, $\|A\|_{m+1}$ be Schatten norm of order $m+1$ for a symmetric matrix $A$ and $r(A)$ be the rank of $A$. Then  
 \begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{\Lambda_m(t, b)},
\end{eqnarray} 
 where\footnote{The function $\Lambda(t,a)$ in ((en_exp of the paper)) and the functions $\Lambda_m(t,b)$ in ((Lambda_m of the paper)) are not related. }
 \begin{eqnarray}

\Lambda_m(t, b)=\frac{r(A)}{2}\sum_{k=2}^m \frac{b^k}{k}-\kappa_m(b)\min\bigg\{\frac{t^{1+\frac{1}{m}}}{\|A\|_{m+1}^{1+\frac{1}{m}}}, \frac{t}{\|A\|} \bigg\} 
\end{eqnarray}
and 
\begin{eqnarray}

\kappa_m(b)=\frac{m}{2(m+1)}\min\bigg\{\frac{1}{\big((m+1)\theta_m(b)\big)^{\frac{1}{m}}}, b\bigg\}
\end{eqnarray}
with $\theta_m(b)$ as defined in ((theta_func of the paper)).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.829829+00:00","domain":"probability theory","id":"claim_2449ecb41d08379df8189f8893c012df6fdf41cd6e2c9fa0033c0c6f37e24e92","kind":"theorem","schema_version":1,"statement":"[Proposition 2 of arXiv:2608.13358, 'Extreme points of sets of probability measures and $\phi$-divergences'] For an element $p \in \cM$, the following statements are equivalent.
