		where $\mathbf{W}_m(F,j)$ is an anti-symmetric vector field on $\overrightarrow{E_d}({\scaleobj{1}{\square}}_m)$
		\begin{align}

			\mathbf{W}_m(F,j) &= \sum_{e\in E_d({\scaleobj{1}{\square}}_m) \setminus F}({\mathbf{a}}^{e}-\mathbf{a})\Big(\nabla V_m(F,j-1) - \nabla V_m(F\cup \{e\}, j-2) \\
