{"assumptions":[],"created_at":"2026-10-28T00:48:45.307573+00:00","domain":"probability theory","id":"claim_248fffbd2a7dd5f3527b1e49bba2bd5e4752a4c6fdcac8dbb4df0de426e22222","kind":"theorem","schema_version":1,"statement":"[Proposition prop:dec of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] For any $\mathbf{q} \in \mathcal{Q}$, $k \in {\mathbb{N}}$, $i \in {\mathbb{Z}}$ and $n \in {\mathbb{Z}}_{\ge 0}$, we have 
                \begin{align}
                    {\mathbb{E}}_{\nu_{\mathbf{q}}}\left[  \Delta Y^{{i}}_{k, \ell}\left( \mathbf{q}, n\right) \right] = 0,
                \end{align}
            and
                \begin{align}
                    &{\mathbb{E}}_{\nu_{\mathbf{q}}}\left[  \Delta Y^{{i}}_{k, \ell}\left( \mathbf{q}, n\right) \Delta Y^{{i}}_{k, \ell'}\left( \mathbf{q}, n\right)  \right] \\ 
                    &= \begin{dcases}
                        {\mathbb{E}}_{\nu_{\theta^{\ell}\mathbf{q}}}\left[Y^{{i}}_{k-\ell}\left(n\right)\right]  \beta_{\ell}\left(\mathbf{q}\right) \ & \ \ell = \ell', \\
                        0 \ & \ \ell \neq \ell'.
                    \end{dcases}
                \end{align}
            In addition, for any $1 \le \ell \le k - 1$, we have 
                \begin{align}
                    {\mathbb{E}}_{\nu_{\mathbf{q}}}\left[  \Delta Y^{{i}}_{k, \ell}\left( \mathbf{q}, n\right) M^{{i}}_{k}\left(n\right) \right] = 0.
                \end{align}
            By combining the above, we have 
                \begin{align}
                    &{\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ \left| Y^{{i}}_{k}\left(n\right) - {\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ Y^{{i}}_{k}\left( n\right) \right] \right|^2 \right] \\
                    &= \frac{v^{\mathrm{eff}}_{k}\left(\mathbf{q}\right)^2}{v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right)^2}  {\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ \left| M^{{i}}_{k}\left(n\right) - {\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ M^{{i}}_{k}\left(n\right)  \right] \right|^2 \right] \\
                    & \ + 4 \sum_{\ell = 1}^{k - 1} \frac{v^{\mathrm{eff}}_{\ell}\left(\mathbf{q}\right)^2 {\mathbb{E}}_{\nu_{\theta^{\ell}\mathbf{q}}}\left[Y^{{i}}_{k-\ell}\left(n\right)\right] \beta_{\ell}\left(\mathbf{q}\right)}{v^{\mathrm{eff}}_{1}\left(\theta^{\ell-1}\mathbf{q}\right)^2}.
                \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:33:43.750490+00:00","domain":"probability theory","id":"claim_24964be5cf1231abdfeedabbce26ae6ddd3082f806d35f283e7861ab80dfbdd4","kind":"concept","schema_version":1,"statement":"[Theorem eq:anis_length of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] For any $\nu>0$, the norm defined by (equation eq:anis_holder_gen of the paper) is equivalent to the H\"older-Zygmund norm induced by $|\cdot|_B$. In particular, for any $n\in{\mathbb {N}}_0$ and $\alpha\in(0,1)$, we have
\begin{align}
\| f \|_{B,n+\alpha} & \asymp \sum_{\substack{\eta\in {\mathbb {N}}^d_0\\  |\eta  |_{B} \leq n}} \| \partial^\eta f \|_{\infty} +\sum_{\substack{\eta\in {\mathbb {N}}_0^d\\  |\eta|_B = n  }}  \sup_{x,y\in \mathbb{R}^d} \frac{|\partial^{\eta} f(x) - \partial^{\eta} f(y)|}{|x - y|^{\alpha}_B} 
\\
&\quad +\sum_{i=1}^{\mathfrak{r} }\sum_{\substack{\eta\in {\mathbb {N}}_0^d\\ k\in\{0,1\} \\  |\eta|_B = n - (2 i - k) }}  \sup_{x,y\in \mathbb{R}^d} \frac{|\partial^{\eta} f(x) - \partial^{\eta} f(x^0 ,\, \dots \,, x^{i-1}, y^{i}, \, \dots \, ,  y^{\mathfrak{r}})|}{|x - (x^0 ,\, \dots \,, x^{h-1}, y^{h}, \, \dots \, ,  y^{\mathfrak{r}})|^{\alpha + 2i - k}_B},
\end{align}
where $|\eta|_B$ is the \emph{anisotropic length} of $\eta = (\eta^0, \dots, \eta^{\mathfrak{r}}) \in {\mathbb {N}}^d_0$, defined as
\begin{equation}
|\eta|_B := \sum_{i=0}^{\mathfrak{r}} (2i + 1) |\eta^{i}|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:01:56.358301+00:00","domain":"probability theory","id":"claim_24996ec48580db55af9a0734fc45c90ffc25f1db2822e215bfa4bd5cc97cc966","kind":"lemma","schema_version":1,"statement":"[Lemma lem:isometric-conjugacy of arXiv:2609.00794, 'On operators whose adjoints or second adjoints attain their norms'] Let $X$ and $Y$ be Banach spaces, and let
