\end{align}
\noindent We say that a characteristic $\varphi: \Omega \times \mathbb{R} \rightarrow \mathbb{R}$ is an {\sl $h$-dependent descendant characteristic}, for $h \in \mathbb{N}_{0}$, if the map $(\omega, t) \mapsto \varphi(\omega, t)$ is measurable with respect the product $\sigma$-algebra $\mathcal{B}(\mathbb{R})\times \mathcal{A}^{(h)}$, where $\mathcal{B}(\mathbb{R})$ is the Borel $\sigma$-algebra.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.734641+00:00","domain":"probability theory","id":"claim_24d31758a85c92630130217318196bc607c4e5e7cabe4810c8131c594561bc18","kind":"concept","schema_version":1,"statement":"[Prop 3 (Remark 3.4 in \cite{Geiss:Ylinen:21}) of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Assume that 
        \begin{itemize}
