{"assumptions":[],"created_at":"2026-10-27T13:52:23.571342+00:00","domain":"probability theory","id":"claim_25cddbb1a0ad3788d5f45bdd701c92f818f0f1ea26c3c9fd312510cd3db28978","kind":"concept","schema_version":1,"statement":"[Lemma L:Delta_t of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] For any $t > 0$ and $\lambda > 0$, let
  \begin{align}
    \Delta_t(\lambda) \coloneqq \int_\mathbb{R} \ensuremath{\mathrm{d} } \tau \, |\tau|^{1-2H} \left| \int_0^t \ensuremath{\mathrm{d} } s \, e^{i\tau s} s^{\beta+\gamma-1} E_{\beta, \beta+\gamma}\left(-2^{-1}\nu\lambda s^\beta\right) \right|^2.
  \end{align}
  For all $0 < S < T < \infty$, the following statements hold:
  \begin{enumerate}[\rm (i)]

    \item If $(\beta, \gamma) \in (0, 2] \times [0, \infty)$, then there exists
          a positive finite constant $C_{S, T}$ such that
          \begin{align}
            \Delta_t(\lambda) \ge C_{S, T} \frac{\lambda^{2(1-H)/\beta}}{1+\lambda^{2(\beta+\gamma)/\beta}}
            \quad \text{for all } t \in [S, T] \text{ and } \lambda > 0.
          \end{align}

    \item If $(\beta, \gamma) \in (0, 2) \times (0, \infty)$ or $(\beta, \gamma)
            \in \{2\} \times [1, \infty)$, then there exists a positive finite
          constant $\widetilde{C}_{S, T}$ such that
          \begin{align}
            \Delta_t(\lambda) \ge \widetilde{C}_{S, T} \max\left\{ \frac{\lambda^{2(1-H)/\beta}}{1+\lambda^{2(\beta+\gamma)/\beta}}, \frac{1}{1+\lambda^2} \right\}
            \quad \text{for all } t \in [S, T] \text{ and } \lambda > 0.
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:04:59.431953+00:00","domain":"probability theory","id":"claim_25d0b46b60b68badfb2215c0644a2a5023c9928135f9ae48a005ebe1e7b207f1","kind":"theorem","schema_version":1,"statement":"[Corollary stopping_quantile_continuity_C of arXiv:2605.20471, 'Note on the Weak Convergence of Hyperplane $α$-Quantile Functionals and Their Continuity i'] Let $\alpha \in (0,1),T>0,\gamma \in \mathbb{R}^d$. Suppose that $x \in C_{\mathbb{R}^d}[0,\infty)$; then we have
