{"assumptions":[],"created_at":"2026-10-27T21:30:14.225782+00:00","domain":"probability theory","id":"claim_2687ae0ded75041a8875fb14fdda56be447a197d4963d1a8d2fc41f13896b8c8","kind":"concept","schema_version":1,"statement":"[Thm cumulants of arXiv:2608.23156, 'Disc counting statistics of the real Ginibre ensemble'] Let $N$ be a positive even integer and let $R\equiv R_N$ be a positive real number.
    For fixed nonnegative integers $j$ and $k$ satisfying $j+k\ge2$, let $\varkappa_k^{\rm r}$ and $\varkappa_k$ be as in (equation def of varkappa real of the paper) and (equation def of varkappa total of the paper). Then the following asymptotic formulas hold.
    \begin{enumerate}[label=\textup{(\roman*)}]
        \item \textup{\textbf{(Bulk)}} Suppose that $R\in(0,1)$ is fixed. Then 
        \begin{align}
            \lim_{N\to\infty} \frac{\kappa_{j,k}(\mathcal{N}_{N}^{ \rm r }(R), \mathcal{N}_N^{ \rm c }(R))}{R \sqrt{2N/\pi}} = \begin{dcases}
                (-1)^k \varkappa_{j+k}^{ \rm r } , &  \textup{if }  j\neq 0,
                \smallskip 
                \\
                (-1)^k \varkappa_k^{ \rm r }  + \varkappa_k(\infty),  &  \textup{if } j = 0. 
            \end{dcases}  
        \end{align} 
         In particular, for every integer $p\ge2$,
        \begin{equation} 
        \lim_{N\to\infty}
        \frac{\kappa_p\bigl(\mathcal N_N(R)\bigr)}
        {R\sqrt{2N/\pi}}
        = \varkappa_p(\infty), 
        \end{equation}
        where $\varkappa_p(\infty)=0$ whenever $p$ is odd. 

        \smallskip 

        \item \textup{\textbf{(Edge)}}  Suppose that $R = 1- s/\sqrt{2N}$ for some $s\in\mathbb{R}$. Then  
        \begin{equation}    
            \lim_{N\to\infty} \frac{ \kappa_{j,k}(\mathcal{N}_{N}^{ \rm r }(R), \mathcal{N}_N^{ \rm c }(R))  }{\sqrt{2N/\pi}} = \begin{dcases}
                (-1)^k \varkappa_{j+k}^{ \rm r}, &  \textup{if } j\neq 0,
              \smallskip 
              \\
                (-1)^k \varkappa_k^{ \rm r} + \varkappa_k(s),  &  \textup{if } j = 0.
            \end{dcases}
        \end{equation}
        In particular, for every integer $p\ge2$,
        \begin{equation}  
        \lim_{N\to\infty} 
        \frac{\kappa_p\bigl(\mathcal N_N(R)\bigr)}
        {\sqrt{2N/\pi}}
        =
        \varkappa_p(s).
        \end{equation}

        \smallskip 

        \item \textup{\textbf{(Outside)}} Suppose that $R \in (1,\infty]$ is fixed. Then 
        \begin{equation}    
            \lim_{N\to\infty} \frac{\kappa_{j,k}(\mathcal{N}_{N}^{ \rm r }(R), \mathcal{N}_{N}^{ \rm c }(R) )}{\sqrt{2N/\pi}} = (-1)^k \varkappa_{j+k}^{ \rm r }.
        \end{equation}
        In particular, for every integer $p\ge2$,
        \begin{equation} 
        \lim_{N\to\infty} 
        \frac{\kappa_p\bigl(\mathcal N_N(R)\bigr)}
        {\sqrt{2N/\pi}}
        = 0.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.581634+00:00","domain":"probability theory","id":"claim_268bc6d5af1508e327f18d74b6f3e98291645982f60f9cfa6526a8c15a428b13","kind":"lemma","schema_version":1,"statement":"[Lemma Maximum principle-Lemma of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Assume  $\upvartheta:\mathbb R\to\mathbb R$ satisfies, for some $C>0$, $|\upvartheta(x)|\leq C |x|$ for $x\in\mathbb R.$
		Let $d\ge2$, $a_0<b_0$ and $T^*>0$. Assume that $v: [0,T^*)\times\mathbb K^d\mapsto v(t,x)\in \mathbb R^d$ such that  $v\in L_{\rm loc}^1([0,T^*);W^{1,\infty}_d\cap L^2_d)$ and
		$$\int_0^{t}\|v(t')\|_{W^{1,\infty}}{\,\rm{d}} t'<\infty,\quad t\in[0,T^*).$$
		If  $\partial_tf\in C([0,T^*);W^{1,\infty}_1)$ and  $f$  satisfies
		\begin{equation*}
			\partial_tf+\upvartheta(f) \, {\rm div}\, v+ v\cdot\nabla  f=0,\quad
			f(0,x)=f_0(x),\quad a_0\le f_0(\cdot)\le b_0,
		\end{equation*}
		then the following estimates hold true for $(t,x)\in[0,T^*)\times \mathbb K^d$:
		\begin{itemize}[leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item {\bf (Positive solution)} When  $a_0>0$,  
			\begin{equation}
				a_0 \exp \left\{-\int_0^tC\|{\rm div}\, v(t')\|_{L^\infty}{\,\rm{d}} t'\right\} \leq f(t,x)\leq b_0 \exp\left\{\int_0^tC\|{\rm div}\, v(t')\|_{L^\infty}{\,\rm{d}} t'\right\}.
			\end{equation}
			\item {\bf (Negative solution)} When  $b_0<0$,  
			\begin{equation}
				a_0 \exp \left\{\int_0^tC\|{\rm div}\, v(t')\|_{L^\infty}{\,\rm{d}} t'\right\} \leq f(t,x) \leq b_0 \exp\left\{\int_0^t-C\|{\rm div}\, v(t')\|_{L^\infty}{\,\rm{d}} t'\right\}.
			\end{equation}
		\end{itemize}","status":"unverified"}

