{"assumptions":[],"created_at":"2026-10-26T19:22:46.468567+00:00","domain":"probability theory","id":"claim_26d4c7df7660345c09dd6aeb759c4aba04c93158a5ae7a17ad1a9ce2e3fa75cd","kind":"definition","schema_version":1,"statement":"[Definition 66 of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Given intervals $I,J \subset \R$ and real numbers $\ubar,u \in \R$, we define:
	\begin{subequations}
		\begin{align}
			\doublenulltoritwoarg{\ubar}{u}  & \eqdef \{ (t,u,x^2,x^3) \in \R\times\R\times\T^2 \ | \ \ubar(t,u,x^2,x^3) = u\},  \\
			\outgoingcharacteristicsurfacetwoarg{u}{I} & \eqdef \bigcup_{\ubar \in I} \doublenulltoritwoarg{\ubar}{u},  \\
			\ingoingcharacteristicsurfacetwoarg{\ubar}{J} & \eqdef \bigcup_{u \in J}  \doublenulltoritwoarg{\ubar}{u},   \\
			\characteristicdiamondtwoarg{I}{J} & \eqdef \bigcup_{\ubar \in I} \ingoingcharacteristicsurfacetwoarg{\ubar}{J} = \bigcup_{u \in J} \outgoingcharacteristicsurfacetwoarg{u}{I}. 
		\end{align}
	\end{subequations}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.867407+00:00","domain":"probability theory","id":"claim_26d5749c6ae977c889a640fe0d71495b91bdad35206d65589e2ced0bb56f5175","kind":"concept","schema_version":1,"statement":"[Thm 2 of arXiv:2609.02040, '\Large Quantum Landau Damping with Coulomb Repulsion in the Whole Space'] Let $h\in[0,1]$, $\op$ be a solution of Equation~\eqref{eq:Hartree_linear} with initial data $\op^{\init}$ a density operator. Let $f_h^\circ(t,x,v)$ be the solution of the free transport equation with initial data $f_h^\init := \Wigner{\op^\init}$ the Wigner transform of $\op^\init$, namely
		\begin{equation*}
			f_h^\circ(t,x,v) = f_h^\init(x - tv,v) \, .
		\end{equation*}
		Let $\rho_\h := \rho_\op$ and $\rho_\h^\circ$ be the corresponding densities
		\begin{equation*}
			\rho_\h(t,x) = \intd \Wigner{\op}(t,x,v) \d v\, , \qquad \rho_\h^\circ(t,x) = \intd f_h^\circ(t,x,v) \d v \, .
		\end{equation*}
		Then, one can decompose $\rho_\h$ in the following way
		\begin{equation*} 
			\rho_\h = \Gosc_{\h,+} \star_{t,x} \rho_\h^\circ + \Gosc_{\h,-} \star_{t,x} \rho_\h^\circ + \Gr_\h \star_{t,x} \rho_\h^\circ ,
		\end{equation*}
		where $\Gosc_{\h,\pm}$, the oscillatory Green functions, are defined by their Fourier transforms
		\begin{equation*}
			\hatGosc_{\h,\pm}(t,k) = a_{\h,\pm}(k)\, e^{\lambda_{\h,\pm}(k) \,t}
		\end{equation*}
		with, $a_{\h,\pm}(k) = 0$ if $\n{k} \ge 1$, $\lambda_{\h,-}(k) = \bar \lambda_{\h,+}(k)$, $a_{\h,-}(k) = \bar a_{\h,+}(k)$, and uniformly in $\h$, as $k \to 0$,
		\begin{align*}
			a_{\h,\pm}(k) &= \pm \frac{i}{2} + O(\n{k}^2) \, ,
			\\
			\im \lambda_{\h,\pm}(k) &= \pm 1 \mp \n{k}^2 + O(\n{k}^4) \, ,

			\\
			\re \lambda_{\h,\pm}(k) &\sim - \frac{2 \pi}{\n{k}^2} \int_{\mathbb{R}^2} \partial_{v_1} \mu\!\lt( \n{k}^{-1},v_2,v_3 \rt) \d v_2 \d v_3 \, ,
		\end{align*}
		and where, uniformly in $\h$,
		\begin{equation*} 
			\n{\hatGr_\h(t,k)} \lesssim {|k|^3 \over \langle k \rangle^4} e^{- \sigma \n{k} t} 
		\end{equation*}
		for some $\sigma > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:40.965409+00:00","domain":"probability theory","id":"claim_26def3d4c8fab44cbc3ecc712c10c202a2ec3e18e17d6d329127c40ea97ddc16","kind":"concept","schema_version":1,"statement":"[Thm defectiveLSI of arXiv:2412.03560, 'Non-asymptotic entropic bounds for non-linear kinetic Langevin sampler with second-order s'] Let $\varepsilon\in(0,1)$. Suppose Assumptions~(assu:semiconvexbound of the paper) and (assu:Poincare of the paper) hold with $\lambda<1/2$. Introduce the following notations:
