\delta_N &= 4\bar{\rho}(1-\varepsilon)\left( 2 \alpha_N  + \frac{M_{mm}^F d}{\bar{\rho}} \left( \frac52 +  \frac{3M_{mm}^F }{4\bar{\rho}\varepsilon} \right) \right) \,.

