If moreover $ \rho_N - \lambda' - \frac{M_{mm}^F}{N}>0$,  then $\mu_\infty^N$ satisfies a tight LSI   with constant
\[\rho_{N,*} =   \rho_{N,*}'\left( 1+\frac{\delta_N}{4\left( \rho_N - \lambda' - \frac{M_{mm}^F}{N}\right) }\right)^{-1}   \,.  \] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.257460+00:00","domain":"probability theory","id":"claim_26e97123184dfd5b70a0f7bc3a92a03de4da326677a84b2cdf021b0b9980575d","kind":"definition","schema_version":1,"statement":"[Definition 5 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $I$ be a solution to~\eqref{eq:SIS epidemic model} with positive paths and $\rho,x_{0} > 0$.
\begin{enumerate}[(i)]
\item We say that $I$ becomes \emph{extinct with exponential rate $\rho$} if 
\begin{equation}
\limsup_{t\uparrow\infty} \frac{1}{t^{\rho}}\log(I_{t}) < 0\quad\text{a.s.}
\end{equation}
In the case $\rho = 1$ we will simply say that $I$ becomes \emph{exponentially extinct}.

\item The solution $I$ is said to \emph{persist above $x_{0}$} if $\limsup_{t\uparrow\infty}I_{t}\geq x_{0}$ a.s. Furthermore, \emph{persistence around $x_{0}$} holds for $I$ if
\begin{equation}
\liminf_{n\uparrow\infty} I_{t} \leq x_{0} \leq \limsup_{t\uparrow\infty}I_{t} \quad\text{a.s}
\end{equation}
\end{enumerate}","status":"unverified"}

