{"assumptions":[],"created_at":"2026-10-28T00:48:45.311351+00:00","domain":"probability theory","id":"claim_2701bd90470370c97f12d53f14dac1286e80a95f3a29c00771058237baf1279b","kind":"lemma","schema_version":1,"statement":"[Lemma lem-hatD of arXiv:2411.14876, 'Limit theorems for stochastic exponentials of matrix-valued L\'evy processes \\'] Let $L=(L_t)_{t\geq 0}$ be a Lévy process in $\mathbb{R}^{d\times d}$ fulfilling (equation eq-nonsingular of the paper) and let $D=(D_t)_{t\geq 0}$ be the determinant process of its stochastic exponential defined in (equation eq-detprocess of the paper). 
	Then $(\check{D}_t)_{t\geq 0}$ given by
	\begin{align} 
		\check{D}_t:=	\log |D_t| &= \operatorname{tr}(L_t^c) - \frac12 \sum_{m,n=1}^d \sigma_{(m,n),(n,m)} \cdot t + \sum_{0<s\leq t} \log |\det(\Id + \Delta L_s)|, \quad t\geq 0,
	\end{align}
	is an (additive) Lévy process in $\mathbb{R}$ with characteristic triplet $(\sigma_{\check{D}}, \gamma_{\check{D}}, \nu_{\check{D}})$ given by
	\begin{align*}
		\sigma_{\check{D}}&= \sum_{m,n=1}^d \sigma_{(m,m),(n,n)} \\
		\gamma_{\check{D}}&= \operatorname{tr}(\gamma_L)  - \frac12 \sum_{m,n=1}^d \sigma_{(m,n),(n,m)}  \\
		& \qquad + \int_S \Big( (\log|\det(\Id+x)|) \mathds{1}_{\{|\det(\Id+x)| \in [e^{-1},e]\}}  -\operatorname{tr}(x)   \mathds{1}_{\{\|\operatorname{vec} x \|\leq 1\}}   \Big)\nu_L(dx) \\
		\nu_{\check{D}}&= \Phi(\nu_L)|_{\mathbb{R}\setminus \{0\}},
	\end{align*}
	where $S=\mathbb{R}^{d\times d}\setminus \big(\{x \in \mathbb{R}^{d\times d}: \det(\Id+x) =0\}\cup \{0\} \big)$, and for the measure transform
	$$\Phi: S \to \mathbb{R}\setminus \{0\}, \quad x\mapsto \log|\det(\Id+x)|.$$
	Moreover, we have $\mathds{E}|\check{D}_1|<\infty$ if and only if
	\begin{equation} 
		\int_S  (\log|\det(\Id+x)|) \mathds{1}_{\{|\det(\Id+x)| \in (0,e^{-1})\cup (e,\infty)\}}\nu_L(dx)<\infty,
	\end{equation}
	and, if this is the case,
	\begin{equation} 
		\mathds{E}[\check{D}_1] = \operatorname{tr}(\gamma_1)  - \frac12 \sum_{m,n=1}^d \sigma_{(m,n),(n,m)}  + \int_S \Big( \log|\det(\Id+x)|  -\operatorname{tr}(x)   \mathds{1}_{\{|\operatorname{vec} x |\leq 1\}}   \Big)\nu_L(dx).
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.968233+00:00","domain":"probability theory","id":"claim_27035064c2db8fb7708ba600996c2f78255e743155d5931fc6b1599eff14edc1","kind":"theorem","schema_version":1,"statement":"[Corollary 21 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] Suppose that \ref{eq:kappa_n} holds for all \(n = 0, \dots, N\). For all \(n + |f| \le N\), we have that
