{"assumptions":[],"created_at":"2026-10-27T23:32:34.746108+00:00","domain":"probability theory","id":"claim_275e66c2ea53144122718c5353d021c2c0e9d45a65c70cb0373f4dc473c6c526","kind":"lemma","schema_version":1,"statement":"[Lemma bound_on_tail of arXiv:2411.07878, 'Bernstein-type and Bennett-type inequalities for unbounded matrix martingales'] Let $X_1, \dots, X_n$ be non-negative random variables adapted to a filtration $(\mathscr{F}_i)^n_{i=1}$, $\alpha > 0$, and $U_i \coloneqq \norm*{X_i \bigm| \mathscr{F}_{i-1}}_{\psi_{\alpha}} \in [0, \infty]$.
    Fix $U \ge K > 0$ and set
    \[
    E_n \coloneqq \lrc{\sum^n_{i=1} U^2_i \le U^2,~\max_{i\in [n]} U_i \le K }.
    \]
    Then for any $\tau \ge K$
    \begin{equation}

        \mathbb{P}\left( \{\max_{i \in [n]} X_i \ge \tau\} \cap E_n \right) \le 2 \lr{\frac{4}{\alpha e}}^{\frac{2}{\alpha}}
        \frac{U^2}{\tau^2} e^{-\frac{1}{2} \lr{\frac{\tau}{K}}^{\alpha} }.
    \end{equation}
    Moreover, if 
    \begin{equation*}

        \tau \ge K \left(2 \mathrm{x} + 4 \ln\lr{\frac{2 U}{K}} + \frac{4}{\alpha} \ln \lr{\frac{4}{\alpha e}} \right)^{1/\alpha} ,
    \end{equation*}
    then
    \begin{equation}

        \mathbb{P}\lr{\{\max_{i\in [n]} X_i \ge \tau\} \cap E_n} \le e^{-\mathrm{x}}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:26:20.567269+00:00","domain":"probability theory","id":"claim_275e6b9adf5be7e9ab4cab762f48890b049413e8b0d872a7f23b3ba83f13b28b","kind":"concept","schema_version":1,"statement":"[Theorem thm:logHol of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] {M}}]
