{"assumptions":[],"created_at":"2026-10-26T19:46:12.278553+00:00","domain":"probability theory","id":"claim_276a160d9fe22bf7e26cfc1b63db2c5a69f8105cc13da1829219c8bd4918fdb5","kind":"definition","schema_version":1,"statement":"[Definition 11 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] For any $t_0 >-\infty$, we define $\sC_{t_0}$ as the space $C(\R;H) \cap  \{ \cap_{N \geq 1} L^2([t_0,N];V) \}$ equipped with the following distance
    \begin{equation*}
         d_{t_0} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 \wedge \int_{-N \vee t_0}^N  \| X_s -Y_s \|_{V}^2 \, \d s}{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{t_0} $.


    The space $\sC_{+\infty}$ is defined as $C(\R;H)$ equipped with the metric
    \begin{equation*}
         d_{+\infty} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 }{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{+\infty} $. For any $t_0 \in [ -\infty, +\infty]$ and $p \geq 1$, we define $L^{p}(\Omega,\sC_{t_0})$ as the space of all random functions lie on $\sC_{t_0}$ with the metric $ |\E |d_{t_0} (\cdot,\cdot)|^{p}|^{1/p} $.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.546738+00:00","domain":"probability theory","id":"claim_276d79d6299a8a379fa1def24a4107b44ccf2d30933073a3438292a0b3bd2abd","kind":"concept","schema_version":1,"statement":"[Lemma 9 (McDiarmid's inequality~\citep{mcdiarmid1989method}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Let $\mbf{z}_1,\dots,\mbf{z}_N$ be independent random variables taking values in a set $\mathcal{Z}$.
Let $\Phi:\mathcal{Z}^N \to \mathbb{R}$ be a function of $(\mbf{z}_1,\dots,\mbf{z}_N)$.
Assume $\Phi$ satisfies the bounded differences property: for each $i\in\{1,\dots,n\}$ there exists $c_i\ge0$ such that for all
$z_1,\dots,z_n,z'_i \in \mathcal{Z}$,
\begin{align}
    \big|\Phi(z_1,\dots,z_i,\dots,z_N) - \Phi(z_1,\dots,z'_i,\dots,z_N)\big|
    \le c_i .

\end{align}
Then for every $t>0$,
\begin{align}
    \prob_{\mbf{z}}*{
        \abs*{ \Phi(\mbf{z}_1,\dots,\mbf{z}_N)
        - \E[\Phi(\mbf{z}_1,\dots,\mbf{z}_N)]}
        \ge t
        }
    \le
    2\exp\parens*{ -\frac{2t^2}{\sum_{i=1}^N c_i^2} }
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:43:55.658250+00:00","domain":"probability theory","id":"claim_276e3b1f11af42286848e049b9bc404e4f2e4c697e5d67202ddaaed939a8554d","kind":"concept","schema_version":1,"statement":"[Prop local_at_1k of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] Fix~$p_0\in(0,1)$ and~$\frac1k\in\mathcal B_{p_0}$. Then,
\begin{itemize}
\item[(i)] for every~$u\in\mathbb R$,
\begin{equation}

\lim_{n\to\infty}\sqrt n\,\bigl(V_n\bigl(p_{n,k}(u)\bigr)-W_n\bigl(p_{n,k}(u)\bigr)\bigr)
=
\gamma_k |u| \Phi(-|u|)
;
\end{equation}
in particular, this local profile is maximized exactly at~$|u|=u_\star$, where it
equals~$2\gamma_kC_\star$;
\item[(ii)] for every~$\rho>0$ and every sequence~$(\pi_n)$ of (possibly randomized) \mbox{$p$-blind} rules,
\begin{equation}

\lim_{\rho\to\infty}\ \liminf_{n\to\infty}\ \sup_{|u|\le\rho}\ \sqrt n\,\bigl(V_n\bigl(p_{n,k}(u)\bigr)-W_n^{\pi_n}\bigl(p_{n,k}(u)\bigr)\bigr)
 \ge
