{"assumptions":[],"created_at":"2026-10-26T19:33:23.319273+00:00","domain":"probability theory","id":"claim_27b0ba36e753720d750d0a67433d431e559f62274cf5a101452c92eccff2e7ec","kind":"theorem","schema_version":1,"statement":"[Proposition 19 of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] Denote
      $\kappa(\gamma,r)=1+1/r-(1-d)(1+\gamma)$.
       \begin{enumerate}[label=(\roman*)]
         \item
      There exists a pair of unique minimizers $(\gamma_0,r_0)$ of $\kappa(\gamma,r)$ over the compact domain
      \begin{align*}
        0
         \ \le \
         \gamma
         \ \le \
  \min \left\{
  \frac{d}{1-d}
  \,,
         1
          -
         \frac{1}{r(1-d)}
         \,,
         \frac{\alpha}{r}
          -
         1
  \right\}
           \qquad\text{and}\qquad
         \frac{1}{1-d}
         \ \le \
         r
         \ \le \
         \alpha
         \,,
      \end{align*}
       namely
       \begin{align*}
 \gamma_0
   :=
  \begin{cases}
    \frac{d}{1-d}
    &
    \ \text{if}\
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\
    \frac{\alpha(1-d)-1}{\alpha(1-d)+1}
    &
    \
    \text{else,}
  \end{cases}
  \
  r_0
   :=
  \begin{cases}
    \alpha(1-d)
    &
    \ \text{if}\
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\
    \frac{1}{2}
    \left(
    \frac{1}{1-d}
    \ + \ \alpha
    \right)
    &
    \
    \text{else,}
  \end{cases}
  \end{align*}
  yielding
  \begin{align*}
  \kappa_0
    \ = \
    \kappa(\gamma_0,r_0)
  \ = \
  \left\{ \begin{array}{l}
    \frac{1}{\alpha(1-d)}
    \ \text{ if } \
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\[10pt]
    \frac{2(1-d) + (1-\alpha(1-d)(1-2d))}{\alpha(1-d)+1} = d
    \ + \
    (1-d)
    \frac{3-\alpha(1-d)}{\alpha(1-d)+1}
    \ \text{ else.}
  \end{array} \right.
\end{align*}
\item
It holds
\begin{align*}
  \gamma_0
  \ = \
  \min \left\{
  \frac{d}{1-d}
  \,,
         1
          -
         \frac{1}{r_0(1-d)}
         \,,
         \frac{\alpha}{r_0}
          -
         1
  \right\}
  \,,\quad
  r_0
  \in
  \left(
  \frac{1}{1-d}
  \,,
  \alpha
  \right)
  \,,
  \end{align*}
  and
  \begin{align*}
  \kappa_0
  \ - \ (d+1/\alpha)
  \ < \
  0
  \,.
\end{align*}
\end{enumerate}","status":"unverified"}

