\dot x_{i}(t)=\xi_{i}(t),\\
\dot \xi_{i}(t)=-B(t,x_{i}(t))\xi_{i}^{\perp}(t)-\frac{1}{N\varepsilon}\underset{j:j\neq i}{\sum}\nabla_{x} V(x_{i}(t)-x_{j}(t)),\\
