{"assumptions":[],"created_at":"2026-10-26T19:34:33.543255+00:00","domain":"probability theory","id":"claim_282e098dc6eb87b6c994732887c0e7afbd1eb52fde0f79738c3c5cd4f7339089","kind":"definition","schema_version":1,"statement":"[Definition 22 (Property~\ref{prop:digits}: Matching digits) of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Suppose that $S\subset\R$.
    Consider fixed constants $\epsilon\in[0,1]$ and $k\in\Z_{\geq 0}$.
    We say that a Glauber dynamic $R$ \emph{matches digits up to $(\epsilon,k)$}
    if we may find an event $M\subset\Sigma$ of $\diff\iota$-probability at least $1-\epsilon$ such that:
    \begin{itemize}
        \item For any $u\in V$ and $\iota\in M$, we have
        \[
            \big\{
                \{R_{u,\iota}(\alpha)_u\}_k=\{R_{u,\iota}(\alpha')_u\}_k \text{ for all $\alpha,\alpha'\in S^V$}
            \big\}
        \]
        \item For any $u\in V$ and $\alpha\in S^V$,
        the event $M$ and the random variable $\lfloor R_{u,\iota}(\alpha)_u\rfloor_k$
        are $\diff\iota$-independent.
    \end{itemize}
    The event $M$ is called the \emph{matching event}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:49.833541+00:00","domain":"probability theory","id":"claim_2830276ce37a0488643d3c8ebd6f9605bb37a51d0b90fe6e9d8be09689670e52","kind":"definition","schema_version":1,"statement":"[Definition 10 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] For $A, B \in \sB_\R$, 
\begin{align*}
	\tau_t(A,B) &= \sum_{x \in A \cap \Z} P_x(\zeta_t \in B)^2, \qquad \text{and} \\
	\kappa_t(A,B) &= \sum_{x,y \in \Z} p(x,y) \int_0^t (P_x(\zeta_s \in B) - P_y(\zeta_s \in B))^2 P_x(\zeta_{t-s} \in A)P_y(\zeta_{t-s} \in A)  \,ds.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:01:48.663553+00:00","domain":"probability theory","id":"claim_283197f182bd4b83100efbc48af4434ad198156cff6590532454e30d22b33901","kind":"lemma","schema_version":1,"statement":"[Lemma lem:overlap of arXiv:2607.06249, 'Extreme least singular values of Gaussian row submatrices and a phase retrieval stability '] Let $S,T$ be independent uniform elements of $\mathcal{S}=\{S\subset[N-1]: |S|=m-1\}$, and set $D=m-|S\cap T|$.
Then for $d\ge1$,
\begin{equation}
  \mathbb{P}\{D=d\}=\frac{\binom{m-1}{d-1}\binom{N-m}{d-1}}{\binom{N-1}{m-1}},
\end{equation}
with the convention that binomial coefficients outside their natural range vanish. Moreover
\begin{equation}
  \mathbb{E}\frac1D=\frac{N}{m(N-m+1)},
  \qquad
  \mathbb{P}\{D=2\}=\frac{(m-1)(N-m)}{\binom{N-1}{m-1}}.
\end{equation}","status":"unverified"}

