\end{equation}
and
\begin{equation}

 \dE[(N_n,M_n)^T(N_n,M_n)] = \dE(N_n^2)\left(\begin{array}{cc}
1 & -1 \\
-1 & 1 
\end{array}
\right)+T_n\dE(N_n)\left(\begin{array}{cc}
0 & 1 \\
1 & -2
\end{array}
\right)
+T_n^2\left(\begin{array}{cc}
