{"assumptions":[],"created_at":"2026-10-26T20:46:09.854654+00:00","domain":"probability theory","id":"claim_29a38177ea42d1f6209b6c0c0c79b434ec84e2eae18f7820aeb05b5a851910be","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2605.20026, 'Quasihelix properties\\ of selected Volterra Gaussian processes'] Let $\gamma\in[0,1)$. Then for any $0<T_1<T_2$ the following statements hold.
\begin{enumerate}
\item[$(i)$]
Let $\alpha \in (-1/2, 1/2)$.
Then 
\begin{equation}
\ex\left(U^{(2)}(t)-U^{(2)}(s)\right)^2
\sim C(\alpha)(t-s)^{2\alpha+1}s^{-\gamma},
\quad \text{as } t\downarrow s,
\end{equation}
for any $s\in[T_1,T_2]$,
where
\begin{equation}
C(\alpha) = \int_0^\infty \bigl[(1+z)^\alpha-z^\alpha\bigr]^2\,dz
+ \frac{1}{2\alpha+1}
= \frac{\Gamma(\alpha+1)^2} {\Gamma(2\alpha+2)\cos(\pi\alpha)}.
\end{equation}
Consequently, the process $U^{(2)}$ is a local $(\alpha+\frac12,T_1,T_2)$-quasihelix.

\item[$(ii)$]
If $\alpha=1/2$, then the process  $U^{(2)}$ is a local $(1,1-\varepsilon,T_1,T_2)$-generalized quasihelix for any $\varepsilon\in(0,1)$.

\item[$(iii)$]
If $\alpha > 1/2$, then the process $U^{(2)}$ is a local $  (1,T_1,T_2)$-quasihelix.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.739752+00:00","domain":"probability theory","id":"claim_29a5304b0617962fcb2f0593e8a565f684ffb2ce0a9b3e844463da98494e845e","kind":"concept","schema_version":1,"statement":"[Theorem 16 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] [\cite{Minh:2020regularizedDiv}, Theorem 11 and Corollary 2]

	Let $\mu = \Ncal(m_1, Q)$, $\nu = \Ncal(m_2,R)$, with $m_2 - m_1 \in \range(Q^{1/2})$, $R = Q^{1/2}(I-S)Q^{1/2}$, $S \in \SymHS(\Hcal)_{<I}$.
	The Radon-Nikodym density $\frac{d\nu}{d\mu}$

	is given by
	\begin{align}

		\frac{d\nu}{d\mu}(x) = \exp\left[-\frac{1}{2}\sum_{k=1}^{\infty}\Phi_k(x)\right]\exp\left[-\frac{1}{2}||(I-S)^{-1/2}Q^{-1/2}(m_2 - m_1)||^2\right],

	\end{align}
	where for each $k \in \Nbb$
	\begin{align}

		\Phi_k = \frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k} - \frac{2}{1-\alpha_k}\la Q^{-1/2}(m_2-m_1), \phi_k\ra W_{\phi_k}+ \log(1-\alpha_k).
	\end{align}
	The series $\sum_{k=1}^{\infty}\Phi_k$ converges in 
	$\Lcal^2(\Hcal,\mu)$ and

	$s(x) = \exp\left[-\frac{1}{2}\sum_{k=1}^{\infty}\Phi_k(x)\right] \in \Lcal^1(\Hcal, \mu)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

