{"assumptions":[],"created_at":"2026-10-26T19:29:52.203903+00:00","domain":"probability theory","id":"claim_2b315f674d13fffd16655ed5953758155f7acb427f945f41c781f49bc9e1ee7e","kind":"concept","schema_version":1,"statement":"[Proposition 11 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let {\rm\Cref{assumpNecessity_meanField}} hold, and let $\hat\alpha$ be a sub-game--perfect mean-field equilibrium. Then, there exists a quadruple $(Y^{1}, Z^{1,1}, M^{1,\star}, \Z^{1,m,1,\star,})$ satisfying the following {\rm BSDE} system
\begin{align}
\notag Y^1_t &= g\big(X^1_{\cdot \land T}, \cL_{\hat\alpha}(X^1_{\cdot \land T})\big) + G\big(\varphi_1(X^1_{\cdot \land T}),\varphi_2(\cL_{\hat\alpha}(X^1_{\cdot \land T}))\big)+ \int_t^T f_s\big(X^1_{\cdot \land s},\cL_{\hat\alpha}(X^1_{\cdot \land s},\hat\alpha_s),\hat\alpha_s\big) \d s \\
\notag &\quad  - \frac{1}{2} \int_t^T \partial^2_{m,m}G\big(M^{1,\star}_s,N^{\star}_s\big) \big\|Z^{1,m,1,\star}_s\big\|^2 \d s - \int_t^T Z^{1,1}_s \cdot \d \big(W_s^{\hat\alpha}\big)^1, \; t \in [0,T], \; \P \text{\rm--a.s.}, \\
\notag M^{1,\star}_t &\;= \varphi_1(X^1_{\cdot \land T}) - \int_t^T Z^{1,m,1,\star}_s \cdot \d \big(W_s^{\hat\alpha}\big)^1, \; t \in [0,T], \; \P \text{\rm--a.s.},\\
N^{\star}_t &\coloneqq \varphi_2(\cL_{\hat\alpha}(X^1_{\cdot \land T})), \; t \in [0,T],\; \P\text{\rm--a.s.},
\end{align}
where, for notational convenience, we write $W^{\hat\alpha} \coloneqq W_s^{\hat\alpha,\xi}$ with $\xi_t \coloneqq \cL_{\hat\alpha}(X^1_{\cdot \land t}, \hat\alpha_t)$ for each $t \in [0,T]$. Furthermore, there exists some $p \geq 1$ such that
\begin{align*}
&\sup_{\alpha \in \cA^\smalltext{1}} \E^{\P^{\smalltext{\alpha}}} \Bigg[ \sup_{t \in [0,T]} \big|Y^{1}_t\big|^p + \bigg(\int_0^T \big\|{Z}_t^{1,1}\big\|^2 \d t\bigg)^\frac{p}{2} \Bigg] +\esssup_{\alpha \in \cA^\smalltext{1}} \Bigg\{\sup_{t \in [0,T]}  \big| M^{1,\star}_t\big| + \sup_{\tau \in \cT_{0,T}} \E^{\P^{\smalltext{\alpha}\smalltext{,}\smalltext{1}\smalltext{,}\smalltext{\tau}}_{\smalltext{\cdot}}} \bigg[ \int_\tau^T \big\|Z^{1,m,1,\star}_t\big\|^2 \d t \bigg] \Bigg\} < +\infty.
\end{align*}
The value process satisfies $V^1_t = Y^{1}_t$, $\P\text{\rm--a.s.}$, for any $t \in [0,T]$, and the sub-game--perfect mean-field equilibrium $\hat\alpha$ satisfies
\begin{align*}
\hat\alpha_t \in \argmax_{a \in A} \big\{h_t\big(X^1_{\cdot \land t}, \cL_{\hat\alpha}(X^1_{\cdot \land t},\hat\alpha_t), Z^{1,1}_t, a\big)\big\}, \; \text{\rm for}\; \d t \otimes \d \P\text{\rm--a.e.} \; (t,\omega) \in [0,T] \times \Omega.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.252760+00:00","domain":"probability theory","id":"claim_2b3442a0776d15c35c3ff10a311de265cf8b6363f7bc07a9066ab77b73c69628","kind":"lemma","schema_version":1,"statement":"[Lemm 11 of arXiv:2605.23292, 'Second-order Poincaré inequalities and localization on the Poisson space'] (localization of  mixed moments of first and  second order difference operators)
Assume the score $\xi: (X \times \R \times \MM) \times \mathbf{N} \to \R$ satisfies $BL(\theta,\theta')$ space-time localization on  $(X,d,\nu) \times (\R, \mu)$ as in Def.~\ref{def:space-time-loc} with short-range scores $(\xi^{[r]})_{r>0},(\xi^{(s)})_{s \in \R}$ and functions $\psi$ and $\phi$. Put $C_p=(36p-20) (M_{5,X}^\xi)^{(p-1)/p}$ for $p \in \N$.

\noindent (i) 
For all non-negative integers $p_1, p_2, p_3, p_4$ satisfying $p_1 + p_2+ p_3+ p_4 = p-1 >0$, there is a constant $c>0$ depending only on $p$ such that for 
 all $(z_1,t_{z_1}),(z_2,t_{z_2}),(z_3,t_{z_3}),(z_4,t_{z_4}),(x,t_{x}) \in X \times \R$
and   for all $r > 0$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi((z_i, t_{z_i},M_{z_i}), \tP \cup \tA_i))\right)^{p_i}\\
 - \E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi^{[r]}((z_i, t_{z_i},M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq c C_p \psi(r)^{1/p}
\end{multline*}
and for all $s \in \R$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi((z_i, t_{z_i},M_{z_i}), \tP \cup \tA_i))\right)^{p_i}\\
 - \E \Pi_{i = 1}^4 \left(D_{(x,t_{x},M_x)} \xi^{(s)}((z_i, t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq  c C_p\phi(s)^{1/p}.
\end{multline*}

\noindent (ii) 
For all non-negative integers $p_1, p_2, p_3, p_4$ satisfying $p_1 + p_2+ p_3+ p_4 = p-1$,
there is a constant $c>0$ 
depending only on $p$  such that for all $(z_1,t_{z_1}),$ $(z_2,t_{z_2}),$ $(z_3,t_{z_3}),$ $(z_4,t_{z_4}),$ $(x,t_x),$ $(y,t_y) \in X \times \R$
and all $r > 0$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi((z_i, t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i}  \\
 - \E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi^{[r]}((z_i,t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq c C_p \psi(r)^{1/p}
\end{multline*}
and for all $s \in \R$
\begin{multline*}
\sup_{\substack{\mathcal{A}_i \subset \{(z_1,t_{z_1}),\hdots,(z_4,t_{z_4})\},\\i=1,\hdots,4}}
\bigg|\E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi((z_i, t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i}  \\
 - \E \Pi_{i = 1}^4 \left(\DD_{(x,t_x,M_x),(y,t_y,M_y)} \xi^{(s)}((z_i,t_{z_i}, M_{z_i}), \tP \cup \tA_i))\right)^{p_i} \bigg| \leq c C_p \phi(s)^{1/p}.
\end{multline*}","status":"unverified"}

