{"assumptions":[],"created_at":"2026-10-26T20:56:49.286352+00:00","domain":"probability theory","id":"claim_2e4c772d4edee44b03648d7a06e92779cb50f717eb66f521a2efa9ff887711c4","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] For any $\widehat{\mathbf{x}}\in\widehat{C}^{\alpha,p}_o$ and some $\beta>0$ and $\gamma\geq\lfloor 1/\alpha\rfloor$, let
    \begin{equation*}
        \psi(\widehat{\mathbf{x}}) := \exp\left(\beta(\lVert \widehat{\mathbf{x}} \rVert_{\textup{hom $p$-var};[0,T]} + \lVert \widehat{\mathbf{x}} \rVert_{\textup{hom $\alpha$-H\"{o}l};[0,T]})^\gamma\right).
    \end{equation*}
    Also, let
    \begin{equation*}
        B_\psi(\widehat{C}^{\alpha,p}_o) := \Bigg\{f:\widehat{C}^{\alpha,p}_o\rightarrow\mathbb{R} \,:\, \lVert f\rVert
        _{\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)}:=\sup_{\widehat{\mathbf{x}}\in\widehat{C}^{\alpha,p}_o}\frac{f(\widehat{\mathbf{x}})}{\psi(\widehat{\mathbf{x}})}<\infty\Bigg\}
    \end{equation*}
    and $\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)$ be the closure with respect to $\lVert \cdot\rVert_{\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)}$ of the space $C_b^0\left(\widehat{C}^{\alpha,p}_o;\mathbb{R}\right)$ of bounded and continuous real-valued functions over $\widehat{C}^{\alpha,p}_o$. Then, for every map $f\in \mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)$ and for every $\varepsilon>0$, there exists a linear function of the form 
    \begin{equation*}
        (T(\mathbb{R}^{k+1}))\ni S(\widehat{\mathbf{x}})_T \longmapsto \langle\ell,S(\widehat{\mathbf{x}})_T\rangle := \sum_{0\leq |I|\leq N} \alpha_I\big\langle \varepsilon_I, S^{|I|}(\widehat{\mathbf{x}})_T \big\rangle_{(\mathbb{R}^{k+1})^{\otimes |I|}},
    \end{equation*}
    where $N\in\mathbb{N}$, $\alpha_I\in\mathbb{R}$, $I=(i_1,\dots,i_m)\in\{1,\dots,k\}^m$ is a multi-index with $|I|=m$, $\varepsilon_I:=\varepsilon_{i_1}\otimes\dots\otimes\varepsilon_{i_m}$ are the basis elements of $(\mathbb{R}^{k+1})^{\otimes m}$, and $\langle \cdot,\cdot\rangle_{(\mathbb{R}^{k+1})^{\otimes |I|}}$ is the usual inner product on $(\mathbb{R}^{k+1})^{\otimes |I|}$, such that
    \begin{equation*}
        \sup_{t\in[0,T]}\sup_{\widehat{\mathbf{x}}\in \widehat{C}^{\alpha,p}_o} \frac{ \big|f(\widehat{\mathbf{x}}_{\cdot\wedge t}) -\langle\ell,S(\widehat{\mathbf{x}})_t\rangle\big| }{ \psi(\widehat{\mathbf{x}}_{\cdot\wedge t}) } < \varepsilon.
    \end{equation*}","status":"unverified"}

