{"assumptions":[],"created_at":"2026-10-26T20:55:37.353616+00:00","domain":"probability theory","id":"claim_2f223579338d60330efc124d6621ba2adb8ad4fe604897234139609115d6dfa0","kind":"definition","schema_version":1,"statement":"[Definition 10 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] \la{def:Kato}
    \begin{enumerate}[(1)]
    \item A smooth measure $\mu \in \cS$ is said to be in Kato class ($\cK$) if
      the associated PCAF $A_{t}^{\mu}$ satisfies
      \begin{align}

      \lim_{t \to 0} \sup_{x \in \bR^{d}} \bE_{x}[A_{t}^{\mu}] = 0. 
      \end{align}
    \item A smooth measure $\mu \in \cS$ is said to be 
    in the class $\cK_{\infty}$
      if for any $\varepsilon > 0$, there is a Borel set $K = K(\varepsilon)$ of
      finite $\mu$-measure and a constant $\delta = \delta(\varepsilon) > 0$
      such that for all measurable sets $B \subset K$ with $\mu(B) < \delta$,
      \begin{align}

        \sup_{x \in \mathbb{R}^{d}} G(1_{B \cup K^{c}} \mu)(x) < \varepsilon.
      \end{align}
     \item A smooth measure $\mu$ is said to be in the class $\cS_{\infty}$
       if for any $\varepsilon > 0$ there exists a Borel subset $K = K(\varepsilon)$
       of finite $\mu$-measure and a constant $\delta = \delta(\varepsilon) > 0$
       such that for all measurable sets $B \subset K$ with $\mu(B) < \delta$,
       \begin{align}

         \sup_{(x,z) \in \bR^{d} \times \bR^{d}} \int_{B \cup K^{c}}^{ }
         \frac{G(x,y) G(y,z)}{G(x,z)} \mu(dy) \le \varepsilon.
       \end{align}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.701206+00:00","domain":"probability theory","id":"claim_2f223d627bc1487745ffecef58e063ef8e1aacc35177ef2310fce88b7d042a57","kind":"concept","schema_version":1,"statement":"[Thm main-use-result-cline-hsing of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $\{Y_k\}_{k\geq 1}$ be an i.i.d. family of random variables with common distribution $F$ and $S_n = Y_1 + Y_2 + ...+ Y_n$. Assume that $\mathbb{P}[|Y_1| >x]$ is regularly varying with index $-2$ and $\sup_{x \geq 0} F(-x)/(1-F(x)) <\infty$. Assume $Y_1$ has mean zero\footnote{Note that the mean of $Y_1$ is well defined since the tail of $Y_1$ is regularly varying with index $-2$.} and let $t_n$ be a sequence such that 

    \[ \lim_{n\to \infty} n(1-F(t_n)) = \lim_{n\to \infty} \frac{n \log t_n \mathbb{E}[Y_1^2 1_{|Y_1| \leq t_n }]}{t_n^2}= 0.\]

Then, \[ \lim_{n\to \infty} \sup_{s \geq t_n} \biggl|\frac{\mathbb{P}[S_n >s]}{n (1 - F(s))} -1 \biggr| =0.\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

