{"assumptions":[],"created_at":"2026-10-27T11:40:59.386735+00:00","domain":"probability theory","id":"claim_2ffd6b7fb06f652be25d564eb60efccb0bd43934c0beabd8879b5143817a6683","kind":"theorem","schema_version":1,"statement":"[Theorem 40 of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $n\ge2$, $0<s<2$, $p\in(1,\infty)$, and let
$f\in\Lambda^{-1,p}(\R^n)^n$, $g\in\Lambda^{s-2,p}(\R^n)$. Then
\eqref{fstokes} admits a solution $(u,P)\in V_{s,p}^n\times L^p(\R^n)$ if
and only if
\begin{equation}
  f\perp\mathcal P_{[1-n/p']}
  \qquad\text{and}\qquad
  g\perp\mathcal P_{[2-s-n/p']}.
\end{equation}
In this case the pressure $P$ is unique, and the solutions are precisely
the pairs $(u+\lambda,P)$ with
$\lambda\in(\mathcal P_{[s-1-n/p]})^n$; thus the solution is unique
whenever $s-1<n/p$, in particular for all $0<s\le1$, and unique up to an
additive constant vector when $s-1\ge n/p$. Moreover every solution
satisfies
\begin{equation}
  \norm{P}_{L^p}
  +\inf_{\lambda\in(\mathcal P_{[s-1-n/p]})^n}
   \norm{u-\lambda}_{\Lambda^{s-1,p}}
  \le C\big(\norm{f}_{\Lambda^{-1,p}}+\norm{g}_{\Lambda^{s-2,p}}\big).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.355679+00:00","domain":"probability theory","id":"claim_2ffdd2a24048feadd41bab444a93a79f7deab2f16990731396277b965d722bea","kind":"theorem","schema_version":1,"statement":"[Proposition lem.optproperties of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] For any $0 < T \leq 1$, the problem
    \begin{equation}
        \inf_{(m,\alpha) \in \mathcal{A}(0,\delta_0)} [m_T]_{\infty},
    \end{equation}
    admits an optimizer $(m,\alpha)$ with the following properties:
    \begin{enumerate}
        \item $m_t$ is even, in the sense that $(x \mapsto -x)_{\#} m_t = m_t$, for each $0 \leq t \leq T$, 
        \item $\alpha(t,\cdot)$ is odd, for each fixed $t$, 
        \item $\alpha$ ``points inwards", in the sense that $\alpha(t,x)x \leq 0$ for each $(t,x) \in [0,T] \times {\mathbb R}$. 
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:41:28.179915+00:00","domain":"probability theory","id":"claim_30033b89e41a4696cf9ebc412f0e34a14bb73146ac799d416bba6be7a360d2c1","kind":"concept","schema_version":1,"statement":"[Theorem thm:shuffle of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $d \geqslant 2$ be an integer and $\mu$ be a distribution on $S_d$. Let $\gamma$ denote the spectral gap of the single ball transition matrix $U$ and $q \coloneqq \min \left\{1-U(i,i): i \in [d]\right\}$. Then the following hold.

    \begin{enumerate}[label=(\alph*)]
        \item Consider a sequence $\{\mathbf{X}^{(n)}\}_{n \in \mathbb{N}}$ of multi-stack random-to-random shuffle chains where the $n^{\mathrm{th}}$ chain has parameters $(d, n, \mu)$. Then, for any fixed $\varepsilon \in (0, 1)$, we have
        \begin{equation*}
            \frac{n \log n}{2 \gamma} - O(n) \leqslant t^{(n)}_{\textup{mix}}(\varepsilon) \leqslant \max \set{\frac{1}{2 \gamma}, 1} \cdot n \log n + O(n \log \log n).
        \end{equation*}

        \item Consider a sequence $\{\mathbf{X}^{(n)}\}_{n \in \mathbb{N}}$ of restricted multi-stack random-to-random shuffle chains where the $n^{\mathrm{th}}$ chain has parameters $(d, n, \mu)$. Then, for any fixed $\varepsilon \in (0, 1)$, we have
        \begin{equation*}
            \frac{n \log n}{2 \gamma} - O(n) \leqslant t^{(n)}_{\textup{mix}}(\varepsilon) \leqslant \max \set{\frac{1}{2 \gamma}, \frac{1}{q}} \cdot n \log n + O(n \log \log n).
        \end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

