{"assumptions":[],"created_at":"2026-10-27T11:23:37.815961+00:00","domain":"probability theory","id":"claim_304a2d1540a796446f3c98b4fd909a6552f2479dcfa61f1d16e4756a7649a564","kind":"theorem","schema_version":1,"statement":"[Theorem 7 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Fix $a<0<b$. Under $\mathbb{P}_{a,b}^{<}$, the following identities hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item For the pre-infimum process,
\begin{equation*}\small
\mathbb{P}_{a,b}^{<}\{M_{0,H_I}^-<d\}=\begin{cases}
0, & d\le -a,\\
\displaystyle
1-\left[\frac{W^{(\gamma)\prime}(d)W^{(\gamma)}(b-a)-W^{(\gamma)\prime}(b-a)W^{(\gamma)}(d)}{W^{(\gamma)\prime}(-a)W^{(\gamma)}(b-a)-W^{(\gamma)\prime}(b-a)W^{(\gamma)}(-a)}\right]
\left(\frac{W^{(\gamma)}(-a)}{W^{(\gamma)}(d)}\right),
& -a<d<b-a,\\
1, & d\ge b-a.
\end{cases}
\end{equation*}

\item For the intermediate process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_I,H_S}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{W^{(\gamma)}(b-a)}{W^{(\gamma)}(d)}
\exp\left\{-(b-a-d)\frac{W_+^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}\right\},
& 0<d<b-a,\\[12pt]
1, & d\ge b-a.
\end{cases}
\end{equation*}

\item For the post-supremum process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_S,T}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{\bigl(Z^{(\gamma)}(d)-1\bigr)\dfrac{W^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}-\gamma W^{(\gamma)}(d)}
{\bigl(Z^{(\gamma)}(b-a)-1\bigr)\dfrac{W^{(\gamma)\prime}(b-a)}{W^{(\gamma)}(b-a)}-\gamma W^{(\gamma)}(b-a)},
& 0<d<b-a,\\[14pt]
1, & d\ge b-a.
\end{cases}
\end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.286015+00:00","domain":"probability theory","id":"claim_3052b96cd48987a36dc27db15495e61a7da71583c67b79e51763f96a11de01ae","kind":"theorem","schema_version":1,"statement":"[Theorem 6 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\geq 1$. There exists a map
    \begin{equation*}
        S(\cdot)_T:C_o^{\textup{$p$-var}}([0,T],G^{\lfloor p\rfloor}(\mathbb{R}^k))\rightarrow (T(\mathbb{R}^k)):=\prod_{\ell=0}^\infty (\mathbb{R}^k)^{\otimes \ell};\quad S(\mathbf{x})_T=\left(1,S(\mathbf{x})^{(1)}_T,S(\mathbf{x})^{(2)}_T,\dots\right)
    \end{equation*}
    such that $S(\mathbf{x})_T^{(m)}=\mathbf{x}^{(m)}_T$ for all $m=0,\dots,\floor{p}$. Moreover, $S(\mathbf{x})_T=S(\mathbf{y})_T$ if and only if $\mathbf{x}\sim_t\mathbf{y}$, where $\sim_t$ denotes the tree-like equivalence (see Definition \ref{def:tree_like_eq} below).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.859299+00:00","domain":"probability theory","id":"claim_305453b7b1830fbf51285d3650dd6e8cc77a5a6a49463504601e923bf97f7661","kind":"concept","schema_version":1,"statement":"[Thm main of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ is a generalised preferential attachment tree. Then,
    \begin{enumerate} 
        \item  If \[\sum_{j=0}^{\infty} \frac{1}{F(j)^2} = \infty \quad \text{almost surely},\] then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ almost surely does not have a persistent hub. 
        \item  Suppose that the following two conditions are satisfied: 
        \begin{enumerate}
            \item There exists a sequence $(x_{j})_{j \in \mathbb{N}_0}$ with $\sum_{j=0}^{\infty} \frac{1}{x_{j}^2} < \infty$ such that,
				\begin{equation}            
             		F(j) \geq x_{j} \quad \text{almost surely.}
             	\end{equation} 
            \item There exists a $\lambda > 0$ such that 
                \begin{equation} 
                \sum_{i=0}^{\infty} \prod_{j=0}^{i}\E{\frac{F(j)}{F(j) + \lambda}} < \infty.
                \end{equation}
        \end{enumerate}
        Then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ has a unique persistent hub almost surely. 
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:23:05.302421+00:00","domain":"probability theory","id":"claim_30552b8a52e6bbd5085a113376a566c123421b05ad0df396a9e685fd4a32ab58","kind":"definition","schema_version":1,"statement":"[Df 6 of arXiv:2608.21787, 'Stability of extremal hyperplane projections of balls in $\ell_p^n(\R)$'] Let $X$ and $Y$ be symmetric random variables. We say that $X$ is dominated by $Y$ in the Choquet ordering and denote $X \preceq Y$ if for every convex function $\phi \colon \R \to [0, \infty)$ we have
        \begin{align*}
            \E\phi(X) \le \E\phi(Y).
