  on   } \{\mathcal{X}_y \neq 0\} \text{    a.s.}
\end{equation*}
Furthermore, for $\delta>0$ we have that
\begin{equation*}
    \text{dim}\Big(\overline{\bigcup_{y \geq \delta}\text{supp}(\mathcal{X}_y)}\Big) = 4 \wedge d \hspace{0.5cm} \text{ 
  on   } \{\mathcal{X}_{\delta} \neq 0\} \text{    a.s.}
\end{equation*}
Finally we have that
\begin{equation*}
