{"assumptions":[],"created_at":"2026-10-27T18:51:26.749595+00:00","domain":"probability theory","id":"claim_330aef0f76ac6872aaa8bcc1814f681078f118275c0b2e659937b7b6722b1f7f","kind":"theorem","schema_version":1,"statement":"[Theorem thrm:multinorm of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Let $(X_n)_{n\in\mathbb{N}}$ and  $(Y_n)_{n\in\mathbb{N}}$ be sequences of real-valued random variables,  and let $(\lambda_n)_{n\in\mathbb{N}}$, $(\mu_n)_{n\in\mathbb{N}}$ sequences of real numbers such that, for any $r,s\in\mathbb{N}$ and any $t\geq r,u\geq s$, 
\begin{equation} 
\mathbb{E}\left[(X_n)_r(Y_n)_s\right]-\lambda_n^r\mu_n^s=o(\lambda_n^{-t}\mu_n^{-u}). 
\end{equation} 
Then, with $Z_1,Z_2$ two independent standard normal random variables, 
\begin{equation} 
\Big(\frac{X_n-\lambda_n}{\sqrt{\lambda_n}},\frac{Y_n-\mu_n}{\sqrt{\mu_n}}\Big)\buildrel {\mathrm{d}}\over{\longrightarrow} (Z_1,Z_2).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:33:12.354921+00:00","domain":"probability theory","id":"claim_330dd5887a8787d22c1f2a03c89032bfba2ae7cbab1eac51905541c80764b6bb","kind":"definition","schema_version":1,"statement":"[Dfn 217 (stochastic control and achievable measures for symmetrized projection pursuit) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $B, W$ be one-dimensional standard Brownian motions, and let $U,U' \sim \unif([0,1])$ (with $B,W,U,U'$ mutually independent).
Define the filtrations 
\[\begin{aligned}
    \cF_X(t) &= \sigma(U, (B(s) : 0\le s\le t))\,, \\
    \cF_{\Ising}(t) &= \sigma(U', (W(s) : 0\le s\le t))\,.
\end{aligned}\]
Let $\ProgMsrbl(\cF_X)$ denote the space of stochastic processes that are progressively measurable with respect to $\cF_X$, and similarly $\ProgMsrbl(\cF_{\Ising})$ for $\cF_{\Ising}$. For $\sigma\in\ProgMsrbl(\cF_X)$ and $w\in\ProgMsrbl(\cF_{\Ising})$, let  
	\begin{align}

	X(t)
	&\equiv\int_0^s \sigma_t\,dB(s)\,,\\
	X^\Ising(t)
	&\equiv\int_0^t w_s\,dW(s)

	\end{align}
Let $\cM^{\Ising,\sym}(\alpha)$ be the set of measures $\mu$ which can be expressed as $\mu=\Law(|X(1)|)$
(i.e., $\mu$ is the law of the real-valued random variable $|X(1)|$)
 for $X$ defined by \eqref{eq:main-process-intro-p=1}, and for controls $(\sigma,w)$ satisfying the following conditions:
\begin{itemize}
\item the nonnegativity condition
$\sigma_t\ge0$ for all $t\in[0,1]$,
\item the time parametrization condition
$\E[(w_t)^2]=1$ for all $t\in[0,1]$,
\item the \textbf{budget constraint}
	\beq
	\E\Big[(\sigma_t-1)^2\Big]
	\le \frac{(\E w_t)^2}{\alpha}
	\eeq
for all $t\in[0,1]$, and 
\item the \textbf{endpoint condition}
$|X^{\Ising}(1)|=1$.
\end{itemize}
 Let $\cM^{\sph,\sym}(\alpha)$ be the set of measures $\mu$ which can be expressed as $\mu=\Law(|X(1)|)$ for $X$ defined by \eqref{eq:main-process-intro-p=1}, and for controls $(\sigma,w\equiv1)$ satisfying the same conditions as above, \textbf{except for the endpoint constraint}. We use $\bar{\cM}^{\Ising,\sym}(\alpha)$,
$\bar{\cM}^{\sph,\sym}(\alpha)$ to denote the closures with respect to the $2$-Wasserstein metric $\bbW_2$ (defined by \eqref{def:W2} below).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:50:30.565662+00:00","domain":"probability theory","id":"claim_330f399394f0082cd6e7b5caafa8fa526536e5264643d2506a8e2987fea21d7c","kind":"theorem","schema_version":1,"statement":"[Proposition 16 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] Let $(\Omega,\mathcal{C})$ and $P_{1}$ and
$P_{2}$ as above, and let $T$ be a $\mathbb{H}$-valued random variable,
with idempotent decomposition 
\begin{equation}
T=U\begin{pmatrix}T_{1} & 0\\
0 & T_{2}
\end{pmatrix}U,
\end{equation}
and $p\in\mathbb{H}$ with idempotent decomposition as in \eqref{p}.
Furthermore,

\begin{equation}
E_{\mathbb H}T=U\begin{pmatrix}E_{1}T_{1} & 0\\
0 & E_{2}T_{2}
\end{pmatrix}U.
\end{equation}

Assume that $T_{1}$ and $T_{2}$ are independent with respect to both
$P_{1}$ and $P_{2}$. We have 
\begin{equation}
\begin{split}P_{\mathbb{H}}(T\le p) & =U\begin{pmatrix}P_{1}(T_{1}\le\lambda_{1})P_{1}(T_{2}\le\lambda_{2}) & 0\\
0 & P_{2}(T_{1}\le\lambda_{1})P_{2}(T_{2}\le\lambda_{2})
\end{pmatrix}U\\
 & =P_{\mathbb{H}}(T_{1}\le\lambda_{1})P_{\mathbb{H}}(T_{2}\le\lambda_{2}).
\end{split}

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.423774+00:00","domain":"probability theory","id":"claim_3316a9e2d5f1b20a12200e0bbd2765d3762f22eb118a14962ea04e2f143fa35a","kind":"lemma","schema_version":1,"statement":"[Lem maypolefilling of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $P \coloneqq D^2 \times S^1$ denote the solid torus endowed with its natural Euclidean metric. We write $H \coloneqq T D^2 \times \{0\}$ for the horizontal plane field on $P$.

    There exists a constant $C > 0$ such that the following holds. Let $\varepsilon > 0$ and let $\xi_\partial$ be a germ of contact structure near $\partial P \subset P$ such that 
    \begin{itemize}
        \item $\xi_\partial$ is $\varepsilon$-close to $H$,
        \item The slope of $\xi_\partial$ along $\partial P$ is positive.
    \end{itemize}
Then, there exists a contact structure $\xi$ on $P$ such that 
    \begin{itemize}
        \item $\xi$ coincides with $\xi_\partial$ near $\partial P$,
        \item $\xi$ is $C\varepsilon$-close to $H$.
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.023909+00:00","domain":"probability theory","id":"claim_3319c9c83612db84119c7f0bbef70a21f25aab50f85cd28cec0ffe0bf43a32dd","kind":"concept","schema_version":1,"statement":"[Corollary cor:tied_weak_recovery_sgd of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under Assumption (assum:tied_initialization of the paper) and the conditions of Theorem (theo:tied-SGD of the paper), suppose additionally that
\begin{equation}
[\nabla\Phi(\bar q(0))]_{12}\neq0,

\end{equation}
Then there exist constants \(c>0\) and \(0<T_-<T_+<\infty\) independent of \(d\), such that
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(
\left\lfloor\frac{T_-d}{4\alpha_d}\right\rfloor<N_{\mathrm{wr}}^{(d)}(c)
\le\left\lceil\frac{T_+d}{4\alpha_d}\right\rceil
\right)=1.

\end{equation}
In particular, choosing the largest learning-rate scaling $\alpha_d=\Theta\left(\frac1{d\log d}\right)$ covered by Theorem (theo:tied-SGD of the paper) gives the weak recovery sample complexity
\begin{equation}
N_{\mathrm{wr}}^{(d)}(c)=\Theta_{\mathbb P}(d^2\log d).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:45:32.064771+00:00","domain":"probability theory","id":"claim_331ed81f9d67f98cae7a8a1a0d451690f293947cd25765037a47595a2346ff20","kind":"lemma","schema_version":1,"statement":"[Lemma l.R(0),A_0 of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $\Phi$ and $X$ be associated with some decomposition $(L,\alpha)$ of some $q\in\mathcal Q_\infty$. 
Let $X(0)= \sqrt{2L(0)}\eta$ for a standard $\mathbb{R}^{D}$-valued Gaussian vector $\eta$ independent of everything else.
Let $R(\cdot)$ and $A_\cdot$ be given as in~(equation e.R(t)=A_t= of the paper). We have
\begin{gather}
    \mathbb{E}_\eta \Phi\left(0, \sqrt{2L(0)}\eta\right) = - \psi(q) ,\qquad \mathbb{E}_\eta  A_0  = \mathbb{E} \left[\left\langle \sigma\sigma^\intercal \right\rangle_q  -\left\langle \sigma\sigma'^\intercal\right\rangle_q\right]
\end{gather}
where $\mathbb{E}_\eta$ averages only over the randomness of $\eta$ and the Gibbs measure is given by
\begin{align}
    \left\langle \cdot \right\rangle_q \propto \exp\left(\sqrt{2}\sigma\cdot w^q(\mathbf{h}) - q(1)\cdot\sigma\sigma^\intercal\right)\mathrm{d} P_1(\sigma)\mathrm{d}\mathfrak{R}(\mathbf{h}).
\end{align}
If $L(0)=0$, we also have $R(0) = \mathbb{E} \left\langle \sigma\right\rangle_q \left(\left\langle\sigma\right\rangle_q\right)^\intercal$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.500390+00:00","domain":"probability theory","id":"claim_3322c8a56fd4199e04ddebf50b64b04e08bc989f7f54371a63d70c1c1c6ae6ea","kind":"concept","schema_version":1,"statement":"[Theo of arXiv:2411.07158, 'Markov chains on trees: almost lower and upper directed cases'] Let $\;{\sf U}$ be an irreducible {\sf AUD}\xspace transition matrix on a finite or infinite tree $T$, and let $\pi:=(\pi_v,v\in T)$ be an invariant measure of $\;{\sf U}$. Set, for all $u,v \in T$,
  \begin{eqnarray} {\sf D}_{v,u}=\pi_u{\sf U}_{u,v}/\pi_v, ~~~u,v\in T.\end{eqnarray}
  \begin{itemize} \topsep0pt   \itemsep=0pt   \partopsep=0pt   \parsep=0pt \setcounter{c}{0}
  \addtocounter{c}{1}\item[($\roman{c}$)] ${\sf D}$ is an {\sf ALD}\xspace irreducible transition matrix, which possesses also $\pi$ as invariant measure
  \addtocounter{c}{1}\item[($\roman{c}$)] ${\sf D}$ is positive recurrent iff ${\sf U}$ is,
  \addtocounter{c}{1}\item[($\roman{c}$)] ${\sf D}$ is recurrent iff ${\sf U}$ is,
  \addtocounter{c}{1}\item[($\roman{c}$)] If ${\sf U}$ has a right eigenvector $R=(R_u,u\in T)$ with positive coordinate (and associated with the eigenvalue 1) then $\begin{pmatrix} \pi_u R_u,u\in T\end{pmatrix}$ is an invariant measure for ${\sf D}$ (so that this property extends to cones). 
  \end{itemize}\vspace{-2em}~ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.226272+00:00","domain":"probability theory","id":"claim_3325cc3910e5b9ffee95d1bcdfea618a13cea993efd20cdc568b789a115ed747","kind":"lemma","schema_version":1,"statement":"[Lem element estimates bfM-n-R of arXiv:2608.23156, 'Disc counting statistics of the real Ginibre ensemble'] Suppose that $R\equiv R_N>0$ satisfies
\begin{equation}
    R_N\to r\in(0,\infty]
    \qquad
    \text{as }N\to\infty.
\end{equation}
For $j,k\in\{1,\ldots,n\}$, set
\begin{equation} 
    x:=\frac{2j-1}{NR^2},
    \qquad
    y:=\frac{2k-1}{NR^2}.
\end{equation}
Then, for every fixed $\epsilon\in(0,1)$, as $N\to\infty$,
\begin{equation}
    \begin{split}
    [\mathbf{M}_N(R)]_{j,k}
    =
    \sqrt{\frac{2}{\pi}}\,
    \frac{(xy)^{1/4}}{\sqrt{N}R(x+y)} 
    \exp\bigg[
        -\frac{NR^2}{2}
        \Big(
            x\log x
            +
            y\log y
            -
            (x+y)\log\frac{x+y}{2}
        \Big)
        +
        O\Big(
            \frac{1}{j}
            +
            \frac{1}{k}
        \Big)
    \bigg].
    \end{split}
\end{equation}
The error term is uniform over all $j,k\in\{1,\ldots,n\}$
satisfying $ 0<x,y\leq1-\epsilon.$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.494448+00:00","domain":"probability theory","id":"claim_3326b98926a0edbd0a64cb1d32797217bb29d1882cf5dcbee0d86b8825f48e89","kind":"concept","schema_version":1,"statement":"[Problem 24 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] One \emph{can} hear the shape of LQG. In other words,  given a domain $\Sigma$ and the eigenvalue sequence $(\bl_n)_{n\ge 1}$ of LQG, one can measurably recover the underlying Gaussian free field $\ph$. More precisely, there exists a measurable function $\Phi = \Phi_\Sigma: \R^\N \to H^{-1} (\Sigma)$ such that 
$$
\Phi_\Sigma( (\bl_n)_{n\ge 1}) = \ph, \text{ a.s.} 
$$
In fact, we conjecture that it is possible to measurably recover the pair $(\Sigma, \ph)$ up to isometry, i.e., up to equivalence of quantum surfaces, in the sense of \cite{DS}. (Stated as a problem by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.097259+00:00","domain":"probability theory","id":"claim_33274144e77e766c06450398eccbc042e40c602b3daf7b06bb9a2189a7e7f6f6","kind":"theorem","schema_version":1,"statement":"[Corollary cor:deg-equality of arXiv:2609.02845, 'Degeneracy bounds, stability, and a sharp gap for $B$-colorings'] Let $d$ and $\Delta$ be integers with $1\le d\le\Delta$.  The maximum
possible value of $q_B(G)$ among all finite simple $d$-degenerate
graphs $G$ with $\Delta(G)\le\Delta$ is $d\Delta$.  Moreover, for
every such graph $G$, the following are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $q_B(G)=d\Delta$;
\item $G$ contains a copy of $K_{d,\Delta}$;
\item $G$ has at least $d$ vertices of degree $\Delta$ with the same
      open neighborhood.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.652098+00:00","domain":"probability theory","id":"claim_332d70b9273da550f92f97e4efb46ab1033a257fa163649845e7bf380e32a177","kind":"theorem","schema_version":1,"statement":"[Theorem thm:center_manifold of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume the same setting as in Theorem (thm:stable_manifold of the paper). Suppose that at least one Lyapunov exponent is zero, denoted by $\mu_{i_c}$. Therefore, $\mu_{i_c} = 0$, $\mu^{-} = \max\{\mu_{i} : \mu_{i} < 0\} = \mu_{i_c+1}$, and if $i_{c} > 1$, then $\mu^{+} = \min\{\mu_{i} : \mu_{i} > 0\} = \mu_{i_c-1}$; otherwise, we set $\mu^{+} := \infty$. We also set $C_\omega := H^{i_c}_{\omega}$.
			Then we can find a continuous cocycle $\tilde{\varphi}$ defined on $\{E_\omega\}_{\omega \in \Omega}$. That is, for every $p, q \in \mathbb{N}$ and $\omega \in \Omega$, the map $\tilde{\varphi}^p_{\omega}: E_\omega \to E_{\theta_{rp}\omega}$ is continuous, and we have $\tilde{\varphi}^{p+q}_{\omega} = \tilde{\varphi}^p_{\theta_{qr}\omega} \circ \tilde{\varphi}^q_{\omega}$. For this new cocycle, and for every $0 < \upsilon < \min\{\mu^{+}, -\mu^{-}\}$, on a set of full measure $\tilde{\Omega}$, which is $\theta_r$-invariant, the following items hold:
			\begin{itemize}
				\item[(i)] There exists a positive random variable $\rho^c:\Omega \to (0, \infty)$ such that
				\begin{align*}
					\liminf_{m \rightarrow \pm \infty} \frac{1}{m} \log \rho^c(\theta_{mr}\omega) \geq 0,
				\end{align*}
				and if $\|\xi_{\omega} - Y_\omega\|_{E_\omega} \leq \rho^c(\omega)$, then $\tilde{\varphi}^{1}_{\omega}(Y_\omega + \xi_\omega) = \varphi^{1}_{\omega}(Y_\omega + \xi_\omega)$.

				\item[(ii)] We can find a map
				\begin{align*}
					h_{\omega}: C_{\omega} \rightarrow \mathcal{M}^{c,\upsilon}_{\omega},
				\end{align*}
				such that this map is a homeomorphism, Lipschitz continuous, and differentiable at zero.

				\item[(iii)] The manifold $\mathcal{M}^{c,\upsilon}_{\omega}$ obtained from the previous item is a topological Banach manifold modeled on $C_\omega$.

				\item[(iv)] $\mathcal{M}^{c,\upsilon}_{\omega}$ is $\tilde{\varphi}$-invariant, i.e., for every $m \in \mathbb{N}_0$, $\tilde{\varphi}^{m}_{\omega}(\mathcal{M}^{c,\upsilon}_{\omega}) \subset \mathcal{M}^{c,\upsilon}_{\theta_{mr}\omega}$.

				\item[(v)] For every $\xi_\omega \in \mathcal{M}^{c,\upsilon}_{\omega}$, we can find a sequence $\{\xi_{\theta_{-mr}\omega}\}_{m \geq 1}$ such that if we set
				\begin{align*}
					\tilde{\varphi}^{jr}_{\omega}(\xi_\omega) \coloneqq \xi_{\theta_{jr}\omega}
				\end{align*}
				for $j \leq 0$, then
				\begin{align*}
					\tilde{\varphi}^p_{\theta_{qr}\omega}(\tilde{\varphi}^q_{\omega}(\xi_\omega)) = \tilde{\varphi}^{p+q}_{\omega}(\xi_\omega)
				\end{align*}
				for all $(p, q) \in \mathbb{N} \times \mathbb{Z}$, and
				\begin{align*}
					\sup_{j \in \mathbb{Z}} \exp(-\nu |j|) \| \tilde{\varphi}^{jr}_{\omega}(\xi_\omega) - Y_{\theta_{jr}\omega} \|_{E_{\theta_{rj}\omega}} < \infty.
				\end{align*}
			\end{itemize}","status":"unverified"}

