{"assumptions":[],"created_at":"2026-10-27T07:23:05.285303+00:00","domain":"probability theory","id":"claim_333b8cbd09cc8e50bb9f88abad1d43ccac3aa661e897e8d5d7ffcb2a5d26b653","kind":"theorem","schema_version":1,"statement":"[Proposition 8 of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] Let $\Psib_1,\ldots,\Psib_d$ be diagonal matrices with positive diagonal entries. There exists a unique vector $(c_1,\ldots,c_d)$ satisfying $c_j>0$, $j=1,\ldots,d$, and $\prod_{j=1}^d c_j=1$ such that
\begin{align}
  \min\left\{\diag(c_1\Psib_1)\right\}
  =
  \cdots
  =
  \min\left\{\diag(c_d\Psib_d)\right\}.

\end{align}
The unique rescaling constants are
\begin{align}
  c_j
  &=
  \frac{\overline{\psi}_{\min}}{\psi_{j,\min}},
  \qquad
  \psi_{j,\min}
  =
  \min\left\{\diag(\Psib_j)\right\},
  \qquad
  \overline{\psi}_{\min}
  =
  \left(
    \prod_{\ell=1}^d\psi_{\ell,\min}
  \right)^{1/d}.

\end{align}
The tuple $(c_1\Psib_1,\ldots,c_d\Psib_d)$ is the unique admissible rescaling satisfying \eqref{eq:min-diag}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:38:58.708609+00:00","domain":"probability theory","id":"claim_333d68572bbec451de2ad71f0f2ffbf9beb66a5aa56ef6a1859f3db661271d04","kind":"concept","schema_version":1,"statement":"[Proposition prop:theFRD of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $d \ge 3$,  $\eta \in [0,2)$ and $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}$ for sufficiently small $\epsilon_p$.  Then there exist covariance matrices $\Gamma_j$ on $\Z^d$ such that (equation eq:LetaFRD of the paper) and the following hold.

\begin{enumerate}
	\item (Symmetries) $\Gamma_j : \Z^d \times \Z^d \rightarrow \R$ is a covariance matrix invariant under isometries,
	i.e., $\Gamma_t \ge 0$ and $\Gamma_t (E (x) , E(y)) = \Gamma_j (x,y)$ for any isometry $E : \Z^d \rightarrow \Z^d$.
	\item (Finite range property) $\Gamma_j$ has range $< L^j$ in the $\ell^1$-metric,  i.e.,  $\Gamma_j (x,y) =0$ whenever $\norm{x-y}_{\ell^{1}} \ge L^j$. 
	\item (Upper bound) For each $k, k_x,k_y \ge 0$ with $k_x + k_y = k$,  
	\begin{align}
		\big\| \nabla_x^{k_x} \nabla_y^{k_y} \Gamma_{j+1} (x,y) \big\|_{\ell^\infty (\Z^d \times \Z^d)} \le C_k \frac{L^{-(d-2+\eta)j}}{1 + \textbf{a}^{(\emptyset)} L^{(2-\eta)j}}	 .  
	\end{align}
	uniformly in $j,  L$ for some constant $C_k$.	
\end{enumerate}
When $\textbf{a}^{(\emptyset)} >0$ and $\Lambda = \Lambda_N$,  then there exist $t_N >0$ and a covariance $\Gamma_N^{\Lambda}$ on $\Lambda_N$,  that satisfy (equation eq:LetaFRD of the paper) with $\Gamma_j$ the projections of those of $\Z^d$ and satisfy the following.
\begin{enumerate}
	\item $\Gamma_N^{\Lambda}$ satisfies the same symmetries and the upper bounds as $\Gamma_N$.  

	\item $t_N \in (0, (\textbf{a}^{(\emptyset)})^{-1})$ and there exists $C >0$ such that $t_N >  (\textbf{a}^{(\emptyset)})^{-1} - CL^{(2-\eta) N}$.
\end{enumerate}
Moreover,  $\Gamma_j$ is continuous in $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}$ and $\Gamma_N^{\Lambda}$ and $t_N$ are continuous in $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p} \backslash \{ \textbf{a}^{(\emptyset)} = 0 \}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.575556+00:00","domain":"probability theory","id":"claim_3345099fdcd068ac84d06d6dd120df1e20275adfc7965b0e746fd9c81f1a2cab","kind":"lemma","schema_version":1,"statement":"[Lemma L:LX23cond of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $\alpha > 0$, $\beta \in (0, 2]$, $\gamma \ge 0$, $H \in [1/2, 1)$ and
  $\ell \in (0, 2d)$. Assume Dalang's condition
  (equation E:main of the paper), and suppose $\rho \in (0, 1)$ and $\theta \in (0, 1)$. Then
  the following estimates hold:
  \begin{enumerate}[\rm (i)]

    \item If $\beta \in (0,1]$ and $\gamma \in [0,1-\beta]$, for any compact interval $I = [S, T]$ in $(0,
            \infty)$ and $x_0 \in \mathbb{R}^d$, there exists a positive finite constant $C$
          such that for all $t, t' \in I$ and $a_0 := 1 \vee (1/S^\rho) \le a < b \le \infty$,
          \begin{align}
            \| v_1([a, b), t', x_0) - v(t', x_0) - v_1([a, b), t, x_0) + v(t, x_0) \|_{L^2}
            \le C \left( a^{\frac{1}{\rho} - 1} |t'-t| + b^{-1} \right)
          \end{align}
          and
          \begin{align}
            \|v_1([0,a_0),t',x_0)-v_1([0,a_0),t,x_0)\|_{L^2} \le C |t'-t|.
          \end{align}

    \item If $\beta \in (0,2]$ and $\gamma \ge 0$, for any compact rectangle $J$ in $\mathbb{R}^d$ and $t_0 > 0$, there exists
          a positive finite constant $C'$ such that for all $x, x' \in J$ and $0
            \le a < b \le \infty$,
          \begin{align}
            \| v_2([a, b), t_0, x) - v(t_0, x) - v_2([a, b), t_0, x') + v(t_0, x') \|_{L^2}
            \le C' \left( a^{\frac{1}{\theta} - 1} |x-x'| + b^{-1} \right).
          \end{align}

  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.364720+00:00","domain":"probability theory","id":"claim_334967a4fa2e2c8cae202682636a551ce5e1031587d6e5c21c9767afa796db15","kind":"concept","schema_version":1,"statement":"[Lemma lem:covariances of arXiv:2606.02472, 'Correlated uniform attachment trees'] Recall the random variables $S_j^X(n), S_j^Y(n)$, and $S_j^Z(n)$, $j=0,1,\ldots,\ell$ just defined, and assume they satisfy~(equation eq:gdcondvars of the paper). Then  there is an $m\in \N$ depending only on  $\ell, N, (K_j)_{j=0}^\ell$, and $\alpha$, such that for 
 all $0\leq j\leq i\leq \ell$ and $n>m$, we have 
