{"assumptions":[],"created_at":"2026-10-27T21:09:59.188225+00:00","domain":"probability theory","id":"claim_338bf61207c231335991410c80579f4bf67701ee3cf695ea12daa61fd00761ac","kind":"definition","schema_version":1,"statement":"[Definition def:Qh of arXiv:2608.05262, 'The law of $(1+1)$D SOS with an area tilt in a wedge'] For independent random variables $\tilde \mathfrak X_k(j) \sim \mathbb P_{\theta_k(j)}$,  we denote by $\mathbb Q_\star(\cdot)$
the joint law of $\underline{\widetilde{\phi}}(\cdot):=(\widetilde{\phi}_1(\cdot),\ldots,\widetilde{\phi}_K(\cdot))$,
where 
\begin{equation}
    \widetilde \phi_k(i) = \sum_{j=-N}^{i-1} \big[ \tilde \mathfrak X_k(j) - \operatorname{sgn}(j) \big],    \qquad i \in [-N,N] \,,  \;\;
    1 \le k \le K \,,  
\end{equation} 
using $\mathbb E_\star(\cdot)$ for the associated expectation. 

Let $\mathbb Q_\mathfrak h$ be the 
probability measure whose density {\sc{\lowercase{wrt}}} $\mathbb Q_\star$ is 
proportional to $e^{-\mathfrak h {\mathcal W}^-} e^{-\mathfrak h {\mathcal W}^+}$, 
where
\begin{align}
{\mathcal W}^- &:= \sum_{k=1}^K \frac{\lambda^{k-1}}{N} 
\sum_{t=-N}^{a_k^-} \big(\widetilde \phi_k(t) \vee 0\big)
- \sum_{k=1}^K \frac{\lambda^{k-1}}{N} \{a_k\} \big(\widetilde \phi_k (a_k^-) \vee 0\big)
, \\
{\mathcal W}^+ &:= \sum_{k=1}^K \frac{\lambda^{k-1}}{N}
\sum_{t=a_k^+}^N (\widetilde \phi_k(t) \vee 0)
- \sum_{k=1}^K \frac{\lambda^{k-1}}{N} \{a_k\} \big(\widetilde \phi_k (a_k^+) \vee 0\big)
\,.

\end{align}","status":"unverified"}

