    \lesssim
     \begin{dcases}
    n^{-\zeta(1-\frac{1}{\alpha}-\theta)+\eta\theta}, & \alpha\in (1,2),\\
    n^{-\zeta(\frac{1}{2}-\theta)+\eta\theta}(\log n)^{\zeta/2}, & \alpha=2,\\
    n^{-\zeta(\frac{1}{2}-\theta)+\eta\theta}, & \alpha\in (2,\infty).
