 	\begin{equation}
 		\mathbb{P}^{D}\big( \mathsf{H}_{v',w'}^{v,w}  \big)\asymp |v-v'|^{\frac{3}{2}}N^{-[(\frac{3d}{2}-1)\boxdot (2d-4)]}; 
 	\end{equation}



 	\item When $ |v-v'|\ge 1$, if there exists $n\in [1,c'N]$ such that $v,v'\in \widetilde{B}(10n)\setminus \widetilde{B}(n)$, then for any $D\subset \widetilde{B}(\frac{n}{C'})\cup [\widetilde{B}(C'N)]^c$, 
 	\begin{equation}
 		\mathbb{P}^{D}\big( \mathsf{H}_{v',w'}^{v,w}  \big)\asymp |v-v'|^{(3-\frac{d}{2})\boxdot 0}N^{-[(\frac{3d}{2}-1)\boxdot (2d-4)]}. 
 	\end{equation}


 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:47:32.879524+00:00","domain":"probability theory","id":"claim_33f4d4d924fe1ed799d95eb222db03a6781943e662941e66a06b1ab9ddd15b46","kind":"concept","schema_version":1,"statement":"[Lemma 7 (Baker) of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $k\ge3$, and suppose that there are integers $r,v_2,\ldots,v_k$ satisfying
