 &=\sqrt{\tfrac2\pi}\,\bigl|\cos (n+\tfrac12)\theta\bigr|,\\
F_{n,\frac12,\frac12}(x)
 &=\sqrt{\tfrac2\pi}\,\bigl|\sin (n+1)\theta\bigr|,
\end{aligned}
\]
while $F_{n,-\frac12,-\frac12}(x)=\sqrt{2/\pi}\,|\cos n\theta|$ for $n\ge1$ and
$F_{0,-\frac12,-\frac12}\equiv\pi^{-1/2}$. Apart from this degree-zero
exception, the maxima are $\sqrt{2/\pi}$. In particular every admissible
constant in either \eqref{eq:main} or \eqref{eq:EMN-corollary} is at least
$\sqrt{2/\pi}$.
\item[(ii)] For every fixed $n\in\Nzero$ and every $\alpha\ge-1/2$,
\begin{equation}
F_{n,\alpha,-\frac12}(-1)^2
=\frac{(2n+\alpha+\tfrac12)\,\Gamma(n+\tfrac12)\,\Gamma(n+\alpha+\tfrac12)}
{\pi\,\Gamma(n+1)\,\Gamma(n+\alpha+1)},
\end{equation}
the right-hand side being read by continuous extension at
$(n,\alpha)=(0,-\frac12)$, where it equals $1/\pi$. Consequently
\begin{equation}
F_{n,\alpha,-\frac12}(-1)\sim
\Bigl(\frac{\Gamma(n+\tfrac12)}{\pi\,\Gamma(n+1)}\Bigr)^{1/2}\alpha^{1/4}
\qquad(\alpha\to\infty),
\end{equation}
so the fixed-degree exponent $1/4$ in $\mathcal E_n$ cannot be lowered.
\item[(iii)] For every fixed $A\ge-1/2$ and $z>0$,
\begin{equation}
 \lim_{n\to\infty}F_{n,A,A}\!\left(\cos\frac zn\right)
 =\sqrt z\,|J_A(z)|.
\end{equation}
Moreover, there is an absolute constant $c>0$ such that, for every sufficiently
large $A$, there exists an integer $n_A$ with $n_A+1\ge(2A+1)^3$ for which
\begin{equation}
 F_{n_A,A,A}\!\left(\cos\frac A{n_A}\right)\ge cA^{1/6}
\end{equation}
holds. Hence, along this sequence, $S=2A+1$, and the term $S^{1/6}$ in
$\mathcal E_n(S)$ cannot be omitted even though
$S^{1/4}(n+1)^{-1/12}\le1$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

