\item  If $\nu_2(b) = 2$, $\nu_2(n) \geq 13$ or $\nu_2(n-1) \geq 11$;
\item  If $\nu_2(b) \geq 3$, $\nu_2(n) \geq 6\nu_2(b) + 1$ or $\nu_2(n-1) \geq 6\nu_2(b)$;
\item  If $3 \mid b$, $\nu_3(n) \geq 6\nu_3(b)$ or $\nu_3(n-1) \geq 6\nu_3(b) + 1$;
