        \item The sequence $(q_n)_{n \in \mathbb{N}}$ is an orthonormal basis of $H_{\mathrm{odd}}$, where
        \begin{align*}
            q_n \coloneqq \frac{1}{\sqrt{2}} (e_n - e_{-n}) \in \ell^2(\mathbb{Z}), \quad n \in \mathbb{N}.
