			\upmu \Transport \tander^N v^i & = - \upmu \Speed^2 \p_i \tander^N \LogDensity + \, ^{(\tander^N)}\ehcurrent_{(v;1)}^i,   \\
			\upmu \Transport \tander^N \vortrenormalized^i & = \upmu \vortrenormalized^a \p_i \tander^N v^a - \upmu \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \upepsilon_{iab}\left(\Transport \tander^N v^a\right) \GradEnt^b + 	\, ^{(\tander^N)}\ehcurrent_{(\vortrenormalized;1)}^i,  \\
			\upmu \Transport \tander^N \GradEnt^i & = - \upmu \GradEnt^a \p_i \tander^N v^a + \, ^{(\tander^N)}\ehcurrent_{(\GradEnt;1)}^i, 
		\end{align}
	\end{subequations}
where $^{(\tander^N)}\ehcurrent_{(\vortrenormalized;1)}^i$ and $^{(\tander^N)}\ehcurrent_{(\GradEnt;1)}^i$ are as in \eqref{E:SHARPDECOMPOSITIONOFTOPORDEREXTERIORDERIVATIVEOFVORTFIRSTERRORTERM},\eqref{E:SHARPDECOMPOSITIONOFTOPORDEREXTERIORDERIVATIVEOFGRADENTFIRSTERRORTERM}, respectively, and: 
\begin{subequations}
		\begin{align}
			 ^{(\tander^N)}\ehcurrent_{(\LogDensity)} & = [\upmu\Transport,\tander^N]\LogDensity + [\upmu\p_a,\tander^N]v^a,  \\
			 \begin{split} 
			 	^{(\tander^N)}\ehcurrent_{(v;1)}^i & = [\upmu \Transport ,\tander^N ] v^i + \Speed^2 [\upmu \p_i,\tander^N]\LogDensity - \sum_{\substack{ \tander^{N_1}\tander^{N_2} =\tander^N \\ N_2 \le N-1}} \left( \tander^{N_1}(\Speed^2)\right) \tander^{N_2}\left( \upmu \p_i \LogDensity\right) \\
				 & \ \ - \tander^N \left\{ \upmu \exp(-\LogDensity) \frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^i\right\}.
