In addition, the following identities hold: 
\begin{subequations}
		\begin{align}
			\upmu \Flatcurl \left( \tander^N v\right)^i & = \upmu \exp(\LogDensity)  \tander^N \vortrenormalized^i + \, ^{(\tander^N)}\ehcurrent_{(v;2)}^i  \\
			\upmu \Flatdiv \left( \tander^N\vortrenormalized\right) & = - \vortrenormalized^a \upmu \p_a \tander^N \LogDensity + \, ^{(\tander^N)}\ehcurrent_{(\vortrenormalized;3)},  \\			
			\begin{split}  
				\upmu \left( \Flatcurl \tander^N \vortrenormalized\right)^i & = \upmu \exp(\LogDensity) \tander^N\VortVort^i + \upmu \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \left( \p_a \tander^N v^a\right) \GradEnt^i \\
				& - \upmu \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^a \p_a \tander^N v^i + \, ^{(\tander^N)}\ehcurrent_{(\vortrenormalized;2)}^i ,
			\end{split} \\
			\begin{split}  
