{"assumptions":[],"created_at":"2026-10-27T07:12:19.510258+00:00","domain":"probability theory","id":"claim_371cc3f0728313c226f0ab58342e3f97ddb1b6503f321c2028acb7bbf8bfbe5d","kind":"lemma","schema_version":1,"statement":"[Lemma 45 of arXiv:2608.18075, '2608.18075'] Fix $T<\infty$. There is a deterministic constant
$C_{{\rm loc},T}\ge1$ such that, if
\begin{align*}
 \mathcal L_T(w_0,y)
 &=\exp\left(C_{{\rm loc},T}
       (1+\mathbb W_T(w_0,y)^{q_\sigma})\right),\\
 \delta_T(w_0,y)
 &=\min\left\{1,\frac1{8\mathcal L_T(w_0,y)^2}\right\},
\end{align*}
then the following assertions hold for every $(w_0,y)\in H^b\times\mathsf Y_T$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item
On the open $H^b\times\mathsf Y_T$ ball
\begin{align*}
 B_{H^b\times\mathsf Y_T}
 \left((w_0,y),\frac{\delta_T(w_0,y)}2\right),
\end{align*}
the map $(x,\tilde y)\longmapsto
\bigl(v^{x,\tilde y},w_T^{x,\tilde y}\bigr)$ 
is twice Fr\'echet differentiable from $H^b\times\mathsf Y_T$ into
$C([0,T];H^b)\times H^b$, with continuous operator valued first and
second derivatives. In particular, for every
$\|(h,k)\|_{H^b\times\mathsf Y_T}<\delta_T(w_0,y)/2$,
\begin{align}
 \|w^{w_0+h,y+k}\|_{L^{p_\sigma}(0,T;H^b)}
 \le \mathbb W_T(w_0,y)+C_T.
\end{align}

\item
For $\mathsf p_0\in H$, put
\begin{align*}
 w^{\circ,x,\tilde y}
 &=v^{x,\tilde y}+\tilde y^\circ,
 \qquad
 \rho_t^{x,\mathsf p_0,\tilde y}
 =U_{w^{\circ,x,\tilde y}}(t,0)\mathsf p_0.
\end{align*}
Then
\begin{align*}
 (x,\mathsf p_0,\tilde y)\longmapsto
 \bigl(w_T^{x,\tilde y},\rho_T^{x,\mathsf p_0,\tilde y}\bigr)
\end{align*}
is locally twice Fr\'echet differentiable into $H^b\times H$, again
with continuous operator valued first and second derivatives. On the
open set where $\rho_T\ne0$, projective normalisation gives an
operator norm $C^2$ projective endpoint.

\item
Let
\begin{align*}
 \mathcal V_T:H^b\times\mathsf Y_T\longrightarrow C([0,T];H^b),
 \qquad
 \mathcal V_T(x,\tilde y)=v^{x,\tilde y}.
\end{align*}
For
$\|(h,k)\|_{H^b\times\mathsf Y_T}<\delta_T(w_0,y)/2$, set
\begin{align*}
 \Xi_1^{h,k}
 &=
 \bigl\|D\mathcal V_T(w_0+h,y+k)\bigr\|_
 {\mathcal L(H^b\times\mathsf Y_T,C([0,T];H^b))},\\
 \Xi_2^{h,k}
 &=
 \bigl\|D^2\mathcal V_T(w_0+h,y+k)\bigr\|_
 {\mathcal L^{(2)}(H^b\times\mathsf Y_T,C([0,T];H^b))},
\end{align*}
and put
\begin{align*}
 \mathcal X_T(w_0,y)
 =
 1+\sup_{\|(h,k)\|_{H^b\times\mathsf Y_T}<\delta_T(w_0,y)/2}
 \bigl(\Xi_1^{h,k}+\Xi_2^{h,k}\bigr).
\end{align*}
Then
\begin{align}
 \log\delta_T(w_0,y)^{-1}
 +\log^+\mathcal X_T(w_0,y)
 \le C_T\bigl(1+\mathbb W_T(w_0,y)^{q_\sigma}\bigr).
\end{align}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:47:12.027679+00:00","domain":"probability theory","id":"claim_371f0135a51e18d45ee20a8df672e0b0259323666003ec95cc9a3efdad5ffbc4","kind":"concept","schema_version":1,"statement":"[Theorem thm:3 of arXiv:2512.09219, 'Strong confluence of geodesics in Liouville quantum gravity'] Fix $\gamma\in (0,2)$ and consider a whole plane GFF $h$ and the associated LQG metric $D_h$. Fix $\varepsilon>0$. Then the following holds almost surely. For any points $u,v\in \mathbb{C}$, any $D_h$-geodesic $P$ from $u$ to $v$ and any sequence of $D_h$-geodesics $\{P_n\}_{n\in \mathbb{N}}$ converging to $P$ in the Hausdorff sense with respect to $D_h$\footnote{Or equivalently, with respect to the Euclidean metric and with Euclidean balls on the right side of (equation eq:14 of the paper). Indeed, since $\gamma\in (0,2)$, the $D_h$-metric is a.s.\ locally bi-H\"older with respect to the Euclidean metric (see Lemma (lem:holder_regularity of the paper)).}, for all $n$ large enough, we have
    \begin{equation}

      (P_n\setminus P)\cup (P\setminus P_n)\subseteq \mathcal{B}_\varepsilon(u)\cup \mathcal{B}_\varepsilon(v).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.434228+00:00","domain":"probability theory","id":"claim_372e4db53af94d55b9c147e55d223656f94854e7e1b1f8ccc798374802d50cfc","kind":"concept","schema_version":1,"statement":"[Lemma lem:grad of arXiv:2601.10568, 'Hydrodynamic Limit with a Weierstrass-type result'] Let $\ndef{\mathbf{J}_\beta}$ be the algebraic current, defined through $\mathcal{L}^{\beta,\ell_N}[\pi_0]=\nabla\tau^{-1}[-\mathbf{J}_{\beta,\ell_N}]$, where $\mathbf{J}_{\beta,\ell_N}$ is given, explicitly, by
\begin{align}
    \mathbf{J}_{\beta,\ell_N}
    =
    \frac{1}{\ell_N+1}
    \sum_{j=1}^{\ell_N}
    \mathbf{J}_{\beta}^j(\eta)
\quad\text{with}\quad
    \mathbf{J}_{\beta}^j(\eta)
    =\beta(\langle \eta\rangle_{j})
    (
    \mathbf{e}_{0,1}(\eta)
    -
    \mathbf{e}_{1,0}(\eta)
    )
    .
\end{align}

For each $\eta\in\Omega_N$, let $\ndef{P_{\ell_N}}(\eta)$ be the number of particles in the box $\llbracket0,\ell_N\rrbracket$. It holds that
\begin{align}
    \mathbf{J}_{\beta,\ell_N}=-\nabla \mathbf{H}_{\beta,\ell_N},
\end{align}
where $\mathbf{H}_{\beta,\ell_N}=\mathbf{h}_{\beta,\ell_N}+\mathbf{g}_{\beta,\ell_N}$ and 
\begin{align}

    \mathbf{h}_{\beta,\ell_N}(\eta)
    &=
    \frac{1}{\ell_N+1}
    \sum_{n=0}^{P_{\ell_N}(\eta)-1}
    \beta(\tfrac{n}{\ell_N})
    ,
    \\

    \mathbf{g}_{\beta,\ell_N}(\eta)
    &=
    \frac{1}{\ell_N+1}
    \sum_{j=1}^{\ell_N}
    \sum_{i=1}^{j}
    \tau^{-i}\mathbf{J}_{\beta,\ell_N}^j(\eta),

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

