{"assumptions":[],"created_at":"2026-10-27T05:30:36.800519+00:00","domain":"probability theory","id":"claim_3967a5b6d2afcfca73fe7a1500e6f9695aef01b3181410f022e1acacf59e3c64","kind":"concept","schema_version":1,"statement":"[Proposition 46 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] The process  
\[
 \bX_n(t)-\bX_n(0)-\int_0^t \bF_n(\bX_n(s))\, \d s =\int_0^t \newG_{0,n}(s,\bX_n(s))\,\d W(s),\;\; t \in [0,T],
\]
is a square integrable $\mathbb{H}_n$-valued martingale on the original probability space. 
\newline
If $f: \mathbb{R} \to \mathbb{C}$ is a $C^2_b$-class function and   $z \in \nU$, then the  following process 
    \begin{equation}
      h(\bX_n(t)) - h(\bX_n(0))-\int_0^t \mathscr{L}_{n,s}(h)(\bX_n(s))\,\d s,\;\; t \in [0,T],
   \end{equation}
where   the function $h:\nU^\prime \to \mathbb{C}$ has the following form,
\begin{equation}
    h(\bX)=f(\duality{\bX}{z}{}{}),\;\; \bX \in \nU^\prime
    \end{equation} 
 and $\mathscr{L}_{n,s}$ is given by
     \begin{equation}
         \mathscr{L}_{n,s} (h)(\bX) \coloneqq D h(\bX) \left[\bF_n(\bX)\right] 
         + \frac12 \sum_{k=1}^\infty D^2 h(\bX) \Bigl[[\newG_{0,n}(s,\bX)](\tilde{e}_k), [\newG_{0,n}(s,\bX)](\tilde{e}_k)\Bigr],\;\; \bX \in \nU^\prime,  
     \end{equation}
is a martingale. \newdela{NOTE: as written the sentence reads ``the function $h$ \dots\ and $\mathscr{L}_{n,s}$ \dots\ is a martingale'', but the martingale is the \emph{process} \eqref{eqn-h(X_n)}; $h$ and $\mathscr{L}_{n,s}$ are just its ingredients. Recommend rephrasing: ``\dots\ the process \eqref{eqn-h(X_n)}, where $h$ is given by \eqref{eqn-h} and $\mathscr{L}_{n,s}$ by \eqref{eqn-L_n}, is a martingale.''} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.713408+00:00","domain":"probability theory","id":"claim_3967a8365a4ac5b9c107f7d4b40f590238bc5b93bacc5a54bcf6477d1116de35","kind":"concept","schema_version":1,"statement":"[Lemma l:BL-limits-pp of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Let  $\tilde{\mathcal{P}}$  be a  marked point process on $\mathbb{R}^d\times\mathbb{K}$ with uniformly bounded  first correlation function  $\rho^{(1)}\le \kappa_1<\infty$.   Let $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat\mathcal{N}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ be a real-valued marking function (score) which is $L^1$-stabilizing on finite windows of $\tilde{\mathcal{P}}$ as in~(equation Lq-stab-windows of the paper) with $p=1$ and  satisfies the first  moment condition on finite windows as in ~(equation e:xinpmom of the paper) with $p=1$. 
\begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item  Then the ground point process marked by the score function 
$\xi$ on finite windows converges weakly in the vague topology to a stationary marking  $\tilde{\mathcal{P}}^\Upsilon$ of this ground point process on the entire space, i.e.,
\begin{equation}
\tilde{\mathcal{P}}^\xi_n=\sum_{x \in \mathcal{P}_n} \delta_{(x, \xi(\tilde{x}, \tilde{\mathcal{P}}_n))}
\xrightarrow[n \to \infty]{d}
\tilde{\mathcal{P}}^\Upsilon=\sum_{x \in \mathcal{P}} \delta_{(x, \Upsilon(x))}.
\end{equation}

\item  If moreover  for $p\in\mathbb{N}$ the input process $\mathcal{P}$ has finite moments of order $p+\epsilon$ for some $\epsilon>0$; i.e., $\mathbb{E} [\mathcal{P}(B)^{p+\epsilon}]<\infty$ for all $B\in\mathcal{B}_b$, with a uniformly bounded correlation function $\rho^{(p)}\le\kappa_p<\infty$, and $\xi$ satisfies~(equation Lq-stab-windows of the paper) then the  Palm distributions $\mathcal{M}_{\bk x1p}^{\Upsilon}$ of $\tilde{\mathcal{P}}^\Upsilon$ of order $p$ satisfy 
$$\mathcal{M}_{\bk x1p}^{\Upsilon}(\cdot) = \mathbb{P}\{\Upsilon_{\bk x1p} \in \cdot\}\quad \text{for $\rho^{(p)}(\bk x1p)\,\mathrm{d} \bk x1p$-almost all $\bk x1p\in\mathbb{R}^{dp}$,}$$
where $\Upsilon_{\bk x1p}$  are limits of  the Palm distributions of the score function $\bk{\xi}1p(\tilde{x},\tilde{\mathcal{P}}_n) \xrightarrow[n \to \infty]{\textnormal{BL},\bk x1p} \Upsilon_{\bk x1p}$ stated in~(equation e:BL-n-limit of the paper).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.654721+00:00","domain":"probability theory","id":"claim_396893a86853818c35cfb2518e50e2c08179b1a0855899cba035fc15a99cea78","kind":"definition","schema_version":1,"statement":"[Defn 8 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Consider the event $\{\mathcal C(0; \mathcal Q_{z, i}^c)=B\}$ for a given $B$.
\begin{itemize}
\item Denote by $\mathrm{Reg}_i(B)$ a maximal subset of $K$-regular points on $\partial \mathcal Q_{z, i}$ whose pairwise $\ell_\infty$-distances are at least $3K$. (If there is more than one possibility for this set, then we choose one arbitrarily according to some fixed procedure.)
\item For each $x \in  \mathrm{Reg}_i(B)$, we define $L_x$ to be a line segment of length $K$ extending from $x$ inside $\mathcal Q_{z, i}$, perpendicularly to the face upon which $x$ is sited. If $x$ lies within a distance $K$ from the intersection of at least two faces of $\mathcal Q_{z, i}$, then $L_x$ is defined to be the union of (at most) $d$ line segments inside $\mathcal Q_{z, i}$ of total length at most $dK$ that connect $x$ to a point that is at a distance $K$ from $\partial \mathcal Q_{z, i}$. Note that, since the vertices are separated by a distance at least $3K$, two distinct $L_x$ are separated by a distance at least $K$.
\item For each $x \in  \mathrm{Reg}_i(B)$, we consider the maximal line segment from $x$ that is contained in $L_x$ and formed by open edges. We write $L(B)$ for the union of all these line segments. (Note this is a random set, depending on $B$ and the configuration within $\mathcal Q_{z, i}$.)
\end{itemize}
A point $x\in \mathrm{Reg}_i(B)$ is said to be $K$-line good if all edges of $L_x$ are open. For such points, write $x'$ for the point of $L_x$ at maximal distance from $x$, and let $\mathrm{Reg}'_i(B)$ be the collection of such points. We write $X_{r,i}^{K-\mathrm{line-good}}$ for the number of $K$-line good points on $\partial Q_{z, (i\varepsilon+1)r}$. (See Figure \ref{fig:KLgooddef}.) Moreover, for the set $\mathcal Q_{z, i}^c$, we define the corresponding extended cluster by setting
\begin{align}
\mathcal C_e(0; \mathcal Q_{z, i}^c)=\mathcal C(0;\mathcal Q_{z, i}^c)\cup L(\mathcal C(0;\mathcal Q_{z, i}^c)). 
\end{align}","status":"unverified"}

