{"assumptions":[],"created_at":"2026-10-27T05:57:28.230620+00:00","domain":"probability theory","id":"claim_3c123d5d916b0ac37d94108befa02aab955638efc146ed82683f548c5efefca4","kind":"theorem","schema_version":1,"statement":"[Theorem 20 of arXiv:2607.18104, '2607.18104'] The periodic directed landscape
$\Lp \colon \{ (x,s;y,t)\in (\mathbb{T}\times [0,1])^2_{\uparrow}\}\rightarrow \R$ satisfies:

\begin{enumerate}
\item[\namedlabel{eq:Cond1}{(i)}] (Locally full-space directed landscape) Let $\mathcal{L}$ denote a full-space directed landscape. For any $r\in (0,1)$ there  exist $c,C>0$, such that for any $\varepsilon\in (0,1]$ and any rectangle $\mathcal{R}_{\varepsilon}=[a_{\varepsilon},a_{\varepsilon}+r]\times [b_{\varepsilon},b_{\varepsilon}+\varepsilon]$ with $a_{\varepsilon}\in \mathbb{T}$ and $b_{\varepsilon} \in [0,1-\varepsilon]$, we have that
\begin{equation}
\TV{ (\Lp(x,s;y,t))_{(x,s;y,t) \in (\mathcal{R}_{\varepsilon})^2_{\uparrow}} - (\mathcal{L}(x,s;y,t))_{(x,s;y,t) \in (\mathcal{R}_{\varepsilon})^2_{\uparrow} }} \leq C \exp( - c\varepsilon^{-1/2} ).
\end{equation} 
\item[\namedlabel{eq:Cond3}{(ii)}] (Independent increments) For all $(t_i)_{i\in \lbr \ell \rbr}$ and $(s_i)_{i \in \lbr \ell \rbr}$ with $\ell \in \N$ such that $\big((t_i,s_i)\big)_{i \in \lbr \ell \rbr}$ are disjoint subintervals of $[0,1]$, we have that the random functions $(t_i,s_i) \mapsto \Lp(\cdot,t_i;\cdot,s_i)$ are independent.  
\item[\namedlabel{eq:Cond4}{(iii)}] (Metric composition) Almost surely, for any $0 \leq s< r < t \leq 1$ and $x,y \in \mathbb{T}$
\begin{equation}
\Lp(x,s;y,t) = \sup_{z \in \mathbb{T}} \Big(\Lp(x,s;z,r) + \Lp(z,r;y,t) \Big).
\end{equation}
\end{enumerate}
Moreover, if we replace \hyperref[eq:Cond1]{(i)} by (the weaker assumption)
\begin{enumerate}
\item[\namedlabel{eq:Cond1prime}{(i')}] For some $r'\in (0,1)$ and some $\alpha>2$, there exists $C'>0$ such that for all $\varepsilon\in (0,1]$ and any rectangle $\mathcal{R}'_{\varepsilon}=[a'_{\varepsilon},a'_{\varepsilon}+r']\times [b'_{\varepsilon},b'_{\varepsilon}+\varepsilon]$ with $a'_{\varepsilon}\in \mathbb{T}$ and $b'_{\varepsilon} \in [0,1-\varepsilon]$, we have that
\begin{equation}
\TV{ (\Lp(x,s;y,t))_{(x,s;y,t) \in (\mathcal{R}'_{\varepsilon})^2_{\uparrow}} - (\mathcal{L}(x,s;y,t))_{(x,s;y,t) \in (\mathcal{R}'_{\varepsilon})^2_{\uparrow} }} \leq C'\varepsilon^{\alpha} .
\end{equation} 
\end{enumerate}
then any random field $\Lp$ supported on the space of continuous functions that satisfies properties \hyperref[eq:Cond1prime]{(i')}, \hyperref[eq:Cond3]{(ii)}, and \hyperref[eq:Cond4]{(iii)} must be a periodic directed landscape.","status":"unverified"}

