			\newuL \muX \ubar & = - \frac{1}{2} (\muX \upmu) \Lunit \ubar + \ReciprocaluLunitAppliedtoTimeFunction[\Lunit,\muX] \ubar -  \MagnitueofinnerproductofnewLandnewuL \angD^A \ubar \left[\geop{x^A},\muX\right] \ubar +  \frac{\muX \upmu}{2\Lunit \ubar} |\angD \ubar|_{\gtorus}^2 +\frac{\upmu}{2\Lunit \ubar} \left( \muX (\gtorus^{-1})^{AB}\right) \geop{x^A} \ubar \geop{x^B} \ubar,  \\ 
