{"assumptions":[],"created_at":"2026-10-27T19:55:37.870427+00:00","domain":"probability theory","id":"claim_3c931d3c75106f6099c3336d871c27974acab279c0a54353a695182a88360a7f","kind":"lemma","schema_version":1,"statement":"[Lemma integral_bound of arXiv:2605.06511, 'Logarithmic Mixing of Random Walks on Dynamical Random Cluster Models'] For all $n \in \mathbb{N}$ sufficiently large, $\mu > 0$ and $\Delta > 0$ such that $\mu \Delta > 2 \log 2$,
		\begin{equation*}
			\int_{0}^{\Delta} \frac{\mu e^{\mu x}}{e^{\mu \Delta} - 1} \left(p + (1-p)e^{-\mu x}\right)^{r - 1} \text{d} x \leq e^{-{\mu \Delta}/{2}} + O\left((\log n)^{-3}\right).
		\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.768616+00:00","domain":"probability theory","id":"claim_3c938206aabead94850fc8d9bc3f97be2d8917e5eaf8b6d5ecdf954914fec0cb","kind":"definition","schema_version":1,"statement":"[Definition 22 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $T_1 \in \mathbb{N}$, $\vec{y} \in \mathfrak{W}_2$, $q \in (0,1)$, $c \in [0, q^{-1})$. Let $\Omega_{\ice}(T_1, \vec{y})$ be as in (\ref{Eq.InteractingPairStateSpace}), and define the probability measure on $\Omega_{\ice}(T_1, \vec{y})$ via
\begin{equation}
\mathbb{P}^{T_1, \vec{y}}_{\ice; q,c} (\mathfrak{B}) = \frac{W(\mathfrak{B};q,c) }{Z(T_1, \vec{y}; q,c)}, \mbox{ for } \mathfrak{B} \in \Omega_{\ice}(T_1, \vec{y}).
\end{equation}
In (\ref{Eq.InteractingPairLaw}) we have that $W(\mathfrak{B};q,c)$ is as in (\ref{Eq.InteractingPairWeight}), $Z(T_1, \vec{y}; q,c)$ is as in (\ref{Eq.FinitePartitionFunction}), and $\mathbb{P}^{T_1, \vec{y}}_{\ice; q, c}$ defines a probability measure on $\Omega_{\ice}(T_1, \vec{y})$ in view of Lemma \ref{Lem.FinitePartitionFunction}. If $\mathfrak{L} = (L_1,L_2)$ is a geometric line ensemble with law $\mathbb{P}^{T_1, \vec{y}}_{\ice; q,c}$, we refer to it as an {\em interacting pair of reverse interlacing geometric random walks with parameters $q,c$} or simply as an {\em interacting pair} for short.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.075139+00:00","domain":"probability theory","id":"claim_3ca8166f9f326b5348c5f6fa506d5e7cd6ad5fd2c6de9cfb859573529a30c4ae","kind":"concept","schema_version":1,"statement":"[Prop effective-cost-deformation of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Assume that the masses $(m_e)_{e\in \mathbb{Z}^2}$ vanish outside $\Lambda_n$ and are bounded by (some small) enough $m>0$ inside $\Lambda_n$. Then for any $0\leq t\leq \frac{1}{n}$, any corner $\frak{p}\in \Lambda_{2n}$, any $v_1\neq v_2 \in \Lambda_{2n}$ one has:
		\begin{enumerate}[label=(\roman*)]
	\item The deviation of $\mathcal{Y}^{(t)}$ can be bounded via
\begin{equation}
| \mathcal{Y}^{(t)}(\frak{p}) - \mathcal{Y}^{(0)}(\frak{p})| \leq  \frac{ 0.1}{n^\frac{1}{2}} \times nt
\end{equation}
\item The embedding  $\mathcal{S}^{(t)}(\Lambda_{2n})$ is proper, and distances in $\mathcal{S}^{(t)}$ satisfy
\begin{equation}
	0.9\leq \frac{|\mathcal{S}^{(t)}(v_1)-\mathcal{S}^{(t)}(v_2)|}{|\mathcal{S}^{(0)}(v_1)-\mathcal{S}^{(0)}(v_2)|} \leq 1.1
\end{equation}
\item The embedding $\mathcal{S}^{(t)}(\Lambda_{2 n})$ satisfies {\mbox{\textsc{Unif(}$\frac{1}{n},10,\frac{\pi}{10}$\textsc{)}}}\,.\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:54:28.041793+00:00","domain":"probability theory","id":"claim_3ca8fa5b6ffbad50473f378ac124f2cac396d7b996d4751098485e00a1aeac43","kind":"concept","schema_version":1,"statement":"[Lemma sup-rosenthal of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] Let $\mathcal{F}$ be a countable class of non-negative functions defined on some measurable set $\mathcal{X}$. Let $X_1, \ldots, X_N$ denote  a collection of $\mathcal{X}$-valued independent random variables. Let $Z = \sup_{f \in \mathcal{F}}\sum_i f(X_i)$ and
    \begin{align*}
        M = \max_{1 \leq i \leq N} \sup_{f \in \mathcal{F}} f(X_i)\,.
    \end{align*}
    Then, for all $p \geq 2$ and $\theta \in (0, 2)$,
    \begin{align*}
        \|Z\|_p \leq (1 + \theta)\mathbb E Z + cp\left(1 + \frac{1}{\theta}\right)\|M\|_p\,,
    \end{align*}
    where $c$ is an absolute constant. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.731733+00:00","domain":"probability theory","id":"claim_3caaa39b12dd7c2276057ae17d17d3c5f832d2efbca780f8c46dc681e63c3a9d","kind":"theorem","schema_version":1,"statement":"[Corollary coro:entropy-initial-bound of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Fix $\alpha >1$ and suppose that $\theta> \theta_{0,L}(\alpha)$. Then, the density $\tilde\rho_t$ of $\tilde X_t$, starting at $\tilde\rho_0$
