{"assumptions":[],"created_at":"2026-10-26T19:22:46.461196+00:00","domain":"probability theory","id":"claim_3cb99624435a590ad3814ec52735de4e3fad06c996999e84b9bdeb07e0132147","kind":"definition","schema_version":1,"statement":"[Definition 15 (The higher order fluid variables) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill

\begin{enumerate}
\item We define the \emph{specific vorticity} to be the $\Sigma_t$-tangent vectorfield whose Cartesian spatial components are:
\begin{align} 
	\vortrenormalized^i 
	& \eqdef 
	\frac{(\Flatcurl v)^i}{\exp(\LogDensity)} 
	= 
	\frac{\upepsilon_{ijk} \updelta^{jl}\p_lv^k}{\exp(\LogDensity)},
\end{align}
where $\updelta^{jl}$ is the Kronecker delta.
\item We define the \emph{entropy gradient} to be the $\Sigma_t$-tangent vectorfield whose Cartesian spatial components are: 
	\begin{align} 
		\GradEnt^i 
		& \eqdef \updelta^{ia}\p_a \Ent = \p_i \Ent.
	\end{align}
\item We define the \emph{modified fluid variables} to be the $\Sigma_t$-tangent vectorfield $\VortVort$ and the scalar function 
$\DivGradEnt$ whose Cartesian spatial components are:
\begin{subequations}
	\begin{align} 
		\VortVort^i
		& \eqdef
			\exp(-\LogDensity) (\Flatcurl \vortrenormalized)^i
			+
			\exp(-3\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^a \partial_a v^i
			-
			\exp(-3\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} (\Flatdiv v) \GradEnt^i,
				\\
		\DivGradEnt 
		& \eqdef 
			\exp(-2 \LogDensity) \Flatdiv \GradEnt 
			-
			\exp(-2 \LogDensity) \GradEnt^a \partial_a \LogDensity.

\end{align}
\end{subequations}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:32:58.374970+00:00","domain":"probability theory","id":"claim_3cb9df72333b36c1e485c4c0e31ac244f6399ebc2df391b5fb8f4cefb1f60051","kind":"lemma","schema_version":1,"statement":"[Lemma sam of arXiv:2506.06559, 'Bi-infinite incipient cluster in high dimensions'] {{Let $\textbf G$ be a diagrammatic graph which contains the labels $u, v$, and let $b \in \mathbb{Z}^d$.}} Then 
