	\bigg\}
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big) \nonumber\\
	&\qquad\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(q_d)^{1/2}
	\bbb^{\frozen,\coarse,N}(q_d, B^{\frozen,\coarse}) 
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big)

	\end{align}
with $B^{\frozen,\coarse}=B^{\frozen,\coarse}(q_d,J_{\vl})$ as defined by \eqref{e:coarsened.bucket}, and recalling that the last term above factorizes as in \eqref{e:a.i.factorization}. We similarly define measures $\rho_{V,N}$, $\rho_{U,N}$, 
$\rho_{\www,N}$,
and $\rho_{\rrr,N}$
 using increments of 
$\tilde{Q}^{\frozen,\RomII,N}$, $\tilde{Q}^{\frozen,\RomII,\RomIII,N}$, $\tilde{Q}^{\frozen,\Ising,N}$, and 
$C^{\frozen,\RomIII,N}$ respectively.","status":"unverified"}

