{"assumptions":[],"created_at":"2026-10-26T20:56:49.281238+00:00","domain":"probability theory","id":"claim_3f45efc7084ea59b8e4150ce59853ee2f305766268ef5189ac3afc5980946bcf","kind":"theorem","schema_version":1,"statement":"[Proposition 24 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For any $\nu\in \eP(T)$, let
\begin{align*}
	H_{\epsilon}(\nu)\deq \sup_{\rho\in B_{{\rm TV}}(\nu,\epsilon) }H(\rho)
\end{align*}
where
\begin{align}
	B_{{\rm TV}}(\nu,\epsilon) \deq \left\{ \mu \in \eP(T): \lVert \mu - \nu \rVert_{{\rm TV}} \le \epsilon \right\}
\end{align}
is the closed ball of radius $\epsilon$ with respect to total variation distance centered at $\nu$.
  For any $\epsilon \in [0,1-\frac{1}{\abs{T}}]$, let $\omega(\epsilon)
  \deq \epsilon \log (\abs{T}-1) + h(\epsilon) $
  where $h(\epsilon) \deq -\epsilon \log \epsilon - (1-\epsilon)\log (1-\epsilon)$ is the binary entropy function.
 \begin{enumerate}
   \item 
     Given any $\nu\in \eP(T)$ and $\epsilon, \delta \in [0, 1-\frac{1}{\abs{T}}]$, 
     \begin{align*}
      H_{\epsilon}(\nu) \le H_{\epsilon+\delta}(\nu)\le H_{\epsilon}(\nu) + \omega(\delta)
     \end{align*}
  \item For any $\epsilon,\delta \in [0, 1-\frac{1}{\abs{T}}]$,
    \begin{align*}
    \sup_{\rho,\nu:\, \lVert \rho-\nu \rVert_{\rm TV}\le \delta} 
    \abs{H_\epsilon(\rho)- H_{\epsilon}(\nu)} \le \omega(\delta)
    \end{align*}

 \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.659516+00:00","domain":"probability theory","id":"claim_3f47aa81cd2a1496ebfb923a80f2fff301a9ee355a987b6db17f9fbe7bb1b151","kind":"lemma","schema_version":1,"statement":"[Lemma 24 of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $\bLambda \in \R^{m \times n}_{\ge 0}$ be a  matrix with $\bLambda_{ij} = 0$ if and only if $\r(i)\c(j) = 0$. Let $\bar{\bLambda} := \bLambda/\|\bLambda\|_1$, $(\bar{\r}, \bar{\c}) := (\r/N, \c/N)$ with $N=\sum_{i} \r(i)=\sum_{j} \c(j)$, and $\bar{\kappa}(i,j) := \log(\bar{\r}(i)\bar{\c}(j)/\bar{\bLambda}_{ij})$ (with the convention $0/0=1$). 
	Then a canonical choice of matrix-scaling potentials $(\balpha, \bbeta)$ (fixing the gauge $\sum_j \bar{\bbeta}(j)\bar{\c}(j) = 0$ in the normalized problem below) satisfies
	\begin{align}
		-2(\bar{\kappa}_{\textup{-}} + \bar{\kappa}_{\textup{+}}) + \log\!\left(\tfrac{N}{\|\bLambda\|_1}\right) \;\le\; \balpha(i) + \bbeta(j) \;\le\; 2\bar{\kappa}_{\textup{+}} + \log\!\left(\tfrac{N}{\|\bLambda\|_1}\right).
	\end{align}
	In particular, \begin{align}
		\tfrac{e^{-4 \| \bar{\kappa}\|_{\infty} } N}{\|\bLambda\|_1} \;\le\; e^{\balpha(i)+\bbeta(j)} \;\le\; \tfrac{e^{2 \| \bar{\kappa}\|_{\infty} } N}{\|\bLambda\|_1} \qquad \text{for all } i,j.
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.289953+00:00","domain":"probability theory","id":"claim_3f48101dc2f9ee35cac1d0fb1992625d9d98bdbe43e50f7186a8c83d6d7e03e8","kind":"concept","schema_version":1,"statement":"[Lemma lem:core of invariant lower probabilities of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] Let $(\Omega,\mathcal{F},V,T)$ be an UPPS. Then
	\begin{enumerate}
		\item[(i)]	given any $P\in \operatorname{core}(V)$, there exists a unique $\widehat{P}\in \mathcal{M}(T)\cap\operatorname{core}(V)$ such that $P(A)=\widehat{P}(A)$ for any $A\in\mathcal{I}$;
		\medskip
		\item[(ii)] given $A\in\mathcal{F}$, if for any $P\in\operatorname{core}(V)$, $\widehat{P}(A)=0$, then $V(A)=0$.
	\end{enumerate}
	If we further assume that $V$ is ergodic, then $\mathcal{ M}(T)\cap \mathrm{core}(V)$ has only one element, denoted by $Q$, which is ergodic, and  $V\ll Q$, i.e., for any $A\in\mathcal{F}$,  $Q(A)=0$ implies that $V(A)=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:37:28.987382+00:00","domain":"probability theory","id":"claim_3f4856c32cf29875e397475c3ac446d6a93f6858050379b149afd5328da40dea","kind":"concept","schema_version":1,"statement":"[Theorem thm:MKT-beta-ensembles of arXiv:2412.01015, 'Classical beta ensembles and related eigenvalues processes at high temperature and the Mar'] Denote by $\mu_c^{(G)}$, $\mu_c^{(L)}$ and $\mu_c^{(J)}$ the limiting measure in the high temperature regime $\beta = 2c/N$ of the empirical distribution of Gaussian beta ensembles, beta Laguerre ensembles and beta Jacobi ensembles~(equation joint-density of the paper), respectively. Here $c\in (0, \infty)$ is given. Then the following hold.
