{"assumptions":[],"created_at":"2026-10-27T15:46:00.357199+00:00","domain":"probability theory","id":"claim_3f4dfc52623e06b642e23e1b453d86844560c87201cf930f76ce8b4e2e0cc525","kind":"lemma","schema_version":1,"statement":"[Lemma lem:01 of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Let $w, \tau: I \times I \to [0\,,\infty)$ be two continuous functions that vanish on the diagonal and are strictly positive near but off the diagonal.
    Suppose $\sigma$ defined by (equation sigma of the paper) is continuous on $I \times I$.
    \begin{enumerate}[$(i)$]
        \item If 
        \begin{align}
            \lim_{h \to 0^+} \sup_{t,s \in I: 0<\tau(t,s)\le h} \frac{\sigma(t\,,s)}{w(t\,,s)} = 0,
        \end{align}
        then there is a non-random number $C \in [0\,,\infty]$ such that
        \begin{align}
            \lim_{h \to 0^+} \sup_{t,s \in I: 0<\tau(t,s)\le h} \frac{|X(t)-X(s)|}{w(t\,,s)} = C \quad \text{a.s.}
        \end{align}
        \item Fix $t_0 \in I$. If
        \begin{align}
            \lim_{h \to 0^+} \sup_{t \in I: 0<\tau(t,t_0)\le h} \frac{\sigma(t\,,t_0)}{w(t\,,t_0)} = 0,
        \end{align}
        then there is a non-random number $C(t_0) \in [0\,,\infty]$ such that
        \begin{align}
            \lim_{h \to 0^+} \sup_{t \in I: 0<\tau(t,t_0)\le h} \frac{|X(t)-X(t_0)|}{w(t\,,t_0)} = C(t_0) \quad \text{a.s.}
        \end{align}
    \end{enumerate}","status":"unverified"}

