{"assumptions":[],"created_at":"2026-10-27T06:25:55.318168+00:00","domain":"probability theory","id":"claim_3f7453a9124b3efabe3c3a884ce522c963c3632e6090d33161cde7cf5b32ddcf","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $n\ge 1$ and $\bs{\theta}=(\theta_1, \ldots, \theta_{n})\in\LX_{n}$. Define 
\begin{align}
\varphiradial{n}(z)=-\frac{1}{2}\sum_{j=1}^n\arg\left(\frac{\ee^{\ii\theta_j}-z}{1-\overline{z}\ee^{\ii\theta_j}}\right)+\frac{n}{2}\arg(z), \quad z\in\U\setminus \{0\}. 
\end{align}
Then
\begin{align}
\| \varphiradial{n}\|_{\nabla(\U),\mathrm{reg}}^2=-2\pi \sum_{1\le i<j\le n} \log \left| \ee^{\ii\theta_i}-\ee^{\ii\theta_j} \right|.
\end{align}
Moreover, its regularized Dirichlet energy is related to the partition function $\LZradial{n}$ in~\eqref{eqn::LZunitdisc_def}:
\begin{align*}
\LZradial{n}(\bs{\theta})=\exp\left(-\frac{1}{4\pi}\| \varphiradial{n}\|_{\nabla(\U),\mathrm{reg}}^2\right)=\prod_{1\le i<j\le n}\left|\ee^{\ii\theta_i}-\ee^{\ii\theta_j}\right|^{\frac{1}{2}}. 
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:30:36.797228+00:00","domain":"probability theory","id":"claim_3f74c504af95d77460252577f2cede220aecca881237b8868adebf51095f768b","kind":"definition","schema_version":1,"statement":"[Definition 33 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $E$ is a normed vector space, e.g. $E=\nU^\prime$,  and 
 $\bu \in C([0,T];E)$. The modulus of continuity of  $\bu$  on $[0,T]$ is defined by:
  \begin{equation*}
    \mc_{E}(\bu,\delta)= \sup_{s,\,t \in[0,T],\; \lvert t-s \rvert \leq \delta} \Vert \bu(t) - \bu(s) \Vert_{E}, \quad 0< \delta \leq 1.
  \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.735986+00:00","domain":"probability theory","id":"claim_3f7681759245e7567a274546335a2cf1ae9fe7f96558fcb8b930cbfb4a30db91","kind":"concept","schema_version":1,"statement":"[Prop 29 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Let $\alpha > 1$ and let $\tilde \Pi_z^\eps \<bs(2)0>$, $\tilde \Pi_z^\eps \<ps(2)0>$ be given as in the statement of Theorem~\ref{theo: bphz_uniform_bound} with $\delta = \eps^\alpha$. Define
	\begin{equs}
		\mfm_{\<bsq>} := \widehat{H_0}\, (\widehat \rho - 1)\, \overline{\widehat{\rho}}\;, &\quad
		\mfm_{\<psq>} := \widehat{H_0}\, (\widehat \rho - 1)\;, \\
		\intertext{as well as}
		c_{\<bsq>} := 2 (2\pi)^{-2}\int_{\mbR \times \mbR} |\mfm_{\<bsq>}|^2(\tau, k) d\tau dk\;, &\quad
		c_{\<psq>} := 2 (2\pi)^{-2}\int_{\mbR \times \mbR} |\mfm_{\<psq>}|^2(\tau, k) d\tau dk\;, \\
		c_{\<halfsq>} := 2 (2\pi)^{-2}& \int_{\mbR \times \mbR} (\mfm_{\<bsq>} \mfm_{\<psq>}) (\tau, k) d\tau dk\;. 
	\end{equs}
	Then $(\xi_\eps, \tilde \Pi_z^\eps \<bs(2)0>, \tilde \Pi_z^\eps \<ps(2)0>)$ converges jointly in law in $(C^{-3/2- 2\kappa})^3$ to $(\xi, \tilde \xi_{\<bsq>}, \tilde \xi_{\<psq>})$ which is a jointly Gaussian triple of random distributions such that for test functions $\varphi_1, \varphi_2, \varphi_3$, the covariance matrix of $(\xi(\varphi_1), \tilde \xi_{\<bsq>}(\varphi_2), \tilde \xi_{\<psq>}(\varphi_3))$ is given by
	\begin{equ}[eq:covariance]
		\begin{pmatrix}
			\|\varphi_1\|_{L^2}^2 & 0 & 0 \\
			0 & c_{\<bsq>} \|\varphi_2\|_{L^2}^2 & c_{\<halfsq>} \langle \varphi_2, \varphi_3 \rangle_{L^2} \\
			0 & c_{\<halfsq>} \langle \varphi_2, \varphi_3 \rangle_{L^2} & c_{\<psq>} \|\varphi_3\|_{L^2}^2
		\end{pmatrix}\;.
	\end{equ}

	In particular, it holds that
	\begin{itemize}
		\item $c_{\<bsq>}, c_{\<psq>}$ are strictly positive;
		\item $c_{\<halfsq>}, c_{\<bsq>}, c_{\<psq>}$ depend only on the mollifier $\rho$ (in particular, they are independent of $\alpha$);
		\item $|c_{\<halfsq>}| < \sqrt{c_{\<bsq>} c_{\<psq>}}$ and $c_{\<bsq>} < c_{\<psq>}$ for every $\rho$.
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

