{"assumptions":[],"created_at":"2026-10-27T22:11:11.724859+00:00","domain":"probability theory","id":"claim_4037314d064d4c0a671abc44aff2748ff04b53e9bea62594ade372c0db905758","kind":"lemma","schema_version":1,"statement":"[Lemma lem:vd-l2-polygonal-poisson of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Let $\varrho\in L^2(\Omega)$, and let $\phi\in H^1_0(\Omega)$ be the unique weak solution of the Poisson problem
\begin{align}
 &-\Delta\phi=\varrho
 \quad\hbox{in }\Omega.

\end{align}
For each reentrant vertex $V_m$, recall from (equation eq:intro-zero-ray-pairs-comp of the paper) that $\lambda_{m,1}=\pi/\omega_m\in(\frac12,1)$. There are fixed cutoffs $\chi_m^{\rm D}\in C_c^\infty(B_{2\ell_{\mathrm{vtx}}}(V_m))$, equal to one in $B_{\ell_{\mathrm{vtx}}}(V_m)$ and supported in pairwise disjoint vertex neighborhoods so small that $\operatorname{supp}\chi_m^{\rm D}$ meets only the two side collars incident to $V_m$, and coefficients $c_m\in\mathbb R$, such that $\phi$ has the singular decomposition
\begin{align}
 &\phi
 =
 \phi_{\rm reg}
 +\sum_{m:\,\omega_m>\pi}
 c_m\chi_m^{\rm D}
 r_{m}^{\lambda_{m,1}}
 \sin(\lambda_{m,1}\theta_m),
 \qquad
 \phi_{\rm reg}\in H^2(\Omega).

\end{align}
With $\nm{\nabla_x\phi}_{L^2_{\rm pw}(\partial\Omega)}^2:=\sum_j\nm{\nabla_x\phi\big|_{E_j}}_{L^2(E_j)}^2$, its parts are controlled by the data:
\begin{align}
 &\nm{\phi_{\rm reg}}_{H^2(\Omega)}
 +\sum_{m:\,\omega_m>\pi}\abs{c_m}
 +\nm{\nabla_x\phi}_{L^2_{\rm pw}(\partial\Omega)}
 \leq C_\Omega\nm{\varrho}_{L^2(\Omega)}.

\end{align}
Moreover the range of exponents
\begin{align}
 &\frac43<p_{\rm P}\leq2,
 \qquad
 p_{\rm P}<\frac{2}{2-\lambda_{m,1}}
 \quad\hbox{for every }m\hbox{ with }\omega_m>\pi,
 \qquad
 p_{\rm P}':=\frac{p_{\rm P}}{p_{\rm P}-1},

\end{align}
is nonempty, and for every $p_{\rm P}$ in it the Hessian obeys
\begin{align}
 &\nm{D_x^2\phi}_{L^{p_{\rm P}}(\Omega)}
 \leq C_{\Omega,p_{\rm P}}\nm{\varrho}_{L^2(\Omega)},

\end{align}
with the conjugate-exponent gain
\begin{align}
 &\frac{2}{p_{\rm P}'}=2-\frac{2}{p_{\rm P}}
 >\frac12.

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.213192+00:00","domain":"probability theory","id":"claim_403761d3a128d14d8012974674b7e4e7c1e3567b30e72b82add814b387b5181d","kind":"concept","schema_version":1,"statement":"[Theorem theo:limitcrowkimura of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] Assume that $g(x): \mathbb{R}^m \rightarrow \mathbb{R}^m$ and $h(x): \mathbb{R}^m \rightarrow \mathbb{R}^n$ are $C^2$, globally Lipschitz continuous functions satisfying linear growth conditions, i.e. there exists a constant $C > 0$ such that 
	\begin{align*}
		\| h(x) - h(y) \| + \|g(x) - g(y) \| &\leq C\|x - y\|, \enskip x, y, \in \mathbb{R}^m \\
		\| h(x)\| + \|g(x) \| &\leq C(1 + \|x \|), \enskip x \in \mathbb{R}^m
	\end{align*}
	Let $\Sigma$ and $\Xi$ be $m \times m$ and $n \times n$ positive definite matrices respectively. 
	Denote by $\mu_t^d(x)$ the solution to the unnormalised Crow-Kimura replicator-mutator equation with time-varying fitness landscape (equation eq:genquadfit of the paper) with $s < r, r >0$
	\begin{align}
		\nonumber 

		\partial_t \mu_t^d(x) &= \mathcal{L}^\ast \mu_t^d(x) +  \mu_t^d(x) \mathbb{E}_{z \sim \mu_t^d}[f_{t}(x,z)] \\

		& =  \mathcal{L}^\ast \mu_t^d(x) -\frac{r}{2}\|h(x) - \frac{dZ_t^d}{dt}\|_{\Xi}^2 \mu_t^d(x) + s \left \langle h(x) - \frac{dZ_t^d}{dt}, h(z) - \frac{dZ_t^d}{dt} \right \rangle_{\Xi} \mu_t^d(x)
	\end{align}
	Let $q_t(x)$ denote the solution of the modified Zakai equation (presented here in Ito form), 
	\begin{align}



		d q_t = \mathcal{L}^\ast q_t(x) -\frac{s}{2}h(x)^\top \Xi^{-1} h(x) q_t(x)  + (r-s)q_t(x) h(x)^\top \Xi^{-1} dZ_t. 
	\end{align}
	Suppose also that $q_0(x) = \mu_0^d(x) = f(x)$ where $f$ is a uniformly bounded $C^\infty$ probability density function.  Then for any $T > 0$, 
	\begin{align}

		\lim_{d \rightarrow \infty} \mathbb{E} \left[ \sup_{0 \leq t \leq T} |\mu_t^d(x) - q_t(x) |^p\right] = 0, \quad \forall \enskip x \in \mathbb{R}^m 
	\end{align}
	for $p \geq 1$ and $r,s$ additionally satisfying $r-s < \frac{2}{ tC(1+ \mathbb{E}^\mathbb{Q}[|x|^2])p \lambda_\Xi^2 r_1r_2} $, where $r_1,r_2 >1$ and $1/r_1 + 1/r_2 = 1$ and $C$ depends on the linear growth constant of $h(x)$. 
	Importantly, when $r=1, s = 0$, (equation eq:repmutnonlin of the paper) converges to the standard Zakai equation (equation eq:zakai of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

