{"assumptions":[],"created_at":"2026-10-27T18:44:24.695924+00:00","domain":"probability theory","id":"claim_4059f3d49bfd6bb56fc11bceddab01b2f4f213d1eaa21102a4ad45f24d7b6290","kind":"theorem","schema_version":1,"statement":"[Theorem thm:homogeneous_theorem of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For the $\alpha$-stable random band  matrices   in Definition (defmodel of the paper), but with Gaussian entries and  $\alpha>d=1$, assuming that $\sum_{i=1}^s n_i$ is even   and   $t_i\in (0,\infty)$ with   $i=1,\ldots,s$,   for any given {typical} connected diagram $\Gamma\in \mathcal{T}_s$ the following hold:
    \begin{itemize}
        \item[(i)]
({\bf Supercritical case})
    If  $W\gg N^{1-\frac{1}{3\alpha}}$  and all $n_i\sim t_i N^{\frac{1}{3}}$, then
    \begin{equation}
        \frac{1}{n_1\cdots n_s}F_\Gamma(\{n_i\}_{i=1}^s)=
        \big(1+o(1)\big)\mathcal{F}^{\mathrm{(Super)}}_\Gamma(t_1,\dots,t_s).
    \end{equation}

 \item[(ii)]({\bf Subcritical case}) If $(\log N)^{\frac{1}{\alpha}}\ll W\ll N^{1-\frac{1}{3\alpha}}$ and all $n_i\sim t_i W^{\frac{\alpha}{3\alpha-1}}$, then
    \begin{equation}
    \begin{aligned}
\frac{1}{n_1\cdots n_s} F_\Gamma(\{n_i\}_{i=1}^s)
 &=   \big(1+o(1)\big)NW^{-\frac{3\alpha}{3\alpha-1}}\mathcal{F}^{\mathrm{(Sub)}}_\Gamma(t_1,\dots,t_s).
\end{aligned}
    \end{equation}

\item[(iii)] ({\bf Critical case})
       If $W\sim   (\gamma N)^{1-\frac{1}{3\alpha}}$ for some $\gamma>0$ and all  $n_i\sim t_i W^{\frac{\alpha}{3\alpha-1}}$, then
    \begin{equation}
        \frac{1}{n_1\cdots n_s}F_\Gamma(\{n_i\}_{i=1}^k)=   \big(1+o(1)\big)\gamma^{|E|-|V|}\mathcal{F}^{\mathrm{(Crit)}}_\Gamma(t_1,\dots,t_s;\gamma^\alpha).
    \end{equation}
 \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:06:55.288722+00:00","domain":"probability theory","id":"claim_4065391dedf93a87e7c319cdd673d85b2a3baa27640593f02339bb03d923c0f5","kind":"definition","schema_version":1,"statement":"[Defi def:relEnt of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] For $\varphi\in \mathcal D_\pi(\ensuremath{\mathbb{Z}})$ we define the \emph{relative entropy} and ($M$-)\emph{Fisher information} 
