        |w_n-\widehat w_n|\leq C' \alpha^n\quad\text{for all }n\in \mathbb N.
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:53.156640+00:00","domain":"probability theory","id":"claim_4317e43e100aa8029682bfc821cfe736cdfda1958a4074d660380a9d648dd127","kind":"definition","schema_version":1,"statement":"[Definition 6 of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For strict partitions $\mu,\lambda$ with $\mu\subseteq\lambda$, set
