{"assumptions":[],"created_at":"2026-10-27T12:59:58.440255+00:00","domain":"probability theory","id":"claim_43c857355f1db50b366fbe7ef8e3788232208fd5f190383fad0f83d9dead2417","kind":"definition","schema_version":1,"statement":"[Definition XY and XY/Villain models on a site percolation configuration of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] We fix an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \geq 2$, a pair of inverse temperatures $\beta_1 , \beta_2 > 0$, a percolation configuration $r \in \{0,1\}^{\Lambda_L}$, and introduce:
\begin{itemize}
    \item The XY model on the extended lattice $\ensuremath{\mathbb{Z}^d}_n$ on a percolation configuration:
\begin{multline*}
    \mu_{\Lambda_L^n, n, \beta_1 , \beta_2, r}^{\mathrm{XY}}(d\theta) := \frac{1}{Z_{\Lambda_L^n, n, \beta_1,  \beta_2, r }^{\mathrm{XY}}}\exp \left( \beta_1  \sum_{\substack{x \sim_n y \\ x \in  \ensuremath{\mathbb{Z}^d}}} r_x \cos (\theta_x - \theta_y)\right)\\  \times \exp \left( n \beta_2 \sum_{\substack{x \sim_n y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} \cos (\theta_x - \theta_y) \right) \prod_{x \in \Lambda_L^n} d \theta_x.
\end{multline*}
    \item The XY/Villain model on a percolation configuration:
    \begin{equation*}
        \mu_{\Lambda_L^3, \beta_1 , \beta_2, r}^{\mathrm{XY/Vil}}(d\theta) := \frac{1}{Z_{\Lambda_L^3, \beta_1 , \beta_2, r }^{\mathrm{XY/Vil}}}\exp \left( \beta_1  \sum_{\substack{x \sim_3 y \\ x \in \ensuremath{\mathbb{Z}^d}}} r_x \cos (\theta_x - \theta_y) \right) \prod_{\substack{x \sim_3 y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} v_{\beta_2}(\theta_x - \theta_y) \prod_{x \in \Lambda_L^3} d \theta_x.
    \end{equation*}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:05:37.770085+00:00","domain":"probability theory","id":"claim_43cd15f5dd436b84d7fb47f207081937dc101e494af418b5c44fe09763046684","kind":"theorem","schema_version":1,"statement":"[Proposition GBSDE-propo3 of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] Let $\xi^1_T$ and $\xi^2_T$ be two terminal conditions\footnote{In the sense of condition \textbf{(H1)$_T$} above. In the present comparison result, only the measurability condition \textbf{(H1)$_T$}-(i) is needed; no integrability assumption is used in the proof.}, and let
