{"assumptions":[],"created_at":"2026-10-27T21:31:49.907032+00:00","domain":"probability theory","id":"claim_44c616a3dcb99d7858d4de8ec2d348d9f9c11c889c1e1ed6e393bf16ddd128a4","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] Suppose (ass:xi,ass:alpha,ass:scale of the paper) hold.  Then, for every fixed $x>0$, the following limits hold.

\medskip
\noindent\textbf{Right tail.}
\begin{enumerate}[label=\textup{(R\arabic*)},leftmargin=3.2em]
\item If $\theta_N^+\to\infty$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^{3/2}}
 \log\mathbb P(Z_N>a_Nx)=-\frac43x^{3/2}.
\end{equation}

\item If $\theta_N^+\to\theta\in(0,\infty)$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^{3/2}}
 \log\mathbb P(Z_N>a_Nx)=-J_+^{(\theta)}(x).
\end{equation}

\item If $\theta_N^+\to0$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{\alpha_N^2a_N^2}
 \log\mathbb P(Z_N>a_Nx)=-\frac{x^2}{2\sigma^2}.
\end{equation}
\end{enumerate}

\medskip
\noindent\textbf{Left tail.}
\begin{enumerate}[label=\textup{(L\arabic*)},leftmargin=3.2em]
\item If $\theta_N^-\to\infty$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^3}
 \log\mathbb P(Z_N\le-a_Nx)=-\frac1{12}x^3.
\end{equation}

\item If $\theta_N^-\to\theta\in(0,\infty)$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^3}
 \log\mathbb P(Z_N\le-a_Nx)=-J_-^{(\theta)}(x).
\end{equation}

\item If $\theta_N^-\to0$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{\alpha_N^2a_N^2}
 \log\mathbb P(Z_N\le-a_Nx)=-\frac{x^2}{2\sigma^2}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:52:32.333769+00:00","domain":"probability theory","id":"claim_44c6e0976c8ff064c033c16d14f55e0ba9615eeb9bf2ac72e87489fc79ff45f8","kind":"theorem","schema_version":1,"statement":"[Proposition prop:kernelandspectrum of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] The kernel of $A_S$ is given by $$\ker(A_S) = \left\{\begin{pmatrix}
