 and
\begin{eqnarray}
\psi_1(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0) & = & -\frac{\mbox{sign}(s) s \beta^2}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(0)\bar{\q}_{k-1}(0)  -\bar{\p}_{k}(0)\bar{\q}_{k}(0)   \Bigg.\Bigg)
\bar{\m}_k(0) \omega(k;p) \nonumber \\
& &  +\psi(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0) \nonumber \\
\psi_1(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1) & = & -\frac{\mbox{sign}(s) s \beta}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(1)\bar{\q}_{k-1}(1)  -\bar{\p}_{k}(1)\bar{\q}_{k}(1)   \Bigg.\Bigg)
\bar{\m}_k(1)  \omega(k;p) \nonumber \\
& &  +\psi(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1).
 \end{eqnarray}
 Moreover, let
 \begin{equation}
\psi_S(\p,\q,\m,t)  =  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{p|s|\sqrt{n}\m_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp
\lp \sum_{i_3=1}^{l} \mE_{{\mathcal U}_1}  Z_{i_3,S}^{\m_1}\rp^p \rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}\rp,
\end{equation}
where,  analogously to (\ref{eq:thm3eq1}) and (\ref{eq:thm3eq2}),
\begin{equation}
Z_{i_3,S}  \triangleq  \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_{0,S}^{(i_1,i_2,i_3)}} \rp^{s}, \nonumber \\
\end{equation}
with
\begin{eqnarray}
 D_{0,S}^{(i_1,i_2,i_3)}
 & \triangleq &
 \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_2)}\|_2 (\y^{(i_2)})^T\lp\sum_{k=1}^{r+1}b_k\u^{(2,k)}\rp  \nonumber \\
& &
 +\sqrt{1-t}\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}c_k\h^{(k)}\rp^T\x^{(i)}
 + f_{\bar{\x}^{(i_3)} } (\x^{(i_1)}).
 \end{eqnarray}
Then
\begin{eqnarray}
\lim_{n\rightarrow\infty} \psi_S(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1) & = &
 -\lim_{n\rightarrow\infty}\frac{\mbox{sign}(s) s \beta^2}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(0)\bar{\q}_{k-1}(0)  -\bar{\p}_{k}(0)\bar{\q}_{k}(0)   \Bigg.\Bigg)
\bar{\m}_k(t) \omega(k;p)
 \nonumber \\
& &  +\lim_{n\rightarrow\infty} \psi_S(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0). \nonumber \\
 \end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.031215+00:00","domain":"probability theory","id":"claim_46428cb666071aba0a2add32f2fb1937fb7f997b8e565759d69188dc61941356","kind":"concept","schema_version":1,"statement":"[Lemma Randersimmersion of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let $R$ be a Randers-Minkowski metric on $\mathbb R^n$ with navigation data $(h, W)$. If $V$ is a subspace, then the induced metric on $V$ is the Randers-Minkowski metric with navigation data $(\tilde h, W^{\top})$ given by
\begin{subequations}
\begin{equation*}
\tilde h := \lambda \, h\vert_{V \times V} \, ,
\end{equation*}
\begin{equation*}
W^{\top} := W - W^{\perp} \, ,
\end{equation*}
\end{subequations}
where $\lambda := \frac{1}{1 - h(W^{\perp}, W^{\perp})}$ and $W^{\perp}$ is the component of $W$ $h$-orthogonal to $V$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.717429+00:00","domain":"probability theory","id":"claim_46445447c17ee9a524cc6ffb6a6b79275aeced7dc917c5f3b2cc7eb7211480d1","kind":"lemma","schema_version":1,"statement":"[Lemma 20 (Properties of the underdamped transient) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Let $\cS_{\mathrm{under}}(k)$ denote the deterministic bias contributed by the underdamped modes ($j \le J_{\max}$). Under the conditions of Proposition~\ref{prop:pol_deterministic_bias}, for every step $k \ge 0$, we have:
