{"assumptions":[],"created_at":"2026-10-27T10:47:32.874955+00:00","domain":"probability theory","id":"claim_485287cc20d276a25b33da79586c4e715b3e759afbf3fe8d0810f8739ce684bc","kind":"theorem","schema_version":1,"statement":"[Theorem 9 (Classwise directional coefficient characterization) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] Fix $\bm{\lambda}\in\Lambda$ and define normalized coefficients by \eqref{eq:normalized-coefficient}.
Let 
\[
\varphi=\sum_{\bm{\gamma}\in\Lambda}\bm{x}^{\bm{\gamma}}r_{\bm{\gamma}}(\log\bm{x})\in\mathscr{F}_{\widetilde{\Lambda}}^{\log}[\Lambda]
\]
be a formal logarithmic expression as in \eqref{eq:classwise-formal-logarithmic-expression}.
Then the following conditions are equivalent.
\begin{enumerate}[\rm (1)]
\item One has
\[
\varphi\in\Sol_{\bm{w},\Lambda}^{\mathrm{dir}}\bigl(H_{A}(\bm{\beta})\bigr).
\]
\item The normalized coefficient $c_{\bm{\gamma}}^{(\bm{\lambda})}$ depends only on $I_{\bm{\gamma}}=\nsupp(\bm{\gamma})$, hence can be denoted by $c_{\Lambda,I}$ for $I\in\NS(\Lambda)$.
The resulting finite family $(c_{\Lambda,I})_{I\in\NS(\Lambda)}$ satisfies
\begin{equation}

(A\partial_{\bm{y}})_{i}\mathbin{\bullet}_{\bm{y}}c_{\Lambda,I}=0\quad(I\in\NS(\Lambda),\ i=1,\dots,d),
\end{equation}
\begin{equation}

\partial_{\bm{y}}^{J\setminus I}\mathbin{\bullet}_{\bm{y}}c_{\Lambda,I}=\partial_{\bm{y}}^{I\setminus J}\mathbin{\bullet}_{\bm{y}}c_{\Lambda,J}\quad(I,J\in\NS(\Lambda)),
\end{equation}
and
\begin{equation}

c_{\Lambda,I}=0\quad(I\in\NS(\Lambda)\setminus\mathcal{A}_{\bm{w}}(\Lambda)).
\end{equation}
\end{enumerate}
Under these equivalent conditions, \eqref{eq:raw-coefficient-reconstruction} recovers the unique raw coefficient family, and
\begin{equation}

\Supp(\varphi)=\coprod_{I\in\Act_{\Lambda}(\bm{c})}\Lambda_{I},\quad\Act_{\Lambda}(\bm{c})\subset\mathcal{A}_{\bm{w}}(\Lambda).
\end{equation}
If $\varphi\neq 0$, then
\begin{equation}

\lexp_{\bm{w}}(\varphi)=\min_{\leq_{\bm{w},\Lambda}}\{\bm{v}_{\Lambda,I}\mid I\in\Act_{\Lambda}(\bm{c})\}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.777991+00:00","domain":"probability theory","id":"claim_4855c3e878d3e82a83a31847591ee9180da33a4d1c712453e45a73a862713668","kind":"concept","schema_version":1,"statement":"[Prop 7 of arXiv:2603.25536, 'The $H^{2|2}$ monotonicity theorem revisited'] Partition the vertex set $V$ into two subsets: the bulk $V_1 = \{1, \dots, N-1\}$ and the boundary $V_2 = \{N,\delta\}$.\footnote{The boundary was $\{1,\delta\}$ in Section~\ref{subse:boundary_variations}; we choose $\{N,\delta\}$ here to cleanly perform the block decomposition.} This partition induces a block decomposition of the symmetric matrices $H_\beta$ and $G$:
\begin{equation*}
    H_\beta = \begin{pmatrix} H_\beta^{V_1, V_1} & H_\beta^{V_1, V_2} \\ H_\beta^{V_2, V_1} & H_\beta^{V_2, V_2} \end{pmatrix}, \quad G = \begin{pmatrix} G^{V_1, V_1} & G^{V_1, V_2} \\  G^{V_2, V_1} & G^{V_2, V_2} \end{pmatrix}.
\end{equation*}
Then conditionally on \((\beta_{i})_{i\in V_{1}}\), \((G^{V_2,V_2})^{-1}\) is distributed according to \(q_{\{N,\delta\}}^{\widetilde{W}_{N\delta},1}\), where
\[\widetilde{W}_{N\delta} = W_{N\delta} + \left[H_{\beta}^{V_{2},V_{1}} (H_\beta^{V_1, V_1})^{-1} H_{\beta}^{V_{1},V_{2}}\right]_{N\delta}.\]
In particular, \(\frac{d \widetilde{W}_{N\delta}}{dW_{N\delta}} =1\). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:31:02.832310+00:00","domain":"probability theory","id":"claim_485cc7cd9a50a0d85dfac5b7faf72d4979f72e7831d19d7269b6af34f761ca91","kind":"theorem","schema_version":1,"statement":"[Thm eq:SigT2 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let ${\boldsymbol{\gamma}} \in {\mathbb R}^{d_1}$ with ${\gamma}_i  > -1$, $1\le i \le d_1$ and ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with ${\kappa}_i > -1$, $1 \le i \le d_2$. Then
the spectral operator can be written as 
\begin{align} 
  {\mathfrak D}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} u = \,  &
  \frac{1}{{\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y})} \left[  \sum_{i=1}^{d_1} 
     (\partial_{x_i}+ \partial_{y_{d_2}} )  x_i {\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y}) (\partial_{x_i}+ \partial_{y_{d_2}}) \right.  \\
       & \qquad\qquad\qquad \quad + \partial_{y_d} (|{\bm y}|- |{\bm x}|)  {\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} \partial_{y_d}\Big] \notag \\
  & + \frac{1}{{\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y})} \sum_{i=1}^{d_2} (\partial_{y_i} - \partial_{y_{d_2}}) 
       y_i  {\bm W}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} ({\bm x},{\bm y})  (\partial_{y_i} - \partial_{y_{d_2}}). \notag 
   \end{align}","status":"unverified"}

