{"assumptions":[],"created_at":"2026-10-27T20:53:00.822543+00:00","domain":"probability theory","id":"claim_48bd57cb20b65a195576d06d5a385a3017c000cb234f73ede015c5fee187e74a","kind":"definition","schema_version":1,"statement":"[Definition Def: branched rough paths of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For $\alpha\in(0,1]$, $N:=\lfloor\frac{1}{\alpha}\rfloor$ and $T>0$, a branched $\alpha$-rough path is a map $\mathbb X:[0,T]_\leq^2\to \mathcal{H}^\ast_N$ such that 
		\begin{itemize}
			\item For any $(s,u,t)\in[0,T]_\leq^3$, $\mathbb X$ satisfies Chen's relation in $\mathcal{H}_N^\ast$
			\begin{equation}
				\mathbb X_{st}=\mathbb X_{su}\star\mathbb X_{ut}\,.
			\end{equation}
			\item For any $\tau\in{\mathcal T}$
			\begin{equation*}
				|\mathbb X_{st}(\tau)|\lesssim |t-s|^{|\tau|\alpha}\, ,
			\end{equation*}
			uniformly on $0\le s\le t\le T$.
			\item For any forest $w=\tau_1\cdots\tau_k\in{\mathcal F}^{\leq N}$,
			\[\mathbb X_{st}(w)=\prod_{i=1}^k\mathbb X_{st}(\tau_i)\,.\]
		\end{itemize}
		If in addition $\mathbb X_{st}(\bullet_i)=\delta X^i_{st}$ for a path $X:[0,T]\to \mathbb{R}^d$, we say that $\mathbb X$ is an $\alpha$-branched rough path lift of $X$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:00:30.488337+00:00","domain":"probability theory","id":"claim_48c2cde8b127b8f7d5114e0f8bde95abe72d556b187d9707823c4a457eee41b9","kind":"theorem","schema_version":1,"statement":"[Thm 4 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] Let $m\geq2$, and let 
\begin{equation}
\Omega_{m}=\left\{ 0,\ldots,m-1\right\} ^{\mathbb{N}}
\end{equation}
with its product Borel structure. If $E$ is a POVM on $\Omega_{m}$,
write 
\begin{equation}
E_{w}=E\left(\left[w\right]\right),\qquad H_{w}=\overline{ran}\,(E^{1/2}_{w})
\end{equation}
for each finite word $w$ in the alphabet $\left\{ 0,\ldots,m-1\right\} $.
Then, for every $w$, there are unique positive contractions 
\begin{equation}
A^{\left(0\right)}_{w},\ldots,A^{\left(m-1\right)}_{w}\in B\left(H_{w}\right)
\end{equation}
such that 
\begin{equation}
\sum^{m-1}_{j=0}A^{\left(j\right)}_{w}=I_{H_{w}}
\end{equation}
and 
\begin{equation}
E_{wj}=E^{1/2}_{w}A^{\left(j\right)}_{w}E^{1/2}_{w}.
\end{equation}

Conversely, suppose that $E_{\varnothing}=I$, and that the cylinder
values are defined recursively by positive contractions $A^{\left(j\right)}_{w}\in B\left(H_{w}\right)$
satisfying \prettyref{eq:2-13} and \prettyref{eq:2-14}. Then there
is a unique POVM $E$ on $\Omega_{m}$ with these cylinder values.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.227068+00:00","domain":"probability theory","id":"claim_48c36c9402e61efd5c5af938973856cc32522e1ec3ec5c5e805d1ecd01682521","kind":"definition","schema_version":1,"statement":"[Definition def-lacunary of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \begin{enumerate}
    \item A point process $\theta$ is called \textbf{lacunary} on $(0,\infty)$ if there exist constants $c,d \in (0, \infty)$, $c<d$, such that  
    \begin{equation} 
        \theta([cx, d x ]) \overset{\mathbb{P}}{\rightarrow} 0
    \end{equation} 
    as $x \rightarrow \infty $\footnote{The intuitive meaning of this definition is that atoms of the point process $\theta$ in $(0,\infty)$ are extremely spaced out and have large gaps, hence the choice of the word \textbf{lacunary}.}. 

    \item A point process $\theta$ is called \textbf{exponentially-lacunary} on $(0,\infty)$ if there exist constants $c,d \in (0, \infty)$, $c<d$, such that 
    \begin{equation}
         \theta([c \log x, d x ]) \overset{\mathbb{P}}{\rightarrow} 0
    \end{equation}
    as $x \rightarrow \infty $. 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:25.275022+00:00","domain":"probability theory","id":"claim_48c716c38ebff7a93c42259b8ddac56d4d33c416612f69d57a3fba1545a5f81a","kind":"theorem","schema_version":1,"statement":"[Proposition 12 (Full-process Sudakov comparison) of arXiv:2606.21137, 'A Sudakov--Fernique proof of Lehner-type edge bounds for matrix-valued GUE sums'] Assume $M\ge N$ and $A_i\succeq0$ for $i=1,\ldots,n$.
