{"assumptions":[],"created_at":"2026-10-27T10:25:49.874060+00:00","domain":"probability theory","id":"claim_48d8dd797c4ebdf1b2dd8773580ca1dacbcabd0bdfaecde2d056f1a2973e6098","kind":"theorem","schema_version":1,"statement":"[Proposition 20 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] The following statements hold.

  \smallskip
  \noindent
  \textup{(i) (\textsf{Polymer endpoint moments})}  
  Recall the definition of $  Q_{x,R}^{\al,\be,\eps}$
  from  \eqref{QxR_abe}. 
  For every compact
  $K\subset\R$ and every $p\in[1,\infty)$,
  we have 

  \noi
  \begin{align}
    \sup_{\substack{x\in K,\ 0<\eps<1\\1\leq R\leq\infty}}
    \bigg\|
      \int_{\R_+^n}\ga_n
      Q_{x,R}^{\al,\be,\eps}(d\ga)
    \bigg\|_{L^p(\Omega)}<\infty.
  \end{align}
  In particular, with
  \begin{align}
    \cU_{x}^{\eps}
    =\int_{\R_+^n}
     \big[  DH_{x}^{\al,\eps}(\ga) \big]
      Q_{x}^{\al,\be,\eps}(d\ga),
  \end{align}
  one has
  \[
    \sup_{x\in K,\,0<\eps<1}
    \|\cU_x^\eps\|_{L^2(\Omega;\fH)}<\infty.
  \]

  \smallskip
  \noindent
  \textup{(ii) (\textsf{Truncated Malliavin derivative})}  For $R<\infty$,
  $\lambda\in[0,\be)$, and $\eps>0$,
  $\log Z_{x,R}^{\al,\be,\eps}(\lambda)\in\DD^{1,2}$ and
  \begin{align}
    D\log Z_{x,R}^{\al,\be,\eps}(\lambda)
    =\frac{\be}{Z_{x,R}^{\al,\be,\eps}(\lambda)}
    \be^{-n}\int_{\ga_n<R}
      e^{\lambda\ga_n+\be H_{x}^{\al,\eps}(\ga)}
     \big[ DH_{x}^{\al,\eps}(\ga) \big]\,\mu_\be(d\ga).
  \end{align}

  \smallskip
  \noindent
  \textup{(iii) (\textsf{Full Malliavin derivative})}  For every fixed
  $\eps>0$, we have
  \begin{align}
    \log Z_{x}^{\al,\be,\eps}\in\DD^{1,2}
    \quad{\rm and}
    \quad
    D\log Z_{x}^{\al,\be,\eps}
    =\be\cU_x^\eps.
  \end{align}
  Moreover,
  $
    D\log Z_{x,R}^{\al,\be,\eps}(0)
    \longrightarrow \be\cU_x^\eps
    \quad\text{in }L^2(\Omega;\fH)
$
  as $R\to\infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.316287+00:00","domain":"probability theory","id":"claim_48dc2f2a3c778f32933d1024b170408fab6311537d371aa7e9e5dc0b2d761bb6","kind":"theorem","schema_version":1,"statement":"[Theorem th3 of arXiv:2411.06089, '{\Large \bf Averaging principle for semilinear slow-fast rough partial differential equati'] Assume that the conditions in Theorem \emph{(MainRes of the paper)} hold. For any $x\in \mathcal{H}_\eta$ and $y\in \mathcal{H}$ with $\eta \in (\gamma-1/4, \gamma)$, $\gamma \in (1/3, \gamma_0)$ and $1/3 <\gamma_0 \leq 1/2$, we have
