{"assumptions":[],"created_at":"2026-10-27T21:53:10.160060+00:00","domain":"probability theory","id":"claim_49037ab63b524bc906bbb5bcca0936046d91b18e1322f3c85ef74ae38b40b840","kind":"lemma","schema_version":1,"statement":"[Lemma of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] The equivalence $\Psi\colon\ul\Spc_{\textup{Glo}/\ul\textup{VRep}}\xrightarrow{\;\smash{\raisebox{-0.25ex}{\ensuremath{\scriptstyle\sim}}}\;}\ul{{\mathfrak S\kern-.4pt}}_\textup{gl}[\textbf{\textup{BOP}}]$ preserves and reflects equivariant weak equivalences.
    \begin{proof}
        We claim that the square
        \[
            \begin{tikzcd}
                \ul\Spc_{\textup{Glo}/\ul\textup{VRep}^\oplus}^\otimes\arrow[d,"\textup{fgt}"']\arrow[r,"\Psi"] & \ul{{\mathfrak S\kern-.4pt}}_\textup{gl}[\textbf{\textup{BOP}}]^\otimes\arrow[d,"\textup{fgt}"]\\
                \ul\Spc_{\textup{Glo}}^\times\arrow[r,"\sim"'] & \ul{{\mathfrak S\kern-.4pt}}_\textup{gl}^\times
            \end{tikzcd}
        \]
        of symmetric monoidal global functors commutes up to equivalence. As all functors in question are symmetric monoidal left adjoints, this can be checked after restricting to $\ul\textup{Rep}$, where it follows immediately from the definition of the equivalence $\Psi$ that both composites send every object to the terminal object, so that the square even commutes up to unique equivalence.

        Plugging in the definitions, we are then reduced to constructing a commutative square as depicted on the left in the following diagram, where the vertical maps are the underlying ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-functors of the unique equivalences:
        \[
            \begin{tikzcd}
                \ul\Spc_{{\vphantom{\textup{t}}\smash{\textup{Orb}}}\triangleright\textup{Glo}}|_{\vphantom{\textup{t}}\smash{\textup{Orb}}}\arrow[from=r,"r"']\arrow[d,"\sim"'] & \ul\Spc_{\textup{Glo}}|_{\vphantom{\textup{t}}\smash{\textup{Orb}}}\arrow[d,"\sim"] &[1em] \ul\Spc_{{\vphantom{\textup{t}}\smash{\textup{Orb}}}\triangleright\textup{Glo}}\arrow[r,hook]\arrow[d,"\sim"'] & \ul\Spc_{\textup{Glo}}\arrow[d,"\sim"]\\
                \ul{{\mathfrak S\kern-.4pt}}|_{\vphantom{\textup{t}}\smash{\textup{Orb}}}\arrow[from=r,"r"] &\ul{{\mathfrak S\kern-.4pt}}_\textup{gl}|_{\vphantom{\textup{t}}\smash{\textup{Orb}}} & \ul{{\mathfrak S\kern-.4pt}}\arrow[r,"c"'] & \ul{{\mathfrak S\kern-.4pt}}_\textup{gl}
            \end{tikzcd}
        \]
        The square on the right commutes up to unique equivalence as both paths are ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-left adjoints preserving the terminal object. Passing to underlying ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-functors and then to mates therefore provides the desired square on the left.
    \end{proof}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.564495+00:00","domain":"probability theory","id":"claim_4904e114bff0e32a55811cb49492f7294c93d6799fba10cf0b351820adbdb358","kind":"theorem","schema_version":1,"statement":"[Proposition 15 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $X$ and $Y$ be Polish spaces and $c: X \times Y \to (-\infty, \infty)$ be a continuous cost function. Then the following properties hold:
    \begin{enumerate}
        \item Let $A_1, A_2 \subset X$. If $A_1 \subseteq A_2$, then $(A_1)^{\circ, c} \supseteq (A_2)^{\circ, c}$.
        \item Let $B_1, B_2 \subset Y$. If $B_1 \subseteq B_2$, then $(B_1)^{\star, c} \supseteq (B_2)^{\star, c}$.
        \item For any subsets $A \subset X$ and $B \subset Y$, one has $A \subseteq (A^{\circ, c})^{\star, c}$ and $B \subseteq (B^{\star, c})^{\circ, c}$.
        \item For any subsets $A \subset X$ and $B \subset Y$, one has $((A^{\circ, c})^{\star, c})^{\circ, c} = A^{\circ, c}$ and $((B^{\star, c})^{\circ, c})^{\star, c} = B^{\star, c}$.
        \item The collections of $c$-polar sets defined by $\mathcal{S}_X := \{B^{\star, c} : B \subset Y\} \subset 2^X$ and $\mathcal{S}_Y := \{A^{\circ, c} : A \subset X\} \subset 2^Y$ are invariant under the composition of the polarities. That is, if $A \in \mathcal{S}_X$ and $B \in \mathcal{S}_Y$, then $(A^{\circ, c})^{\star, c} = A$ and $(B^{\star, c})^{\circ, c} = B$.
    \end{enumerate}
    Suppose further that $X$ and $Y$ are geodesic spaces, and that the dualities are convex. Then:
    \begin{enumerate}
        \setcounter{enumi}{5}
        \item For any sets $A \subset X$ and $B \subset Y$, one has $A^{\circ, c} = (\operatorname{conv}(A))^{\circ, c}$ and $B^{\star, c} = (\operatorname{conv}(B))^{\star, c}$, where $\operatorname{conv}$ denotes the geodesic convex hull. Moreover, if there exists a point $x_0 \in X$ such that $-c(x_0, y) \le 1$ for all $y \in Y$, then for any set $A \subset X$, one has $A^{\circ, c} = (A \cup \{x_0\})^{\circ, c} = (\operatorname{conv}(A \cup \{x_0\}))^{\circ, c}$. Similarly, if there exists $y_0 \in Y$ such that $-c(x, y_0) \le 1$ for all $x \in X$, then $B^{\star, c} = (B \cup \{y_0\})^{\star, c} = (\operatorname{conv}(B \cup \{y_0\}))^{\star, c}$.
    \end{enumerate}
    Finally, suppose $X = M_{n,m}(\R)$, $Y = \R^n$, and the cost is given by $c(A,v) = -h_Q(A^t v)$ for some $Q \in \conbodo[m]$. Then:
    \begin{enumerate}
        \setcounter{enumi}{6}
        \item For every $K \in \conbode$, one has $(K^{\star, c})^{\circ, c} = K$.
    \end{enumerate}","status":"unverified"}

