{"assumptions":[],"created_at":"2026-10-27T16:30:50.702964+00:00","domain":"probability theory","id":"claim_4989b3f52221a7ae0a5eb16123b9ea5f3b8aa69b8589e3bb14acfe1e1bfdba6e","kind":"concept","schema_version":1,"statement":"[Thm thm-BBG17-4.3 of arXiv:2608.30807, 'Isodiametric-type upper bounds for Steklov eigenvalues'] {BBG17}}]
