    \item  For every $\mathbf{i}\in\mathscr{I}$ with $|\mathbf{i}|\geqslant 1$, 
    \begin{align*}
        \sup_{(L,\alpha)}\sup_{[0,T]\times \mathbb{R}^{D}}\left|\partial^\mathbf{i}_x\Phi\right|<\infty. \end{align*}
    In particular, we have $|\nabla \Phi|\leqslant \sup_{\sigma \in\supp\mu}|\sigma|$ everywhere on $[0,T]\times \mathbb{R}^D$.
    \item  
