+ \int_{0}^{t} \ddual{V^\prime }{B(u(s))}{v}{V}{}\, \mathrm{d}s
   =\ip{{u}_{0}}{v}{H} 
   \\
   &+ \int_{0}^{t} \ddual{V^\prime }{f(s)}{v}{V}{}\, \mathrm{d}s
 + \int_{0}^{t} \int_{Y} \ip{F(s,u(s-),y)}{v}{H} \,  \tilde{\eta} (\mathrm{d} s,\mathrm{d} y).
\end{aligned}
\end{equation*}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.041018+00:00","domain":"probability theory","id":"claim_4c72ae8ca46e30a81216b77c0fe4c5767b3afcdf027d4e3f65122eabc499e30f","kind":"concept","schema_version":1,"statement":"[Theorem 40 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] There is a
