{"assumptions":[],"created_at":"2026-10-26T19:44:17.169050+00:00","domain":"probability theory","id":"claim_4e667a1f5e5ec34d67c7b96bd76c05b3c959ce8a8f0555857f479508050d48bf","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE}~and~\ref{assump-particles} hold, and in particular let $p\in (d,+\infty)$, $\gamma \in (\tfrac{d}{p},1)$ and an integer $k \geq 3$ for which these assumptions hold. Assume further that the cut-off parameter satisfies
${A\geq \| u\|_{L^{\infty}_{t,x}}}$, and if $d=3$, that $\frac{\gamma}{2} + \frac{3}{2}(\frac{1}{2}-\frac{1}{p}) <1$. Then the following holds:
\begin{itemize}
\item If $\sigma>0$, then for any $q\in [1,+\infty)$, there exists $C = C(q,d,\gamma,p,A,\sigma)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}}\\
&\quad + N^{-2(\alpha-\beta)} +N^{-2\beta(\gamma-\frac{d}{p})} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)} + \ratetilde^2 \bigg) + 2 \rate^2 ,
\end{align*}
where
\begin{equation}

\rate^2 = \sup_{t\in[0,T]} \big\| u_t^{(N)} - u_t \big\|_{ \gamma,p}^2 +  \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}
and
\begin{equation}
\ratetilde^2 = \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F^{(N)}_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}

\item If $\sigma=0$, then for any $q\in [1,+\infty)$ and any $\varepsilon>0$, there exists $C = C(q,d,\gamma,p,A,\varepsilon)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}} +\ratetilde^2 \\
&\quad + N^{-2(\alpha-\beta)} + N^{-2\beta(\gamma-\frac{d}{p})+\varepsilon} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)}
\bigg) \, \frac{1}{1-\tilde\gamma} e^{CT\big(1+\sigma_{N}^{-2} + \sigma_{N}^{-\frac{1}{1-\tilde\gamma}}\big)}
 + 2 \rate^2,
\end{align*}
where
\begin{equation}
\tilde{\gamma} = \frac{1}{2} \Big(\gamma + d\big(\frac{1}{2}-\frac{1}{p}\big)\Big) \vee \frac{\gamma+1}{2} \in (0,1) .
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.596464+00:00","domain":"probability theory","id":"claim_4e68f6da29850aae9502a9b8dd4483ad37b7cc069f281e72f0fdfd64ae8214ec","kind":"concept","schema_version":1,"statement":"[Thm two-sided of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Let $X_1,X_2,\ldots$ be integer-valued i.i.d. random variables with characteristic function $\varphi$, and let $S_j = \sum_{i = 1}^{j} X_i$. Let $\alpha$ be an irrational number. Suppose that
\begin{enumerate}[(i)]
\item there exists $0 < \beta \leq 2$ such that in an open neighborhood of $0$,\footnote{Throughout the paper $A \asymp B$ means that there exists an absolute constant $C > 0$ such that $C^{-1} B \leq A \leq C B$.}
$$
|1 - \varphi(x)| \asymp |x|^\beta;
$$

\item there exists $\gamma \geq 1$ such that
\begin{align} 
0 < \liminf_{q \rightarrow \infty} q^\gamma \| q \alpha \| < \infty.
\end{align}
\end{enumerate}
Set $\mu_n = \frac{1}{n} \sum_{j = 1}^{n} \delta_{\{ S_j \alpha \}}$, $n \geq 1$. Then for any $1 \leq p < \infty$,
\begin{enumerate}[(1)]
\item if $\beta \gamma < 2$, assume furthermore that $X_1$ is non-constant, then

$$\mathbb E \big[  \mathbb W_p(\mu_n, \mu)  \big] \asymp \frac{1}{\sqrt{n}};$$

\item if $\beta \gamma = 2$, assume furthermore that $X_1$ is non-constant, then there exist $c_1, c_2 > 0$ such that for any $n \in \mathbb N$,

$$\frac{c_1}{\sqrt{n}} \leq \mathbb E \big[  \mathbb W_p(\mu_n, \mu)  \big] \leq \frac{c_2 (\log n)^{1 - \frac{1}{p \vee 2}} }{\sqrt{n}};$$

\item if $\beta \gamma > 2$, then

$$
0 < \limsup_{n \rightarrow \infty} n^{1/(\beta \gamma)} \mathbb E \big[ \mathbb W_p(\mu_n, \mu) \big] < \infty,
$$
\end{enumerate}
where all constants and implied ones depend on $p$ and conditions on $\varphi$ and $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:38:23.595060+00:00","domain":"probability theory","id":"claim_4e6905069e16828a801676ce95e7232017a0c578e508215b31c6b973302f3afb","kind":"theorem","schema_version":1,"statement":"[Theorem th4.2 of arXiv:2511.07173, '\bf Mean-field backward stochastic Volterra integral equations: well-posedness and related'] \rm
