{"assumptions":[],"created_at":"2026-10-27T06:21:45.321981+00:00","domain":"probability theory","id":"claim_50491d51a81ae0c62fc119cca56d08b21e05a5b51229357ebda60dc4ed1a3513","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Assume that the subordinator $S(t)$, $t\ge0$, is given by a general exponent $\phi$ as in \eqref{bernstein-eq} with $b>0$ or $\nu(0,+\infty)=+\infty$, and let $L(t)$, $t \geq 0$ be its inverse subordinator. Let $P_s$, $s \geq 0$, be a strongly continuous semigroup of operators on some Banach space $(\mathfrak{B}, \left\| \cdot \right\|)$, with the generator $(G,\DD(G))$, {such that}
		\begin{align}
			\left\| P_t u \right\| \, \leq \, M e^{\lambda_0 t} \left\| u \right\|, \quad {u \in \mathfrak{B},}
		\end{align}
		{where $M>0$ and $\lambda_0\ge0$}\footnote{{All strongly continuous semigroups are exponentially bounded in this way, see Appendix \ref{appendix_semigroups}.}}. Define
		\begin{align}
			\mathcal{P}_tu \, = \, \int_0^{+\infty} P_su \, l_t(ds),
		\end{align}
		as a Bochner integral on $\mathfrak{B}$, where $l_t(ds)$  denotes the distribution of $L$ under $\PP^{(x,0)}$ (which is independent of $x$).

		Then, whenever $u \in \mathfrak{B}$, the mapping $[0,+\infty)\ni t \mapsto q(t) \coloneqq \mathcal{P}_tu$ is strongly continuous on $\mathfrak{B}$ and {exponentially} bounded ({bounded by a constant if $\lambda_0=0$}). If, in addition, $u \in \mathcal{D}(G)$, then
		\begin{align}
			\phi(\partial_t) (q(t)-q(0)) \, = \, G q(t), \qquad q(0) = u,

		\end{align}
		in the sense that $q(t) \in \mathcal{D}(G)$ for all $t \geq 0$, $t \mapsto q(t)$ is strongly continuous (on $\mathfrak{B}$) and {exponentially} bounded {(bounded by a constant if $\lambda_0=0$)}, the generalized derivative on the left hand side of \eqref{eq_conv_theorem} exists for all $t > 0$ in the strong sense, and both $t \mapsto Gq(t)$ and $t \mapsto \phi(\partial_t) (q(t)-q(0))$ are strongly continuous and {exponentially} bounded {(bounded if $\lambda_0=0$)}.

		Finally, if $\mathpzc{q}(t)$ is another solution with the same properties as above, then $\mathpzc{q}(t) = q(t)$ for all $t \geq 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.568425+00:00","domain":"probability theory","id":"claim_504c869f66e5369f3a5c6b386a62de45e65361f8933d24cae7a679b794f3c1aa","kind":"theorem","schema_version":1,"statement":"[Proposition pro.additive-renewal of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] For every $\lambda\in(0,1]$, the limit $\lim_{t\to\infty}t^{-1}A^\lambda(t)$ exists $\widehat{\mathbb P}_0^\lambda$-almost surely and in $L^1(\widehat{\mathbb P}_0^\lambda)$ and is the deterministic number
	\begin{equation}
	\eta(\lambda)=\frac{\widehat{\mathbb E}_0^\lambda\left[\int_{\tau_1}^{\tau_2}e^{-2V(X^\lambda(s))} ds\right]}{\widehat{\mathbb E}_0^\lambda[\Delta\tau_1]}\, .
	\end{equation}
	Moreover,
	\begin{equation}
		\Lambda^{-1}\le\eta(\lambda)\le\Lambda\, .
	\end{equation}
		For every integer $M\ge2$, there exists a finite constant $C=C(M,d,\Lambda,r_0)>0$ such that for all $\lambda\in(0,1]$ and all $t\ge\lambda^{-2}$,
		\begin{equation}
			\mathbb{E}_\mathbb{Q} \widehat E^{\lambda,\omega}_0\big|A^\lambda(t)-\eta(\lambda)t\big|^M
			\le C\lambda^{-M}t^{M/2}\, .
		\end{equation}","status":"unverified"}

