{"assumptions":[],"created_at":"2026-10-27T20:36:16.007055+00:00","domain":"probability theory","id":"claim_50c8eedb74a9864b0a7ed07b566db64c67d4cc9dc69a7775baa53884ac6dc33d","kind":"lemma","schema_version":1,"statement":"[Lemma compofm of arXiv:2606.27844, 'Critical percolation on preferential attachment graphs with infinite variance'] Define 
