{"assumptions":[],"created_at":"2026-10-27T18:44:24.713655+00:00","domain":"probability theory","id":"claim_511318cb27e1d31e1050cba0a0e6b004ecd66681a3d1ddc104efe8d38fe4d0aa","kind":"theorem","schema_version":1,"statement":"[Proposition prop:wegner_asymptotics of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For $x \in \mathcal{I}_{\alpha}$ and $y \in \mathcal{I}_{\beta}$, the following asymptotic regimes hold as $n, N \to \infty$:
\begin{enumerate}
    \item \textbf{Frozen regime} ($n\lambda \ll 1$):
    The transition probability is dominated by the initial state:
    \begin{equation}
        \left| p_n(x,y) - \frac{1}{M}\delta_{\alpha\beta} \right| = O(n\lambda).
    \end{equation}

    \item \textbf{Skellam regime} ($n\lambda \to \mu \in (0,\infty)$):
    The transition probability converges to the continuous-time random walk kernel:
    \begin{equation}
        \left| p_n(x,y) - \frac{1}{M}p^{\mathrm{(Skellam)}}(\beta-\alpha,\mu) \right| = O(n^{-1} M^{-1}).
    \end{equation}
    Here $p^{\mathrm{(Skellam)}}$ was defined in (equation equ:skellam of the paper).
    \item \textbf{Diffusive regime} ($n\lambda \to \infty$):
    The transition probability satisfies a local central limit theorem. For $\sigma^2 = n\lambda/d$, we have
    \begin{equation}
        \sup_{x,y} \left| p_n(x,y) - \frac{1}{M}\mathcal{G}_{n\lambda/d}(\alpha-\beta) \right| = o\Big( \frac{1}{M (n\lambda)^{d/2}} \Big).
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:35:05.802822+00:00","domain":"probability theory","id":"claim_5117a07be0ce456cd135a5790a527d063b0b43a191c2a87fb5dfbb41cfa21fe8","kind":"lemma","schema_version":1,"statement":"[Lemma L:Second-der-Integrating-factor of arXiv:2606.23865, 'Uniform-in-time Gaussian fluctuations for multiscale nonlinear stochastic systems via Mall'] For any $t \ge r,$ let the process $Z$ be defined as follows:
\begin{equation}
Z_{t,r} \triangleq \exp \left[ \int_{r}^t \frac{1}{\eta}f_y(Y_s^\eta)\thinspace ds + \int_{r}^t \frac{1}{\sqrt{\eta}}\tau_y(Y_s^\eta)\thinspace dW_s^2 - \frac{1}{2\eta} \int_{r}^t \tau_y(Y_s^\eta)^2 \thinspace ds \right].
\end{equation}
Suppose that Assumption (A:Derivatives-Assumption-f of the paper) holds. Then, there exists a time-independent constant $K>0$ such that 
$$\mathbb{E} \left[ \left| Z_{t,r}\right|^{2p} \right] \le K e^{-\frac{(2p)\lambda}{\eta}(t-r)}.$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:26:52.654598+00:00","domain":"probability theory","id":"claim_5117ac4457692677bbca6a05fb2bd77b9bac9f038ec38a5027a0cde602c6caa4","kind":"theorem","schema_version":1,"statement":"[Prop 9 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $M>0$ and $(u,w)\in\mathcal{S}_{M,rad}$. Then $u\in\Sigma_a$ for $a:=M/|\mathbb{B}_R|$. In fact, with $v = \mathcal{K}[u-\langle u\rangle]$ it holds that
\begin{equation}
	u(x)\ge\min\left\{1,\exp\left(m^{-1}\big(\langle \phi'(u)\rangle-\|v\|_\infty\big)\right)\right\}>0\,,\quad x\in\bar{\mathbb{B}}_R\,.
\end{equation}
Moreover, $\phi'(u)=v+\langle \phi'(u)\rangle$ satisfies
\begin{equation}
