{"assumptions":[],"created_at":"2026-10-28T01:16:46.727036+00:00","domain":"probability theory","id":"claim_52ba521617e4d8a1d7212516d2f70cac413a4b8156a44cf6c652f8659bdb524f","kind":"lemma","schema_version":1,"statement":"[Lemma lem:ReductionLemma of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] For any $\mathbf{w}\in\mathbb{S}^{d-1}$ let $\mathbf{v}=(v_1,\ldots,v_m)\in \mathbb{S}^{m-1}_+\subset W_m$ be such that $\mathbf{w} = (v_1 \mathbf{u}_1,\ldots,v_m\mathbf{u}_m)$ for some $\mathbf{u}_i\in\mathbb{S}^{d_i-1}$, $i\in\{1,\ldots,m\}$. Then, for all $\operatorname{bd}=(d_1,\ldots,d_m)$ with $d_i\ge 1$ and all ${\boldsymbol{\beta}}=(\beta_1,\ldots,\beta_m)$ with $\beta_i>-1$, $i\in\{1,\ldots,m\}$ we have that
        \begin{equation*}
        \mathbb{P}_{d}(Z_{\operatorname{bd}}\cap H^+(\mathbf{w},s);{\boldsymbol{\beta}},\operatorname{bd}) = \left(\prod_{i=1}^m \frac{c_{\beta_i,d_i}}{c_{\beta_i,d_i-1}c_{\beta_i}}\right) \mathbb{P}_{m}(C^+(\mathbf{v},s);(\operatorname{bd}-\mathbbm{1})/2+{\boldsymbol{\beta}}),
    \end{equation*}
    and
    \begin{equation}
    \operatorname{Vol}_{d-1}(Z_{\operatorname{bd}}\cap H(\mathbf{w},s); {\boldsymbol{\beta}},\operatorname{bd})=\left(\prod_{i=1}^m \frac{c_{\beta_i,d_i}}{c_{\beta_i,d_i-1}c_{\beta_i}}\right)\operatorname{Vol}_{m-1}(C(\mathbf{v},s);(\operatorname{bd}-\mathbbm{1})/2+{\boldsymbol{\beta}}),
    \end{equation}
    where $c_{\beta,d}$ and $c_{\beta}$ are the normalizing constants of the beta density given by (equation eq:CbetaConstant of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:15:15.496232+00:00","domain":"probability theory","id":"claim_52bade6c76c13a511969ff56173c3e938533d43d2fb58b041d0276f33517a307","kind":"lemma","schema_version":1,"statement":"[Lemma l-cross of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] For each $n\geq 0$, the function $L_{n}$ has two fixed
points at $0$ and $1$, and a unique fixed point in $(0,1)$. If we denote the
latter by $c_{n}$, then
\begin{equation}
L_{n}(x)<x\quad \text{for }x\in (0,c_{n}),\qquad L_{n}(x)>x\quad \text{for }
x\in (c_{n},1).  
\end{equation}

Moreover, there exists a closed interval $O_{n}\subset (0,1)$ such that $
c_{n}\in O_{n}$ and 
\begin{equation}
L_{n}^{\prime }(x)\geq 1\quad \text{for all }x\in O_{n}.  
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:05:28.145360+00:00","domain":"probability theory","id":"claim_52bbb483199f7dc2349cbe0e28a7608b60c4c2938180f0926291cf34f0800157","kind":"concept","schema_version":1,"statement":"[Proposition prop:polyroot of arXiv:2602.00988, 'Wealth exchange under ceiling and flooring constraints: a modified Bennati–Dragulescu–Yako'] Given $0 \leq a < \mu < b$ with $a, \mu, b \in \mathbb N$, and define for $x \geq 0$ the polynomial function
\begin{equation}
f(x) =  (b-\mu)\,x^{b+2-a} + (\mu-b-1)\,x^{b+1-a} + (\mu-a+1)\,x + a - \mu.
\end{equation}
Then \begin{enumerate}[label=(\roman*)]
\item when $\mu<\frac{a+b}{2}$, $f(x)$ has a unique root within $(0,1)$,
\item when $\mu=\frac{a+b}{2}$, $f(x)$ has a unique root at $x= 1$,
\item when $\mu>\frac{a+b}{2}$, $f(x)$ has a unique root within $(1,\infty)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:53:30.650557+00:00","domain":"probability theory","id":"claim_52bbba48ae31ed27ce6413f8e359225a082f879ec222d691dfd3d9c05ed2a3da","kind":"theorem","schema_version":1,"statement":"[Thm Determinant of affine meander matrix of arXiv:2506.01306, 'Asymptotic of Coulomb gas integral, Temperley-Lieb type algebras and pure partition functi'] Let $\widetilde{\mathcal{G}}_n^d$ denote the Gram matrix for the standard module with $n$ nodes and $d = n - 2m$ through-lines. Then:
\[
\begin{aligned}
\det \widetilde{\mathcal{G}}_n^0 &= \prod_{k=1}^{n/2} \left(a^2 - 4 \cos^2\left( \frac{4k\pi}{\kappa} \right) \right) \binom{n}{n/2 - k}, \\
\det \widetilde{\mathcal{G}}_n^d &= \prod_{k=1}^{m} \left(4 - 4 \cos^2\left( \frac{4(k + d/2)\pi}{\kappa} \right) \right) \binom{n}{(n-d)/2 - k}, \quad \text{for } d > 0, \\
\det \widetilde{\mathcal{G}}_n^n &= 1.
\end{aligned}
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.156603+00:00","domain":"probability theory","id":"claim_52bc4a602dbfafece263c78efd188912910b62f9fd9dfb9fd7e99f74d0bec16a","kind":"concept","schema_version":1,"statement":"[Theorem thm:exist+ of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] For each $n_0 \in \mathbb{N}$, and $M_{n_0} \leq j \leq N_{n_0}$, the following limits exist almost surely, uniformly on compact subsets of $[0,\infty)$:
\begin{equation} 
X_j = \lim_{\substack{n \to \infty, \\ n \geq n_0}}  X_j^{[n,n]}, \quad\quad L_{(j,j+1)} = \lim_{\substack{n \to \infty, \\ n \geq n_0}} L_{(j,j+1)}^{[n,n]}, 
\end{equation}
\begin{equation} 
X_j^- = \lim_{\substack{n \to \infty, \\ n \geq n_0}} \lim_{\substack{m \to \infty, \\ n,m\geq n_0}} X_j^{[m,n]}, \quad\quad L_{(j,j+1)}^- = \lim_{\substack{n \to \infty, \\ n \geq n_0}} \lim_{\substack{m \to \infty, \\ n,m\geq n_0}} L_{(j,j+1)}^{[m,n]},
\end{equation}
\begin{equation} 
X_j^+ = \lim_{\substack{m \to \infty, \\ m \geq n_0}} \lim_{\substack{n \to \infty, \\ n,m\geq n_0}} X_j^{[m,n]}, \quad\quad L_{(j,j+1)}^+ = \lim_{\substack{m \to \infty, \\ m \geq n_0}} \lim_{\substack{n \to \infty, \\ n,m\geq n_0}} L_{(j,j+1)}^{[m,n]}.
\end{equation}
Moreover, the processes $\{(X_j,L_{(j,j+1)})\}_{j \in \mathbb{Z}}$, $\{(X^{\pm}_j,L_{(j,j+1)}^\pm)\}_{j \in \mathbb{Z}}$ solve (equation eq:asym_eq of the paper) (with initial data $\{x_j\}$ and Brownian motions $\{B_j\}$). The collections of local times $\{L_{(j,j+1)}\}$, $\{L_{(j,j+1)}^\pm\}$  satisfy the assumption (equation eq:aloc of the paper). Furthermore, the three solutions coincide: $X_j = X_j^- = X_j^+$, and $L_{(j,j+1)} = L_{(j,j+1)}^- = L_{(j,j+1)}^+$ for all $j \in \mathbb{Z}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

