{"assumptions":[],"created_at":"2026-10-26T19:23:58.627208+00:00","domain":"probability theory","id":"claim_52e705ca7881c87fc41b68d6eac59881c05649cf330efb548cdc62faea3a06ad","kind":"lemma","schema_version":1,"statement":"[Lemma 212 (Preliminary below-top-order $L^2$ estimates for the eikonal function quantities) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $1 \le N \le \Ntop -1$ and consider any 
	\begin{subequations}
		\begin{align}
			\varphi_N  & \in \left\{ \tander^{[1,N+1]} \Lsmall^i, \tander^{\le N} \mytr_{\gtorus} \upchi, |\angLie_\tander^{\le N} \upchi|_{\gtorus}\},  \right\} \\
			 \widetilde{\varphi}_N & \in \left\{\tandersmall^{[1,N+1]} \upmu, \comdersmall^{[1,N+1];1} \Lsmall^i, \comder^{\le N;1} \mytr_{\gtorus}\upchi, |\angLie_{\comder}^{\le N;1} \upchi|_{\gtorus}\right\}. 
		\end{align}
	\end{subequations}	
	Let $\blowuprateofacousticgeoWRTnumberofcommutations(N)$ denote the blowup rate of the null geometry variables defined as in \eqref{E:BLOWUPRATEOFACOUSTICBELOWTOPWRTNUMBEROFCOMMUTATORS}. Then for sufficiently small $\varsigma_0 \in (0,1]$, the following estimates hold for $(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$, where the implicit constants are \textbf{independent} of $\varsigma_0$: 
	\begin{align}
		\left\| \varphi_N  \right\|^2_{L^2_{\blowuprateofacousticgeoWRTnumberofcommutations(N)}\left( \ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}\right)}		  
		&    \lesssim \initialsmalldoublenull^2 + (1 + \varsigma_0^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N+1]}(\ubar,u') \, \mathrm{d} u' + (1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N+1]}(\ubar,u) \\
		& \ \ + \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N+1}(\ubar,u')+ \fluxcontrolGradEnt_{\le N+1}(\ubar,u')\right\} \, \mathrm{d} u',    \\
		\begin{split} 
			\left\| \widetilde{\varphi}_N  \right\|^2_{L^2_{\blowuprateofacousticgeoWRTnumberofcommutations(N)}\left( \ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}\right)}		  
			&    \lesssim \initialsmalldoublenull^2 +  (1 + \varsigma_0^{-1}) \int_{\ubar' = \leftubar}^{\ubar} \totalfluxcontrolvelocity_{[1,N+1]}(\ubar',u) \, \mathrm{d} \ubar'   \\
			& \ \ +  (1 + \varsigma_0^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N+1]}(\ubar,u') \, \mathrm{d} u' + (1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N+1]}(\ubar,u) \\
			& \ \ + \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N+1}(\ubar,u')+ \fluxcontrolGradEnt_{\le N+1}(\ubar,u')\right\} \, \mathrm{d} u'. 
		\end{split}
	\end{align} 

Moreover, whenever $\blowuprateofacousticgeoWRTnumberofcommutations(N-1) > 0$, we have: 
	\begin{align}
		\left\| \tander^N \Lsmall^i  \right\|^2_{L^2_{\blowuprateofacousticgeoWRTnumberofcommutations(N-1) -1 }\left(\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}\right)}		  
		&    \lesssim \initialsmalldoublenull^2 + (1 + \varsigma_0^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N+1]}(\ubar,u') \, \mathrm{d} u' + (1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N+1]}(\ubar,u) \\
		& \ \ + \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N+1}(\ubar,u')+ \fluxcontrolGradEnt_{\le N+1}(\ubar,u')\right\} \, \mathrm{d} u',    \\
		\begin{split} 
			\left\| \tandersmall^N \upmu  \right\|^2_{L^2_{\blowuprateofacousticgeoWRTnumberofcommutations(N-1) -1}\left( \characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}\right)}		  
			&    \lesssim \initialsmalldoublenull^2 +  (1 + \varsigma_0^{-1}) \int_{\ubar' = \leftubar}^{\ubar} \totalfluxcontrolvelocity_{[1,N+1]}(\ubar',u) \, \mathrm{d} \ubar'   \\
			& \ \ +  (1 + \varsigma_0^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N+1]}(\ubar,u') \, \mathrm{d} u' + (1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N+1]}(\ubar,u) \\
			& \ \ + \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N+1}(\ubar,u')+ \fluxcontrolGradEnt_{\le N+1}(\ubar,u')\right\} \, \mathrm{d} u'. 
		\end{split}
