\end{align}
where $(l)_k := l(l-1)\cdots(l-k+1)$ denotes the falling factorial.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:38.359081+00:00","domain":"probability theory","id":"claim_55fb39c0d3a49c4a577ce9174a1c3bb9e29585c60d0c8965cf912debe4e89510","kind":"theorem","schema_version":1,"statement":"[Proposition 11 (Corrector bound on bounded domains) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Under Assumption~\textup{(U)}, let~$U \subset \Rd$ be a bounded Lipschitz domain and let~$\eps \in (0,1)$.
		For~$1 \le i \le d$, let~$\phi_i$ solve the corrector problem
		\begin{equation} 
			\begin{cases}
				\mathcal{L}^\eps(\ell_{e_i} + \phi_i) = 0 & \text{in } U^\eps\,,\\
				\phi_i = 0 & \text{on } \eps\Zd \setminus U^\eps\,.
			\end{cases}
		\end{equation}
		Then
		\begin{equation}

			\|\phi_i\|_{H^1_{\mathrm{crit}}(U^\eps)}^2 + \|\phi_i\|_{L^2(U^\eps)}^2
			\le \frac{C}{\kappa_\eps}
			+ \mathcal{O}_1\left(\frac{C\eps^d}{\kappa_\eps}\right)
			+ \mathcal{O}_2\left(C\eps^{d/2}\right),
		\end{equation}
		where~$C$ depends only on~$d$,~$\lambda$, and~$U$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:41:11.647905+00:00","domain":"probability theory","id":"claim_560a88132900a36e003ad62741902d6259064412f0f999bee1e02955dab98c79","kind":"lemma","schema_version":1,"statement":"[Lem of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] For any $\gamma'\in \Gamma_{\infty}$ we have that, in law,  
\begin{align}
	\eta^A_t(\gamma_t') &=  
	Q_t+ R_t(\gamma_t') + 
	S_t(\gamma_{[0,t]}') \\&+ \sum_{s=0}^{t-1} \sum_{k=1}^{N_s(\gamma_s')} \delta_{(\gamma_t',t)}(\gamma_s'+W_t^{(s,k)},t),
