{"assumptions":[],"created_at":"2026-10-27T20:29:14.936309+00:00","domain":"probability theory","id":"claim_58cfa95e7edb40f27ed04b79988e62d0032ec2110df086275ae1623641d26f78","kind":"concept","schema_version":1,"statement":"[Corollary Cor.JumpDeg2 of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] There exists a constant $C(c_{-},c_{+})$ such that, for any bond $b\in(\mathbb{Z})^*$ and $\lambda\in(0,1)$,  we have the following uniform bound for $\pi_b\widetilde{G}_\lambda$:
		\begin{equation*}
			\norm{\pi_b\widetilde{G}_\lambda}_{L^\infty}\leqslant C m 3^{3m}\lambda^{-\frac{1}{2}},\qquad\forall b\in(\mathbb{Z})^*,\ \lambda\in(0,1),\quad\forall m\in\mathbb{N}
		\end{equation*}
		\begin{proof}
			Suppose $b=\{x,x+1\}\in\overline{(z+{\scaleobj{1.2}{\square}}_m)^*}$, we can compute $\pi_b\widetilde{G}_\lambda(\eta)$ explicitly as:
			\begin{equation*}
				\pi_{b}\widetilde{G}_\lambda(\eta) = 2\sum_{y\in\mathbb{Z}}{\mathsf{D}}_1\overline{g}_\lambda(x,y)\overline{\eta}_y(\overline{\eta}_{x}-\overline{\eta}_{x+1})+\sum_{z'\in\mathcal{Z}_m}\pi_{b}[{\mathsf{D}}\overline{G}_\lambda]_m^{z'}\cdot \phi_m^{z'}+[{\mathsf{D}}\overline{G}_\lambda]_m^z\pi_b\phi_m^z.
			\end{equation*}
			Taking supreme of $\eta\in\mathcal{X}$ for each terms yields:
			\begin{equation*}
				\norm{\pi_b\widetilde{G}_\lambda}_{L^\infty}\leqslant 2\sum_{y\in\mathbb{Z}}|{\mathsf{D}}_1\overline{g}_\lambda(x,y)|+\sum_{z'\in\mathcal{Z}_m}\norm{\pi_{b}[{\mathsf{D}}\overline{G}_\lambda]_m^{z'}}_{L^\infty}\norm{\phi_m^{z'}}_{L^\infty}+\norm{[{\mathsf{D}}\overline{G}_\lambda]_m^z}_{L^\infty}\left\Vert{\pi_b\phi_m^z}\right\Vert_{L^\infty}.
			\end{equation*}
			Utilizing (equation lem.CorrectorLp of the paper) in Lemma~(lem.Homogenization of the paper) we have
			\begin{equation*}
				\norm{\phi_{m}^z}_{L^\infty}\leqslant Cm3^{3m},\quad \left\Vert{\pi_b\phi_m^z}\right\Vert_{L\infty}\leqslant C m3^{3m},\qquad \forall z\in\mathcal{Z}_m.
			\end{equation*}
			From the computation (equation eq.PibDG of the paper) we can derive
			\begin{align*}
				\sum_{z'\in\mathcal{Z}_m}\norm{\pi_{b}[{\mathsf{D}}\overline{G}_\lambda]_m^{z'}}_{L^\infty}&\leqslant \frac{2}{|{\scaleobj{1.2}{\square}}_m|}\sum_{y\in\mathbb{Z}}\left(|{\mathsf{D}}_1{\mathsf{D}}_2\overline{g}_\lambda(y,x)|+|{\mathsf{D}}_1\overline{g}_\lambda(y,x)|+|{\mathsf{D}}_1\overline{g}_\lambda(y,x+1)|\right)\\
				&\leqslant\frac{4}{|{\scaleobj{1.2}{\square}}_m|}\sum_{y\in\mathbb{Z}}\left(|{\mathsf{D}}_1\overline{g}_\lambda(y,x)|+|{\mathsf{D}}_1\overline{g}_\lambda(y,x+1)|\right).
			\end{align*}
			By the definition of the averaged slope $[{\mathsf{D}}\overline{G}_\lambda]_m^z$ in (equation eq.AveSlopeDeg2 of the paper), we can obtain
			\begin{equation*}
				\norm{[{\mathsf{D}}\overline{G}_\lambda]_m^z}_{L^\infty}\leqslant \sum_{y\in\mathbb{Z}}\frac{2}{|{\scaleobj{1.2}{\square}}_m|}\sum_{x\in z+{\scaleobj{1.2}{\square}}_m}|{\mathsf{D}}_1\overline{g}_\lambda(x,y)|.
			\end{equation*}
			Combining the above estimates, we can obtain
			\begin{align*}
				\norm{\pi_b\widetilde{G}_\lambda}_{L^\infty}&\leqslant Cm3^{3m}\sup_{x\in\mathbb{Z}}\left\{\sum_{y\in\mathbb{Z}}\left(|{\mathsf{D}}_1\overline{g}_\lambda(x,y)|+|{\mathsf{D}}_1\overline{g}_\lambda(y,x)|\right)\right\}\\
				&\leqslant Cm3^{3m}\sup_{x\in\mathbb{Z}}\left\{\sum_{y\in\mathbb{Z}}\left(|\overline{g}_\lambda(x,y)|+|\overline{g}_\lambda(y,x)|\right)\right\}\\
				&=Cm3^{3m}\sup_{x\in\mathbb{Z}}\sum_{y\in\mathbb{Z}}\overline{g}_\lambda(\{x,y\}),
			\end{align*}
			where in the last line, we use the symmetric assumption (equation eq.SymmetricAssumption of the paper).

			Using (equation lem.TwoParticleTransition of the paper) in Lemma~(lem.TransitionGreen of the paper), we have
			\begin{align*}
				\sum_{y\in\mathbb{Z}}\overline{g}_\lambda(\{x,y\}) 
				& =\int_0^\infty e^{-\lambda t}\sum_{y\in\mathbb{Z}}\overline{p}_t(\{0,1\},\{x,y\})\, {\mathrm{d}} t\\
				& \leqslant C\int_{C_1}^{\infty}\frac{e^{-\lambda t}}{(1+t)}\sum_{y\in\mathbb{Z}}\left(\exp\left(-\tfrac{y^2}{C_2t}\right)+\exp\left(-\tfrac{|y|}{C_2\log t}\right)\1_{|y|>\frac{C_3et}{\log t}}\right)\, {\mathrm{d}} t+C.
