    \begin{align*}
        \lim_{L \rightarrow \infty} \mathbb P_L^+\left(\mathcal{A}((\log L)^{\Delta + \varepsilon}) = \mathbb{T}^d_L\right) = 1.
    \end{align*}
\item If $\alpha \ge d$, then for any $\lambda > 0$, there exists a positive constant $C$ such that
\begin{align*}
\lim_{L \rightarrow \infty} \mathbb P_L^+\left(\mathcal{A}(C L) = \mathbb{T}^d_L\right) = 1.
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:42:55.317313+00:00","domain":"probability theory","id":"claim_591fc57a77e51a8182291ffab6dff7a1704b48235f4f37c866707a5d8073bd90","kind":"lemma","schema_version":1,"statement":"[Lem 18 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For every $a > 0$, with $K_a \coloneqq \log\left(e^{1/(2a^2)} - 1\right)$,
