{"assumptions":[],"created_at":"2026-10-26T20:24:47.659838+00:00","domain":"probability theory","id":"claim_5ab51bc81aa6ded047bf75271a8b763d2ce12573e6eea3a7e369253cf6dcd949","kind":"theorem","schema_version":1,"statement":"[Proposition 19 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] If $X$ has bounded variation, then for every non-empty word $I = i_1\dots i_n$, $n\leq \kappa-1$:
    \[
K^{(I)}
=
\sum_{\pi \in NC(n)}
\left(
\prod_{(p,q) \in P(\pi)} (-1) \delta_{i_p,i_q}
\right)
K_{\,i_{U_1},\ldots,i_{U_r}},
\]
with the convention $K^{(\emptyset)} = K_\emptyset$ and for a non-empty word $J = j_1 \dots j_m$
\begin{equation}
K_{J}(s,t) =   (-1)^{m} \int_{s < u_1 < \dots < u_m <t} K(s, u_1)K(u_1, u_2) \dots K(u_{m-1}, u_{m})K(u_{m}, t) dX^{(j_1)}_{u_1}\dots dX^{(j_m)}_{u_m}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.483795+00:00","domain":"probability theory","id":"claim_5abc33b62903bdf35fb907ce2cd118ba6df92c44099e86cb9dde68fafa19e379","kind":"lemma","schema_version":1,"statement":"[Lemma 47 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta\in (0,1)$ and $b\geq v + 2\lambda + 2\log(2)\pi$.
Then
\begin{multline*}
\int_{D^{2}}
e^{-(b-v-2\lambda)^{2}/(2\log(2)/\pi + 2 G_{D}(z,w))}
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w
\\
\leq 
e^{-((2\pi\eta)\wedge 1)(b-v-2\lambda - 2\log(2)/\pi)}
(c_{\eta}\vert D\vert \diam(D)^{2\eta} +
\Vert 1_{D} \Vert_{H^{-\eta}(\C)}^{2}
),
\end{multline*}
where $\vert D\vert$ is the Lebesgue measure (area) of $D$,
and $c_{\eta}>0$ is a constant depending only on $\eta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:41:33.832733+00:00","domain":"probability theory","id":"claim_5abe6a5d909bb92f3d2400a84faf75a2fd8e06521927f0f4de3aef18f9ea9678","kind":"theorem","schema_version":1,"statement":"[Theorem 27 (Intrinsic quotient-space characterization of strict coarse-depth loss) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Fix $m<r$ and assume exact depth $r$ at $\theta_0$ together with \cref{ass:regularity}. Let $T\subset T_{\theta_0}\Theta$ be a tangent block. Set
\begin{equation}
L_m:=Dq_{\cQ}^{(m)}(\theta_0)|_T, \qquad L_r:=Dq_{\cQ}^{(r)}(\theta_0)|_T, \qquad K_r:=\Ker(L_r).
\end{equation}
Let $\pi:T\to T/K_r$ be the quotient map, and let
\begin{equation*}
\widetilde L_m, \widetilde L_r:T/K_r\to \RR^N
\end{equation*}
denote the unique linear maps induced by $L_m$ and $L_r$, where $N$ is any ambient coordinate dimension containing the relevant images.
Then the following hold:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $\widetilde L_r$ is injective,
\item the depth-$m$ window is first-order locally sufficient relative to depth $r$ on $T$ if and only if
\begin{equation}
\Ker(\widetilde L_m)=\{0\},
\end{equation}
\item the depth-$m$ window is not first-order locally sufficient relative to depth $r$ on $T$ if and only if
\begin{equation}
\rank(\widetilde L_m)<\dim(T/K_r),
\end{equation}
\item the depth-$m$ window is not first-order locally sufficient relative to depth $r$ on $T$ if and only if
\begin{equation}
\rank\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_T\bigr)<\rank\bigl(Dq_{\cQ}^{(r)}(\theta_0)|_T\bigr).
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:41:33.830398+00:00","domain":"probability theory","id":"claim_5abeac6eb71d352f1955d3b480980abd53b13b237a1fccededbb470c50304e3c","kind":"theorem","schema_version":1,"statement":"[Proposition 11 (Pathwise truncation identity) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Let $m<r$. Whenever both boundary words are defined on a sample path,
