    \end{displaymath}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:29:28.002704+00:00","domain":"probability theory","id":"claim_5c079ff9339b4154e976cef61a05fe6d42686178de3d45bf3f10c97d5c329943","kind":"theorem","schema_version":1,"statement":"[Proposition 27 (Thermal equilibrium and compact-temperature bounds) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] For every $\beta>0$, \eqref{eq:free-energy} has a unique minimizer $\mu_\beta=\rho_\beta\D x$, whose density $\rho_\beta$ is radial, strictly positive, bounded, and smooth.  Writing $U_\beta$ for the logarithmic potential generated by $\mu_\beta$, there exists a constant $C_\beta\in\R$ such that
\begin{equation}
 \log\rho_\beta(x)
 =-\beta\left(\frac{|x|^2}{2}+U_\beta(x)\right)+C_\beta,
 \qquad U_\beta=\g*\mu_\beta.
\end{equation}
Moreover, for every multi-index $\alpha$ there exists a constant $0<C_{\beta,\alpha}'<\infty$ such that

\begin{equation}
 |\partial^\alpha\rho_\beta(x)|
 \le C_{\beta,\alpha}'(1+|x|)^{\beta+|\alpha|}e^{-\beta|x|^2/2}.
\end{equation}

Let
\begin{equation}
 c_\beta:=\iint_{\C^2} \g(x-y)\,\D\mu_\beta(x)\D\mu_\beta(y).
\end{equation}
For every compact interval $I=[\beta_-,\beta_+]\Subset(0,\infty)$,
\begin{equation}
 \|\rho_\beta\|_{L^\infty(\C)}\le\frac1\pi,
 \qquad
 \int_{\C}|x|^2\,\D\mu_\beta(x)=\frac12+\frac2\beta
 \qquad (\beta\in I).
\end{equation}
Moreover, for every $m\ge0$ and $\theta>0$,
\begin{equation}
 \sup_{\beta\in I}\left(
 |c_\beta|+
 \int_{\C}(1+|x|)^m\,\D\mu_\beta(x)+
 \int_{\C}e^{-\theta\beta U_\beta(x)}\,\D\mu_\beta(x)
 \right)<\infty.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.202369+00:00","domain":"probability theory","id":"claim_5c0cb03366074a23f35338e706eaced67629acb17421f18102437aba29d66ba7","kind":"definition","schema_version":1,"statement":"[Definition rem:density of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] The choice (equation eq:canond of the paper) of $\r\in\ensuremath{\mathcal D}_{\ensuremath{\mathcal A},N}$ will be called the {\em canonical density} associated to $\nu$. We also define the {\em canonical tensor product} associated to $\nu\in \mathcal{P}(\Omega)$ as the product measure 
