{"assumptions":[],"created_at":"2026-10-27T11:32:18.850267+00:00","domain":"probability theory","id":"claim_5c7f9d0ca2946c8ccf8af26290bcd9809c28c16c7997814f06888d70b7e16708","kind":"concept","schema_version":1,"statement":"[Thm 14 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] Assume that $u_0(i,x)$ is a nontrivial, absolutely continuous and compactly supported function  in $[0,i_\dagger)\times\R$, which is  nonnegative for $x\ge 0$ and nonpositive  for $x\le 0$, uniformly in $i\in[0,i_\dagger)$, such that
	\begin{equation}

	\int_0^{+\infty}\Big(  \K_* *  u_0(i,x)+ \K_* *  u_0(i,-x)\Big)\md x=0~~~~~ \hbox{for all $i\in[0,i_\dagger)$.}
\end{equation}
	 Let $\mathbf\Phi$ be the solution   to the linear renewal equation \eqref{renewal eqn=3} for $t>0$ and $x\in\R$ starting with initial condition $u_0$. Choose $T>i_\dagger$ sufficiently large so that Theorem \ref{thm_3.1} holds true for all $t\ge T$. Then, up to increasing $T$ if necessary, the function $\mathbf\Phi$ has the following asymptotics  
	\begin{equation*}
		\mathbf\Phi(t,x)\sim \frac{x-c_*t}{t^{\frac{3}{2}}}e^{-\frac{(x-c_*t)^2}{4bt}},~~~~~~~~t\ge T,~~|x-c_*t|\le O(t^{\frac{1}{2}+\varsigma}),
	\end{equation*}
	for $\varsigma\in(0,\frac{1}{2})$ small enough. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.778943+00:00","domain":"probability theory","id":"claim_5c82de37e2f27477f9b10e02cd7e0668294400c69b379d83b13fce1a16b49c1f","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2603.25615, 'Fourier dimension of Mandelbrot cascades on planar curves'] For some $p >4$, let $\Phi(t)\lesssim t^{-p}$ when $t \geq 1$. Let $X_1,\ldots, X_N$ be independent random variables with zero expectation such that
\begin{equation}
\PP(X_k>t)\le\Phi(t)    
\end{equation}
for all $1\le k\le N$. Then, for all $a_1,a_2,\ldots a_N\ge 0$, $M>1$, and $t>0$,
\[\PP\left(\sum_{k=1}^N a_k X_k>t\right)=N\Phi(M)+\exp\left(-\lambda t+O(\lambda^2)\sum_{k=1}^N a_k^2\right)\,,\]
where 
\begin{equation}
    \lambda=\frac{q\log M}{M\max_{1\le k\le N}a_k}\,.
\end{equation}
and $q\leq p/2-1$. The $O$-constant only depends on $p$ and $\Phi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:23.330951+00:00","domain":"probability theory","id":"claim_5c8996ff7e212c2f34a4f13ab6297d3d0f6f23e658a9a1c870bafdb53261a56d","kind":"concept","schema_version":1,"statement":"[Corollary 13 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $(\xi^R,\Xi^R)$ be the underlying MAP of $R$ with respect to the norm $\|\cdot\|_{\text{L}^1}$ in dimension $d=2$. For every $f\in C^2_b(\mathbb{R}\times\mathcal{S}^+)$ satisfying the boundary conditions




	\begin{enumerate}[i]
		\item $(1,1,-1)\cdot \grad{f}(w,0,1)=0\enspace\enspace  \forall w\in\mathbb{R};$
		\item $(1,-1,1)\cdot \grad{f}(w,1,0)=0\enspace\enspace \forall w\in\mathbb{R},$
	\end{enumerate}
	the process
	\begin{equation*}
		f(\xi_t^R,\Xi^R_t)-f(\xi_0^R,\Xi^R_0)-\int_0^t Af(\xi^R_s,\Xi_s^R) ds,
	\end{equation*}
	for $t<\varsigma\coloneqq\inf\{s>0:\Xi^R_s=\dagger\}=\int_0^\upsilon \|R_s\|_{\text{L}^1}^{-\alpha} ds$, is a martingale, where the operator $A:C^2_b(\mathbb{R}\times\mathcal{S}^+)\to C^2_b(\mathbb{R}\times\mathcal{S}^+)$ is defined by
	\begin{equation*}
		Af(y,\boldsymbol{\theta})={\rm e}^{\alpha y} \mathcal{A}f(y,\boldsymbol{\theta}),
	\end{equation*}
	where $\mathcal{A}:C^2_b(\mathbb{R}\times\mathcal{S}^+)\to C^2_b(\mathbb{R}\times\mathcal{S}^+)$ is the operator









	\begin{align*}
		\mathcal{A}f(y,\boldsymbol{\theta})=& c_1\int_y^\infty (f(y,\begin{pmatrix}
			\theta^{(1)}+(1-{\rm e}^{y-x})\theta^{(2)} \\ {\rm e}^{y-x}\theta^{(2)}
		\end{pmatrix})-f(y,\boldsymbol{\theta}) \\
		&\qquad\qquad\qquad\qquad+(1-{\rm e}^{x-y})\mathbbm{1}_{(y,\log(1+{\rm e}^y))}(x)\begin{pmatrix}
			1 \\ \theta^{(2)} \\ -\theta^{(2)}
		\end{pmatrix}\cdot \grad{f(y,\boldsymbol{\theta})}){\rm e}^x({\rm e}^x-{\rm e}^y)^{-(1+\alpha)} dx \\
		&+c_1\int_y^\infty (f(y,\begin{pmatrix}
			{\rm e}^{y-x}\theta^{(1)} \\ (1-{\rm e}^{y-x})\theta^{(1)}+\theta^{(2)}
		\end{pmatrix})-f(y,\boldsymbol{\theta}) \\
		&\qquad\qquad\qquad\qquad+(1-{\rm e}^{x-y})\mathbbm{1}_{(y,\log(1+{\rm e}^y))}(x)\begin{pmatrix}
			1 \\ -\theta^{(1)} \\ \theta^{(1)}
		\end{pmatrix}\cdot \grad{f(y,\boldsymbol{\theta})}){\rm e}^x({\rm e}^x-{\rm e}^y)^{-(1+\alpha)} dx,
	\end{align*}
	where $c_1\coloneqq\frac{-\Gamma(1+\alpha)\sin(\pi\alpha)}{\pi}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:09.856448+00:00","domain":"probability theory","id":"claim_5c8cfe2d48036f25afaa0c88de485380d978db0722fee8ba412ca39e58948640","kind":"concept","schema_version":1,"statement":"[Proposition 16 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] There exist $C_0,C_1,C_2\ge1$ depending only on $\Lambda$, such that for $C_2\le p\le C_1^{-1}\gamma$, the (stationary) corrector gradient satisfies
