	\qquad \text{with } \sigma^2 = \log(1+\varrho) \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:40:21.312157+00:00","domain":"probability theory","id":"claim_5de6fee76373103a32b27458e58f7c97444a13947e1933696a8be3d34b77de95","kind":"concept","schema_version":1,"statement":"[Lemma 24 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] A sequence $\widetilde{\mu}^{\otimes p}$ in $\widetilde{\mathcal{M}}_1^{\otimes p}$ converges to $\{ \widetilde{\alpha}_i^{\otimes p} \}$ in $(\widetilde{\mathcal{X}}^{\otimes p}, \mathbf{D}^{\otimes p})$ if there exists a decomposition
    \[
    \mu_n^{\otimes p} = \sum_{i \in I} \alpha_{i, n}^{\otimes p} + \beta_n^{\otimes p}
    \]
    and points $x_{i, n} \in \mathbb{R}^d$ such that
    \begin{enumerate}
        \item $\alpha_{i, n}^j \ast \delta_{x_i^n} \to \alpha_i^j$ weakly for all $i \in I$ and  $j = 1 , \dots , p$,
        \item $\beta_n^j$ \emph{totally disintegrates}, i.e., $\lim_{n \to \infty} \sup_{x \in \mathbb{R}^d} \beta_n^j (B(x, R)) = 0$ for any finite $R > 0$.
        \item Distinct sequences are \emph{widely separated}, i.e., $\lim_{n \to \infty} |x_{i_1}^n - x_{i_2}^n| = \infty$ for any $i_1 \ne i_2$.
    \end{enumerate}
    As a consequence, the inclusion $\widetilde{\mathcal{M}}_1 \hookrightarrow \widetilde{\mathcal{X}}_{\le 1}^{\otimes p}$ is a continuous injection and $\widetilde{\mathcal{M}}_1$ is a dense subset of $\widetilde{\mathcal{X}}_{\le 1}^{\otimes p}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.494292+00:00","domain":"probability theory","id":"claim_5de73f08920dc97b2de49804ebae502a81ffc5936114580f43d43e19d418c7f0","kind":"theorem","schema_version":1,"statement":"[Corollary cor:Poisson_fringe of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume that $\mu$ is critical and belongs to the domain of attraction
of an $\alpha$-stable law for some $\alpha\in(1,2]$. Let $(k_n)_{n\geq 0}$ be
an integer sequence such that $k_n\to\infty$ and $k_n=o(n)$.
Suppose that, for every $k\ge1$ and every plane tree $\tau$, $
G_k(\tau)=1
\implies
|\tau|=k$.
Then:
\begin{enumerate}
\item[(i)] If $(n\pi_n)$ is bounded, then
\begin{equation}

d_{\mathrm{TV}} \left(
\# \{u \in \mathcal{T}^{n} : G_{k_{n}}( \mathcal{T}^{n}_{u})=1\},
\mathrm{Poisson}(n \pi_{n})
\right)
\quad \mathop{\longrightarrow}_{n \rightarrow \infty} \quad 0.
\end{equation}

\item[(ii)] If $n\pi_n\to\infty$, then
$$
\frac{
\#\{u\in\mathcal T^n: G_{k_n}(\mathcal T^n_u)=1\}
}{n\pi_n}
\quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad 1.
$$
In particular,
$$
\#\{u\in\mathcal T^n: G_{k_n}(\mathcal T^n_u)=1\}
\quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad \infty.
$$
\end{enumerate}","status":"unverified"}

