{"assumptions":[],"created_at":"2026-10-27T17:43:53.645974+00:00","domain":"probability theory","id":"claim_5e6cf83535ec83ecb7b22c40c8bada06201bf81eb40df91538f12219104997d8","kind":"theorem","schema_version":1,"statement":"[Corollary cor:useful-bound of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\alpha\in\mathbb R$ be a real number and $B,\Gamma$ be two continuous functions.
    Define the function
    \begin{align*}
        F_t(x,y)=\frac{t^\alpha}{B(x)}\exp\left(-\frac{t}{\Gamma(y)}\right)\,.
    \end{align*}
    Assume that $B,\Gamma$ are strictly positive on $(0,a_+]$ and that there exists $C_\beta,C_\gamma>0$ and $\beta,\gamma>0$ such that $B(x)\sim C_\beta x^\beta$ and $\Gamma(x)\sim C_\gamma x^\gamma$ when $x\rightarrow0$.
    Then, for any $\epsilon=\epsilon(t)$ converging to $0$ as $t$ diverges and $\Tilde{a}_+=\Tilde{a}_+(t)\leq a_+$, there exists $k=k(t)$ an integer depending on $t$ and a sequence of increasing values $(a_0\leq\ldots\leq a_k)$ (implicitly depending on $t$) such that $a_0=\epsilon$, $a_k=\Tilde{a}_+$, and satisfying
    \begin{align*}
        \lim_{t\rightarrow\infty}\sum_{i=1}^kF_t(a_{i-1},a_i)=0\,.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.162220+00:00","domain":"probability theory","id":"claim_5e6d5881990f2fc74580ea693da58cd5fdf53cbd0bfc6fb123ce46ec9ad1ffcd","kind":"theorem","schema_version":1,"statement":"[Prop Prop_TotallyReal=>UniformlyFredholm of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let $({\mathbf{B}},f,{\mathbf{V}})$ be a family of local residue conditions such that
