{"assumptions":[],"created_at":"2026-10-26T20:24:30.012744+00:00","domain":"probability theory","id":"claim_5ec495f92e0c9c6b5d6ec69e076e9a55b8943640afa981b70d6e1c722d6bc85d","kind":"definition","schema_version":1,"statement":"[Definition 16 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $Y \in \mathcal{S}^2_{\beta}$.
	\begin{itemize}
		\item  The process $Y$ is said to be a strong $\mathcal{E}^f$-supermartingale (resp. $\mathcal{E}^f$-submartingale), if $\mathcal{E}^f_{\sigma,\eta}(Y_{\eta}) \leq Y_\sigma$ (resp. $\mathcal{E}^f_{\sigma,\eta}(Y_{\eta}) \geq Y_\sigma$) a.s. on $\sigma \leq \eta$, for all $\sigma,\eta \in \mathcal{T}_{[0,T]}$.
		\item The process $Y$ is said to be a strong $\mathcal{E}^f$-martingale, if it is both a strong $\mathcal{E}^f$-supermartingale and a strong $\mathcal{E}^f$-submartingale.
	\end{itemize}
	Let $\sigma,\eta \in \mathcal{T}_{[0,T]}$.
	\begin{itemize}
		\item The process $Y$ is said to be a strong $\mathcal{E}^f$-supermartingale (resp. $\mathcal{E}^f$-submartingale) on $[\sigma,\eta]$, if for all $\sigma^{\star}, \eta^{\star} \in \mathcal{T}_{[0,T]}$ such that $\sigma \leq \sigma^{\star} \leq \eta^{\star} \leq \eta$ a.s., we have $\mathcal{E}^f_{\sigma^{\ast},\eta^{\ast}}(Y_{\eta^{\ast}}) \leq Y_{\sigma^{\ast}}$ (resp. $\mathcal{E}^f_{\sigma^{\ast},\eta^{\ast}}(Y_{\eta^{\ast}}) \geq Y_{\sigma^{\ast}}$) a.s. Finally, the notion of $\mathcal{E}^f$-martingale on $[\sigma,\eta]$ is defined similarly.
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:48:43.579776+00:00","domain":"probability theory","id":"claim_5ecad0bd4b2d8ed6fbbec3c16f51283c2d36f080bc7ab8c150b8bab7d4fd87b4","kind":"concept","schema_version":1,"statement":"[Theorem 34 of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Assume that $\alpha\to\infty$, with $\ell$ fixed and $M=O(\alpha^{\sfrac12}/(\log\alpha)^2)$.
		\begin{enumerate}[(i)]
			\item Consider an FMIS $S$ of $G$. Define 
			\begin{align}
				\mathscr{P}(S)&:=\exp(P|F|+\tfrac12P|R^*(S)|+P\b(V)-\b(S))\prod_{t=1}^{\alpha}\frac{t}{n_t},\\
				\mathscr{E}(\alpha,M)&:=\frac{M^2\log\alpha}{\alpha}+\frac{M(\log\alpha)^2}{\alpha}.
			\end{align}
			Then the IMFIS process samples $S$ with probability
			\begin{align}
				\mathbb{P}(\boldsymbol{S}_{\infty}=S)&=(1+O(\mathscr{E}(\alpha,M)))\mathscr{P}(S).
			\end{align}
			\item The IMFIS process samples an FMIS with probability $$\mathbb{P}(|\boldsymbol{S}_{\infty}|=\alpha)=1-O(M/\alpha).$$ In particular, for $\alpha$ sufficiently large, this probability is positive, so $G$ has at least one FMIS.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

