			_{p^{\prime }}^{p^{\prime }}+\left\Vert \nu \right\Vert _{p^{\prime
			}}^{p^{\prime }})^{1-\hat{p}} \overline{W}^{\mathcal{A}}_{1}(\mu ,\nu )^{\hat{p}}.

		\end{equation}
		In particular, for  $ \mathcal{A}=\{\varphi \in  C_{b}^{1}({\mathbb{R}}^{d})\text{ s.t. }\left\Vert \varphi \right\Vert
		_{\infty }\times \left\Vert \nabla \varphi \right\Vert _{\infty }\leq 1 \}$, (equation assump_calA of the paper) holds with $\mathbf{e}_d=d+1/2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.201362+00:00","domain":"probability theory","id":"claim_60faeaa5236bb668f991a1bcc04f5380fc71076cd83f902aac84b17d0a10fe79","kind":"lemma","schema_version":1,"statement":"[Lemma psi_exp of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] For any $\varepsilon \in (0,1)$ and $T \in \mathbb{R}_+$ we have
