{"assumptions":[],"created_at":"2026-10-27T20:50:48.852843+00:00","domain":"probability theory","id":"claim_61371650710013c95a3763d265b9ef3754045a04278a5f76838f595b7946f264","kind":"theorem","schema_version":1,"statement":"[Theorem thm:stat.dist.alpha>0.beta=lambda0 of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] \addcontentsline{toc}{subsection}{Theorem \thetheorem\ {case \texorpdfstring{$\beta=\lambda_o$}{Theorem β=λₒ}} and \texorpdfstring{$\alpha>0$}{α>0}}
