            \mbox{Exactly one component of } G_M^n(r) \\
            \mbox{ has }d_M\mbox{-diameter at least } r\phi
        \end{array}
        \right) \geq 1- C r^{-d}\exp(-c\phi)\,.
        \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.686367+00:00","domain":"probability theory","id":"claim_61b33d1bb9c3f934c5724066c5ad9960ed724a80881480e4dd4551b40615b9f4","kind":"definition","schema_version":1,"statement":"[Definition Cumu of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] The joint cumulants of mixed Chebyshev  moments are defined recursively by
    \begin{equation}
        \begin{gathered}
            \kappa_X(n_1)=\mathbb{E}\!\Big[\mathrm{Tr}\big(U_{n_1}(\tfrac{X}{2})\big)\Big],\\
            \kappa_X(n_1,n_2)=\mathbb{E}\!\Big[\mathrm{Tr}\big(U_{n_1}(\tfrac{X}{2})\big)\mathrm{Tr}\big(U_{n_2}(\tfrac{X}{2})\big)\Big]-\kappa_X(n_1)\kappa_X(n_2),\\
            \cdots\\
            \kappa_X(n_1,\dots,n_s)=\mathbb{E}\!\Big[\mathrm{Tr}\big(U_{n_1}(\tfrac{X}{2})\big)\mathrm{Tr}\big(U_{n_2}(\tfrac{X}{2})\big)\cdots\mathrm{Tr}\big(U_{n_s}(\tfrac{X}{2})\big)\Big]-\sum_{\Pi}\prod_{P\in\Pi}\kappa_X\big(\{n_j\}_{j\in P}\big),
        \end{gathered}
    \end{equation}
    where the sum runs over all nontrivial partitions $\Pi$ of $[s]$, i.e., excluding the partition $[s]$ itself.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:10.193370+00:00","domain":"probability theory","id":"claim_61b7f6285d286212c7a38dc9475be467d5987962f74e83be0551830165fceb8a","kind":"definition","schema_version":1,"statement":"[Definition 12 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Zone of Eventual Relaying.}

For a building $(a, b)$, we define its \textit{zone of eventual relaying} $\zone (a, b)$ as the set of points of $\Half$ that are eventually relayed by $(a, b)$:
\[\zone (a, b) := \{(x, y)\in \Half : \exists n\in \N : \tau^{(n)}(x, y) = (a, b).\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:38:04.524369+00:00","domain":"probability theory","id":"claim_61c33aa866f3fd4c34a20dba1528fa40df06466f1331e32a4888a91c07c346cf","kind":"lemma","schema_version":1,"statement":"[Lemma eq:kernel_lower_bound of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:integrability}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel.

    Suppose that $J$ satisfies $J(x,y) = \Omega(d_G(x,y)^{-d \alpha})$ with $\alpha > 0$.

    If $\alpha > 1$ then there exists $c = c(G,J) > 0$ such that     for all $x \in V$ and $r \in \mathbf{N}$

    \begin{equation}

        c
        r^{d(1-\alpha)}
        \leq
        \sum_{L = r}^{\infty}
        \sum_{y \in S(x,L)}
        J(x,y).
    \end{equation}

    If $\alpha \leq 1$ then $\sum_{L = r}^{\infty} \sum_{y \in S(x,L)} J(x,y) = \infty$ and hence $\sum_{L = r}^{\infty} \mathbf{E}_{\beta} \left[ \deg(x,L) \right] = \infty$ for all $x \in V$ and $r \in \mathbf{N}$.

    Suppose that $J$ satisfies $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$.

    Then there exists $c = c(G,J) > 0$ such that     for all $x \in V$ and $r \in \mathbf{N}$

    \begin{equation}

        \sum_{L = r}^{\infty}
        \sum_{y \in S(x,L)}
        J(x,y)
        \leq 
        c 
        r^{d(1-\alpha)}.
    \end{equation}

    In particular, $\sum_{y \in V \setminus \{x\}} J(x,y) < \infty$ and $\mathbf{E}_{\beta} \left[ \deg(x) \right] < \infty$ for all $x \in G$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.782228+00:00","domain":"probability theory","id":"claim_61c4bec160dfa5695a8bec8eeb20ace262d7b0963c984bd4c99d48049e63adea","kind":"lemma","schema_version":1,"statement":"[Lm of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Define 
    \begin{equation*}
        G(A,x):=F(A,P_0(A)x,P_1(A)x,\dots,P_k(A) x),
    \end{equation*}
    and also 
    \begin{equation*}
        \Tilde{G}(A,x) := G\left(\frac{\min(100,||A||)}{||A||}A,\frac{\min(100,||x||)}{||x||}x\right). 
    \end{equation*}
    Then $\Tilde{G}(A,x)$ is Lipschitz on $\mathbb{R}^{n^2+n}$ with $||\Tilde{G}||_{Lip} \lesssim 1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:24.614774+00:00","domain":"probability theory","id":"claim_61c5613955f1f7bdeaa7b69b10b9399ebfd104e7181ed0d5a91fa9d27b603f1e","kind":"definition","schema_version":1,"statement":"[Definition 11 (Transition rate) of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] The \textbf{$AB$ transition rate} \(k_{AB}\) is defined as:  
    \begin{equation*}
        k_{AB} = \lim_{T \to \infty} \frac{\mathrm{N}_T}{T},
    \end{equation*}
    which quantifies the rate of transitions from \(A\) to \(B\). Additionally, the limits:  
    \begin{equation*}
        T_{AB} := \lim_{\mathrm{N} \to \infty} \frac{1}{\mathrm{N}} \sum_{n=0}^{\mathrm{N}-1} (\tau_{B,n+1}^+ - \tau_{A,n}^+),
    \end{equation*}
    and  
    \begin{equation*}
        T_{BA} := \lim_{\mathrm{N} \to \infty} \frac{1}{\mathrm{N}} \sum_{n=0}^{\mathrm{N}-1} (\tau_{A,n+1}^+ - \tau_{B,n}^+),
    \end{equation*}
    are called the \textbf{expected transition times} from \(A \to B\) and \(B \to A\), respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:53:10.203728+00:00","domain":"probability theory","id":"claim_61d21cb11d8f49becbe2451a9443cc7c21bbe541931a36b0384367152a402da0","kind":"definition","schema_version":1,"statement":"[Defi Def:Realization-WSC of arXiv:2608.29013, 'Weighted Homology and Cohomology of Weighted Polyhedra'] \ \vskip 0.1cm
  Any weighted simplicial complex $(K,\mu)$ determines
  a map $\lambda_{\mu}: |K| \rightarrow \mathbb Z_+$ by:
      \begin{equation} 
         \lambda_{\mu} (x) = \mu(\mathrm{Car}_K(x)), \ \forall  x\in |K|,
    \end{equation}
   where $\mathrm{Car}_K(x)$ is the unique simplex of $K$
   such that $|\mathrm{Car}_K(x)|$ contains $x$ in the relative interior.  
     We call $(|K|,\lambda_{\mu})$ the \emph{geometric realization} of $(K,\mu)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:53:39.162671+00:00","domain":"probability theory","id":"claim_61d229c5a2ea7c278565dd4bde930390263bdaba2143b23923348eaaf7398eef","kind":"theorem","schema_version":1,"statement":"[Proposition 38 of arXiv:2608.26953, '2608.26953'] Let \(\nabla\) be a left connection and let \( \sigma = [v_0,v_1,v_2] \in S_2\). Write \( e_{01}^{ \sigma} \coloneq d_2\sigma,\ e_{02}^{\sigma} \coloneq d_1\sigma,\ e_{12}^{\sigma} \coloneq d_0\sigma, \) and, for \(0 \leq i < j \leq 2\), set \( R_{ij}^{\sigma} \coloneq R_{e_{ij}^{ \sigma} } \colon M_{v_i} \rightarrow M_{v_j}. \) Then \( ( K_\nabla )_\sigma = R_{02}^{\sigma} - R_{12}^{\sigma} R_{01}^{\sigma} \colon M_{v_0} \rightarrow M_{v_2}.\)
