{"assumptions":[],"created_at":"2026-10-27T07:12:19.496332+00:00","domain":"probability theory","id":"claim_61f54193a10d581e223dc9ab1f922624eaeb01a5683f0217a5560542f66d3c99","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2608.18075, '2608.18075'] For $z\in\mathsf X$ and $h\in E_z$, define
\begin{align*}
 u_{z,h}(\omega)
 =-K_q(z,Y(\omega))h
 =-\sum_i\chi_i(z,Y(\omega))K_i(z)h.
\end{align*}
Then $(z,h,\omega)\mapsto u_{z,h}(\omega)$ is Borel and, for every fixed
$(z,h)$,
\begin{align*}
 u_{z,h}\in\mathbb D^{1,p}(\mathcal H)
 \qquad\text{for every finite }p.
\end{align*}
In addition,
\begin{align}
 \|u_{z,h}\|_{\mathcal H}
 +\|D_{\mathcal H}u_{z,h}\|_{\HS}
 &\le C_q\|h\|,
 \\
 \|D_{\mathcal H}u_{z,h}\|_{\rm op}
 &\le C_q\|h\|.

\end{align}
Furthermore, 
\begin{align}
 Y\bigl(\omega+\mathbf u_{z,h}(\omega)\bigr)
 =
 Y(\omega)-\Gamma K_q(z,Y(\omega))h,
\end{align}
and whenever $\|h\|\le(2C_q)^{-1}$,
\begin{align}
 (T_{z,h})_\#\mathbf P&\sim\mathbf P,\notag\\
 \operatorname{Ent}\bigl((T_{z,h})_\#\mathbf P\mid\mathbf P\bigr)
 &\le C_{\rm Ram}\|h\|^2,
\end{align}
where
\begin{align*}
 T_{z,h}(\omega)
 =\omega+\mathbf u_{z,h}(\omega).
\end{align*}","status":"unverified"}

