{"assumptions":[],"created_at":"2026-10-27T12:59:58.439623+00:00","domain":"probability theory","id":"claim_62850337d4bac07bc1a268c70654f0bc8b6487728baab0edc8ea906e6887fd29","kind":"definition","schema_version":1,"statement":"[Definition def:threespinsystems of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] We fix an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \in \ensuremath{\mathbb{N}}^*$, three inverse temperatures $\beta, \beta_1, \beta_2 \geq 0$ and introduce three spin systems on the extended lattice:
\begin{itemize}
    \item The first one is the XY model on the extended lattice $\ensuremath{\mathbb{Z}^d}_n$ with inverse temperature $n \beta$, i.e.,
    \begin{equation} 
        \mu_{\Lambda_L^n, n,  \beta}^{\mathrm{XY}}(d \theta)  := \frac{1}{Z_{\Lambda_L^n, n,  \beta}^{\mathrm{XY}}} \exp \left( n \beta \sum_{x \sim_n y}  \cos ( \theta_x - \theta_y ) \right) \prod_{x \in \Lambda_L^n} d \theta_x.
    \end{equation}
    We denote by $\left\langle \cdot \right\rangle_{L, n  ,\beta}^{\mathrm{XY}}$ the expectation with respect to this measure.
    \item The second one is an XY model on the extended lattice $\ensuremath{\mathbb{Z}^d}_n$ with heterogenous temperatures defined as follows. For any $n \geq 2$ and any pair of inverse temperatures $\beta_1 , \beta_2 > 0$, we set
\begin{equation} 
        \mu_{\Lambda_L^n, n, \beta_1 , \beta_2}^{\mathrm{XY}}(d\theta) := \frac{1}{Z_{\Lambda_L^n, n, \beta_1,  \beta_2 }^{\mathrm{XY}}}\exp \left( \beta_1 \sum_{\substack{x \sim_n y \\ x \in \ensuremath{\mathbb{Z}^d} }} \cos (\theta_x - \theta_y) + n \beta_2 \sum_{\substack{x \sim_n y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} \cos (\theta_x - \theta_y) \right) \prod_{x \in \Lambda_L^n} d \theta_x.
\end{equation}
 We denote by $\left\langle \cdot \right\rangle_{L, n  ,\beta_1 , \beta_2}^{\mathrm{XY}}$ the expectation with respect to this measure.
    \item The third one is a spin system defined on the extended graph $\ensuremath{\mathbb{Z}^d}_{3}$ where the interaction on the edges connected to $\ensuremath{\mathbb{Z}^d}$ is the one of an XY model with inverse temperature $\beta_1$ and the interaction along the other edges is the one of a Villain model with inverse temperature $\beta_2$, i.e.,
    \begin{equation} 
        \mu_{\Lambda_L^3, \beta_1 , \beta_2}^{\mathrm{XY/Vil}}(d\theta) := \frac{1}{Z_{\Lambda_L^3, \beta_1 , \beta_2 }^{\mathrm{XY}}}\exp \left( \beta_1 \sum_{\substack{x \sim_3 y \\ \{ x , y \} \cap \ensuremath{\mathbb{Z}^d} \neq \emptyset}} \cos (\theta_x - \theta_y) \right) \prod_{\substack{x \sim_3 y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} v_{\beta_2}(\theta_x - \theta_y) \prod_{x \in \Lambda_L^3} d \theta_x.
    \end{equation}
    We refer to this model as \textbf{the XY/Villain model} and denote by $\left\langle \cdot \right\rangle_{L  ,\beta_1, \beta_2}^{\mathrm{XY/Vil}}$ the expectation with respect to this measure.
\end{itemize}","status":"unverified"}

