{"assumptions":[],"created_at":"2026-10-26T19:25:12.194700+00:00","domain":"probability theory","id":"claim_632a2283da76e0a073414f7875f1befb39c3c06031783b56ec058a6787a9c5b8","kind":"concept","schema_version":1,"statement":"[Lem 13 (\hspace{-0.05em}{\cite[Lemma~3.1) of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] {mark2022cutoff}}]
