{"assumptions":[],"created_at":"2026-10-27T11:26:52.680938+00:00","domain":"probability theory","id":"claim_641fc2b5c318166a27ac101a8f7956acbd371c7e2f29404fee5079ced0e8e463","kind":"concept","schema_version":1,"statement":"[Mainthm 2 of arXiv:2609.03777, '2609.03777'] \begin{enumerate}[(i)]
