{"assumptions":[],"created_at":"2026-10-27T13:52:23.567220+00:00","domain":"probability theory","id":"claim_6487ab1e408adf34d49560766185d21773b6a8ba10fed427300a8643135c7b44","kind":"theorem","schema_version":1,"statement":"[Theorem T:SLND of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume Hypothesis (H:para of the paper) and the Dalang condition~(equation E:main of the paper). Let $0<S<T<\infty$.
  \begin{enumerate}[\rm (i)]

    \item \emph{(SLND in time)}\index{strong local nondeterminism (SLND)!temporal}
          \begin{enumerate}[\rm (a)]

            \item If $\beta = 1$, $\gamma \ge 0$; or $\beta = 2$, $\gamma \in [0,
                      1]$, then there exist constants $C > 0$ and $\delta>0$ such that for
                  all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1, \dots, t_n
                    \in [S, T]$ with $\max_{1\le j \le n}|t-t_j| \le \delta$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} |t-t_j|^{2\rho}.
                  \end{align}

            \item If $\beta \in (0, 2)$, $\gamma \ge 0$, then there exists a constant $C>0$ such
                  that for all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1,
                    \dots, t_n \in [S, T]$ with $\max\{t_1, \dots, t_n \} \le t$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} (t-t_j)^{2\rho}.
                  \end{align}

          \end{enumerate}

    \item \emph{(SLND in space)}\index{strong local nondeterminism (SLND)!spatial} If $\beta \in (0, 2]$, $\gamma \ge 0$, then
          for any $M>0$, there exists a constant $C>0$ such that for all $t \in [S,
              T]$, for all $n \ge 1$, and for all $x, x_1, \dots, x_n \in B(0, M)$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t, x_1), \dots, u(t, x_n) \big) \ge C \min_{1 \le j \le n} |x-x_j|^{2\tilde\rho}.
          \end{align}

  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.243897+00:00","domain":"probability theory","id":"claim_64938c62be3637b2074489182ef03122e56ac333126f6ae2e5c22c859acee0e8","kind":"concept","schema_version":1,"statement":"[Lemma firstlemma of arXiv:2607.01463, 'Two Multi--Draw Coupon Collector models with different retention rules'] Let $\phi(s)$ be analytic in a domain that contains the half--line $[n_{0},\infty)$. Then, the differences of the sequence $\left\{\phi(k)\right\}$ admit the integral representation
\begin{equation}
