{"assumptions":[],"created_at":"2026-10-26T19:44:17.188282+00:00","domain":"probability theory","id":"claim_651ed3b20d2a9368875805fdb5a05afaa879a64097851641b77ecca987463d0c","kind":"theorem","schema_version":1,"statement":"[Proposition 18 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumption~\ref{assump-PDE} and the same assumptions as in Proposition \ref{propu} hold. In particular, recall that $p> d$, $\gamma\in (\frac{d}{p}, 1)$ and that if $d=3$, $\frac{\gamma}{2} + \frac{3}{2}(\frac{1}{2}-\frac{1}{p}) <1$. Let $q \geq 1$ and $\varepsilon\geq 0$, with $\varepsilon=0$ allowed if $\lim \sigma_{N}=\sigma>0$. Then there exists $C=C(A,k,\gamma,p,d)>0$ and $\mathfrak{C}_{\varepsilon} >0$ such that for any $t\leq T$ and any $N\in \N^*$, we have
\begin{align}
& \bigg(\E \sup_{s\in[0,t]} \big\|\langle v \rangle^{k} (F_{s}^{N} - \tilde{F}_{s}^{N}) \big\|_{L^{2}_{x,v} }^{2q}
+ \sigma_N^{2q}\, \E \bigg[ \Big(\int_{0}^t \big\lVert \langle v \rangle^k \nabla_{v} (F_{s}^{N} - \tilde{F}_{s}^{N})\big\rVert_{L^{2}_{x,v}}^{2} \dd s\Big)^q\bigg] \bigg)^{\frac{1}{q}} \nonumber\\
 & \leq C  \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\tilde{F}_{0}^N) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}}
  + C \Big( N^{-2(\alpha-\beta)} + \mathfrak{C}_{\varepsilon} N^{-2\beta(\gamma-\frac{d}{p})+\varepsilon} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)} \Big)\nonumber\\
 &\quad + C (1+\sigma_{N}^{-2}) \int_{0}^t \big(\E \sup_{r\in[0,s]} \big\| \langle v \rangle^{k} (F_{r}^{N} - \tilde{F}_{r}^{N}) \big\|_{L^{2}_{x,v} }^{2q}\big)^{\frac{1}{q}} \dd s \\
&\quad + C (1+\sigma_{N}^{-2}) \int_{0}^{t}  \big(\E \big\|u^{N}_s -u^{(N)}_s \big\|_{L^\infty_{x}}^{2q}\big)^{\frac{1}{q}} \dd s.\nonumber
\end{align}
Here and in the rest of the paper, if $\sigma>0$, then one can choose $\varepsilon=0$ and $\mathfrak{C}_{0}<\infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.193398+00:00","domain":"probability theory","id":"claim_652307b06a4dc65d81fca8f1d72ad379805a12d5ab675596b93512ca212ca53e","kind":"theorem","schema_version":1,"statement":"[Corollary 20 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Assume $\mathbbm{E}\!\left[(X_1^{[u]})^2\right]<\infty$ for all $u=1,\ldots,d$ and let
$k_{1:d}\stackrel{\lambda}{\to}\infty$ in the sense of \eqref{eq:lambda-scaling}.
Set $\mu_u:=\mathbbm{E}[X_1^{[u]}]$ and

\begin{equation*}
\mu_\lambda:=\min_{1\le u\le d}\left\{\frac{\lambda^u}{\mu_u}\right\}.
\end{equation*}

\noindent
\emph{Interpretation.}
Since $N(k)=\min_{u}N^{[u]}(k_u)$ and $N^{[u]}(k_u)\approx k_u/\mu_u$ for large $k_u$,
the smallest linear trend $\min_u k_u/\mu_u$ governs the asymptotic growth of $N(k)$.
If the minimizer is unique, the corresponding coordinate becomes the unique active constraint
and eventually $N(k)=N^{[u_\lambda]}(k_{u_\lambda})$ along the direction $\lambda$.

Now, assume that this minimum is attained at a unique index $u_\lambda\in\{1,\ldots,d\}$, i.e.

\begin{equation}
\frac{\lambda^{u_\lambda}}{\mu_{u_\lambda}}
<
\frac{\lambda^{v}}{\mu_{v}},
\qquad v\neq u_\lambda.
\end{equation}

Let $\sigma_{u_\lambda}^2:=\mathrm{Var}(X_1^{[u_\lambda]})$. Then

\begin{equation}
\frac{N(k_{1:d})-\frac{k_{u_\lambda}}{\mu_{u_\lambda}}}{\sqrt{|k|_1}}
\xrightarrow[k_{1:d}\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}\!\left(0,\ \lambda^{u_\lambda}\,\frac{\sigma_{u_\lambda}^2}{\mu_{u_\lambda}^3}\right).
\end{equation}

If in addition the deterministic scaling satisfies
$k_{u_\lambda}=\lambda^{u_\lambda}|k|_1+o(\sqrt{|k|_1})$, then \eqref{eq:clt-N-unique-centered-ku}
is equivalent to

\begin{equation}
\sqrt{|k|_1}\left(\frac{N(k_{1:d})}{|k|_1}-\mu_\lambda\right)
\xrightarrow[k_{1:d}\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}\!\left(0,\ \lambda^{u_\lambda}\,\frac{\sigma_{u_\lambda}^2}{\mu_{u_\lambda}^3}\right).
\end{equation}","status":"unverified"}

