	\begin{equation}
		\mathcal L(B_t\mid \mathcal{H}_{t})=
		\frac{x\prod_{j=1}^{n}\left[e^{(t_j-t_{j-1})(T-D_\alpha)}D_\alpha\right] e^{(t-t_{n})(T-D_\alpha)}}{x\prod_{j=1}^n\left[e^{(t_j-t_{j-1})(T-D_\alpha)}D_\alpha\right] e^{(t-t_{n})(T-D_\alpha)}\boldsymbol1}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

