\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:33:21.472186+00:00","domain":"probability theory","id":"claim_659fd38f90b30c05125d1d7ca5a0fcb13a4859986f2e9758d508041d59565efe","kind":"theorem","schema_version":1,"statement":"[Corollary cor:lp of arXiv:2606.19763, 'Optimal Sparsification of Gaussian Processes'] Let $p\geq2$, let $0<\alpha<1$, and let $T\sse\R^n$ be bounded.  
	Then there exists a subset $S\sse T$ and non-negative shifts $\{c_s\}_{s\in S}$ such
	that
	\[
		|S|
		\leq
		\exp\pbra{
			O\pbra{
				\frac{p}{\alpha^2}
			}
		}
		\qquad\text{and}\qquad 
		\left\|
			\sup_{t\in T}\bg\cdot t-\max_{s\in S}\{\bg\cdot s+c_s\}
		\right\|_{L^p(\gamma_n)}
		\leq
		\alpha\cdot w(T)\,.
	\]
	Additionally, there exists an integer $m\geq n$ and a set $U \sse \R^m$ such that  
	\[
		|U|
		\leq
		\exp\pbra{
			O\pbra{
				\frac{p}{\alpha^2}
			}
		}
		\qquad\text{and}\qquad 
		\left\|
			\sup_{t\in T}\bg\cdot(t,0_{m-n})-\sup_{u\in U}\bg\cdot u 
		\right\|_{L^p(\gamma_m)}
		\leq
		\alpha\cdot w(T)\,.
	\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.357994+00:00","domain":"probability theory","id":"claim_65a4b8d5400d47b46b7ee398dae56c367037b617fd911e311c900394becebe4f","kind":"definition","schema_version":1,"statement":"[Definition 3 (Cannings tree) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Given a population profile $q = (q(s))_{s \in \mathbb{N}_+}$ and offspring vectors $\nu^s = (\nu_1^s, \ldots, \nu_{q(s)}^s)$, we define the associated Cannings tree $\mathscr{T}$ as a subset of $\mathcal{U}$ constructed recursively as follows:
\begin{itemize}
    \item $\emptyset\in \mathscr{T}$;
    \item Suppose all elements \( u \in \mathscr{T} \) with \( |u| = s \) have been defined. Label them in lexicographic order as \( u^1 \prec u^2 \prec \cdots  \prec u^{q(s)} \). Then the elements \( u \in \mathscr{T} \) with \( |u| = s + 1 \) are defined as
    \[
    \left\{ u^i j : 1 \le i \le q(s),\, 1 \le j \le \nu^s_i \right\},
    \]
    where we set \( q(0) := 1 \) and \( \nu^0_1 := q(1) \).
\end{itemize}
The resulting set $\mathscr{T}$ is a prefix-stable subset of $\mathcal{U}$ representing a random rooted ordered tree.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:30:50.735746+00:00","domain":"probability theory","id":"claim_65a89720649dcc2e39475dd833c2af1e74337df11d8510a2d2a0d104a42f32d7","kind":"concept","schema_version":1,"statement":"[Proposition prop_LSI_fluct_measure_nonquad of arXiv:2503.24372, 'A criterion on the free energy for log-Sobolev inequalities in mean-field particle systems'] Let $\psi=(\varphi,\zeta)\in\bbH=\R^d\times\bbH_0$ (recall~(equation eq_def_Hilbert_space of the paper)). 
There are $c,N_0>0$ independent of $N,\psi,T$ such that
the fluctuation measure $\mu^{N,\psi}_T$ satisfies a log-Sobolev inequality with the following constant. 

\begin{itemize}
	\item[(i)] (Theorem 1 in~[wang2024LSI]). For any $N\geq N_0 e^{c\|\zeta\|_{\bbH_0}/T}$, 

\begin{equation}
\big(\gamma^{N,\psi}_{T}\big)^{-1}
\leq 
c\exp\big ( c\|\zeta\|_{\bbH_0}/T\big)
.
\end{equation}

\item[(ii)] For any $N\geq 1$ (recall that $M^2\geq \|W^+\|_\infty, \|W^- -\alpha(x,y)\|_\infty$ by (equation eq: borne sup n of the paper)),

\begin{equation}
\big(\gamma^{N,\psi}_{T}\big)^{-1}
\leq 
c\exp\Big( \frac{2M}{T}(  MN+2\|\zeta\|_{\bbH_0})\Big)
.
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.514019+00:00","domain":"probability theory","id":"claim_65b433ebaaa6d43682a4c13e2a58f99f8fc2454b31619185b79fad775e3b7ef4","kind":"concept","schema_version":1,"statement":"[Thm null vector equations in mathbb H infty 0 constant of arXiv:2505.16093, 'Multiple chordal SLE($\kappa$) and quantum Calogero-Moser system'] For a local multiple chordal SLE(\(\kappa\)) system, there exists a positive function \( \psi(\boldsymbol{x}) \) such that the drift term \( b_j \) in the marginal laws satisfies:
\begin{equation}
    b_j = \kappa \frac{\partial_j \psi}{\psi}, \quad j = 1,2,\dots,n.
\end{equation}  

As a consequence of the commutation relations, \( \psi \) satisfies the null vector equation  
\begin{equation} 
\frac{\kappa}{2} \, \partial_{ii} \psi + \sum_{j \neq i} \frac{2}{x_j - x_i} \, \partial_i \psi 
+ \left(1 - \frac{6}{\kappa} \right) \sum_{j \neq i} \frac{\psi}{(x_j - x_i)^2} = 0,
\end{equation}

Moreover, by conformal (rotational) invariance, for any conformal map \( \tau \in {\rm Aut}(\mathbb{H},\infty) \) of the form \( \tau(z) = az + b \), the drift term \( b_i(\boldsymbol{x},u) \) transforms as a pre-Schwarzian form:  
\begin{equation}
    b_i = \tau^{\prime} \widetilde{b}_i \circ \tau + \frac{6-\kappa}{2} \left(\log \tau^{\prime}\right)^{\prime} = a \cdot \widetilde{b}_i \circ \tau.
\end{equation}  

In particular, there exists a dilation constant \( d \) such that  
\begin{equation} 
\psi(x_1, x_2, \dots, x_n, \infty) 
= a^{\frac{n(\kappa-6)}{2\kappa} - d} \psi(ax_1+b, ax_2+b, \dots, ax_n+b, \infty).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:14:46.370674+00:00","domain":"probability theory","id":"claim_65b46b1e8e4adede75d9425681599903d1f3c90356717afbf40c63c4ff2d71eb","kind":"theorem","schema_version":1,"statement":"[Theorem of arXiv:2608.10415, 'Continuous random variables'] The following happen, in the context of the biased coin game:
\begin{enumerate}
\item The Bernoulli laws $b_p$ produce the binomial laws $b_{np}$, by iterating the coin game $n\in\mathbb N$ times, via the independence of the throws.

\item We have in fact $b_{np}=b_p^{*n}$, with $*$ being the convolution operation for the real probability measures, given by $\delta_x*\delta_y=\delta_{x+y}$, and linearity.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.483059+00:00","domain":"probability theory","id":"claim_65b4855af9f2c577d76b4bd9f80c01163980a38cc22b0b9b504c71d0c725b9a4","kind":"theorem","schema_version":1,"statement":"[Prop 38 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $w\in\C$, $x>0$ and $y\in\R$ such that $\vert y\vert <x$,
the following holds:
\begin{equation}

\sum_{k=0}^{+\infty}
\dfrac{1}{2^{k} k! (k+1/2)}
\Big(\sum_{j=0}^{k}\dfrac{(2k+1)!}{2^{j} j! (2(k-j)+1)!}
\,\vert y\vert^{j}\,\vert w\vert^{2(k-j)+1}
\Big)
\dfrac{1}{x^{k + 1/2}}
<+\infty,
\end{equation}
and
\begin{multline}

\sum_{k=0}^{+\infty} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{w^{2k+1}}{(x-y)^{k + 1/2}}
\\
=
\sum_{k=0}^{+\infty} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\Big(\sum_{j=0}^{k}(-1)^{j} \dfrac{(2k+1)!}{2^{j} j! (2(k-j)+1)!}
\,y^{j}\,w^{2(k-j)+1}
\Big)
\dfrac{1}{x^{k + 1/2}}
\\=
\sum_{k=0}^{+\infty} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
Q_{2k+1}(w,y)
\dfrac{1}{x^{k+1/2}}.
\end{multline}","status":"unverified"}

