          \kappa_\lambda(s)\xrightarrow{\lambda\to\infty} 1.
        \end{equation} 
    \end{enumerate}    
    Then, there exists $\lambda_c  <\infty$ such that, for every $\lambda>\lambda_c$, the OPRE almost-surely percolates for almost-all realisations of the environment $(\xi_x)_{x\in\mathbb{Z}_{\geq0}},(\nu_{x,x+1})_{x\in\mathbb{Z}_{\geq0}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:10.966010+00:00","domain":"probability theory","id":"claim_669dc113efa1bfda355aeb60f2290add6a639c46c50ac11dc847092b5e592c57","kind":"definition","schema_version":1,"statement":"[Definition 23 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Sub-Gaussian Vector}


