{"assumptions":[],"created_at":"2026-10-27T12:48:49.853247+00:00","domain":"probability theory","id":"claim_672c223d88e32daa7b5048104c458ab3791340424f8c29dc46b9cd698013dbcb","kind":"concept","schema_version":1,"statement":"[Lemma lem:order_of_RNx of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $0\leq \nu<\xi\leq 1$ and $M\in \mathbb{Z}_{+}$. Then, for all $N$ large enough (depending on $M,\nu,\xi$), 
for all integers $0\leq l<l'\leq \lceil \xi M \rceil$, $|l-l'|>1$, every $x\in A_l$ and $y\in A_{l'}$,
\begin{equation}
        R_{N^{\nu},N^{\xi}}(x-y)\leq \begin{cases}
            (\xi-\frac{l'}{M}+ \frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \nu<\frac{l'}{M}<\xi,\\
            (\xi-\nu + \frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \frac{l'}{M}<\nu,
        \end{cases}
    \end{equation}
    and
    \begin{equation}
        R_{N^{\nu},N^{\xi}}(x-y)\geq  \begin{cases}
            (\xi-\frac{l'}{M}-\frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \nu<\frac{l'}{M}<\xi,\\
            (\xi-\nu-\frac{3}{M})\frac{\log N}{\pi} \quad \text{if } \frac{l'}{M}<\nu.
        \end{cases}
    \end{equation}
Furthermore, for all $x,y\in\mathbb{Z}_{\text{even}}^2$ such that $|x|\leq N^{\frac{l}{2M}}$ and $|y|\geq N^{\frac{l+1}{2M}}$,
\begin{equation}
    R_{N^\xi}(x-y)\leq 2 R_{N^\xi}(y)\leq 4 R_{N^\xi}(x),
\end{equation}
Finally, for some universal constant $c>0$, 
\begin{equation} 
    \sup_{|y| \leq N^{\xi/2}}\sum_{|x|\geq N^{(\xi+1/M)/2}} R_N(x-y) \leq e^{-cN^{1/M}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.222409+00:00","domain":"probability theory","id":"claim_6732f4b52ddf6ebe5c164ed197c8149c6ce98a80c7046ee57baaec137ab9e360","kind":"lemma","schema_version":1,"statement":"[Lemma lem:lacuna-small of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] There exists a constant $C(d) > 0$ such that for all $t \geq \hat{t}$ and $\lambda > 0$,
  \begin{equation}

    u(\hat{t}, b_{\hat{t}}, \h\theta; t, \lambda) \leq C(d) \lambda A^2 (\log \hat{t})^{d/2} \, \hat{t}^{-A^2}.
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.595920+00:00","domain":"probability theory","id":"claim_67370ebbcf827fdd9449f83ba81d58886b8d9139258aa314708c5a82d01565d0","kind":"definition","schema_version":1,"statement":"[Definition def:scaleFunction of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] For constants $0 < \alpha_1 \le \alpha_2$, 
  we say a continuous function $\psi : [0,\infty) \to [0,\infty)$ satisfies $LU(\alpha_1,\alpha_2)$
  if $\psi$ is strictly increasing, $\psi(0) = 0$, $\psi(1) = 1$  and 
  there exists constants $C \ge 1$ such that
  \begin{align}
    C^{-1} \left(\frac{R}{r}\right)^{\alpha_1} \le \frac{\psi(R)}{\psi(r)} \le C \left(\frac{R}{r}\right)^{\alpha_2}, \qquad 0 < r \le R.
  \end{align}
  We call such function $\psi$ a scale function.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.707985+00:00","domain":"probability theory","id":"claim_673a6d43b9c9c6c9917a0727ffc81db17d0eba93fb16d5c105355552cec83062","kind":"theorem","schema_version":1,"statement":"[Prop Kac-Rice Formula of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] For the random polynomials $P_n$, we have almost surely 
    \begin{equation}
        \mathscr{C}(\Lambda_n) \hspace{1mm}(\textrm{resp.} \hspace{1mm} \tildea{\mathscr{C}}(\Lambda_n) ) = 1 + \lim_{\varepsilon \to 0} \frac{1}{\pi \varepsilon^2} \int_{\mathbb{D} \hspace{1mm}(\textrm{resp.} \hspace{1mm} \mathbb{A}_n )} |P_n''(z)|^2 \mathbbm{1}_{\{|P_n'(z)|<\varepsilon, |P_n(z)| >1\}} A(dz). 
    \end{equation} 
   Moreover, 
   \begin{equation}
       \mathbb{E}[\tildea{\mathscr{C}}(\Lambda_n)] = 1 + \lim_{\varepsilon \to 0} \frac{1}{\pi \varepsilon^2} \int_{\mathbb{A}_n} \mathbb{E}\bigl[|P_n''(z)|^2 \mathbbm{1}_{\{|P_n'(z)|<\varepsilon, |P_n(z)| >1\}}\bigr] A(dz).
   \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:56:37.644728+00:00","domain":"probability theory","id":"claim_673f2693a7f90340c8e0df19be99b2d0ddbe3a9592ccf308128bb5f2ac0445c3","kind":"theorem","schema_version":1,"statement":"[Prop monotonicity in plus of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] {PV26}}]
Let $\beta,h \geq 0$. There exists $r=r(\beta,h)\geq 0$ such that, for every $\Lambda'\subset \Lambda \subset \mathbb Z^d$ finite and such that $\mathrm{d}(\partial \Lambda,\Lambda')\geq r$, and every $\mathsf h \in (\mathbb R^+)^{\Lambda}$ and $\mathsf h' \in (\mathbb R^+)^{\Lambda'}$ such that $\mathsf h' \geq \mathsf h_{|_{\Lambda'}}$ and $\mathsf h,\mathsf h'\leq h$,
\begin{equation}
\nu_{\Lambda,\beta, \mathsf h}^+ \preccurlyeq \nu_{\Lambda',\beta, \mathsf h'}^+ \quad \text{and} \quad \nu_{\Lambda,\beta, \mathsf h}^+(|\cdot|) \preccurlyeq \nu_{\Lambda',\beta, \mathsf h'}^+(|\cdot|).
\end{equation}
In particular, for every $\Lambda \subset \mathbb Z^d$ finite and every $\mathsf h \in (\mathbb R^+)^{\mathbb Z^d}$ with $\mathsf h \leq h$,
\begin{equation}
\nu_{\beta,\mathsf h}^+ \preccurlyeq \nu_{\Lambda,\beta, \mathsf h}^+ \quad \text{and} \quad \nu_{\beta, \mathsf h}^+(|\cdot|) \preccurlyeq \nu_{\Lambda,\beta, \mathsf h}^+(|\cdot|).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.545708+00:00","domain":"probability theory","id":"claim_6742cfc68fb385ebc535df27480524fda83c576bfc2e82145f5d5c687f2301d8","kind":"definition","schema_version":1,"statement":"[Definition def:F of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] Suppose $x_1<x_2<x_3$ and $y_1,y_2\in\mathbbm{R}\cup\{\infty\}$. Define $F^{(1)}, F^{(2)}$ as follows.
\begin{itemize}
    \item Let $F^{(1)}(y_1,y_2,x_1,x_2,x_3):=G_{\mathbbm{H},y_1,y_2}(x_1,x_2,x_3)$.
    \item Denote $\rho_{\mathbbm{H},y_1,y_2,x_1}^\#(d\eta)$ to be the law of chordal $\SLE_\kappa(\kappa-8)$ on $\mathbbm{H}$ from $y_1$ to $y_2$ with force point at $x_1$, which can be viewed as a chordal $\SLE_\kappa$ from $y_1$ to $y_2$ and conditioned to hit $x_1$. Let
    \begin{equation}
    F^{(2)}(y_1,y_2,x_1,x_2,x_3):=G_{\mathbbm{H},y_1,y_2}(x_1)\int H_{\mathcal{U}(\eta)}(x_2,x_3)^{h}\rho_{\mathbbm{H},y_1,y_2,x_1}^\#(d\eta).
    \end{equation}
    Here $\mathcal{U}(\eta)$ is the unbouned connected component of $\mathbbm{H}\setminus\eta$, and $H_{\mathcal{U}(\eta)}$ stands for the boundary Poisson kernel on $\mathcal{U}(\eta)$. When $x_2$ or $x_3$ is not in $\ol {\mathcal{U}(\eta)}$, we set $H_{\mathcal{U}(\eta)}(x_2,x_3):=0$.
\end{itemize}","status":"unverified"}

