{"assumptions":[],"created_at":"2026-10-26T19:46:12.279614+00:00","domain":"probability theory","id":"claim_684643e89b34907ed77999863b9435e3fbfc790b11fbc63bb011076291393d49","kind":"definition","schema_version":1,"statement":"[Definition 22 (Freidlin-Wentzell uniform LDP) of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Let $\mathcal{K}$ be the family of all compactness subset of $H$. We say sequence $\{X^{\epsilon}_{\cdot;t_0,\xi}\}_{\epsilon>0}\subset \mathcal{E}$ indexed by $\xi \in H$ satisfies the uniform large deviation principle with rate function $\cI_{\xi}$, uniformly in $\mathcal{K}$ if the following two conditions hold:
    \begin{itemize}
        \item [1.] Upper bound. For any $K \in \mathcal{K}$, $\delta>0$ and $s_0>0$,
            \begin{equation*}
                \limsup_{\epsilon \rightarrow 0} \sup_{\xi \in K} \sup_{s \leq s_0} \Big\{ \epsilon \log \P \big( \inf_{\Phi \in \{\Phi \in \mathcal{E}; \, \cI_{\xi}(\Phi) \leq s\} } d_{\mathcal{E}}(X^{\epsilon}_{\cdot;t_0,\xi},\phi) \geq \delta \big) + s \Big\} \leq 0.
            \end{equation*}
        \item [2.] Lower bound. For any $K \in \mathcal{K}$, $\delta>0$ and $s_0>0$,
            \begin{equation*}
                \liminf_{\epsilon \rightarrow 0} \inf_{\xi \in K} \inf_{\{\Phi \in \mathcal{E}; \, \cI_{\xi}(\Phi) \leq s_0\}} \Big\{ \epsilon\,\log \P \big( d_{\mathcal{E}}(X^{\epsilon}_{\cdot;t_0,\xi},\Phi) <\delta \big) + \cI_{\xi}(\Phi) \Big\} \geq 0.
            \end{equation*}
    \end{itemize}","status":"unverified"}

