    and
    \begin{align}
        \Vert f\Vert_{W^{s,p}}\lesssim\Vert f\Vert_{B_{p,q}^{s+\delta}}\quad \forall f\in\mathcal{S}'(\mathbb{T}^d).
    \end{align}
    For all $\alpha\in\N_0^d$ and for all $s,t\in\R$, $p_1,p_2,q_1,q_2\in [1,\infty]$, with
