{"assumptions":[],"created_at":"2026-10-27T23:32:34.786576+00:00","domain":"probability theory","id":"claim_68eaef9dc73bd201ae94406d4e0dcae41af0c7b5a756663a582db8363b5adc21","kind":"concept","schema_version":1,"statement":"[Proposition prop:deformKLprop of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi \in \mathcal{P}(\mathcal{X})$ and $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ be an isometric involution transition matrix. For $P,L \in \mathcal{L}$, we have the following:
	\begin{enumerate}
		\item(Non-negativity) 
		\begin{align*}
			{}^Q D_{KL}(P \| L) \geq 0.
		\end{align*}
		Equality holds if and only if $QP = QL$ if and only if $P = L$. Similarly, 
		\begin{align*}
			D_{KL}^Q(P \| L) \geq 0.
		\end{align*}
		Equality holds if and only if $PQ = LQ$ if and only if $P = L$.

		\item(Duality) Let $P,L \in \mathcal{S}(\pi)$.
		\begin{align*}
			{}^Q D_{KL}(P \| L) = D_{KL}^Q(P^* \| L^*).
		\end{align*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.859066+00:00","domain":"probability theory","id":"claim_68ee74a0afe11f3d3fc2d55fb32bb2bd5a4ed85b4665d63acaa91d8a1cb9bcf7","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2609.02019, '2609.02019'] Let $\sigma\in\mathscr S(\mathbb R;\mathbb R)$, and define
		\[
		\mathsf K_\sigma(z,y)
		\triangleq
		\frac{\sigma(z)-\sigma(y)}{(z-y)^2}
		-
		\frac{\sigma'(z)}{z-y}
		=
		\frac{
			\sigma(z)-\sigma(y)-\sigma'(z)(z-y)
		}{
			(z-y)^2
		},
		\qquad z\neq y.
		\]
		Then $\mathsf K_\sigma$ extends uniquely to a function in
		$C^\infty(\mathbb R^2)$, still denoted by $\mathsf K_\sigma$, and
		\[
		\mathsf K_\sigma(z,z)
		=
		-\frac12\sigma''(z),
		\qquad z\in\mathbb R.
		\]
		Moreover, the following estimates hold:
		\begin{equation}
			\sup_{z\in\mathbb R}
			\left\|
			\mathsf K_\sigma(z,\cdot)
			\right\|_{L_y^2}
			\le
			\frac43
			\left\|\sigma''\right\|_{L^2},
		\end{equation}
		\begin{equation}
			\sup_{z\in\mathbb R}
			\left\|
			\partial_z^a\partial_y^b
			\mathsf K_\sigma(z,\cdot)
			\right\|_{L_y^1}
			\le
			\left(
			\int_0^1
			(1-\vartheta)^{a+1}
			\vartheta^{b-1}
			\d \vartheta
			\right)
			\left\|
			\sigma^{(a+b+2)}
			\right\|_{L^1},\quad a\in\mathbb N_0,\ b\in\mathbb{N},
		\end{equation}
		and
		\begin{align}
			\sup_{z\in\mathbb R}
			\left\|
			\partial_y
			\left[
			\sigma(\cdot)
			\partial_y\mathsf K_\sigma(z,\cdot)
			\right]
			\right\|_{L_y^1} \le
			\frac12
			\|\sigma'\|_{L^\infty}
			\|\sigma^{(3)}\|_{L^1}
			+
			\frac16
			\|\sigma\|_{L^\infty}
			\|\sigma^{(4)}\|_{L^1}.

		\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:47:07.704893+00:00","domain":"probability theory","id":"claim_68ef4cc2c7883cfc16b9ad09b0961aaea730703468a09c5c6bb8fd7b1390e394","kind":"concept","schema_version":1,"statement":"[Corollary 16 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] For $B\in\cX_0$ we have
