\mathbb{E} \left[ \left. \frac{\partial \mathcal{H}}{\partial u} \left(t,\hat{X}(t), \hat{u}(t), \hat{p}(t), \hat{q}(\cdot,t) \right) \, \right| \, \mathcal{G}_t \right]= 0 \quad \text{p.s.}		
\end{eqnarray*}
