{"assumptions":[],"created_at":"2026-10-27T06:57:30.959174+00:00","domain":"probability theory","id":"claim_69c53e62e1cf409f6904c64654c5479d5b7088ed8e2cf93cf00d1e267cda8f5d","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] Suppose   the process $\mathbf{X}=\{X_n:n\geq0\}$  is defined by \eqref{111} and satisfies {\bf (A)}. Then as $n\to \infty$, 
\begin{align*}
\frac{S_n-\beta K_n/(1-m)}{a_n}\stackrel{d}{\rightarrow} \pi_0^{-1/\kappa}\zeta_\kappa,
\end{align*}
  where  $\{a_n\}$ is an integer-valued sequence satisfying $na_n^{-\kappa}l_1(a_n)\to (1-m)^{\kappa}$,   and $\zeta_\kappa$ is a $\kappa$-stable random variable with characteristic function $$\psi(t)=\exp\left(- |t|^\kappa\Gamma(1-\kappa)\cos\frac{\pi\kappa}{2} (1+\mathrm{i}\mathrm{sgn}(t)\tan\frac{\pi\kappa}{2}) \right),\quad t\in\mathbb{R}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.531688+00:00","domain":"probability theory","id":"claim_69d28209ca6054c093c10b7962e469cec449ba3c959c7e8db15eae2ef9f63ff5","kind":"theorem","schema_version":1,"statement":"[Prop good_cube_property of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $d \geqslant 2$, $\mathfrak{p} \in (\mathfrak{p}_c, 1]$, $\mathsf{r} \in (\frac{4}{3}, 2)$, and $N \in \mathbb{N}$, there exist constants $C_{Me},\varepsilon_{Me}$ and $\{C_{Sc,k}, K_k, s_k\}_{k\geqslant 0}$ depending on $\mathfrak{p}, d, \mathsf{r}, N$ and a sequence of good cubes $(\mathcal{G}^{(N)}_k)_{k \geqslant 0}$ 
		\begin{align}
			\mathcal{T} \supseteq \mathcal{G} \supseteq \mathcal{G}^{(N)}_0 \supseteq \mathcal{G}^{(N)}_1 \supseteq \mathcal{G}^{(N)}_2 \supseteq \mathcal{G}^{(N)}_3 \cdots
		\end{align}
		For every cube ${\scaleobj{1}{\square}} \in \mathcal{G}^{(N)}_k$, it is $N$-$\mathsf{stable}$ for the statement that
		\begin{enumerate}[label=(\roman*)]
			\item \emph{Meyers' estimate}: ${\scaleobj{1}{\square}} \in \mathcal{M}(\mathbf{a}^\#, \mathsf{r}, \varepsilon_{Me}, C_{Me})$;
			\item \emph{Connectivity}: ${\scaleobj{1}{\square}}, \frac{4}{3}{\scaleobj{1}{\square}}, \mathsf{r} {\scaleobj{1}{\square}}$ are very-well connected under $\mathbf{a}^\#$;
		\end{enumerate}
		and it also satisfies the following properties
		\begin{enumerate}	
			\item \emph{Partition cube size}: when $k \geqslant 1$, then ${\scaleobj{1}{\square}} \in \Lambda\left(\mathcal{G}^{(N)}_{k-1}, d + k, C_{Sc,k}\right)$.



			\item \emph{Locality and tail-estimate}: ${\scaleobj{1}{\square}}$ verifies the locality (equation e:local_dependence of the paper) and the tail probability estimate (equation e:rarely_bad of the paper) with constants $K_k, s_k$.
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:03:59.165054+00:00","domain":"probability theory","id":"claim_69d4d927db1f1fbfeda863246067858e0272966fd408d9163df620d767c23439","kind":"theorem","schema_version":1,"statement":"[Proposition prop: 1wr fixed n of arXiv:2507.04505, 'Heights of butterfly trees'] Let $\pi \sim \operatorname{Unif}(S_n \wr S_m)$ or $\pi \sim \operatorname{Unif}(S_m \otimes S_n)$, and $h_{n,m} = h(\mathcal T(\pi))$. Then for any $\varepsilon>0$,
