\item[(b)] $0< f_1(x)<f_2(x)$, $\forall x\in\RR$;
\item[(c)] $h_1(x)\leq h_2(x)$, $\forall x\in\RR$.
\end{itemize}
Then, for all $t> 0$, we have $x^1_t<x^2_t$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:37:28.988179+00:00","domain":"probability theory","id":"claim_69e5cf3dd9af6a22e6d235e5a8fd5a4649e6277d4cb750eec461a3d8973d214f","kind":"theorem","schema_version":1,"statement":"[Theorem thm:G-moments of arXiv:2412.01015, 'Classical beta ensembles and related eigenvalues processes at high temperature and the Mar'] Assume that each moment of the initial empirical measure $\mu_0^{(N)}$ converges to a limiting moment, that is, for each $n$,
\begin{equation}
	S_n^{(N)}(0) = \frac{1}{N} \sum_{i=1}^N x_i(0)^n \to a_n \quad \text{as} \quad N \to \infty.
\end{equation}
Then it holds that 
\[
	S_n^{(N)}(t) \to m_n(t) \quad \text{as} \quad N \to \infty,
\]
in probability as random elements in $C([0, T])$. Here the limiting moment processes are recursively defined by $m_0(t) = 1, m_1(t) = a_1,$
\begin{align}
	m_n(t) &= a_n + \sigma^2 \frac{cn}2 \sum_{j=0}^{n-2}\int_0^t m_j(u) m_{n-2-j}(u) du\notag\\
	&\quad +\sigma^2 \frac12 n(n-1) \int_0^t m_{n-2}(u) du, \quad (n \ge 2).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:21:56.725972+00:00","domain":"probability theory","id":"claim_69e77cc1fe979b79727fb8001b6824be6ad464dade4655ead064f8dd7b707497","kind":"theorem","schema_version":1,"statement":"[Proposition pr:tightness_bubble_bdry of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] There exists $\zeta > 0$ such that the following is true. Assume~(equation eq:epsexp2 of the paper). For $\delta>0$, let $E_\delta$ be the event that there exist $x,y\in \eta[0,\infty] \cap \eta^R$ such that if $U_{x,y}$ denotes the region bounded between the segments of $\eta[0,\infty]$ and $\eta^R$ from $x$ to $y$, then
\begin{itemize}
\item $U_{x,y} \subseteq B(0,1)$,
\item $\mathrm{diam}(U_{x,y}) \le \delta$,
\item $\mathrm{dist}(U_{x,y},\eta[-\infty,0]) \ge \delta^\zeta$, and
\item $\sup_{u,v \in \partial U_{x,y} \cap \eta} \median{\epsilon}^{-1} \metapproxacres{\epsilon}{U_{x,y}}{u}{v}{\Gamma} \ge L\delta^\zeta+\epsilon^{a_0}$.
\end{itemize}
Then $\mathbf{P}[E_\delta] = o^\infty(L^{-1}\delta)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.077030+00:00","domain":"probability theory","id":"claim_69e80c2dcb301c11832fdefbc67ed1d61677d1ee3f091bf2081f85ce521b8391","kind":"concept","schema_version":1,"statement":"[Theorem thm:1p_HP of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] Let $\delta>0$ and $\beta>0$. 
