{"assumptions":[],"created_at":"2026-10-26T20:54:53.440992+00:00","domain":"probability theory","id":"claim_6c25e82b51a68ec52244319df079e1b409418030d8e8e8bdcf2d3d4d7d0be5b5","kind":"definition","schema_version":1,"statement":"[Definition 21 (Local solution) of arXiv:2606.15425, 'Well-posedness of stochastic parabolic equations with gradient nonlinearities and applicat'] Let ${\bm z}_0$ be an $\mathcal F_0$-measurable random variable with values in $B^{d/q}_{q,2p}(\mathbb T^d)$ for some $p \geq 1$.
A pair $({\bm z},\tau)$ is called a \emph{local mild solution} of
\begin{equation}
\d {\bm z}_t = \left(\Delta {\bm z}_t + F({\bm z}_t) \right)\d t + G({\bm z}_t)\d {\bm W}_t
\end{equation}
with initial datum $\bm z_0$
if, for some $T > 0$ and $\lambda > 0$, $({\bm z}_t)_{t \in [0,T]}$ is an $\mathcal F_t$-adapted, $B^{d/q}_{q,2p}(\mathbb T^d)$-valued process and $\tau \leq T$ is a monotone limit of strictly positive $(\mathcal F_t)_{t\geq 0}$-stopping times $(\tau_n)_{n \in \N}$ such that for all $n$,
\begin{enumerate}[(i)]
    \item $({\bm z}_{t \wedge \tau_n})_{t \in [0,T]}$ is $\mathcal F_{t}$-adapted with weakly continuous paths
    $${\bm z}_{t \wedge \tau_n}\in C_w([0,T];B^{d/q}_{q,2p}(\mathbb T^d)) \cap L^{2}([0,T];H^{1,q}(\mathbb T^d)) \cap L^4([0,T];H^{\delta,q}(\mathbb T^d)).$$
    \item As an $L^{q/2}$-valued process, \begin{equation}
    {\bm z}_{t\wedge\tau_n}
    =
    S(t\wedge\tau_n){\bm z}_0
    +(S\ast F({\bm z}_{\cdot \wedge \tau_n}))(t \wedge \tau_n)
    +(S\diamond G({\bm z}_{\cdot \wedge \tau_n}))(t \wedge \tau_n),
    \end{equation}
    holds for all $t \in [0,T]$, almost surely.
    \item
    For all finite stopping times $\sigma \leq \tau$, the relative lifetime after $\sigma$ defined by
    \begin{equation} 
    \tau^\lambda(\sigma) = \inf\bigg\{ 
    t \in [0,(\tau-\sigma)_+]: \Sigma_\sigma\left(t,{\bm z},S\ast F({\bm z}),S\diamond G({\bm z})\right)> \lambda 
    \bigg\} 
    \end{equation} is almost surely strictly positive on the event $\Set{\sigma < \tau}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.502396+00:00","domain":"probability theory","id":"claim_6c2b059fd89249b0d7d5ccbe442e90948a5fa71615de303026e277702e66c14e","kind":"definition","schema_version":1,"statement":"[Definition def : LDP/ExpEquiv of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $(\mathbb{X}, \mathrm{d}_\mathbb{X})$ be a metric space. All the random variables mentioned in this definition are assumed to be defined on the probability space.
	\begin{enumerate}[(i)]
		\item We say that two processes $(X_n)_{n\ge 1}$ and $(Y_n)_{n\ge 1}$ on $\mathbb{X}$ are \emph{exponentially equivalent} if for all $\varepsilon>0$ and $n\ge 1$, the event $\acc{ \mathrm{d}_\mathbb{X}\mathopen{}\mathclose\bgroup\originalleft( X_n, Y_n  \aftergroup\egroup\originalright) \ge \varepsilon  }$ is measurable, and with fixed $\varepsilon>0$, \begin{equation}
			\lim_{n\to \infty} -\frac1n \log\Pb{ \mathrm{d}_\mathbb{X}\mathopen{}\mathclose\bgroup\originalleft( X_n, Y_n  \aftergroup\egroup\originalright) \ge \varepsilon  } = \infty.
		\end{equation}
		\item We say that a family of processes $\p{ (X_n^{(b)})_{n \ge 1} , b\in\intervallefo0\infty }$ on $\mathbb{X}$ is an \emph{exponentially good approximation} of $\mathopen{}\mathclose\bgroup\originalleft( X_n \aftergroup\egroup\originalright)_{n\ge 1}$ as $b\to \infty$ if for all $\varepsilon>0$, $b\ge 1$ and $n\ge 1$, the event $\acc{ \mathrm{d}_\mathbb{X}\p{X_n^{(b)}, X_n } \ge \varepsilon  }$ is measurable, and with fixed $\varepsilon>0$,
		\begin{equation}
			\lim_{b\to \infty} \liminf_{n\to\infty} -\frac1n \log\Pb{ \mathrm{d}_\mathbb{X}\p{X_n^{(b)}, X_n } \ge \varepsilon  } = \infty.
		\end{equation}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.320693+00:00","domain":"probability theory","id":"claim_6c332b30b3b0fdd0bdf987cef5e6a5b1733bf05740b0548b5f32770a616e618c","kind":"theorem","schema_version":1,"statement":"[Theorem thmmin of arXiv:2411.06245, 'On the longest/shortest negative excursion of a Lévy risk process and related quantities'] Let $r>0$, $x\in \mathbb{R}$ and $\mathbb{E}[X_1]>0$. If $W(0)>0$ (or equivalently $X$ has paths
