\begin{align*}
{\cal W}_p^p(\mu, \nu)& \le   \frac{\diamd^p(2^p+1)}{2(2^{p-d}-1)}    D^{\infty}(\mu,\nu) .


\end{align*}
If furthermore, $1+2^{-p}-2^{p-d}>0$, i.e. $p< d+\frac{\log(1+\sqrt{1+2^{-(d-2)}})}{\log 2}-1$, then
\begin{align*}
{\cal W}_p^p(\mu, \nu)& \le   \frac{\diamd^p}{2^{p-d}-1}\left[\frac{2^p+1}{2}    D^{\infty}(\mu,\nu) -  2^{p(1-\frac{1}{d})}\left(1+2^{-p}-2^{p-d}\right) D^{\infty}(\mu,\nu)^{\frac{p}{d}}\right].


\end{align*}

\item If $p=d$  then
\[
{\cal W}_p^p(\mu, \nu) \le  \diamd^d   \bigg( \bigg(   \frac{(d+1)2^{d-1}}{d}+\frac 1{2d}\bigg) D^{\infty}(\mu,\nu)+\frac{2^d+1}{2d\log 2} D^{\infty}(\mu,\nu)\log\Big(\frac{1}{ D^{\infty}(\mu,\nu)}\Big)\bigg).
\]
\item If $p<d$ then
\[
{\cal W}_p^p(\mu, \nu) \le \diamd^p    {2^{-\frac pd}}   \bigg( \frac{2^p+1}{1-{2^{p-d}}} + 2^{p}\bigg) D^{\infty}(\mu,\nu)^{\frac pd}.
\]
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.314927+00:00","domain":"probability theory","id":"claim_6d49cc1fd312efd108bcf0ce0165203edeea464889335a548b8ddab275912b78","kind":"concept","schema_version":1,"statement":"[Proposition pro:2 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] For each $w>0$, there exist $M_0=M_0(w)<\infty$ and $a_3=a_3(w)>0$ such that for $x\in\partial \mathcal B_0$ and $n'\geq n\geq 1$,
