{"assumptions":[],"created_at":"2026-10-27T23:09:15.295390+00:00","domain":"probability theory","id":"claim_6d66633d717300f90e6e90cad38eb66db206e6c1fefbfa0efd82bb354e50e8df","kind":"theorem","schema_version":1,"statement":"[Prop Feynman-Kac of arXiv:2411.05441, 'Sticky diffusions on star graphs : characterization and It\^o formula'] Let $T > 0$ and $u \in C^{1,2}_b((0,T) \times \Gamma) \cap C_b([0,T] \times \Gamma)$  be a solution to
 \begin{equation}
  \begin{cases}
   -\partial_t u(t,\mathsf{x}) - L u(t,\mathsf{x}) = f(t,\mathsf{x}) \quad & \textnormal{for all } t \in (0,T), \, \mathsf{x} \neq \mathsf{v}, \\
   u_i(t,0) = u_j(t,0) \quad & \textnormal{for all } 1 \leq i, j \leq N, \, t \in (0,T), \\
   -\eta \partial_t u(t,\mathsf{v}) - \sum_{i=1}^N \rho_i \partial_x u_i(t,0) = \eta \theta(t) \quad &  \textnormal{for all } t \in (0,T), \\
   u(T, \cdot) = u_T,
  \end{cases}
 \end{equation}
 with $f \in C([0,T], PC(\Gamma))$, $u_T \in C_b(\Gamma)$ and $\theta \in C([0,T])$. Then
 \[
  u(t,\mathsf{x}) = \mathbf E \left[u_T(X(T)) + \int_t^T f(s,X(s)) \mathbf 1_{\{X(s) \neq \mathsf{v} \}} + \theta(s) \mathbf 1_{\{X(s) = \mathsf{v} \}} ds \big \vert X(t) = \mathsf{x} \right ],
 \]
 where $X$ is the sticky diffusion generated by $L$ with stickiness $\eta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:06:39.354621+00:00","domain":"probability theory","id":"claim_6d6749b984721f5bcc8bd137e6636849261698cff1d83d962f37f577c1a5e7a9","kind":"lemma","schema_version":1,"statement":"[Lemma l:control_mesoscopic of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Suppose that Assumption (ass:forcing_regularity_iteration of the paper) holds. Let $\mu>0$, $r\in (1,\infty)$ and $p_0\in (2,p)$.
Fix $0<\gamma_0< (1-\frac{2}{p}-\frac{d}{q})\wedge (1-\frac{2}{p_0})$.  
Then there exist constants 
$$
L_0\geq 1\qquad \text{ and } \qquad \eta\in (0,1/4],
$$ 
depending only on $\mu,p,q,r,p_0,d$ and $\gamma_0$, for which the following assertion holds whenever $N\geq 1$ and $m\geq 1$ satisfy 
$$
N^{-1}\leq \eta^{m-1} L_0^{-1}.
$$
For all local solutions $(v^N,\pi^N,(\widetilde{\pi}^N_{k,\alpha})_{k,\alpha})$ to the stochastic Stokes system (equation eq:turbulent_Stokes_scaling_original_iteration of the paper) on $Q$, it holds that 
\begin{align*}
\Big({\mathbf E} \Big\|v^N -\fint_{\eta^\ell B} v^N  \Big\|_{\underline{L}^2(\eta^\ell Q)}^{r}\Big)^{1/r}
 \leq \eta^{\ell \gamma_0}
\mathcal{L}_{Q}^\#,\\
\Big({\mathbf E} \Big\|\pi^N -\fint_{\eta^\ell B} \pi^N  \Big\|_{\underline{L}^2(\eta^\ell I;\underline{H}^{-1}(\eta^\ell B))}^{r}\Big)^{1/r}
 \leq \eta^{\ell \gamma_0}
\mathcal{L}_{Q}^\#,\\
\Big({\mathbf E} \Big\|\Big( \widetilde{\pi}_{k,\alpha}^N -\fint_{\eta^\ell B} \widetilde{\pi}_{k,\alpha}^N\Big)_{k,\alpha} \Big\|_{\underline{L}^{p_0}(\eta^{\ell} I;\underline{L}^2(\eta^\ell B; \ell^2))}^{r}\Big)^{1/r}
 \leq  \eta^{\ell \gamma_0}
 \mathcal{L}_{Q}^\#,
\end{align*}
for all $\ell\in \{1,\dots,m\}$,
where $\mathcal{L}_{Q}^\#$ is the sharp Lebesgue-energy of $(v^N,\pi^N,(\widetilde{\pi}^N_{k,\alpha})_{k,\alpha})$ at (large) scale $Q$, i.e.,\begin{align}
\nonumber
\mathcal{L}_Q^{\#}
=&\Big( \max\Big\{{\mathbf E} \|F \|_{\underline{L}^p(I;\underline{L}^q(B))}^r,\,
{\mathbf E} \|G \|_{\underline{L}^p(I;\underline{L}^q(B))}^r , \,
{\mathbf E} \Big\|v^{N} -\fint_{B} v^{N}\Big\|_{\underline{L}^2(Q)}^r
,\\

&{\mathbf E} \Big\|\pi^{N}-\fint_{B} \pi^{N}\Big\|_{\underline{L}^2(I;\underline{H}^{-1}(B))}^r,\, 
{\mathbf E} \Big\|\Big( \widetilde{\pi}_{k,\alpha}^{N}-\fint_{B} \widetilde{\pi}^{N}_{k,\alpha} \Big)_{k,\alpha}\Big\|_{\underline{L}^{p_0}(I; \underline{L}^2(B;\ell^2))}^r \Big\}\Big)^{1/r}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:04:59.429827+00:00","domain":"probability theory","id":"claim_6d6e9bf92b170ab6850a889c25cfcfd87c972b958a61d3485e75af7ca74a1f2b","kind":"theorem","schema_version":1,"statement":"[Theorem weak_convergence_alpha_quantile of arXiv:2605.20471, 'Note on the Weak Convergence of Hyperplane $α$-Quantile Functionals and Their Continuity i'] Let $\alpha \in (0,1),t>0,\gamma \in \mathbb{R}^d$. Let $X^n\Rightarrow X$. Suppose that for all $\varepsilon >0$ we have, alternatively:
