&+ \kappa\left[ 3(\kappa - 4)(\kappa - 8) + \lambda(\lambda - 1)(18\kappa^2 - 212\kappa + 608) \right]U' \\&+ 6(2\lambda - 1)(\kappa - 4)(\kappa - 8)^2 U = 0.
