{"assumptions":[],"created_at":"2026-10-27T16:53:30.575741+00:00","domain":"probability theory","id":"claim_706e495e0486147b5c6335b51daa82ef53452a3a193187ef13ea5afa3790ebbb","kind":"definition","schema_version":1,"statement":"[Definition def-counting measure of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Suppose that $(X, \mathscr{B}_X) $ is a measure space and  $p$ is  a point function on $X $. We put
\begin{equation}
  \eta_p((0,t]\timesU):= \# \bigl\{ s \in \mathrm{Dom}(p)\cap (0,t] : p(s) \inU \bigr\}, \;\; t>0,\;\;U \in \mathscr{B}_X.
\end{equation}
Following [Ikeda+Watanabe_1989] we have the following result. 

\begin{proposition}
Suppose that $(X, \mathscr{B}_X) $ is a non-empty measure space and  $p$ is a point function on $X $.
The function $\eta_p$ defined above in (equation eqn-IW_I.9.1 of the paper) has a unique extension to a $\sigma$-additive measure
\[
\mathscr{B}(0,\infty)\otimes \mathscr{B}_X \to \bar{\mathbb{N}}:=\mathbb{N}\cup \{\infty\},
\]
where $\mathscr{B}(\mathbb{R}_+)$ is the Borel $\sigma$-field on $\mathbb{R}_+$. Moreover, this  unique extension is of the following form
\[
\sum_{(t,x) \in p} \delta_{(t,x)}.
\]
In other words, this extension is the  counting measure on $(0,\infty) \times X$  associated with $p$ and it will be denoted by   $\eta_p$.
\end{proposition}

The following exercises can be found useful by some attentive readers.
\begin{exercise}
In the framework of Defintion (def-counting measure of the paper), if $U \in \mathscr{B}_X$, then the function
\[
(0,\infty) \ni t \mapsto \eta_p((0,t]\timesU) \in \bar{\mathbb{N}}
\]
is weakly-increasing and right-continuous.\\
Moreover, a number $t_0\in (0,\infty)$ is a discontinuity point of it if and only if $t_0 \in \mathrm{Dom}(p)$ and $p(t_0) \inU$.
\end{exercise}
\begin{exercise}
Show that formula (equation eqn-IW_I.9.1 of the paper) is equivalent to
\begin{equation}
  \eta_p((0,t]\timesU)= \sum_{s>0} \1_{(0,t]\timesU}\bigl(s,p(s)\bigr),   \;\; t>0,\;\;U \in \mathscr{B}_X,
\end{equation}
with an obvious understanding that $\1_{(0,t]\timesU}\bigl(s,p(s)\bigr)=1$ if and only if $\bigl(s,p(s)\bigr)\in (0,t]\timesU$ if and only if $s \in (0,t] \cap \mathrm{Dom}(p)$ and $p(s) \inU$. \\
Deduce that
\begin{equation}
 \iint \1_{(0,t]\timesU} \eta_p(\mathrm{d} s,\mathrm{d} u)= \sum_{s>0} \1_{(0,t]\timesU}\bigl(s,p(s)\bigr),   \;\; t>0,\;\;U \in \mathscr{B}_X,
\end{equation}
or
\begin{equation}
 \iint_{(0,t]\timesU}  \eta_p(\mathrm{d} s,\mathrm{d} u)= \sum_{s>0} \1_{(0,t]\timesU}\bigl(s,p(s)\bigr),   \;\; t>0,\;\;U \in \mathscr{B}_X,
\end{equation}
\end{exercise}

It is obvious that if $p$ and $q$ are two point functions  on $X$ with $p=q$, then the measures $\eta_p$ and $\eta_q$ are equal. We have also a converse assertion.

\begin{proposition}
Suppose that singletons are $\mathscr{B}_X$-measurable. If $p$ and $q$ are two point functions on $X$ such that  the measures $\eta_p$ and $\eta_q$ are equal, i.e.\ for every $U \in \mathscr{B}_X$ and every $t>0$,
\begin{equation}
\# \bigl\{ s \in \mathrm{Dom}(p)\cap (0,t] : p(s) \inU \bigr\}= \# \bigl\{ s \in \mathrm{Dom}(q)\cap (0,t] : q(s) \inU \bigr\},
\end{equation}
or, equivalently,
\begin{equation}
\sum_{s \in (0,t]} \1_{\mathrm{Dom}(p) \timesU}(s,p(s)) = \sum_{s \in (0,t]} \1_{\mathrm{Dom}(q) \timesU}(s,q(s))
\end{equation}
then \[p=q.\]
\end{proposition}
\begin{proof}[Proof of Proposition (prop-injectivity of map p to eta_p of the paper)]
Let us choose and fix $t>0$. Then, since (equation eqn-eta_p=eta_q of the paper) holds  for every $U \in \mathscr{B}_X$ we infer that
\[
 \bigl\{ p(s): s \in \mathrm{Dom}(p)\cap (0,t]  \bigr\}=  \bigl\{ q(s): s \in \mathrm{Dom}(q)\cap (0,t] \bigr\}.
\]
Since the above equality holds also for every $r<t$ we infer that
\[
 \bigl\{ p(s): s \in \mathrm{Dom}(p)\cap [t,t]  \bigr\}=  \bigl\{ q(s): s \in \mathrm{Dom}(q)\cap [t,t] \bigr\}.
\]
This obviously implies that
\[
t \in \mathrm{Dom}(p) \iff  t \in \mathrm{Dom}(p) \mbox{ and if so } p(t)=q(t).
\]
The proof is complete.
\end{proof}

In the framework of Example (example-point function from a cadlag function of the paper) Proposition (prop-injectivity of map p to eta_p of the paper) yields the following result.

