{"assumptions":[],"created_at":"2026-10-27T13:20:07.912283+00:00","domain":"probability theory","id":"claim_7119411bf8f4694bc4c9770428eabcc73e3becc3f02d1f3aae26390de844e05e","kind":"concept","schema_version":1,"statement":"[Thm BS1 of arXiv:2608.29914, 'Fixed points in abstract provability structures'] {beklemishev2016some}}]
