{"assumptions":[],"created_at":"2026-10-28T02:39:12.349374+00:00","domain":"probability theory","id":"claim_713c571eaa037f62e92c4e7fb2c0f907eb6158d1e869daf457ed5f0523a544bb","kind":"theorem","schema_version":1,"statement":"[Corollary cor:LackerZhang of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfies Assumption (as:results:fixedPoint of the paper). Let $\nu_0$ be a solution to the Cayley fixed point{} in the sense of Definition (def:results:CBP of the paper). Then, $(F, 0)$
    solves the Lacker-Zhang fixed point problem with
    \begin{equation}
        F(x) = \frac{1}{\kappa}\Big(U(x) + \log \nu_0(x) \Big), \quad x \in \ensuremath{\mathbb{R}}^d.

    \end{equation} Conversely, if $(F, C)$ solves the Lacker-Zhang fixed point problem, then there is a solution $\nu$ to Cayley fixed point{} in the sense of Definition (def:results:CBP of the paper) characterized by its marginal $\nu_0$, which is given by
    \begin{equation}
        \nu_0(x) = \frac{1}{\mathcal{Z}_F} e^{-U(x) - \kappa F(x)}, \quad  \mathcal{Z}_F := \int_{\ensuremath{\mathbb{R}}^d}  e^{-U(y) - \kappa F(y)} dy, \quad x \in \ensuremath{\mathbb{R}}^d.

    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.497128+00:00","domain":"probability theory","id":"claim_713d84b51798277e23bb410fca729091c8dfe27ca5c89b3f01374fa0b459a918","kind":"lemma","schema_version":1,"statement":"[Lemma 4 of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Fix $T,\beta,\varepsilon>0$ and $0\le s<t\le T$. For each partition $\pi$ of $[s,t]$, the map $\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[s,t]}$ defined in~\eqref{FirstTrans3dSub} is a sub-probability kernel on $E_\varepsilon$ and satisfies the following:
\begin{enumerate}[(i)]
\item The family $\{\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[s,t]}\}_\pi$ is monotone under refinement pointwise in $(x,A)$: if $\pi'$ refines $\pi$, then for every $x\in E_\varepsilon$ and $A\in\mathcal B(E_\varepsilon)$,
\begin{align}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi'}_{[s,t]}(x,A)
\;\le\;
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[s,t]}(x,A).
\end{align}

\item Fix $0\le r<s<t\le T$ and let $\pi$ be a partition of $[r,t]$ with $s\in\pi$. Then for every $x\in E_\varepsilon$ and $A\in\mathcal B(E_\varepsilon)$,
\begin{align}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[r,t]}(x,A)
\,=\,
\int_{E_\varepsilon}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi|_{[r,s]}}_{[r,s]}(x,dy)\,
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi|_{[s,t]}}_{[s,t]}(y,A).
\end{align}
Here $\pi|_{[r,s]}$ and $\pi|_{[s,t]}$ denote the restrictions of $\pi$ to $[r,s]$ and $[s,t]$, respectively.
\end{enumerate}","status":"unverified"}

