{"assumptions":[],"created_at":"2026-10-27T12:48:49.901959+00:00","domain":"probability theory","id":"claim_73456ea5c11aa4e43ac342248d8a20f3b2761a5dc44d468710556ec7b30a1c4d","kind":"concept","schema_version":1,"statement":"[Theorem SSK with CW interaction at phase transitions \cite{BL17,BLW18,JKOP2} of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] At the boundaries between each pair of phases and at the triple point, $F_N$ exhibits the following convergence in distribution as $N\to\infty$.
\begin{enumerate}[(i)]
\item Spin glass $\leftrightarrow$ Ferromagnetic [BL17]: If $\beta>1$ and $J=1-wN^{-1/3}$ for fixed $w\in\mathbb{R}$, then
 \begin{equation} 
\frac{2N^{2/3}}{\beta-1}(F_N(\beta)-F(\beta))\to \TW_{1,w}
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the spin glass regime and  $\TW_{1,w}$ is a parametrized family characterized in Theorems 1.5 and 1.7 of [Bloemendal_2012], interpolating between Tracy-Widom and Gaussian.
\item Ferromagnetic $\leftrightarrow$ Paramagnetic [BLW18]: If $J>1$ and $\beta=J^{-1}+BN^{-1/2}$ for fixed $B\in\mathbb{R}$, then
 \begin{equation} 
N\left(F_N(\beta)-F(\beta)-\frac{\log N}{4N}\right)\to \mathcal{G}_1+Q(\mathcal{G}_2)
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the ferromagnetic regime, $(\mathcal{G}_1,\mathcal{G}_2)$ has bivariate Gaussian distribution with explicit mean and variance depending on $J$, and $Q$ is an explicit function depending on both $J$ and $B$ (in the GOE case that we consider $\mathcal{G}_1,\mathcal{G}_2$ are independent, but the theorem is more general).
\item Spin glass $\leftrightarrow$ Paramagnetic [JKOP2]: If $J<1$ and $\beta=1+bN^{-1/3}\sqrt{\log N}$ for fixed $b\in\mathbb{R}$, then
 \begin{equation} 
\frac{N}{\sqrt{\frac16\log N}}\left(F_N(\beta)-F(\beta)+\frac{\log N}{12N}\right)\to\mathcal{N}(0,1)+\sqrt{\frac32}b_+\TW_1
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the spin glass ($b\geq0$) and paramagnetic ($b\leq0$) regimes, $b_+=\max\{b,0\}$, and $\TW_1$ is independent of $\mathcal{N}(0,1)$.
\item Triple point [JKOP2]: If $\beta=1+bN^{-1/3}\sqrt{\log N}$ and $J=1-wN^{-1/3}$ for fixed $b,w\in\mathbb{R}$, then
 \begin{equation} 
\frac{N}{\sqrt{\frac16\log N}}\left(F_N(\beta)-F(\beta)+\frac{\log N}{12N}\right)\to\mathcal{N}(0,1)+\sqrt{\frac32}b_+\TW_{1,w}.
 \end{equation} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-09-07T12:18:08.278392+00:00","domain":"probability theory","id":"claim_7345c4b6d6feb744dc1104586a8616815a2d1a6046a665e03f064dd07f981513","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Assume that $\{\delta_{i}, 1\le i\le n \}$ and $\{\zeta_{i}, 1\le i\le n \}$ are two independent sequences of random variables, where $\delta_{i}\sim\textnormal{Bernoulli}(p_{i})$ are independent and $\zeta_{i}$ are independent centered $\alpha$-sub-exponential random variables.
	Consider a random vector $\xi=(\xi_{1}, \cdots, \xi_{n})$  with $\xi_{i}=\delta_{i}\cdot\zeta_{i}$. Let $A=(a_{ij})_{n\times n}$ be a symmetric fixed matrix. Then for $0<\alpha\le 2$ and $t\ge 0$
	\begin{align}
		&\mathbb{P}\{\vert \xi^\top A\xi-\mathbb{E}\xi^\top A\xi\vert\ge L(\alpha)^{2}t  \}\nonumber\\
		\le& 2\exp\left(-c(\alpha)\min\left\{ \frac{t^{2}}{\sum_{k}a_{kk}^{2}p_{k}+\sum_{i\neq j}a_{ij}^{2}p_{i}p_{j}}, \left(\frac{t}{\Vert A\Vert_{l_{2}\to l_{2}}}\right)^{\alpha/2}  \right\}      \right),\nonumber
	\end{align}
where $L(\alpha)=\max_{i}\Vert \zeta_{i}\Vert_{\Psi_{\alpha}}$ and $c(\alpha)$ is a positive constant depending only on $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.229090+00:00","domain":"probability theory","id":"claim_734baaa05ac5bd03dc865cd4902422632a15cdd8ef90083a9a6b2da097d75c58","kind":"concept","schema_version":1,"statement":"[Lemma gap_convergence of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For any fixed $\delta >0$ and $f$ of the form (Form of f of the paper) with $supp (f) \subset [-K_f, \infty), $ for some $K_f>0$, uniformly in $x\in[-(\mu -\lambda)t-\delta\sqrt{t},-(\mu -\lambda)t+\delta\sqrt{t}]$, we have
