{"assumptions":[],"created_at":"2026-10-26T20:55:18.051751+00:00","domain":"probability theory","id":"claim_753a59ed5234269db9cad8adf6b6deedbf08c5f867ee07e49eaa6e620a51b541","kind":"theorem","schema_version":1,"statement":"[Proposition 21 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma\in(0,1)$, $\alpha\in\mathbb R$ and $0\le \tau'\le \tau\le T$.
\begin{enumerate}
\item The restriction map
\begin{equation*}
\operatorname{Res}_{\tau,\tau'}:\mathfrak C^{\gamma}(\Delta^2_\tau;B_\alpha)\to \mathfrak C^{\gamma}(\Delta^2_{\tau'};B_\alpha), \quad [r]_\tau\mapsto\operatorname{Res}_{\tau,\tau'}[r]_\tau:= [r|_{\Delta_{\tau'}^2}]_{\tau'}
\end{equation*}
is well defined and linear. The map satisfies the seminorm bound 
$$\|\operatorname{Res}_{\tau,\tau'}\mathfrak r\|_{\mathfrak C_2^{\gamma,\alpha}(\tau')}\le \|\mathfrak r\|_{\mathfrak C_2^{\gamma,\alpha}(\tau)}.$$
\mlabel{it:froza}

\item The transport map
\begin{equation*}
\mathcal T_{\tau,\tau'}:\mathfrak C^{\gamma}(\Delta^2_{\tau'};B_\alpha)\to \mathfrak C^{\gamma}(\Delta^2_{\tau'};B_\alpha), \quad
[q]_{\tau'}\mapsto \mathcal T_{\tau,\tau'}[q]_{\tau'}:=[S_{\tau-\tau'}q]_{\tau'}
\end{equation*}
is well defined and linear. The map satisfies the seminorm bound 
$$\|\mathcal T_{\tau,\tau'}\mathfrak q\|_{\mathfrak C_2^{\gamma,\alpha}(\tau')}\le M_{\alpha,T}\|\mathfrak q\|_{\mathfrak C_2^{\gamma,\alpha}(\tau')}.$$
\mlabel{it:frozb}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:49:15.411210+00:00","domain":"probability theory","id":"claim_753b67850d31ede726aedee37656629386cca998ddc34cb441236652f8de8762","kind":"lemma","schema_version":1,"statement":"[Lemma Weighted radial lemma of arXiv:2608.27248, 'Optimal Transport and the ABP Method in Higher Codimension'] Let $A\subset\mathbb{B}_R^4$ be relatively closed and convex, and let
$g:A\to[0,a]$ be continuous and concave.  For almost every $s\in(0,R^2)$ set
\begin{equation*}
 J_0(s)=s\int_{\mathbb{S}^3}g(\sqrt{s}\,\theta)^n
 \mathbf1_A(\sqrt{s}\,\theta)\,\mathrm d\theta.
\end{equation*}
Here $g$ is extended by zero outside $A$, and $\mathrm d\theta$ is the area
measure on $\mathbb{S}^3$.  Then $J_0$ has a
left-continuous $\mathrm{BV}$ representative $J$ on $(0,R^2]$, with $J(0)=0$,
and
\begin{equation}
 J(s_2)-J(s_1)\leq|\mathbb{S}^3|a^n(s_2-s_1).
\end{equation}
Set $\gamma=g(0)$ when $0\in A$ and $\gamma=0$ otherwise.  Then
\begin{equation}
 J(s_2)-J(s_1)
 \leq\frac{|\mathbb{S}^3|}{2}(a^n+\gamma^n)(s_2-s_1).
\end{equation}
If $R>0$, $a>0$, and for some $h_j\downarrow0$,
\begin{equation}
 \frac{J(R^2)-J(R^2-h_j)}{h_j}\longrightarrow|\mathbb{S}^3|a^n,
\end{equation}
then $A=\mathbb{B}_R^4$ and $g\equiv a$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.858263+00:00","domain":"probability theory","id":"claim_754270d5021f747b541745ee0894b665dea80f1743b0aed62d5a766a4ac35149","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2506.10650, 'Admitted symmetries of Backward Stochastic Differential Equations'] \cite{srihirun2007definition}
    Let $\eta(t,y,a)$ and $Y_t$ be as above and $B_t$ a standard Brownian motion. Define 
