     &\hspace{1cm} \times
    \prod_{\vb*{y} \in \mathds{N}^{\delta}} \Bigg( \frac{1}{\alpha(\vb*{y})!} \Big(\frac{n\mathds{E}\big[\prod_{i=1}^{\delta} (f^{(i)}(U))^{y_i}\big]\big(\sum_{i=1}^{\delta} y_i-1\big)!}{\prod_{i=1}^{\delta} y_i!} \Big)^{\alpha(\vb*{y})} \Bigg).
