{"assumptions":[],"created_at":"2026-10-26T19:22:20.952333+00:00","domain":"probability theory","id":"claim_78974cabca1d1a8944bebea2729e82fde25153884547f1a2324313eec5c14339","kind":"theorem","schema_version":1,"statement":"[Theorem 12 (Mimicking theorem) of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Let $d \in \bbN$ and $(\Omega, \mA, \mF, \bbP)$ be a filtered probability space supporting a $d$-dimensional $\mF$-Brownian motion $B$ and a $d$-dimensional $\mF$-adapted continuous process $X$ satisfying
\begin{equation}

    X_t = X_0 + \int_0^t a_sds + B_t,
\end{equation}
where $a$ is a $d$-dimensional progressively measurable $\mF$-adapted process satisfying
\begin{equation*}
    \bbE \bigg[\int_0^t|a_s| ds  \bigg] < \infty, \quad t \in [0, T].
\end{equation*}
Let $(\mF_t^X)_{t\geq 0}$ be the filtration generated by $X$ and define  $\tilde{a}:[0, T] \times \mC^d \rightarrow \R^d$ to be a progressively measurable function satisfying
\begin{equation*}
    \tilde{a}_t(X) = \bbE\big[a_t \mid \mF_t^X\big], \quad \text{a.e. } t \in [0, T], \quad \bbP\text{-a.s.}
\end{equation*}
 There exists a $d$-dimensional $\mF^X$-adapted Brownian motion ${W}$ such that
\begin{equation*}
    X_t = X_0 + \int_0^t \tilde{a}_s(X) ds + {W}_t, \quad t \in [0, T], \quad \bbP\text{-a.s.}
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.841456+00:00","domain":"probability theory","id":"claim_789d2acee49da65723eaf50c83db339ca376678f46acc9dc8126bdafb828b0f7","kind":"concept","schema_version":1,"statement":"[Lemma 17 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] Let $\Bi \in \boldsymbol{L}^1_\loc(I\times \R^d \times \R)$
	be such that $\dive_x \Bi(t,x,z) = 0$ for a.e. $(t,z)\in I \times \R$.
	Let $\rho \in L^1_\loc(I\times \R^d \times \R)$
	be such that
	$\rho \Bi \in \boldsymbol{L}^1_\loc(I\times \R^d \times \R)$.
	Suppose that $\rho$ solves
	\begin{equation}
		\d_t \rho + \dive_x (\rho \Bi) + \d_z \rho = 0, \qquad (t,x,z)\in I \times \R^d \times \R.
	\end{equation}
	Then for any $f\in L^\infty(\R)$ with compact support the function
	\begin{equation}
		\eta(t,x,z) := f(z-t) \rho(t, x, z)
	\end{equation}
	solves
	\begin{equation}

		\d_t \eta + \div_x (\eta \Bi) + \d_z \eta = 0.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.224059+00:00","domain":"probability theory","id":"claim_789f0f511202f06816ff2763b1aae3301e0b3af4eae0037bcc18ed0f20b70590","kind":"lemma","schema_version":1,"statement":"[Lemma lem:G of arXiv:2506.15949, 'On the passage times of self-similar Gaussian processes on curved boundaries'] \begin{compactenum}[\rm (1)]
