\end{equation}
Moreover, let $u_N=E_N/N$ and $\beta_N=m^{-1}(u_N)$, then
\begin{equation}
G_N(E_N,\Delta)=\frac{Z(\beta_N)^Ne^{\beta_NE_N}}{\sqrt{2\pi N\sigma^2(\beta_N)}}\left(\int_0^{\Delta}e^{\beta_Nt}dt\right)(1+o(1)).
\end{equation}
Consequently, the thermodynamic limit
\begin{equation}
\lim_{N\to+\infty}\frac{1}{N}R_{N,E_N,\Delta}^{\mc}=\psi(\beta)+\beta u=s(u).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:58:09.890252+00:00","domain":"probability theory","id":"claim_78f71ea44399e62304340d3b7b88745bc97f00322add42a392643249040745b6","kind":"theorem","schema_version":1,"statement":"[Proposition prop:two-point of arXiv:2607.18824, 'Non-Abelian multiplicative chaos on the circle'] For all $z_1,z_2\in\mathbb D$ distinct,
