        \mathbb{E}\left[I_{n}(f\1_{B}^{\otimes n})I_{n}(g\1_{B}^{\otimes n})\right] 
        &\leqslant \mathbb{E}\left[I_{n}(f)I_{n}(g)\right].
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:06:39.320130+00:00","domain":"probability theory","id":"claim_7a6b468bef89c071085d4b69c2c044dd528e9fdf07817f4f558f829f66c1518c","kind":"concept","schema_version":1,"statement":"[Theorem t:global_NSE of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Suppose that $q,p\in (2,\infty)$ satisfy
\begin{equation}

\frac{2}{p}+\frac{3}{q}<2, \quad {{\normalfont\text{(subcriticality)}}}
\end{equation}
and fix 
\begin{equation*}
M \geq 1  \qquad \text{ and }\qquad \varepsilon\in (0,1).
\end{equation*}
Then there exist $\mu>0$ and $\theta\in \ell^2$ satisfying $\#\{k\,:\, \theta_k\neq 0\}<\infty$ for which the following assertion holds. For any
\begin{equation}

u_0\in \mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^3)\qquad \text{ such that }\qquad \|u_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^3;{\mathbb R}^3)}\leq M,
\end{equation}
the unique maximal $(p,q)$-solution $(u,\tau)$ to the stochastic {\normalfont{3D NSEs}} (equation eq:navier_stokes_intro of the paper) is global in time with high probability:
\begin{equation}

{\mathbf P}(\tau=\infty)>1-\varepsilon.
\end{equation}
Moreover, $(u,\tau)$ has the following regularity properties:
\begin{align}

u&\in L^p_{{\rm loc}}([0,\tau);H^{1,q}(\mathbb{T}^3;{\mathbb R}^3))\cap C([0,\tau);B^{1-2/p}_{q,p}(\mathbb{T}^3;{\mathbb R}^3)) \ \text{ a.s.\ }\\

u&\in C^{\vartheta_0,\vartheta_1}_{{\rm loc}}((0,\tau)\times \mathbb{T}^3;{\mathbb R}^3)\ \text{ a.s.\ for all }\vartheta_0<1/2,  \ \vartheta_1<\infty.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.319654+00:00","domain":"probability theory","id":"claim_7a6d297a1bae37e6302bd5e276e060135d425414a2ac7e202f9cae3954df9ff2","kind":"concept","schema_version":1,"statement":"[Lemma lem:inv-NWU of arXiv:2411.14926, 'Convex combinations of random variables stochastically dominate the parent for a new class'] A random variable $X$ is super-heavy-tailed if and only if
\begin{equation}

F_X(\tfrac{x}{\theta})F_X(\tfrac{x}{1-\theta})\leq F_X(x),\quad\forall x\geq0,\,\theta\in(0,1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.446241+00:00","domain":"probability theory","id":"claim_7a6f26e4ddd7fc399710f57be1491c31c6bd2c4a644eee9c02eca288b1bf035b","kind":"definition","schema_version":1,"statement":"[Def weak of arXiv:2601.10568, 'Hydrodynamic Limit with a Weierstrass-type result'] For $ \rho^{\rm ini}:\mathbb{T}^d\to[0,1] $ a measurable function, we say that $ \rho:[0,T]\times \mathbb{T}\mapsto [0,1] $ is a weak solution of the equation
        \begin{align}
		\begin{cases}
		    \partial_t\rho
            =\partial_u^2\Phi(\rho), & \text{in } (0,T]\times\mathbb{T}^d,\\
            \rho_0=\rho^{\text{ini}},& \text{in }\mathbb{T}^d
		\end{cases} 
	\end{align}
    if
	\begin{enumerate}
    \item $\Phi(\rho)\in L^2([0,T];\mathcal{H}^1(\mathbb{T}^d))$;
	\item for any $ t\in[0,T] $ and $ G\in C^{1,2}([0,T]\times \mathbb{T}) $, $\rho$ satisfies the formulation $\mathfrak{F}_t(\rho^{\rm ini},\rho,G)=0$, where   
		\begin{equation}
			\mathfrak{F}_t(\rho^{\rm ini},\rho,G)
			:=
			\langle \rho_t,G_t\rangle-\inner{\rho^{\rm ini},G_0}
			-\int_0^t
			\bigg\{
			\langle \rho_s,\partial_sG_s\rangle
			+
                \langle \Phi(\rho_s),\partial_u^2 G_s\rangle
			\bigg\}
			\mathrm{d} s
			.
		\end{equation}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:47.662555+00:00","domain":"probability theory","id":"claim_7a71916885f5d54d4c15126517b749e687ff48ac60e47b5f3c1dc7b7e9346488","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1<p<\infty$. Given a matrix weight $W\in A_p$, we have
