\item[(2)] let $E_{i,1}$ denote the event that there exists at least one long edge connecting $B_{r_{i}-M_i/8}({\bm 0})$ and $B_{r_i}({\bm 0})^c$. Here we use a subscript 1 in $E_{i, 1}$ since later we will introduce some other events with subscripts 2, 3 and 4.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:03:39.756257+00:00","domain":"probability theory","id":"claim_7b1758a540e841dd38039295fe2b60198c5a3be01895f1b732cbf946c16d18ce","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_3 of arXiv:2411.02362, 'Limit theorems for random Dirichlet series: boundary case'] For all $\rho>0$,
\begin{equation}
\lim_{s\to 0+}\sum_{k\ge M(s)+1}\frac{(\log k)^{-1/2}}{k^{1/2+s}}|\eta_k|\1_{A_{k,\rho}(s)}=0\quad \text{\rm{a.s.}}
    \end{equation}
    and
