{"assumptions":[],"created_at":"2026-10-27T22:31:02.830164+00:00","domain":"probability theory","id":"claim_7cbbcdbf4afbce30dfdd180c3ed309e694dfd1109c94467f94096edb3f939990","kind":"theorem","schema_version":1,"statement":"[Thm Bernstein of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let  $\mu > -\frac12$, ${\kappa}_1,\ldots, k_{d_2} > -1$. Then for every polynomial $f$ of degree at most $n$, 
\begin{align}
  &  \sum_{i=1}^{d_1}  \left \| \frac{\sqrt{(1-|\bm y|)^2- \|\bm x\|^2}}{\sqrt{1-|\bm y|}} \partial_{x_i} f \right \|_{\mu,{\boldsymbol{\kappa}}}^2  
   + \sum_{1 \le i< j \le d_1}  \left\|   \frac{1}{\sqrt{1-|\bm y|}} D_{i,j}^{(\bm x)} f \right \|_{\mu,{\boldsymbol{\kappa}}}^2 \\
  &\qquad +  \sum_{1\le i< j \le d_2} \left \| (\partial_{y_j} - \partial_{y_j}) f  \right \|_{\mu,{\boldsymbol{\kappa}}}^2 +
     \sum_{i=1}^{d_2} \left \| \frac{\sqrt{y_i}}{\sqrt{1-|\bm y|}}  {\mathfrak D}_i f \right \|_{\mu,{\boldsymbol{\kappa}}} \le {\lambda}_n^{\mu,{\boldsymbol{\kappa}}} \| f |_{\mu,{\boldsymbol{\kappa}}}^2.  \notag
\end{align}
Moreover, the inequality is sharp in the sense that the equality is attained by some polynomial of degree $n$, and 
so is the inequality  
\begin{align}
  \sum_{1\le i< j \le d_2} \left \| (\partial_{y_j} - \partial_{y_j}) f  \right \|_{\mu,{\boldsymbol{\kappa}}}^2 +
     \sum_{i=1}^{d_2} \left \| \frac{\sqrt{y_i}}{\sqrt{1-|\bm y|}}  {\mathfrak D}_i f \right \|_{\mu,{\boldsymbol{\kappa}}} \le {\lambda}_n^{\mu,{\boldsymbol{\kappa}}} \| f |_{\mu,{\boldsymbol{\kappa}}}^2.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:35:04.199653+00:00","domain":"probability theory","id":"claim_7cbf8277227721b31cd5daba27cc2a828b4590e25ca86f6bb4d4a23688b6636d","kind":"theorem","schema_version":1,"statement":"[Proposition 21 of arXiv:2608.03497, 'Connective Constants on Nested Fractal Graphs'] If \(N=4k_N+\ell_N\notin\{3,5\}\), where
\(\ell_N\in\{1,2,3\}\), then the functions in
\eqref{eq:ngasket-crossings} satisfy
\begin{equation}
  \begin{aligned}
  X_0
    &=e^{-(k_N+1)\beta}
      +e^{-(3k_N+\ell_N-1)\beta},&
  Y_0
    &=e^{-2(k_N+1)\beta}
      +e^{-(2k_N+\ell_N-2)\beta},\\
  X_{m+1}
    &=X_m^2
      \bigl(Y_m^{k_N}+Y_m^{3k_N+\ell_N-2}\bigr),&
  Y_{m+1}
    &=X_m^2
      \bigl(Y_m^{2k_N+\ell_N-3}+Y_m^{2k_N+1}\bigr).
  \end{aligned}

\end{equation}

For \(N=3\),
\begin{equation}
  \begin{aligned}
  x_0&=e^{-\beta},&
  y_0&=e^{-2\beta},\\
  x_{m+1}
    &=(x_m+y_m)^2+x_m^2(x_m+2y_m),&
  y_{m+1}
    &=x_my_m(x_m+2y_m).
  \end{aligned}

\end{equation}

For \(N=5\), put
\[
  \bar\phi_m=\phi_{1,m}+\phi_{2,m},
  \qquad
  \bar\theta_m=\theta_{1,m}+\theta_{2,m}.
\]
Then
\begin{equation}
  \begin{aligned}
  (\phi_{1,0},\phi_{2,0},\theta_{1,0},\theta_{2,0})
    &=(e^{-2\beta},e^{-3\beta},e^{-\beta},e^{-4\beta}),\\
  \phi_{1,m+1}
    &=\bar\phi_m^2\bar\theta_m(1+\theta_{1,m}),\\
  \phi_{2,m+1}
    &=\bar\phi_m^2\bar\theta_m\theta_{2,m},\\
  \theta_{1,m+1}
    &=\bar\phi_m^2+
      \bar\theta_m^2\theta_{1,m}\phi_{1,m}
      (\phi_{1,m}+2\phi_{2,m}),\\
  \theta_{2,m+1}
    &=\bar\theta_m^2\theta_{2,m}\phi_{1,m}
      (\phi_{1,m}+2\phi_{2,m}).
  \end{aligned}

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:48:02.409806+00:00","domain":"probability theory","id":"claim_7cc5daf3165eaaa37058f2f91e749ead0ff06431bd2a09924035d5ada423c8af","kind":"lemma","schema_version":1,"statement":"[Lemma lma:residuehalf of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Write $P_i = \rho_i^B(m_{i,3}) = \left(\begin{smallmatrix}1&p_i\\0&1\end{smallmatrix}\right)$. Set
\begin{equation*}
	K_i(t) = \epsilon_{i+2}\Sigma_i(t)(\ell_{i+2}) \ \ \ \ \ q_i(t) := (K_i(t))_{21}
\end{equation*}
Then there is a nonzero real number $s$ such that $q_i(t) = \frac{2s}{p_i}t + O(t^2)$, and $\theta(t) = \frac{8s^2}{p_1p_2}t^2 + O(t^3)$. Consequently, $p_1p_2 > 0$, and $\frac{q_1(t)q_2(t)}{\theta(t)} = \frac12 + O(t)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.748478+00:00","domain":"probability theory","id":"claim_7cc65c64330481e92445e325d794416f755144a68b3a7d1a2e9c442d68b9f932","kind":"lemma","schema_version":1,"statement":"[Lem 17 of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Fix $j>2\ell-2$ and set
\begin{align*}
    \fL_0:=\{0,1,\ldots,\ell-1\},
    \qquad
    \fR_j:=\{j-\ell+1,\ldots,j\}.
\end{align*}
For $u\in\{\ell-1,\ldots,j-\ell\}$, let
\begin{align*}
    \cC_u^{(j)}
    :=
    \{(x,y)\in\cE[0,j]:x\le u<y\}.
\end{align*}
Then, for every $S\subseteq\cE[0,j]$, the following hold.
\begin{enumeratei}
    \item If $|S|<\lc$, then deleting $S$ does not disconnect $\fL_0$ from $\fR_j$.

    \item If $|S|=\lc$ and deleting $S$ disconnects $\fL_0$ from $\fR_j$, then
    $S=\cC_u^{(j)}$ for a unique $u\in\{\ell-1,\ldots,j-\ell\}$.  Moreover, for every
    $e\in\cC_u^{(j)}$, there is a simple $\fL_0$-$\fR_j$ path whose unique edge in
    $\cC_u^{(j)}$ is $e$.
\end{enumeratei}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.454688+00:00","domain":"probability theory","id":"claim_7ccc19fe7b3341f6125b925f953f89ee6990b3461c20fae3a10b4634f2ba5524","kind":"definition","schema_version":1,"statement":"[Df eq:1-arm_event of arXiv:2605.14910, 'Sharp Phase Transition for the Formation of Infinite Tubes'] Let $p\in[0,1]$.
  For a width parameter $w>0$ and a scale parameter $n\in\mathbb{N}$, we define the \emph{tubular one-arm probability} $\theta_{w,n}^{\mathrm{tube}}(p)$ by
  \begin{equation}
  \theta_{w,n}^{\mathrm{tube}}(p)
 :=\mathbb{P}_p\left(
  \begin{array}{l}
    \text{$\exists$ an open $k$-tube of width at most $w$ whose initial sphere}\\
    \text{intersects $\Lambda_o$ and terminal sphere intersects $\partial\Lambda_n$}
  \end{array}
  \right).
  \end{equation}
  By convention, when $n\le1/2+w$, we regard the event in~(equation eq:1-arm_event of the paper) as occurring trivially, and hence set $\theta_{w,n}^{\mathrm{tube}}(p):=1$.
  Indeed, when $n\le1/2+w$, there exists a single topological $(k-1)$-sphere intersecting both $\Lambda_o$ and $\partial\Lambda_n$, which may be viewed as a trivial $k$-tube whose initial and terminal spheres coincide.
  We refer to the event in~(equation eq:1-arm_event of the paper) as a \emph{tubular one-arm event} with width at most $w$, and denote it by $\mathcal{T}_{w,n}$~(see Figure~(fig:one-arm of the paper)).","status":"unverified"}

