        \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:57:20.590784+00:00","domain":"probability theory","id":"claim_7e3f35fb4b477a10c2ed138dc01643c870355e2a70142b599f9676baf7504844","kind":"theorem","schema_version":1,"statement":"[Theorem thm_momrec of arXiv:2411.09976, 'Occupation times on the legs of a diffusion spider'] For $r\in\{2,\dotsc,R\}$ and $n_1,\dotsc,n_r \geq1$, 
\begin{equation} 
\mathcal{L}_t\Bigg\{ \mathbf{E}_\mathbf{0}\left(\prod_{i=1}^r (A_t^{(i)})^{n_i}\right) \Bigg\}(\lambda) = \sum_{i=1}^r \sum_{k=1}^{n_i} \frac{{n_i}! D_k^{(i)}(\lambda)}{(n_i-k)! \lambda^k} \mathcal{L}_t\Bigg\{ \mathbf{E}_\mathbf{0}\left( \frac{\prod_{j=1}^r (A_t^{(j)})^{n_j} }{(A_t^{(i)})^{k}} \right) \Bigg\}(\lambda),
\end{equation}
where $D_k^{(i)}$ is defined in~(equation eq_Dk of the paper).   
If $X$ is self-similar, then  for any $\lambda>0$, 
\begin{equation} 
\mathbf{E}_\mathbf{0}\left(\prod_{i=1}^r (A_1^{(i)})^{n_i}\right) = \sum_{i=1}^r \sum_{k=1}^{n_i} \dfrac{\binom{n_i}{k}}{\binom{n_1+\dotsc+n_r}{k}} D_k^{(i)}(\lambda) \mathbf{E}_\mathbf{0}\left( \frac{\prod_{j=1}^r (A_1^{(j)})^{n_j} }{(A_1^{(i)})^{k}} \right). 
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.532410+00:00","domain":"probability theory","id":"claim_7e423ab0b1372fd33421bdae58891bad15813c324f472dd5ed7b9b862bd9dae1","kind":"concept","schema_version":1,"statement":"[Thm Lamperti-Kiu of arXiv:2411.07671, 'Long Time Behavior of General Markov Additive Processes'] \cite[Thm.2.3] {alili2017inversion} Let $\alpha >0$ and $((\xi,\Theta),\mathbb{P})$ be a MAP in $S\times \mathbb{R}$ with an extra isolated state $\partial$ and lifetime $\zeta$. Define a process $X$ by \begin{equation*}
    X_t=
 \begin{cases}
        \Theta_{\tau_t}e^{\xi_{\tau_t}} & \text{if  }  t< \int_0^\zeta e^{\alpha \xi_s}ds  \\
        0 &  \text{if   }  t\geq \int_0^\zeta e^{\alpha \xi_s}ds
    \end{cases}
    \end{equation*}
where the time change is given by\begin{equation*} \tau_t := \inf \{ s \, : \, \int_0^s e^{\alpha \xi_u}du>t\}
\end{equation*}
for $t< \int_0^\zeta e^{\alpha \xi_s}ds$. Define $P_x = \mathbb{P}_{x/||x||,\log ||x||}$ for $x\in \mathcal{H}$ and $P_0 = \mathbb{P}_{\partial}$. Then, the process $(X,P_x)$ is an $\mathcal{H}$-valued ssMp with index $\alpha>0$ and lifetime $\int_0^\zeta e^{\alpha \xi_s}ds$.\\
Conversely, let $(X,P_x)$ be an $\mathcal{H}$-valued self-similar Markov process with index $\alpha>0$ and lifetime $\zeta'$. Define the process $(\xi,\Theta)$ by \begin{equation*}
     \quad 
 \begin{cases}
        \xi_t = \log ||X_{A_t}|| \quad \text{and} \quad \Theta_t = \frac{X_{A_t}}{||X_{A_t}||} & \text{if  }  t< \int_0^{\zeta'} \frac{ds}{||X_s||^\alpha}  \\
        (\xi_t,\Theta_t)=\partial &  \text{if   }  t\geq \int_0^{\zeta'} \frac{ds}{||X_s||^\alpha}
    \end{cases}
\end{equation*}
where the time change is given by\begin{equation*}
    A_t := \inf \{  s \, : \, \int_0^s \frac{du}{||X_u||^\alpha}>t\} 
\end{equation*} for $t< \int_0^{\zeta'} e^{\alpha \xi_s}ds$. Define $\mathbb{P}_{y,\theta}= P_{\theta e^y}$ for $\theta \in S$ and $y\in \mathbb{R}$, and $\mathbb{P}_\partial = P_0$. Then, the process $((\xi,\Theta),\mathbb{P}_{y,\theta})$ is a MAP in $S\times \mathbb{R}$ with lifetime $ \int_0^{\zeta'} \frac{ds}{||X_s||^\alpha}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:53.155983+00:00","domain":"probability theory","id":"claim_7e44cd9b8b331e7fbc0a51442882d29b49bb476c21516a769c5c9cd07f077988","kind":"theorem","schema_version":1,"statement":"[Proposition 1 (Intermediate strict partition) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For every strict partition $\lambda$,
