{"assumptions":[],"created_at":"2026-10-28T02:28:34.931710+00:00","domain":"probability theory","id":"claim_7ea8ea35e6960aa37c248600da462047497fc92481f749d70f2e25cfa7967f27","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_paths of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$ and $\delta\in (0,1)$, there exist $0<c<c'<c''<1$ depending on $d$ and $\delta$ such that the following holds. Arbitrarily fix $N_{-1}>N_{1}\ge 1$, $x_1\in \partial B(N_{1})$, $x_{-1}\in \partial B(N_{-1})$ and $D\subset \widetilde{B}(cN_{1})\cup [\widetilde{B}(c^{-1}N_{-1})]^c$. For each $j\in \{1,-1\}$, we arbitrarily take $y_{j}\in \partial B((c'')^{j}N_{j})$ and $y_{j}'\in \partial B((10c'')^{j}N_{j})$ and consider the following two random paths:
\begin{equation}
	\widetilde{\eta}_{1,j}\sim \widetilde{\mathbb{P}}_{x_{j}}\big(\{\widetilde{S}_t\}_{0\le t\le \tau_{\partial B(N_{-j})}}\in \cdot \mid \tau_{\partial B(N_{-j})}=\tau_{x_{-j}}<\tau_{D}\big),
\end{equation} 
\begin{equation}
	\widetilde{\eta}_{2,j} \sim \widetilde{\mathbb{P}}_{y_{j}}\big(\{\widetilde{S}_t\}_{0\le t\le \tau_{\partial B((10c'')^{j}N_{j})}}\in \cdot \mid \tau_{\partial B((10c'')^{j}N_{j})}=\tau_{y_{j}'}<\tau_{D}\big).
\end{equation}
For each $i\in \{1,2\}$ and $j\in \{1,-1\}$, let $\mathbf{z}_{i,j}^{\mathrm{F}}$ be the position where $\widetilde{\eta}_{i,j}$ first hits $B((c')^{j}N_{j})$ and let $\mathbf{z}_{i,j}^{\mathrm{B}}$ be the last position where $\widetilde{\eta}_{i,j}$ stays in $B((c')^{j}N_j)$ (when $\widetilde{\eta}_{i,j}$ does not reach $B((c')^{j}N_j)$, we set $\mathbf{z}_{i,j}^{\mathrm{F}}=\mathbf{z}_{i,j}^{\mathrm{B}}=\emptyset$). Then for any $v,w\in \partial B((c')^{j}N_j)$, 		
		\begin{equation}
			\mathbb{P}_{\widetilde{\eta}_{1,j}}(\mathbf{z}_{1,j}^{\mathrm{F}}=v, \mathbf{z}_{1,j}^{\mathrm{B}}=w) \le \delta \mathbb{P}_{\widetilde{\eta}_{2,j}}(\mathbf{z}_{2,j}^{\mathrm{F}}=v, \mathbf{z}_{2,j}^{\mathrm{B}}=w).
					\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:55:18.921447+00:00","domain":"probability theory","id":"claim_7ea8f750659c7acfdaad2c7061bf3e48f871801b92d086c869350be075167460","kind":"definition","schema_version":1,"statement":"[Definition smoothing-est of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] A smoothing on a scale of Banach spaces $(H^{m},\left\| \cdot \right\|_{m})_{m\in \mathbb{R}_{+}}$ is a family of operators
