{"assumptions":[],"created_at":"2026-10-27T06:32:20.019972+00:00","domain":"probability theory","id":"claim_7f3a658e6057e47f8d37eb6e1e450fe07c2c92b4f8776ccded33eb45e12ac81f","kind":"theorem","schema_version":1,"statement":"[Proposition 22 (Six descriptions of the singular mass) of arXiv:2608.03353, '\bfseries A Direct Route to Markov Chain Convergence\\[2mm] \Large via Asymptotic Equivale'] Assume \hyp{A1}{A1} and let $\alpha, \beta : \XXA \to [0,\infty)$ be finite measures,
with Lebesgue decomposition $\alpha = \alpha_{\acp{\beta}} + \alpha_{\sgp{\beta}}$ of
$\alpha$ with respect to $\beta$ as in Theorem \ref{thm:lebesgue}, and let
$S \in \XXA$ be a set with $\beta(S) = 0$ carrying $\alpha_{\sgp{\beta}}$. Then the
following six numbers coincide, and their common value is $\sing(\alpha\mid\beta)$.
\begin{enumerate}[label=\textup{(\roman*)},nosep,topsep=3pt,leftmargin=2.4em,itemsep=4pt]
  \item \emph{The variational form}, which is Definition \ref{def:singmass}:
        \begin{equation}
          \alpha(\XX) \;-\; \max\,\bigl\{\, \gamma(\XX) \ :\ \gamma \le \alpha,\ \gamma \ll \beta \,\bigr\} ,

        \end{equation}
        the maximum being attained at $\gamma := \alpha_{\acp{\beta}}$.
  \item \emph{The mass of the singular part}:
        \begin{equation}
          \alpha_{\sgp{\beta}}(\XX) .

        \end{equation}
  \item \emph{The mass the absolutely continuous part leaves over}:
        \begin{equation}
          \alpha(\XX) \;-\; \alpha_{\acp{\beta}}(\XX) .

        \end{equation}
  \item \emph{The largest mass hidden on a $\beta$-null set}:
        \begin{equation}
          \max\,\bigl\{\, \alpha(A) \ :\ A \in \XXA,\ \beta(A) = 0 \,\bigr\} ,

        \end{equation}
        the maximum being attained at $A := S$.
  \item \emph{The null set of the reversed density}:
        \begin{equation}
          \alpha\bigl( \{ g = 0 \} \bigr) ,
          \qquad\text{$g$ any density of $\beta_{\acp{\alpha}}$ with respect to $\alpha$.}

        \end{equation}
  \item \emph{The distance to the measures that have a density}:
        \begin{equation}
          \min\,\bigl\{\, \tv{\alpha - \gamma} \ :\ \gamma : \XXA \to [0,\infty)
          \text{ a finite measure},\ \gamma \ll \beta \,\bigr\} ,

        \end{equation}
        the minimum being attained at $\gamma := \alpha_{\acp{\beta}}$; and if
        $\alpha,\beta \in \Prob$ the same minimum is attained over the smaller set of
        competitors $\gamma \in \Prob$ with $\gamma \ll \beta$.
\end{enumerate}
Moreover $\alpha_{\acp{\beta}}(S) = 0$, so that the carrier $S$ splits the mass of
$\alpha$ as
\begin{equation}
  \alpha(S) = \sing(\alpha\mid\beta)
  \qquad\text{and}\qquad
  \alpha(\XX\setminus S) = \alpha(\XX) - \sing(\alpha\mid\beta) .

\end{equation}
In particular $\sing(\alpha\mid\beta) = 0$ if and only if $\alpha \ll \beta$, and
$\sing(\alpha\mid\beta) = \alpha(\XX)$ if and only if $\alpha \perp \beta$, that is
if and only if $\alpha$ is carried by a $\beta$-null set.","status":"unverified"}

