{"assumptions":[],"created_at":"2026-10-27T11:07:35.030678+00:00","domain":"probability theory","id":"claim_7f547af7b7b34be3733790dfd7c2a9027beadc6aa47fd339f5cad9b30a85e735","kind":"theorem","schema_version":1,"statement":"[The 31 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Suppose $H$ is a Tonelli Hamiltonian on $\T^n$, $\phi\in \SCL(\T^n)$, and $u$ is the viscosity solution of \eqref{eq:HJephi pre}. Let $\gamma: [0,T] \to \T^n$ be a $(u,H)$-calibrated curve with dual arc $p(t) = L_v(\gamma(t),\dot{\gamma}(t))$ for $t \in [0,T]$. The following statements are true:

	\begin{enumerate}
		\item 	If $\gamma(t_0)\in\operatorname{Alex}(u(t_0,\cdot))$ for some $t_0\in[0,T)$, then $\gamma(t)\in\operatorname{Alex}(u(t,\cdot))$ for all $t\in[t_0,T)$. Moreover, the map $t\mapsto Q(t)=D^2_xu(t,\gamma(t))$ is of class $C^1$ on $[t_0,T)$ and $Q(t)$ satisfies the following matrix Riccati equation
		\begin{equation}
			\dot{Q}(t)+Q(t)\cdot H_{pp}(\gamma(t),p(t))\cdot Q(t)+Q(t)\cdot H_{px}(\gamma(t),p(t))+H_{xp}(\gamma(t),p(t))\cdot Q(t)+H_{xx}(\gamma(t),p(t))=0. \tag{Ricc}
		\end{equation}		
		\item  If $\gamma(t_0)\in\operatorname{Alex}(u(t_0,\cdot))\cap \operatorname{supp}_{C^{1,1}}(u(t_0,\cdot))$ for some $t_0\in[0,T)$, where $\text{supp}_{C^{1,1}}(u(t_0,\cdot))$ is the $C^{1,1}$ support of $u(t_0,\cdot)$ (see the definition before Theorem \ref{thm:close_cut}), then $\gamma(t)\in\operatorname{Alex}(u(t,\cdot))$ for all $t\in[0,T)$. Moreover, the map $t\mapsto Q(t)=D^2_xu(t,\gamma(t))$ is of class $C^1$ on $[0,T)$ and $Q(t)$ satisfies \eqref{eq:Ricc}.
	\end{enumerate}","status":"unverified"}

