{"assumptions":[],"created_at":"2026-10-27T23:07:56.650365+00:00","domain":"probability theory","id":"claim_80d9d00ff89614f490c397f24f984619be176c48e58d84ff7e4ed2bc049c7282","kind":"lemma","schema_version":1,"statement":"[Lemma delay_rough of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let $\mathbf{X}$ be a \emph{$\pi$-delayed $\gamma$-rough path with delay $r > 0$}. Suppose $\frac{1}{3}<\beta\leq\gamma$ , $r_1\leq r$ $(\zeta,\zeta^\prime)\in\mathscr{D}_{\mathbf{X}}^{\beta}([-r,0],\mathbb{R}^d) $, $(\xi_1,\xi_{1}^{\prime})\in\mathscr{D}_{\mathbf{X}}^{\beta}([-r,0],\mathbb{R}^d)$ and $(\xi_2,\xi_{2}^{\prime}),(\eta,\eta^{\prime})\in \mathscr{D}_{\mathbf{X}}^{\beta}([0,r_1],\mathbb{R}^d) $. Assume $F:\mathbb{R}^{d}\times\mathbb{R}^d\times\mathbb{R}^d\rightarrow \mathcal{L}(\mathbb{R}^m,\mathbb{R}^n)\in C^{2}_{b}$. Let $\xi: [-r,r_1]\rightarrow \mathbb{R}^d$ is defined by
			\begin{align}
				\xi_{t}:=\begin{cases}
					\xi_{1}(t), & \text{for } -r\leq t<0\\
					\xi_{2}(t), & \text{for } 0\leq t\leq r_1
				\end{cases} \ \ 
			\end{align}
			and
			\begin{align}
				\xi_{t}^{\prime}:=\begin{cases}
					\xi_{1}^{\prime}(t), & \text{for } -r\leq t<0\\
					\xi_{2}^{\prime}(t), & \text{for } 0\leq t\leq r_1
				\end{cases} \ \ 
			\end{align}
			Then for every  $s,t\in [0,r_1]$ and $A_{s}:=\big(\eta_{s},\zeta_{s-r},\int_{-r}^{0}\xi_{\theta+s}\pi(\mathrm{d}\theta)\big)$, following statement is well defined
			\begin{align}
				\begin{split}
					&\int_{s}^{t}F\big(\eta_{\tau},\zeta_{\tau-r},\int_{-r}^{0}\xi_{\theta+\tau}\pi(\mathrm{d}\theta)\big)\circ\mathrm{d}\mathbf{X}_{\tau}:=\quad\lim_{\vert\Pi\vert\rightarrow 0}\bigg[\sum_{t_j\in\Pi}F(A_{t_j})\circ X_{t_{j},t_{j+1}}\\&\quad+\sum_{t_j\in\Pi} \frac{\partial F}{\partial Y_{1}}|_{A_{t_j}}\circ (\eta^{\prime}_{t_j}\circ\mathbb{X}_{t_j,t_{j+1}})+\sum_{t_j\in\Pi}\frac{\partial F}{\partial Y_{2}}|_{A_{t_j}}\circ(\zeta^{\prime}_{t_j-r}\circ \mathbb{X}_{t_j,t_{j+1}}(-r))\\ &\qquad+\sum_{t_j\in\Pi} \frac{\partial F}{\partial Y_{3}}|_{A_{t_j}}\circ \big(\int_{-r}^{0}\xi_{\theta+t_j}^{\prime}\circ \mathbb{X}_{t_j,t_{j+1}}(\theta)\pi(\mathrm{d}\theta)\big)\bigg{]}.
				\end{split}
			\end{align}
			Where by $\frac{\partial F}{\partial Y_{1}}|_{A_{\tau}}, \frac{\partial F}{\partial Y_{2}}|_{A_\tau}$ and $ \frac{\partial F}{\partial Y_{3}}|_{A_\tau}$, we mean the derivative of $F$ respect to first, second and the third arguments at $A_\tau$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:43:53.643914+00:00","domain":"probability theory","id":"claim_80dd3ce37a9c01129c9a6c29d1703d3f7f0ad395acdfccf4f0115d2d18efaa37","kind":"concept","schema_version":1,"statement":"[Theorem thm:gartner_ellis of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Consider a sequence of random variables $(X_n)_{n \geq 1}$ and a sequence $(a_n)_{n \geq 1}$ with $a_n \gg 1$. Assume for every $\lambda \in \mathbb R$ the limit
    \begin{align*}
    \lim_{n \to \infty}\frac{1}{a_n}\log \mathbb{E}\left[\Big.\exp\big(\lambda a_nX_n\big)\right]= \Lambda(\lambda),  \addtocounter{equation}{1}\tag{\theequation} 
\end{align*}
    exists point-wise as a convex function of $\lambda$, possibly assuming an extended real value for some $\lambda$, with the origin lying inside the interior of the domain $\mathcal D_{\Lambda}:=\{\lambda \in \mathbb R:\Lambda(\lambda)<\infty\}.$ Let $\Lambda$ further satisfy the following:
    \begin{itemize}
    \item Interior of $\mathcal D_{\Lambda}$ is non empty.
    \item $\Lambda$ is differentiable at all points of the interior of $\mathcal D_{\Lambda}$.
    \item $\Lambda(\cdot)$ is steep, namely, $\lim_{n \to \infty} |\Lambda'(\Lambda_n)|=\infty$ whenever $\lambda_n$ is a sequence of interior points of $\mathcal D_{\Lambda}$ converging to some boundary point of the interior of $\mathcal D_{\Lambda}$.
\end{itemize}
Then the sequence $(X_n)_{n \geq 1}$ satisfies a LDP with speed $a_n$ and with good rate function $\Lambda^*$, the \emph{Fenchel-Legendre} transform of $\Lambda$, defined as,
\begin{align*}
    \Lambda^*(x)=\sup_{\lambda \in \mathbb R}\Big\{\lambda x -\Lambda(\lambda)\Big\}\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

