                    \end{align}
                In addition, we have 
                    \begin{align}
                        \Psi_{k }\left( \Psi_{\ell}\left(\eta\right) \right)\left( \ \cdot \ \right) =  \Psi_{k + \ell }\left( \eta\right)\left( \ \cdot \ \right),
                    \end{align}
                and 
                    \begin{align}
                        \zeta_{k}\left(\Psi_{\ell}\left( \eta \right), \ \cdot \ \right) = \zeta_{k+\ell}\left(\eta, \ \cdot \ \right) .
                    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.861167+00:00","domain":"probability theory","id":"claim_8109d193f3c60c2fefa54e5626df00c1392d4870811c703d3a0f34d0c84ca6f9","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $X^h, Y$ be defined as above, let Assumption \ref{Aspt_new} hold and assume that $f:\mathbb{R}\rightarrow \mathbb{R}$ is $l$-times weakly differentiable with derivatives which are functions of polynomial growth. Then, for $h \in (0,1)$, 
