{"assumptions":[],"created_at":"2026-10-27T21:48:02.409005+00:00","domain":"probability theory","id":"claim_820c35f694f5caed5c42b713589e2d9f9066f7e4c21aa0f3d69da7918dca023a","kind":"lemma","schema_version":1,"statement":"[Lemma lma:flipgroups of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $T$ denote $T_n^{tor}$ or $T_m^{tw}$, and let $T^{fl}$ be its flip. 
\begin{enumerate}
	\item The flipped torus-trivial group is free of rank two on $A = x_{n+3}, H^{fl} = x_1^{-1}D^{-n}$, with $D = A(H^{fl})^{-1}AH^{fl}$. The flipped twist-trivial group is free of rank two on $Y = x_{2m+4}$, $H^{fl} = x_1^{-1}C^m$, with $A = Y^{-1}(H^{fl})^{-1}YH^{fl}Y$ and $C = AYA^{-1}Y^{-1}$.
	\item Killing the trivial-strand meridian gives the same quotients $Q_n^{tor}$ and $Q_m^{tw}$ for standard and flipped tangles, with the same presentations as Propositions (prop:torusgroup of the paper) and (prop:twistgroup of the paper). 
	\item Let $r$ be a root of $P_n$. The assignments $\rho_r^{fl}(A) = A_r$, $\rho_r^{fl}(H^{fl}) = D_r^{-n}$ define a representation of the flipped torus-trivial group. It satisfies 
	\begin{equation*}
		\rho_r^{fl}(m_1) = \rho_r^{fl}(m_2) = I \ \ \ \ \ \rho_r^{fl}(m_3) = \rho_r^{fl}(m_4) = B_r
	\end{equation*} Let $z$ be a real root of $\Lambda_{2m-1}$. The assignments $\rho_z^{fl}(Y) = W_z^{-1}T_z$, $\rho_z^{fl}(H^{fl}) = W_z^m$ define a representation of the flipped twist-trivial group. It satisfies 
	\begin{equation*}
		\rho_z^{fl}(m_1) = \rho_z^{fl}(m_2) = I \ \ \ \ \ \rho_z^{fl}(m_3) = \rho_z^{fl}(m_4) = T_z
	\end{equation*}
	In both cases, every knot-strand Wirtinger generator has the same image as $\rho_r$ and $\rho_z$; indeed, both representations descend to the same $\bar\rho_r$ and $\bar\rho_z$ on the quotients. 
	\item Let $l_{1,n}^{tor, fl} = x_{n+4}^{-1}$, and $l_{1,m}^{tw, fl} = x_{2m+3}$ be the identity-strand pieces in the flipped diagrams. Then 
	\begin{equation*}
		\rho_r^{fl}(l_{1,n}^{tor,fl}) = \rho_r(l_{1,n}^{tor})^{-1} \ \ \ \ \ \rho_z^{fl}(l_{1,m}^{tw, fl}) = \rho_z(l_{1,m}^{tw})^{-1}
	\end{equation*}
	If $l_2^{fl}$ denotes the knot-strand piece in the flipped diagram, its quotient image agrees with that of $l_2$. Consequently, $\rho^{fl}(l_2^{fl}) = \rho(l_2)$. 
	\item The pair $(T^{fl}, \rho^{fl})$ satisfies hypotheses (1)-(4) of Theorem (thm:main of the paper) if and only if $(T, \rho)$ does. 
	\item Let $\widetilde{\bar\rho}: Q \to \widetilde{PSL}_2(\mathbb R)$ be the meridian-normalized lift of the quotient, and define the standard and flipped tangle lifts by composition with their quotient maps. Then 
	\begin{equation*}
		\mathrm{trans}(\widetilde\rho^{fl}(l_1^{fl})) = 0 \ \ \ \ \ \mathrm{trans}(\widetilde\rho^{fl}(l_2^{fl})) = \mathrm{trans}(\widetilde\rho(l_2))
	\end{equation*} 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.168782+00:00","domain":"probability theory","id":"claim_820d0f48d4ba5e6bada79c45aa816a5f6843ddb6a723df0f65c6129d3435a78f","kind":"theorem","schema_version":1,"statement":"[Proposition 5 of arXiv:2604.18427, 'Expected perimeter and area of the convex hull of planar Brownian motion stopped upon exit'] For $y\in (-b_a,b_a)$,
    density of $\omega_{\cD_a}^0$ at $a+i\,\D y$ is
    \begin{equation}

        \omega_{\cD_a}^0(a+i\,\D y)
        =
        \frac{2b_a}{\beta_a(b_a-y)^2}
        \frac{\rho_a(y)^{\lambda_a-1}\sin\Phi_a}{\sin^2\Phi_a + \bigl(\rho_a(y)^{\lambda_a}-\cos\Phi_a\bigr)^2} \, \D y,
    \end{equation}
    where $\rho_a(y):= \mathfrak{l}_a(a+iy) = (b_a+y)/(b_a-y)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:54:28.026955+00:00","domain":"probability theory","id":"claim_820d3e227250e352485be22a0da4129b6cb554db0bff4f057ac3bc4132b7c394","kind":"concept","schema_version":1,"statement":"[Theorem thm:count of arXiv:2608.09465, 'Balancing fractional Brownian motion'] Let $f_1, \ldots, f_n$ be independent sample paths of standard Brownian motion on $[0,1]$ started from the origin.
Let $Z_n(a)$ be the number of elements $\sigma$ with $L(\sigma)\leq a$, and let $Y_n(a)$ be the number of signings that are also local minima. For any sequence $a_n$ with $a\coloneqq \inf_n a_n>a_0$ and $a_n<n^{1/4}/\sqrt{4\log n}$, 
\begin{align}
\mathbb{E}[Y_n(a_n)] = (1-o(1))\mathbb{E}[Z_n(a_n)] = \left(\frac{4}{\pi}-o(1)\right)\exp\left\{\left(\log 2-\frac{\pi^2}{8a_n^2}\right)n\right\}. 
\end{align}
If we further assume $a_n\to\infty$, with probability $1-o(1)$, $Y_n(a_n) = (1+o(1))\mathbb{E}[Y_n(a_n)]$ and $Z_n(a_n) = (1+o(1))\mathbb{E}[Z_n(a_n)]$, where $o(1)$ depends only on $a_n$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:10.191919+00:00","domain":"probability theory","id":"claim_820dd772b00634fecb60422497ef2d5d5440a6c460b5d6569b07edb6cd7d2e59","kind":"concept","schema_version":1,"statement":"[Prop 7 (Pro\"inov Theorem (1984)) of arXiv:2605.03528, '\bf Kolmogorov-Smirnov distance and discrepancies {\em versus} Wasserstein distances'] Let $d$, $n \!\in \N$ and let   $\big([0,1]^d\big)^n$-valued $n$-tuple $(\xi_k)_{k=1,\ldots,n}$. Then there exists a real constant $C_d\!\in [1,4]$ such that 
\[
{{\cal W}_1^{\ell^{\infty}}\Big( \frac 1n \sum_{k=1}^n \delta_{\xi_k}, {\cal U}([0,1]^d) \Big)\le C_d D^{\star, {\cal U}([0,1]^d)}\big((\xi_k)_{k=1,\ldots,n}\big)^{\frac 1d},}
\]
where ${\cal W}_1^{\ell^{\infty}}$ denotes the  Wasserstein distance w.r.t. the $\ell^\infty$-norm on $[0,1]^d$. Moreover when $d=1$, then $C_1=1$ and both error moduli attain their minimum, $n$ being fixed, at $\Big(\frac{2k-1}{2n}\Big)_{k=1,\ldots,n}$ with a common resulting value $\frac{1}{2n}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.635335+00:00","domain":"probability theory","id":"claim_8214087d85041145fc7142d0ba8727ebcbda7d829c5aad0e61734104568657fa","kind":"concept","schema_version":1,"statement":"[Theorem a1 of arXiv:2411.19926, 'Sparse Pseudospectral Shattering'] For any $\rho$, $M \in \mathbb C^{n\times n}$ satisfying
\begin{equation} 
    \frac{\left[\log(n)\log(2\|M\| + n)\right]^{3}}{n} \le \rho \le \frac{n^{1/2}}{n}
\end{equation}
we have
\begin{align}
    \Pr\pare{\kappa_V(M+N_g)\ge(2\left\|M\right\|+n)^{15K}}
