{"assumptions":[],"created_at":"2026-10-27T14:18:13.247910+00:00","domain":"probability theory","id":"claim_826ad0ea38413a9b6cd7b6048a501f296a80998b8d1dc43e5ce9c36b348a4012","kind":"definition","schema_version":1,"statement":"[Definition eq-operators of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp We will introduce the following operators for functions {\small$\mathsf{A}:[0,\infty)\times\R\to\R$}.

\begin{enumerate}
\item Let us introduce notation that will capture the main error terms. Suppose {\small$\mathfrak{q}\in\mathscr{C}^{\infty}(\R^{\Z})$} is a local function so that {\small$\mathfrak{q}[\bphi]$} depends only on {\small$\bphi_{\w}$} for {\small$\w\in\{1,\ldots,\mathfrak{l}_{\mathfrak{q}}\}$} for some {\small$1\leq\mathfrak{l}_{\mathfrak{q}}\lesssim1$}. We define the following space-time average, in which {\small$\mathfrak{t}_{\mathbf{Av}}=N^{-2/3-10\delta_{\mathbf{S}}}$} and {\small$\mathfrak{n}_{\mathbf{Av}}=N^{1-3\delta_{\mathbf{S}}/2}$}:

\begin{align}
\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}}_{\t,\x}:=\mathfrak{t}_{\mathbf{Av}}^{-1}{\int_{0}^{\mathfrak{t}_{\mathbf{Av}}}}\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\Big(\mathfrak{q}[\tau_{\x+\j}\bphi_{\t-\r}]\cdot\mathbf{Z}^{N}_{\t-\r,\x+\j}(\mathbf{Z}^{N}_{\t,\x})^{-1}\Big)\d\r.
\end{align}

Note that {\small$\mathfrak{t}_{\mathbf{Av}}\ll1$} and {\small$\mathfrak{n}_{\mathrm{Av}}\ll N$}; thus, these scales are mesoscopic. {\color{black}We also note that the exact exponents of {\small$\approx-2/3$} and {\small$\approx1$} are not so meaningful; they are just sufficiently large to yield enough cancellations in (equation eq:mult-op-1 of the paper).} On the other hand, suppose {\small$\mathfrak{q}[\bphi]$} depends only on {\small$\bphi_{\w}$} for {\small$\w\in\{-\mathfrak{l}_{\mathfrak{q}},\ldots,0\}$} for some {\small$1\leq\mathfrak{l}_{\mathfrak{q}}\lesssim1$}. In this case, let us define the space-time average in the same way but with the ``left-wards" orientation:

\begin{align}
\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}}_{\t,\x}:=\mathfrak{t}_{\mathbf{Av}}^{-1}{\int_{0}^{\mathfrak{t}_{\mathbf{Av}}}}\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\Big(\mathfrak{q}[\tau_{\x-\j}\bphi_{\t-\r}]\cdot\mathbf{Z}^{N}_{\t-\r,\x-\j}(\mathbf{Z}^{N}_{\t,\x})^{-1}\Big)\d\r.
\end{align}

We remark that (equation eq:mult-op-1 of the paper) and (equation eq:mult-op-2 of the paper) make sense for any other non-negative {\small$\mathfrak{t}_{\mathbf{Av}}$}. In particular, if {\small$\mathfrak{t}_{\mathbf{Av}}=0$}, then the meaning of (equation eq:mult-op-1 of the paper)-(equation eq:mult-op-2 of the paper) is obtained by setting {\small$\r=0$} and dropping the {\small$\d\r$} integration; for this, we write

\begin{align}
\mathbf{Av}^{\mathbf{X},\mathfrak{q}}_{\t,\x}:=\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}}_{\t,\x}|_{\mathfrak{t}_{\mathbf{Av}}\mapsto0}.
\end{align}

In particular, by (equation eq:ch of the paper), if {\small$\mathfrak{q}[\bphi]$} is supported on {\small$\bphi_{\w}$} for {\small$\w\geq1$}, then

\begin{align}
\mathbf{Av}^{\mathbf{X},\mathfrak{q}}_{\t,\x}&:=\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\mathfrak{q}[\tau_{\x+\j}\bphi_{\t}]\cdot\exp\Big\{\lambda N^{-\frac12}(\bphi_{\t,\x+1}+\ldots+\bphi_{\t,\x+\j})\Big\}.\nonumber
\end{align}

On the other hand, if {\small$\mathfrak{q}[\bphi]$} is supported on {\small$\bphi_{\w}$} for {\small$\w\leq0$}, then

\begin{align}
\mathbf{Av}^{\mathbf{X},\mathfrak{q}}_{\t,\x}&:=\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\mathfrak{q}[\tau_{\x-\j}\bphi_{\t}]\cdot\exp\Big\{\lambda N^{-\frac12}(\bphi_{\t,\x}+\ldots+\bphi_{\t,\x-\j+1})\Big\}.\nonumber
\end{align}

\item For any {\small$\mathfrak{t}_{0}\geq0$}, we define the following averaged time-gradient operator acting on functions {\small$\mathsf{f}:[0,1]\to\R$}:

\begin{align}
\grad^{\mathbf{T},\mathrm{av}}_{\mathfrak{t}_{0}}\mathsf{f}_{\t}:=\mathbf{1}_{\mathfrak{t}_{0}>0}\mathfrak{t}_{0}^{-1}{\int_{0}^{\mathfrak{t}_{0}}}\Big(\mathsf{f}_{\t}-\mathsf{f}_{\t-\r}\Big)\d\r.
\end{align}

In (equation eq:timegrad of the paper), we implicitly extend {\small$\mathsf{f}_{\t}$} to {\small$\t\not\in[0,1]$} via {\small$\mathsf{f}_{\t}=\ma","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.696195+00:00","domain":"probability theory","id":"claim_826da215ddbf4c2b36a1c552dd98ae016f4594bae3d05dc19fc176ab6723b3a2","kind":"theorem","schema_version":1,"statement":"[Theorem thm:limit_cumulant of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Consider the mixed cumulant $\kappa_X(n_1,\dots,n_s)$ as   in  Definition (Cumu of the paper)   for the $\alpha$-stable random band Gaussian matrices (Definition (defmodel of the paper)) with $ \alpha>d=1$. Assume that $n = \sum_{i=1}^s n_i$ is even and $t_i \in (0,\infty)$ for $i=1,\dots,s$. Suppose further that the parameters $(\{n_i\}, W, N)$ satisfy the following scalings:
\begin{itemize}
    \item \textbf{Supercritical regime:} $n_i \sim t_i N^{1/3}$;
    \item \textbf{Subcritical/Critical regimes:} $n_i \sim t_i W^{\alpha/(3\alpha-1)}$.
\end{itemize}
Then, as $N \to \infty$,
\begin{equation}
\frac{1}{n_1\cdots n_s}\,\kappa_X(n_1,\dots,n_s) = \big(1+o(1)\big)\sum_{\Gamma\in \mathcal{T}_{s}} \mathcal{L}_\Gamma \bigl(\{t_i\}, (W,N)\bigr),
\end{equation}
where $\mathcal{T}_s$ is the set of typical connected diagrams on $s$ marked points (Definition (def:typical_diagram of the paper)), and
\begin{equation} 
\mathcal{L}_\Gamma (\{t_i\}, (W,N)): = \begin{cases}
    \mathcal{F}_{\Gamma}^{\mathrm{(Super)}}(t_1,\dots,t_s), & \mathrm{Supercritical ~case,} \\
    N W^{-\frac{3\alpha}{3\alpha-1}}\mathcal{F}_{\Gamma}^{\mathrm{(Sub)}}(t_1,\dots,t_s), & \mathrm{Subcritical ~case,} \\
    \gamma^{|E|-|V|}\mathcal{F}_{\Gamma}^{\mathrm{(Crit)}}(t_1,\dots,t_s;\gamma^{\alpha}), & \mathrm{Critical ~case ~} (W \sim (\gamma N)^{1-\frac{1}{3\alpha}}).
\end{cases}
\end{equation}
Furthermore, there exist  constants $C, C_{\gamma} > 0$ such that the sum is uniformly bounded by
\begin{equation}
\sum_{\Gamma\in \mathcal{T}_{s}} \mathcal{L}_\Gamma \le \begin{cases}
    e^{Ct^{3/2}}, & \mathrm{Supercritical ~case,} \\
    N W^{-\frac{3\alpha}{3\alpha-1}}e^{Ct^{\frac{3\alpha-1}{2\alpha-1}}}, & \mathrm{Subcritical ~case,} \\
    e^{Ct^{3/2}} + e^{C_{\gamma}t^{\frac{3\alpha-1}{2\alpha-1}}}, & \mathrm{Critical ~case.}
\end{cases}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.050095+00:00","domain":"probability theory","id":"claim_826f32fdda092b7e81b2a6618454e2cb511821e231c3a354f4a5dcee124a1bc7","kind":"theorem","schema_version":1,"statement":"[Mypropo 11 of arXiv:2607.00495, 'Rank deficiency of Bernoulli random matrices for growing corank'] Let $\delta,\rho,\varepsilon \in (0,1)$ and $k \ge 1$, there exist $n_{\ref{Incomp Levy}}$, $L_{\ref{Incomp Levy}}$ and $c_{\ref{Incomp Levy}}$ depending on $\delta,\rho,\varepsilon,p$ such that for all $n\ge n_{\ref{Incomp Levy}}$ and $1 \le k \le c_{\ref{Incomp Levy}}\sqrt{\log{n}}$, with the probability at least $1-(1-p)^{4kn}$, for all $x \in \mathrm{Incomp}_{n}(\delta,\rho) \cap \ker{B}$:
