{"assumptions":[],"created_at":"2026-10-27T12:15:15.512258+00:00","domain":"probability theory","id":"claim_82a243a3a270615d12b81c3de54094b001d629e9befbfad0cbe38d77b670fae3","kind":"theorem","schema_version":1,"statement":"[Corollary HF-one-sign of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] If 
