0&{\rm if}\ {i\not\!\!-\,j}
\end{cases}$$
Moreover, the matrices $d\in M_N(0,1)$ which can appear in this way, from graphs, are precisely those which are symmetric, and have $0$ on the diagonal.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:00:30.495916+00:00","domain":"probability theory","id":"claim_8339c19b050e8c3f729dec1719230435a6457286e772ac8d84ab6be0ca5708ee","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2607.04193, 'Onsager--Machlup Functionals for Generalized Newtonian Equations of Motion with Time-Varyi'] Let $f \in L^1([a,b];\mathbb{R})$. For $\alpha > 0$, the operators
    \begin{align*}
        (I_{a^+}^\alpha f)(x) &:= \frac{1}{\Gamma(\alpha)} \int_a^x (x - y)^{\alpha-1} f(y) \, dy, \quad x \ge a, \\
        (I_{b^-}^\alpha f)(x) &:= \frac{1}{\Gamma(\alpha)} \int_x^b (y - x)^{\alpha-1} f(y) \, dy, \quad x \le b,
    \end{align*}
    are called the left-sided and right-sided Riemann--Liouville fractional integrals of order $\alpha$, respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.890078+00:00","domain":"probability theory","id":"claim_8346fedfc5d8ad70bfe5088bd3121e81462da202cf3acb764e31fc549ebbe8a5","kind":"lemma","schema_version":1,"statement":"[Lemma 26 (Time change formula for It\^o integrals) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] \textcolor{white}{,}\\   Suppose $\eta(s,\omega)$, $\ B(s,\omega)$ and $\alpha(s,\omega)$ are $ s$-continuous, $\alpha(0,\omega)=0$ for a.a. $\omega$, $\mathbb{E}[\alpha_t]<\infty$ and $ B(s,\omega) \in SO(m)$. Let $ W_s$ be an $ m$-dimensional Brownian motion and let $ v(s,\omega)$ be bounded and $ s$-continuous. Define
 \begin{equation}
     \tilde{W}_t=\lim_{j \rightarrow \infty} \sum_{j} \sqrt{\eta(\alpha_j,\omega)} B(\alpha_j,\omega)\Delta W_{\alpha_j} = \int_0^{\alpha_t}  \sqrt{\eta(s,\omega)} B(s,\omega) dW_s.
 \end{equation}
 Then  $\tilde{W}_t$ is an $\mathcal{F}_{\alpha_t}$-Brownian motion and
 \begin{equation}
     \int_0^{\alpha_t} v(s,\omega) dW_s = \int_0^t v(\alpha_r,\omega) \sqrt{\alpha'_r(\omega)} B^{-1}(\alpha_r,\omega) d\tilde{W}_r \ \ \mathbb{P}-a.s.,
 \end{equation}
 where $ \alpha'_r(\omega)=\frac{1}{\eta(\alpha_r,\omega)} .$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:11.423153+00:00","domain":"probability theory","id":"claim_8349408d9368591934b227c49c338e2ffa30eea2efc05deac9c74da474984f4c","kind":"theorem","schema_version":1,"statement":"[Proposition 26 of arXiv:2606.09121, 'Truncated Signature Information for Mixed Fractional Brownian Paths'] For $n\ge1$ and $\alpha>0$, define
\begin{equation}
    \kappa_n(\alpha)
    :=\frac1n\sum_{k=0}^{n-1}
    \left[
        \frac12\left(
        \left(1-\frac{k}{n}\right)^\alpha
        +\left(1-\frac{k+1}{n}\right)^\alpha
        \right)
        -\frac16 n^{-\alpha}
    \right].
\end{equation}
Then
\begin{equation}
    \kappa_n(\alpha)
    =\frac{1}{2n}
     +\frac{1}{n^{\alpha+1}}\sum_{m=1}^{n-1}m^\alpha
     -\frac{1}{6n^\alpha},
\end{equation}
and $\kappa_n(\alpha)>0$.  Moreover, with
\[
    R_\theta^{(n)}(h)
    :=2\E_\theta\!\left[\pi_{122}S(Z_{t,h}^{(n)})\right],
\]
the quantity $R_\theta^{(n)}(h)$ is independent of $t$, and one has the exact representation
\begin{equation}
    R_\theta^{(n)}(h)
    =\sum_{r=1}^K v_r\kappa_n(\alpha_r)h^{\alpha_r}.
\end{equation}
For every $0<a\le b<\infty$,
\begin{equation}
    \sup_{\alpha\in[a,b]}
    \left|\kappa_n(\alpha)-\frac{1}{\alpha+1}\right|
    \le \frac{1}{2n}+\frac{1}{6n^a},
\end{equation}
and consequently
\begin{equation}
    \kappa_n(\alpha)\longrightarrow \frac{1}{\alpha+1}
\end{equation}
uniformly on compact subsets of $(0,\infty)$.","status":"unverified"}

