&\bI = \alpha^2\, \bS\int \bfeta\,\bB\,\bfeta^*\, \nu(\de\bT)\, \bS^*\bB^{-1} 
+ \alpha\, \bS\,\Im(\bZ)\,\bS^* \bB^{-1}.
\end{align}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.188462+00:00","domain":"probability theory","id":"claim_84e382b37a39e3f8550e90db607ec0c69264c4ac8e9969841e8cfbb9630f34d9","kind":"lemma","schema_version":1,"statement":"[Lemma 20 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE} and \ref{assump-particles} hold, with $\sigma\in [0,+\infty)$.
